update content_bodies set title = 'イオンモール沖縄ライカム 後編 フードコート4階編', description = 'この動画では、県内最大級のリゾート型ショッピングセンターであるイオンモール沖縄ライカムのフードコート4階を紹介しています。現地を訪れることが難しい方々に向けて、さんぽ気分を楽しんでもらうことを目的としています。動画は「おきなわさんぽ」シリーズの一部で、沖縄観光の魅力を伝えています。詳細は説明文に記載されたチャンネルリンクから他の動画もご覧いただけます。' where id = 'Ssv1YiHdiDgyZjhjS8rDM';
