update content_bodies set title = 'Seeing differently: Market Edition', description = 'This video aims to reduce stress and barriers such as anxiety, confusion, and discomfort for foreign tourists visiting Japan by promoting an understanding of Japanese culture, customs, behaviors, and social norms. It also encourages Japanese residents to reconsider basic manners and foster a spirit of hospitality. The goal is to raise awareness of different perspectives and encourage consideration for those around us.' where id = 'ZXdGnlLWnY4YLWi-xl3Q4';
