update content_bodies set title = 'Seeing differently: Market Edition', description = 'This video aims to reduce stress and barriers such as anxiety, confusion, and discomfort for foreign tourists visiting Japan by promoting an understanding of Japanese culture, customs, behaviors, and social norms. It also encourages Japanese residents to reconsider basic manners and foster a spirit of hospitality. The goal is to raise awareness of different perspectives and encourage consideration for those around us.' where id = 'K3A45hn7ccFgSjuNmdVNO';
update content_bodies set title = '【行かなきゃ損】地元民が選ぶ夏の和歌山・白浜観光スポット7選', description = '和歌山を知り尽くした地元民が厳選した白浜の観光スポット7つを紹介します。1泊2日の旅行を計画している方に向けて、アドベンチャーワールドや美砂家、かげろうカフェ、円月島、平草原展望台、白良浜、ホテルシーモアなど、夏休みに訪れるべきスポットをお届けします。特に、白良浜は「日本の快水浴場百選」にも選ばれた美しいビーチです。和歌山の観光スポットについての質問があれば、コメントで教えてください。' where id = 'rppEn4uUItwM8wd-IOGVK';
update content_bodies set title = 'Must-Visit Summer Tourist Spots in Shirahama, Wakayama: 7 Picks by Locals', description = 'This article highlights seven essential tourist spots in Shirahama, Wakayama, as recommended by locals who know the area well. It provides valuable information for those planning a one-night, two-day trip to Shirahama, especially during the summer vacation. The featured attractions include Adventure World, a pizza and cheese restaurant called Misa-ya, Kagerou Cafe, the iconic Engetsu Island, the Hirakusa Plain Observatory, the beautiful Shirarahama Beach, and Hotel Seamore, where guests can enjoy stunning ocean views from hot springs and foot baths. Readers are encouraged to ask questions about other tourist spots in Wakayama in the comments.' where id = 'B7-shCUQvNGzxCnlQrWSp';
update content_bodies set title = 'バイクパッキングウィークエンド「水の国」で清流と奇岩の絶景を追いかけて（古座川町・串本町）', description = 'Papersky vol.66に掲載された「水の国、わかやま。」ライドでは、古座川の清流や力強い奇岩、串本の青い海と絶景を巡るおすすめのライドコースを紹介しています。' where id = 'gmhH6ykRTr9iQfeF7YeR3';
update content_bodies set title = 'Bike Packing Weekend: Chasing Scenic Views of Clear Streams and Unique Rocks in ''Water Country'' (Kozagawa Town & Kushimoto Town)', description = 'This ride featured in Papersky vol.66 showcases the beautiful landscapes of ''Water Country, Wakayama.'' It highlights recommended cycling routes that explore the clear streams of Kozagawa, the powerful unique rocks, and the stunning blue sea of Kushimoto.' where id = 'avdXXHhPdk9SDaeFN9vKE';
update content_bodies set title = '紀州浪漫2022春号　わかやま庭園回遊', description = '和歌山県にある名園を巡る旅です。日差しが暖かくなると外に出かけたくなりますが、そんな時には美しい庭園を眺めながら静かに散策するのがおすすめです。また、その地域ならではのグルメを楽しむことも旅の楽しみの一つです。春はわかやま庭園回遊にぴったりの季節です！' where id = 'q6LuxEsXNgUBrlKJtAIlF';
update content_bodies set title = 'Kishu Romance Spring 2022: Exploring Wakayama Gardens', description = 'This is a journey to explore the famous gardens in Wakayama Prefecture. As the weather warms up, it''s the perfect time to go outside and enjoy the beauty of these gardens while taking a peaceful stroll. Additionally, indulging in local gourmet food is another highlight of the experience. Spring is the ideal season for a garden tour in Wakayama!' where id = 'F8BxrscymQjesLApLV0Nh';
update content_bodies set title = 'サイクリング王国わかやま　Route.4　熊野三山巡り', description = '世界遺産の熊野をサイクリングするのは、ベキさんと筧五郎さんです。那智の滝でパワーをもらった後、熊野速玉大社を経由して熊野本宮を目指します。川湯温泉や湯の峰温泉で癒されながら、大自然の中をサイクリングを楽しむことができます。' where id = 'vp2KCGauguFsemt_uHXMx';
update content_bodies set title = 'Cycling Kingdom Wakayama: Route 4 - Kumano Sanzan Tour', description = 'Join Beki and Goro Kakei as they cycle through the UNESCO World Heritage site of Kumano. After gaining energy from the Nachi Falls, they will visit Kumano Hayatama Taisha and head towards Kumano Hongu Taisha. Experience the healing powers of Kawayu Onsen and Yunomine Onsen while cycling amidst the great outdoors!' where id = 'X9y1SJUxN_oBb3rNhihbm';
update content_bodies set title = '紀州浪漫 2021秋　「心浄める聖地の旅～高野山～」', description = '秋の高野山は特に美しい季節です。穴場的なフォトジェニックスポットであるケーブルカーを利用して、聖地「高野山」へ出かけてみませんか。' where id = 'xYx4g_TSRLDJxGiiayqNk';
update content_bodies set title = 'Kishu Romance Autumn 2021: A Journey to the Sacred Place that Purifies the Heart - Mount Koya', description = 'Autumn is a particularly beautiful season at Mount Koya. Why not take a trip to the sacred site of Mount Koya using the photogenic cable car, which is a hidden gem?' where id = 'gdNs7i_ErrtxS-7MAVSVB';
update content_bodies set title = 'サイクリング王国わかやま　WAKAYAMA800を走る　～紀の川サイクリングロードから夕陽を追って海へ～', description = '和歌山県のおすすめサイクリングロードを平野由香里さんがライドします。映える駅である隅田駅から紀の川サイクリングロードを西へ進み、桃の産地である紀の川市では人気の藤桃庵のジェラートで一休みします。その後、美しい夕陽を追いかけながら和歌浦方面へ快適にサイクリングを続けます。' where id = 'H6zWAmDIXC0I5i7QgOXYw';
update content_bodies set title = 'Cycling Kingdom Wakayama: Riding WAKAYAMA800 - Following the Sunset from the Kinokawa Cycling Road to the Sea', description = 'Yukari Hirano rides along recommended cycling routes in Wakayama Prefecture. Starting from the photogenic Sumida Station, she heads west on the Kinokawa Cycling Road. In Kinokawa City, known for its peaches, she takes a break to enjoy popular gelato from Fujimomokan. Continuing her ride, she comfortably cycles towards Wakayura, chasing the beautiful sunset.' where id = 'Rmdd0hhqTJWosaO6SAwgq';
update content_bodies set title = 'サイクリング王国わかやまWAKAYAMA800【ローディー編】', description = '和歌山県は「サイクリング王国わかやま」としてサイクリストを歓迎しています。ローディーや初心者など、あらゆるタイプのサイクリストが楽しめる無限のコースが用意されています。ぜひ、和歌山県でサイクリングを楽しんでください。' where id = 'srm_5LXZdoDVeFj3Co55_';
update content_bodies set title = 'Cycling Kingdom Wakayama WAKAYAMA800 - For Road Cyclists', description = 'Wakayama Prefecture welcomes cyclists as the ''Cycling Kingdom Wakayama.'' There are countless courses available for all types of cyclists, from roadies to beginners. Enjoy cycling in Wakayama Prefecture!' where id = 'rjjs-tLxe0U3uvp_MlzoU';
update content_bodies set title = '【熊野】Photographic Video Magazine -KUMANO- 2014', description = 'この映像は、毎年3月から5月の3ヶ月間立ち入りが禁止されている神域、熊野の美しさを捉えたものです。特別な許可を得て、11月の晩秋シーズンに撮影されました。色彩豊かな扇型の滝壺に降り注ぐ「二の滝」、そしてその奥に位置する「三の滝」では、太陽の光と水しぶきが見事に調和し、「奇跡の虹」を映像として捉えることに成功しました。' where id = 'W7NXDCIAtWK0irLvB01LH';
update content_bodies set title = 'KUMANO Photographic Video Magazine - 2014', description = 'This video captures the stunning beauty of Kumano, a sacred area that is completely off-limits from March to May each year. With special permission, the footage was taken during the late autumn season in November. It features the magnificent ''Ni no Taki'' waterfall, known for its vibrant colors, and further in the background, ''San no Taki'' waterfall, where the perfect harmony of sunlight and water spray creates a ''miraculous rainbow'' that was successfully captured on film.' where id = 'xS9UJBtlzQkcrC7yD3arn';
update content_bodies set title = 'ラベンダーフェスタかみふらの2023  ライティングアップ＆花火とネネ＆ワカ', description = '上富良野の新たな夏のイベント「ラベンダーフェスタかみふらの2023」が開催されます。ラベンダーが上富良野町の花として親しまれて42年を迎え、町民や全国、海外の人々に愛されてきたこの花を、今年も夜間に楽しむことができます。7月15日（土）には、上富良野産のホップや大麦を使用したビールを楽しむブースが1日限定で設置されます。幻想的なライティングで彩られたラベンダーの大パノラマを楽しむことができ、さらに、北海道を中心に活動する音楽ユニット「Nene＆Waka」によるスペシャルライブが特別にライブ配信されます。お楽しみに！' where id = '2m_dDfWeDgLrcAKNal4M4';
update content_bodies set title = 'Lavender Festa Kamifurano 2023: Lighting up & Fireworks with Nene & Waka', description = 'The ''Lavender Festa Kamifurano 2023'' is a new summer event that celebrates the lavender flower, which has been the symbol of Kamifurano for 42 years. This event allows both locals and visitors from across Japan and abroad to enjoy the beauty of lavender, even at night, for a limited time. On July 15th, a special booth will be set up for one day only, featuring beers made from locally sourced hops and barley. Attendees can experience a stunning panorama of lavender illuminated by enchanting lighting. Additionally, a special live performance by the music unit ''Nene & Waka,'' known for their activities in Hokkaido, will be streamed live. Don''t miss it!' where id = '2rG6f-do7-1MXJAdKc7z4';
update content_bodies set title = 'ラベンダーフェスタかみふらの2021 Special Omnibus Edjition', description = '2021年7月17日（土）にLive配信された日の出ラベンダー園のライトアップと花火大会の映像を再編集した「ラベンダーフェスタかみふらの2021 Special Omnibus Edjition」が登場します。迫力あるドローンからの花火映像を楽しむことができ、最後にはLive配信の総集編が配信されます。また、「らべとん」の新しいアニメーションも登場しますので、ぜひ最後までご覧ください。' where id = 'DF2KAVtvZskEcFq46cjYy';
update content_bodies set title = 'Lavender Festa Kamifurano 2021 Special Omnibus Edition', description = 'The ''Lavender Festa Kamifurano 2021 Special Omnibus Edition'' features a re-edited video of the live-streamed event held on July 17, 2021, showcasing the illuminated lavender fields and a fireworks display at Hinode Lavender Park. Viewers can enjoy stunning drone footage of the fireworks. The compilation concludes with a special segment, including a new animation featuring ''Rabeton.''' where id = '_MB3b8RTogbpHvpJtbXVe';
update content_bodies set title = 'ラベンダーフェスタかみふらの2021: ライトアップ＆花火と牧野由依', description = '上富良野町の日の出公園で、7月10日（土）から18日（日）まで「ラベンダーフェスタかみふらの」が開催され、夜のラベンダーを楽しむことができます。今年はラベンダーが町の花になって40年を迎え、日の出ラベンダー園がライトアップされます。町民や日本全国、海外からも愛されているラベンダーを夜間に楽しむことができます。7月17日（土）には、かみふらのPR大使の牧野由依さんによるミニライブと特別な花火がYouTubeでライブ配信されます。この日は無観客での配信となり、夕方以降は会場内に入場できませんので、自宅での視聴をお願いします。' where id = 'rRsxN3Om94QKAly_mVsPn';
update content_bodies set title = 'Lavender Festa Kamifurano 2021: Lighting up & Fireworks with Yui Makino', description = 'The Lavender Festa Kamifurano will be held at Hinode Park in Kamifurano from July 10 to 18, 2021, allowing visitors to enjoy the beauty of lavender at night. This year marks the 40th anniversary of lavender being recognized as the town''s flower, and for a limited time, the Hinode Lavender Garden will be illuminated. People from Kamifurano, across Japan, and even from abroad can enjoy the town''s beloved flower in the evening. A special event on July 17 will feature a mini live performance by Kamifurano PR ambassador Yui Makino and a special fireworks display, which will be streamed live on YouTube. Please note that the event on July 17 will be held without an audience, and entry to the venue, including parking, will not be allowed after the evening. Viewers are encouraged to watch from home.' where id = 'zlvlChmnwdusBX2EcwyTm';
update content_bodies set title = 'ラベンダーフェスタかみふらの2021 オープニングセレモニー', description = '2021年7月10日（土）から7月18日（日）まで、毎日19:00から21:00まで、ラベンダーの町である上富良野町の日の出ラベンダー園が無数の光で照らされます。特に7月17日には、かみふらのPR大使の牧野由依さんによるミニライブと特別な花火がYouTubeで開催されるスペシャルイベントがあります。上富良野町に来られない方も、ぜひオンラインで一緒に楽しんでください。チャンネル登録とリマインダーの設定をしていただけると嬉しいです。' where id = 'j0iVeedQHldEGFId1N80R';
update content_bodies set title = 'Lavender Festa Kamifurano 2021 Opening Ceremony', description = 'From July 10 to July 18, every day from 19:00 to 21:00, the Sunrise Lavender Park in Kamifurano, a town known for its lavender, will be illuminated by countless lights. On July 17, a special event featuring a mini live performance by Kamifurano PR ambassador Yui Makino and a spectacular fireworks display will be held on YouTube. We invite those who cannot visit Kamifurano to join us in enjoying the event online! We would appreciate it if you could subscribe to the channel and set a reminder.' where id = 'A3Jfsela0uS3Qc8vnMtC7';
update content_bodies set title = 'フラワーランドかみふらの花火オンライン2020', description = 'フラワーランドかみふらの花火オンライン2020は、絶景のパノラママウンテンビューと10万㎡の花畑で花火が打ち上げられるイベントです。新型コロナウイルスの影響を受け、世界の平和を願う「悪疫退散」「無病息災」「五穀豊穣」をテーマにしています。花火はドローンによる空撮でYouTubeでライブ配信され、花園に配置されたランタンも楽しめます。会場は立ち入り禁止で、自宅からの視聴を推奨しています。イベントは2020年8月29日19:30から予定されており、悪天候の場合は中止となる可能性があります。主催は一般社団法人かみふらの十勝岳観光協会です。' where id = 'J8t76LwNCipkKgUp7RiPy';
update content_bodies set title = 'FLOWERLAND KAMIFURANO FIREWORKS ONLINE 2020', description = 'The FLOWERLAND KAMIFURANO FIREWORKS ONLINE 2020 event features a stunning panorama of mountain views and a flower field of 100,000 square meters, where fireworks will be launched. Amid the global COVID-19 pandemic, the event aims to wish for world peace with themes of ''warding off epidemics,'' ''health,'' and ''abundant harvests.'' The fireworks will be broadcast live on YouTube from a unique drone perspective, showcasing the beautiful lanterns arranged in the flower garden. Attendees are advised that the venue will be closed to the public, including parking areas, and to enjoy the live stream from home. The event is scheduled for August 29, 2020, at 7:30 PM, and may be canceled due to bad weather. The event is organized by the Kamifurano Tokachidake Tourism Association.' where id = 'EciapQKfuZX7aGqoiKiWu';
update content_bodies set title = '北海道上富良野町深山峠（みやまとうげ）アートパーク', description = '北海道上富良野町深山峠アートパークの観覧車の映像です。観覧車に乗車して絶景をご覧ください！' where id = 'O_aRQPZeObhbQNnG4-RHU';
update content_bodies set title = 'Miyama Pass Art Park in Kamifurano, Hokkaido', description = 'This is a video of the Ferris wheel at Miyama Pass Art Park in Kamifurano, Hokkaido. Enjoy the breathtaking views from the Ferris wheel!' where id = '-Ei3vX2hD7rXn5wLaZkoz';
update content_bodies set title = '🎨黒板にお絵描き第2弾🎨 #北広島町', description = '今回の黒板に描いたのは、神楽の演目「恵比寿」です。恵比寿様は商売繁盛・豊漁の神で、釣りをする姿が描かれています。演目では、鯛を釣るために餅やお菓子を撒き、これを「福の種」として拾うと幸せが訪れると言われています。恵比寿様のにこやかな表情と軽やかな舞は、見る人の心を晴れやかにします。お祝いの席でよく舞われるこの演目を、春らしく桜とコラボさせ、鯛のウロコを桜に見立てたのがポイントです。次回の黒板絵のリクエストも募集中で、神楽や北広島町に関するものが好ましいです。観光案内所に訪れるお客様の心が和むような絵を描けたらと思っています。次回もお楽しみに！' where id = 'y_WS-RoZqWQAYO7RHN-Lj';
update content_bodies set title = 'Second Round of Blackboard Drawing 🎨 #Kitahiroshima Town', description = 'The second round of blackboard drawing features the auspicious Kagura performance ''Ebisu.'' Ebisu, also known as ''Ebisusama,'' is the god of prosperous business and abundant fishing, depicted fishing in this performance. During the act, rice cakes and sweets are scattered as bait for catching sea bream, which are considered ''seeds of fortune'' that bring happiness when picked up. The cheerful expression of Ebisu and his light dance are truly divine and uplifting. The performance is often seen at celebratory events. This time, the drawing combines the theme of spring with cherry blossoms and Ebisu, creatively using cherry blossom petals as scales for the sea bream. Requests for future drawings are welcome, especially those related to Kagura or Kitahiroshima Town. The aim is to create artwork that brings joy to visitors at the tourist information center. Stay tuned for the next drawing!' where id = 'T1d9AKvbCIUNn_xbCWQQi';
update content_bodies set title = 'なめらかプリンと軽やかなシフォンケーキ専門店「にわのにわとり」に観光協会職員が行ってきました', description = '観光協会職員が北広島町の「にわのにわとり」を訪れました。このお店は横山さんご夫婦が営む、なめらかプリンと軽やかなシフォンケーキの専門店です。店内に入ると甘い香りが広がり、並ぶプリンやシフォンケーキに心が躍ります。香料を使わず、卵の味がしっかり感じられるお菓子が特徴で、ネットプリン部門で1位を獲得した実績もあります。おすすめは「プリンマドンナ」で、ほろ苦いカラメルが絶品です。期間限定のいちごのミルクプリンや高カカオチョコレートの生チョコプリンも人気です。シフォンケーキはふわふわで、紅茶やショコラ、桜など多彩な種類があります。撮影中も和やかな雰囲気で、横山さんご夫婦の人柄が伝わります。自分へのご褒美や大切な人への贈り物にぴったりなお菓子です。' where id = 'wJ1gDTvUmh68t3j6T9TU_';
update content_bodies set title = 'Smooth Pudding and Light Chiffon Cake Specialty Store ''Niwa no Niwatori'' Visited by Tourism Association Staff', description = 'The tourism association staff visited ''Niwa no Niwatori'' in Kitahiroshima Town, a specialty store run by the Yokoyama couple, known for its smooth pudding and light chiffon cakes. Upon entering, the sweet aroma fills the air, and the sight of various puddings and chiffon cakes is delightful. The sweets are made without artificial flavors, allowing the taste of the eggs to shine through. The store has won first place in the online pudding category. The staff recommends the ''Pudding Madonna,'' a rich and smooth treat with a delightful bitter caramel. The strawberry milk pudding is a limited-time offering until May, and the high-cocoa chocolate pudding is also popular. The chiffon cakes are fluffy and come in various flavors, making them perfect for gifts. The atmosphere during filming was warm and cheerful, reflecting the couple''s friendly nature. These delightful sweets are perfect for treating yourself or gifting to loved ones.' where id = 'fq3wd8oAcHcUjtSspvqyp';
update content_bodies set title = '神秘的な「氷瀑ツアー」へ⛄⛄ #北広島町 #北広島市', description = '皆さんは雪山に登った事がありますか？？季節限定の氷瀑モニターツアーが、豊平の「りゅうずの森」で開催されました。真冬の龍頭山を登るのは2回目で、雪を踏みしめながら進みます。藏田さんが山の豆知識やクイズを出してくれ、飽きることなく登山を楽しめます。最初の見どころ「駒ヶ滝」では、凍った滝を見ることができ、次の「黒滝」では大きな氷柱が立っていました。雪山の美しさと静けさに包まれ、下山後はカフェで特製スパイスキーマカレーと手作りマーマレードティーを楽しみました。冬の龍頭山を満喫できる神秘的なツアーで、2月8日と11日にも開催予定です。興味のある方は「りゅうずの森」へDMをお願いします。' where id = 'CU4Q1tyZDpSTG87DckL7p';
update content_bodies set title = 'Mysterious ''Ice Waterfall Tour'' ⛄⛄ #KitaHiroshimaTown #KitaHiroshimaCity', description = 'Have you ever climbed a snowy mountain? This seasonal event features a mysterious ice waterfall monitoring tour organized by Mr. Kurata from the wild glamping and camping site ''Ryuzu no Mori'' in Toyohira. This was the second time climbing Mount Ryuzudake in mid-winter, stepping firmly on the snow. To keep the hike engaging, Mr. Kurata shared mountain trivia and quizzes. The first highlight was ''Koma Falls,'' where, if the timing is right, you can see a frozen waterfall. Although the weather was slightly warm that day, there were still icicles and frozen plants resembling jewels. The second highlight, ''Kuro Falls,'' featured icicles piercing the ground, matching the height of a staff member. The beauty of the sunlit snowy mountains was breathtaking, creating a serene and mystical atmosphere. After descending, the group enjoyed lunch at ''Caf''e de la Richesses 六,'' savoring Mr. Kurata''s special spice keema curry and homemade marmalade tea. This tour offered a unique experience of winter on Mount Ryuzudake, with additional tours scheduled for February 8 and 11. Interested participants should DM Ryuzu no Mori.' where id = 'YFuYrsUKbWt3QMQLMVCx3';
update content_bodies set title = '何を描いているでしょうか？', description = '黒板にお絵描きシリーズが復活しました！今回は北広島町の伝統芸能「神楽」の人気演目「悪狐伝」を描きました。美しい女人「玉藻前」は実は悪い狐の化身で、平安時代の物語では、様々な姿に変化しながら悪行を続け、名人の弓によって退治されます。和尚さんと悪狐が冬を楽しむ様子を描きました。描いているとお餅が食べたくなり、今夜食べる予定です。観光案内所に訪れるお客様の心がほぐれるような絵を描けたらと思っています。神楽や北広島町に関するリクエストも募集中です！' where id = '3ZgynJ4JxuV4Gi3SwE-cn';
update content_bodies set title = 'What Are We Drawing?', description = 'The drawing series on the blackboard is back due to popular demand! This time, we feature ''Akko-den,'' a popular performance of the traditional art of Kagura from Kitahiroshima Town. The story revolves around the beautiful woman Tamamo-no-Mae, who is actually a wicked fox in disguise. The tale, set in the Heian period, depicts the fox''s various transformations and misdeeds, ultimately leading to its defeat by a skilled archer. The drawing captures a cozy winter scene with a monk and the evil fox. As I was drawing, I felt a craving for rice cakes, which I plan to enjoy tonight. I hope to create artwork that warms the hearts of visitors at the tourist information center. Requests for drawings related to Kagura or Kitahiroshima Town are welcome!' where id = 'f4-8ov6N09CkNKDIwTDsp';
update content_bodies set title = '洗礼された宿でた特別な時間を過ごす', description = '大朝にある「hitaru石橋邸」は、築200年の古民家をリノベーションした宿で、刀鍛冶職人の邸宅です。高台に位置し、温かみのある光に包まれた空間が広がります。黒を基調としたシックなインテリアが特徴で、キッチンを中心に旬の食材を楽しむことができます。大きな丸いテーブルは、地元の酒造の酒樽の蓋をリメイクしたものです。焚き火やBBQを楽しむことができ、真っ暗な夜空には満天の星が広がります。2部屋のベッドルームがあり、最大12名まで宿泊可能です。広島市内から車で1時間の距離にあり、特別な人たちとの大切な時間を過ごすのに最適な場所です。' where id = 'Ob59PK0tNXq3lHhT69fNQ';
update content_bodies set title = 'Experience Special Moments at a Refined Traditional Inn', description = 'Located in Oasa, the ''Hitaru Ishibashi Residence'' is a renovated 200-year-old traditional house, originally the home of a swordsmith, now available for exclusive rental. The warm ambiance welcomes guests as they ascend to the property. The interior features a chic black-themed design centered around a kitchen, ideal for enjoying seasonal ingredients or gourmet meals prepared by selected chefs. A large round table, made from a repurposed sake barrel lid from a local brewery, enhances the dining experience. Guests can enjoy outdoor activities like bonfires and BBQs, with a stunning starry sky visible in the absence of city lights. The residence offers two bedrooms, accommodating up to 12 guests, making it a unique getaway just an hour''s drive from Hiroshima City. ''Hitaru Ishibashi Residence'' provides a luxurious experience of eating, sleeping, and soaking in nature, perfect for creating cherished memories with loved ones.' where id = 'OaLhAk-EeaQydJzxR5owe';
update content_bodies set title = 'ベーグル屋さんが作る宿！？✨リアンドベーグルさんプロデュースの宿へ観光協会職員がお邪魔してきました✨ #北広島町 #グルメ', description = '観光協会職員がリアンドベーグルさんがプロデュースした宿「FERMELL」を訪れました。人気のベーグルは自家製酵母を使い、3日間の低温長時間発酵で作られ、旨味が詰まっています。この宿は北広島町の自然や人々の温かさを伝えることを目的にしており、来年4月にオープン予定です。店内はおしゃれで、手作りの温かさが感じられます。特に注目は広々としたお風呂で、家族で一緒に入ることができます。宿には3つの寝室や発酵貯蔵庫など、魅力的な部屋がたくさんあります。リアンドベーグルは宿の完成に向けてクラウドファンディングを行っています。' where id = 'eq9NUEYbYGQrPHwSMcGFV';
update content_bodies set title = 'A Bagel Shop''s New Accommodation!?✨ A Visit to the FERMELL Inn Produced by Rian Bagel✨ #KitahiroshimaTown #Gourmet', description = 'The staff of the tourism association visited the FERMELL inn, produced by Rian Bagel. The bagels, known for their unique texture, are made using homemade yeast and undergo a three-day low-temperature fermentation process, resulting in a delicious flavor. This popular bagel shop has launched a new project to promote the beauty and warmth of Kitahiroshima Town. The inn, set to open in April next year, features a stylish interior designed by the Ikeda couple, who previously worked in apparel design. The space combines elegance with a cozy, handmade feel. A highlight of the inn is its bath, which offers a mystical atmosphere. The inn includes three bedrooms and a fermentation storage room, among other exciting features. Rian Bagel is currently seeking support through crowdfunding to complete the project, aiming to become a hub for the community.' where id = 'p3gUhTRCaauPtsdYKCgis';
update content_bodies set title = '北広島町で秋のサイクリングツアー🍂🍂', description = '「O.M.S大朝モビリティステーション」の秋のサイクリングツアーに観光協会職員が参加しました。このステーションは、サイクリストや観光客が集まる場所として、バス駅から生まれ変わりました。スポーツタイプの電動アシスト自転車（E-BIKE）を使ったツアーやレンタサイクルがあり、駐車場や自転車のメンテナンスも完備されています。ツアーでは加計山のヒルクライムを体験し、頂上からの眺めやシンプルな塩むすびを楽しみました。西教寺の銀杏やほとけばら遊園にも立ち寄り、地元の歴史や文化についての知識を得ることができました。ガイドの田川さんは、参加者一人一人に合わせたツアーを提供し、楽しいだけでなく学びの要素も盛り込んでいます。ぜひ田川さんに会いに来てください！' where id = '1MAuLbO_nCgJ9-LKTx99p';
update content_bodies set title = 'Autumn Cycling Tour in Kitahiroshima Town 🍂🍂', description = 'The tourism association staff visited the autumn cycling tour at the O.M.S. Oasa Mobility Station. This station, formerly a bus station, has become a gathering place for cyclists and tourists. It offers electric assist bicycles (E-BIKES) for tours and rental services, along with parking and maintenance for bikes. The tour includes a climb up Mt. Kake, where participants can enjoy refreshing views and simple yet delicious salt rice balls. The tour also features stops at Ginkgo trees at Saikyoji Temple and the Hokebara Amusement Park. Guided by Mr. Tagawa, who provides rich local knowledge and tailors the experience to each participant, the tour combines fun with educational elements about the area''s history and culture. The cycling experience is enjoyable and fatigue-free, thanks to Mr. Tagawa''s warm guidance. Visitors are encouraged to meet this local professional!' where id = '4FkDG4H4HZBWtaumFHLE6';
update content_bodies set title = '第75回 芸石神楽競演大会', description = '芸石神楽競演大会は、神楽を競う最古の歴史を持つ大会の一つで、多くの人々に愛されてきました。2023年10月7日、広島県の交流センター紫の里で開催され、圧巻の舞を会場で体験できます。プログラムには、様々な神楽団による新舞と旧舞の競演が含まれています。入場料は前売り券が3,500円、当日券が4,000円、カメラ席は5,000円です。会場内での飲食は禁止されており、ビデオ撮影も禁止です。詳細については、北広島町観光協会にお問い合わせください。' where id = '4yvN0i6dsHPNZgGqqdGca';
update content_bodies set title = '75th Geiseki Kagura Performance Competition', description = 'The Geiseki Kagura Performance Competition is one of the oldest and most beloved events that showcases Kagura performances. Experience breathtaking dances live at the venue. The event will take place on October 7, 2023, at the Murakami Center in Hiroshima Prefecture. The program includes various performances by different Kagura groups, featuring both new and traditional dances. Tickets are available for purchase, with advance tickets priced at 3,500 yen and day-of tickets at 4,000 yen. Special camera seats are available for 5,000 yen. Please note that food and drink are prohibited inside the venue, and video recording is not allowed. For inquiries, contact the Kitahiroshima Town Tourism Association.' where id = 'tuRFib3WmK1E_44800JYu';
update content_bodies set title = '北広島町「ほとけばら遊園」', description = 'ほとけばら遊園は、北広島町の寒曳山のふもとに位置する個人所有の庭園で、紅葉の隠れた名所として知られています。見頃は例年11月上旬頃です。また、名水も楽しめます。掲載されている写真は過去に撮影されたものであり、紅葉の見頃時期は例年に基づいています。紅葉の状況については、（一社）北広島町観光協会にお問い合わせください。電話番号は0826-72-6908（定休日：火曜日）です。詳細は「ぐるっと、きたひろしま」ウェブサイトをご覧ください。' where id = '0ElettSZhc_acYaSM0ux-';
update content_bodies set title = 'Hokuhiroshima Town ''Hotokebara Park''', description = 'Hotokebara Park is a privately owned garden located at the foot of Sanbaku Mountain in Hokuhiroshima Town, known for its hidden beauty during the autumn foliage season. The best time to visit is around early November. The park also features famous spring water. Please note that the photos included were taken in the past, and the peak foliage period is based on annual trends. For current foliage conditions, please contact the Hokuhiroshima Town Tourism Association at 0826-72-6908 (closed on Tuesdays). More information can be found at ''Gurutto, Kitahiroshima'' website.' where id = '3dk_rxmIdZYQp0Suksvj7';
update content_bodies set title = 'スノーフェスティバルでこどもたちと雪あそび', description = '2021年1月30日と31日に広島県北広島町のユートピアサイオトで開催された「スノーフェスティバル」では、参加したこどもたちと一緒に雪あそびを楽しみました。スノーモービルで登場した舞太郎くんが特別ゲストとして参加し、その後はソリや雪だるまづくりなどのアクティビティが行われました。このイベントは北広島町スキー場連絡協議会が主催し、BGMには月山翔雲の「おいでよ！キタひろ」が流れました。詳細は地元のスキー場や北広島町観光協会のウェブサイトで確認できます。' where id = 'LIHzj2MiHf8pL74p2NWnP';
update content_bodies set title = 'Snow Play with Children at the Snow Festival', description = 'On January 30 and 31, 2021, a Snow Festival was held at Utopia Saioto in Kitahiroshima Town, Hiroshima Prefecture, where children participated in snow play activities. The event featured a special appearance by Maitaro-kun on a snowmobile, followed by fun activities such as sledding and building snowmen. The festival was organized by the Kitahiroshima Ski Resort Liaison Council and included the background music ''Oideyo! Kita Hiro'' by Shoun Tsukiyama. For more information, visitors can check the websites of local ski resorts and the Kitahiroshima Town Tourism Association.' where id = '00BH7PBTh5y9bV40ZkThZ';
update content_bodies set title = '【北広島町】スノーフェスティバル2021～ユートピアサイオト～', description = '2021年1月30日と31日の2日間、ユートピアサイオトで「スノーフェスティバル」が開催されました。このイベントの様子を動画でお届けします。北広島町のイメージキャラクター「花田舞太郎」くんも子供たちと遊びながら観光PRに努めました。北広島町には、ユートピアサイオトのほかに、芸北高原大佐スキー場ややわたハイランド191リゾートの3つのスキー場があります。' where id = 'RUddte-SA3idbljD63PTH';
update content_bodies set title = 'Snow Festival 2021 at Kitahiroshima Town - Utopia Saioto', description = 'The Snow Festival was held at Utopia Saioto on January 30th and 31st, 2021. This summary includes a video showcasing the event. The town''s mascot, Maitaro Hanada, engaged with children and promoted tourism during the festival. Kitahiroshima Town features three ski resorts, including Utopia Saioto, Geihoku Kogen Osa Ski Resort, andYawata Highland 191 Resort.' where id = 'fahQRx4rJnNkq7vHptytC';
update content_bodies set title = 'もうたろうくんがスキー場で雪遊び【北広島町】', description = '広島県山県郡北広島町は、意外にも積雪が多い町で、時には2メートルに達することもあります。町内には3つのスキー場があり、12月19日には町のイメージキャラクター「花田舞太郎」くんがユートピアサイオトに遊びに行きました。営業状況や積雪情報は各スキー場の公式サイトで確認できます。' where id = 'ieiljXqSrzS2oV3ujJx56';
update content_bodies set title = 'Snow Fun at Ski Resort with Moutarou-kun in Kitahiroshima Town', description = 'Kitahiroshima Town, located in Hiroshima Prefecture, is surprisingly known for its heavy snowfall, sometimes reaching up to 2 meters. The town features three ski resorts. On December 19, the town''s mascot, Moutarou-kun, visited the Utopia Saioto ski resort to enjoy the snow activities. For the latest information on operating status and snowfall, please check the respective websites of the ski resorts.' where id = 'gtZ6WUqc7UP43hu-Y61d1';
update content_bodies set title = '安の花田植保存会さんのイベントに招待されました。', description = '10月11日(日)に、イオンモール広島祇園2Fで『安の花田植』と『壬生の花田植』のPRイベントが開催されました。現在、10月3日から22日まで、花田植の魅力を伝える写真展も行われています。このイベントは安の花田植保存会が主催し、安の花田植と北広島町の深い関係を紹介しました。北広島町のイメージキャラクター、花田舞太郎が登場し、子どもたちがテーマソング「おいでよ！キタひろ」に合わせて踊り、観客を魅了しました。今年は花田植の披露はできませんでしたが、来年に向けてしっかりとPRができました。来年、青空の下でお会いしましょう！' where id = 'iJOYX3jUJuDAnS5sTZzjj';
update content_bodies set title = 'Invitation to the Event by the An''s Hanada-ue Preservation Society', description = 'On October 11th, a PR event for ''An''s Hanada-ue'' and ''Mibu''s Hanada-ue'' was held at the 2nd floor of Aeon Mall Hiroshima Gion. A photo exhibition showcasing the beauty of Hanada-ue is ongoing from October 3rd to 22nd. The event, hosted by the An''s Hanada-ue Preservation Society, highlighted the deep connection between An''s Hanada-ue and Kitahiroshima Town. The town''s mascot, Hanada Muitaro, made an appearance, and children danced to the theme song ''Oideyo! Kita Hiro'' in adorable costumes, impressing the audience with their nearly perfect performance. Although the Hanada-ue could not be showcased this year, effective PR for both ''An''s Hanada-ue'' and ''Mibu''s Hanada-ue'' was achieved, setting the stage for next year''s event. Looking forward to meeting everyone under the blue sky next year!' where id = 'dHAkPhnKFd3HCBC28-w9O';
update content_bodies set title = '【北広島町】大朝のテングシデ群落ドローン撮影（2020.5.11）', description = '『大朝のテングシデ群落』は、国の天然記念物に指定されている場所で、約100本の曲がりくねったイヌシデの変種が群生しています。テングの伝説に由来して名付けられ、地域の人々に大切にされています。この景色は北広島町だけで見られる貴重なもので、5月11日にドローンで撮影された新緑の美しい映像をぜひご覧ください。' where id = '4gc-808NPSSh9g_WobvqS';
update content_bodies set title = 'Drone Footage of the Tengu Shide Grove in Kitahiroshima Town (May 11, 2020)', description = 'The Tengu Shide Grove, a national natural monument, features around 100 twisted and gnarled trees of the unique Inushide variety. Named after the local legend of Tengu, these trees are cherished by the community. This grove is unique to Kitahiroshima Town, making it a rare sight in the world. On May 11, stunning drone footage was captured, showcasing the beautiful fresh greenery of this precious landscape. Be sure to check out the video!' where id = 'OnhSE8MGMwSRUdZ3OP6Dh';
update content_bodies set title = '朝日と鶴　出水市', description = '鹿児島県出水市の冬の日常では、朝日が昇ると万羽の鶴が一斉に飛び立ちます。真っ赤に染まった空を埋め尽くすツルの姿は、見る人すべてを魅了し、息をのむ美しさです。この絶景は、ぜひあなたにも体験していただきたい出水の魅力の一つです。' where id = 'G_tzasm1upRndExAlFK9Z';
update content_bodies set title = 'Sunrise and the crane (Japan Izumi)', description = 'In Izumi City, Kagoshima, winter mornings are marked by the breathtaking sight of thousands of cranes taking flight at sunrise. As the sun rises, the sky is painted a brilliant red, filled with these magnificent birds. This stunning spectacle leaves all who witness it in awe. It is a must-see view in Izumi that you should experience.' where id = '-BI6wjUc7pegaZJ9qlWJa';
update content_bodies set title = '出水でデート / 出水市観光PR動画', description = 'この動画は、出水市を観光しながらゆったりとしたデートを楽しむ様子を紹介しています。デートの計画に役立つ参考になるでしょう。鹿児島大学のアクティブ・ゼミを受講している学生たちが出水市を訪れ、インバウンド調査を行い、「デート」をテーマにした動画を制作しました。出水の観光名所として、武家屋敷や着物体験、出水麓歴史館、箱崎八幡神社、諏訪神社、東光山公園などが紹介されています。この動画は出水市の観光を促進し、訪れる人々にそのユニークな魅力を楽しんでもらうことを目的としています。' where id = 'n_BoflexUcbMpc_KladMt';
update content_bodies set title = 'Follow me to Izumi! Date ideas / 出水でデート / 出水市観光PR動画', description = 'This video showcases a leisurely date experience while exploring Izumi City. It serves as a great reference for planning dates. Students from Kagoshima University enrolled in the Active Zemi course visited Izumi City to conduct inbound research and created a video themed around dating. The video highlights various attractions in Izumi, including the Samurai Residence, kimono experiences, and local historical sites. Key locations featured are the Izumi Fumoto History Museum, Hakozaki Hachiman Shrine, Suwa Shrine, Tokozan Park, and more. The video aims to promote tourism in Izumi City and encourage visitors to enjoy its unique offerings.' where id = 'qY9S_gOBNpl3cHSQju_pJ';
update content_bodies set title = '観光満喫＆ショートステイ! / 一日出水', description = 'この動画は、鹿児島大学の学生たちが出水市で過ごした一日を紹介しています。アクティブ・ゼミに参加している学生たちは、「暇だね」と話し合い、出水市を訪れることに決めました。彼らは、箱崎八幡神社や武家屋敷、温泉センターもみじなどの観光名所を巡り、いずみ親子ステーキごはんなどの地元料理を楽しみます。また、農家民泊体験を通じて地域の文化に触れます。この動画は、出水市の魅力を伝え、観光地としての重要性を強調しています。' where id = '_hRoEc0ATlN7xYbRffEpM';
update content_bodies set title = 'One day in Izumi / Enjoying Tourism & Short Stay!', description = 'This video showcases a day in Izumi City, where a group of students from Kagoshima University, enrolled in the Active Zemi course, embark on an inbound tourism survey. The students express their boredom and decide to explore Izumi City. Throughout the day, they visit various attractions, including the Hakozaki Hachiman Shrine, Samurai Residences, and the Onsen Center MOMIJI. They also experience local cuisine, such as the Izumi oyako steak meal, and engage in activities like farm stays. The video captures their journey and highlights the beauty and cultural significance of Izumi City, promoting it as a tourist destination.' where id = 'jIuIytJq6CrTAJxJrjUsb';
update content_bodies set title = '鹿児島県出水市農家民泊PR　VIDEO', description = '鹿児島県出水市の農家民泊を紹介するイメージビデオです。農家との触れ合いや農業体験、武家屋敷での着物着付け体験、観光牛車など、出水市の魅力が詰まった内容となっています。地域の文化や伝統に触れながら、訪れる人々に特別な体験を提供することを目的としています。' where id = 'nsR2C5ioN_8ezmrCeVV1f';
update content_bodies set title = 'Kagoshima Prefecture Izumi City Farm Stay PR Video', description = 'This is an image video promoting farm stays in Izumi City, Kagoshima Prefecture. It showcases the charm of Izumi, featuring interactions with local farmers, agricultural experiences, kimono dressing experiences in samurai residences, and sightseeing by ox cart.' where id = 'PAUVmOcytKN-gZvRVW7pJ';
update content_bodies set title = '【利尻島２分ver】大自然を旅する１年間 〜小さな島の大きな世界がここにある〜', description = '日本最北の利尻島には、中心に雄大な利尻山がそびえ、氷河期から生き延びた美しい花や植物が点在しています。暖流と寒流が交わる豊かな海では、山からの湧水も流れ、豊富な海産物が獲れます。山と海に生きる人々の文化も色濃く、訪れる人々は多様なアクティビティを通じて島の自然を体感できます。この動画では、利尻島の大自然を旅する1年間を2分30秒に凝縮してお届けします。' where id = 'nLxpLNaFPqpqtBMLFFixy';
update content_bodies set title = 'A Year Traveling Through the Great Nature of Rishiri Island in 2 Minutes', description = 'Rishiri Island, located at Japan''s northernmost point, features the majestic Mt. Rishiri at its center. The island is home to a variety of beautiful flowers and plants that have thrived since the Ice Age. Its rich seas, nourished by both warm and cold currents along with mountain spring water, provide abundant seafood. The culture of the people who have lived in harmony with the mountains and the sea is vibrant. Visitors can engage in various activities to experience the island''s natural beauty. This video condenses a year of exploring Rishiri Island''s great nature into just 2 minutes and 30 seconds.' where id = 'K03c9OIJPf8nv1rrUCVjb';
update content_bodies set title = '利尻島 「海」', description = '現在作成中の利尻島PR動画の一部を事前公開します。この動画では、利尻島の美しさや魅力、特に海との関わりを紹介しています。利尻島の観光情報やガイドページへのリンクも提供されています。' where id = 'zhUrRW-RfoUa0rm4nGiVD';
update content_bodies set title = 'Sea of Rishiri Island', description = 'This is a preview of a promotional video currently being created for Rishiri Island. The video highlights the beauty and attractions of the island, particularly its connection to the sea.' where id = 'xvzmNSTYliKwigyP_6Ouz';
update content_bodies set title = '利尻島 「夏へ」', description = '現在作成中の利尻島PR動画の春のシーンを一部事前公開します。この動画は、利尻島の美しさや魅力を夏に向けて紹介することを目的としています。' where id = '05BN1w_spCTIFqu5n-4cs';
update content_bodies set title = 'To Summer Rishiri Island', description = 'A preview of the spring scenes from the PR video currently being created for Rishiri Island is being released. The video aims to promote the beauty and attractions of Rishiri Island as it transitions into summer.' where id = '0mAt3hh304sChP122HgFd';
update content_bodies set title = '利尻島ガイド事業者紹介', description = '利尻アクティビティは、利尻島を拠点としたガイドサービスです。ガイドは室田雄飛氏、杉本貴亮氏、古川真志氏の3名が担当しています。予約は公式ウェブサイト（http://rishiri-activity.com/）から行えます。' where id = 'dB4TcRBBqvbCJ9hJgnJuH';
update content_bodies set title = 'RISHIRI ACTIVITY - Guide Service Introduction', description = 'RISHIRI ACTIVITY is a guide service based on Rishiri Island, featuring guides Yuhi Murota, Takaaki Sugimoto, and Masashi Furukawa. For reservations, visit their website at http://rishiri-activity.com/' where id = 'PetHWCj4cMipUxEhekZ2M';
