update content_bodies set title = '利尻町ウニ種苗生産センター', description = '利尻町ウニ種苗生産センターは、北海道利尻島に位置し、利尻島のウニの魅力を広めることを目的としています。利尻島の観光情報は「りしぷら」で確認でき、詳細は https://www.rishiri-plus.jp/ を訪れてください。また、ウニに関する特設サイト「ウニっこ図鑑」もあり、こちらは https://www.rishiri-plus.jp/unikko/ でご覧いただけます。' where id = 'IaS0rk5WW03Xf0YTvAzpD';
update content_bodies set title = 'RISHIRI Uni (Sea urchin) seed production center', description = 'The Rishiri Uni seed production center is located on Rishiri Island in Hokkaido, Japan. It aims to promote the appeal of sea urchins from Rishiri Island. For more information on tourism in Rishiri Island, please visit ''Rishipura'' at https://www.rishiri-plus.jp/. Additionally, there is a special site for the ''Uni-kko'' encyclopedia at https://www.rishiri-plus.jp/unikko/.' where id = 'AeM42so5xM3U-k7qEj_dq';
update content_bodies set title = '利尻島 神居海岸パーク うに漁体験', description = 'この文章は、北海道利尻島の観光情報を提供しています。利尻島の観光に関する詳細は「りしぷら」をご覧ください。ウェブサイトは https://www.rishiri-plus.jp/ です。' where id = 'Y7jcWk-h9AE6XIFDO62tP';
update content_bodies set title = 'Rishiri Island Kamei Coast Park Sea Urchin Fishing Experience', description = 'This text provides tourism information about Rishiri Island in Hokkaido, Japan. For more details about sightseeing on Rishiri Island, please visit ''Rishiri Plus'' at https://www.rishiri-plus.jp/.' where id = 'SZtax26psdcRag3TApgcH';
update content_bodies set title = '利尻島の観光情報', description = 'この文章では、北海道利尻島の観光情報を紹介しています。利尻島の詳細な観光情報は「りしぷら」で確認できます。ウェブサイトは https://www.rishiri-plus.jp/ です。' where id = 'REHyA2N1MWFn63RQ4Vwl9';
update content_bodies set title = 'Rishiri Island Tourism - Seaweed Craft Experience', description = 'This text provides tourism information about Rishiri Island in Hokkaido, Japan. For more details, please visit ''りしぷら'' (Rishiri Plus) at https://www.rishiri-plus.jp/.' where id = '3A0q79w6fufC8rRoH-qCq';
update content_bodies set title = '利尻島観光情報', description = 'この文章では、北海道利尻島の観光情報を紹介しています。詳細については「りしぷら」をご覧ください。ウェブサイトのURLは https://www.rishiri-plus.jp/ です。' where id = 'VH2vy_YBNxdivIaFcDqr1';
update content_bodies set title = 'Rishiri Island Tourism Information', description = 'This text provides tourism information about Rishiri Island, located in Hokkaido, Japan. For more details, please visit ''りしぷら'' (Rishiri Plus) at https://www.rishiri-plus.jp/.' where id = 'm7K_NNd0JVurdkGb2zAyo';
update content_bodies set title = '利尻島 神居海岸パーク お土産昆布づくり', description = 'この文章は、北海道利尻島の観光情報を提供しています。利尻島の観光に関する詳細は、リンク先の「りしぷら」をご覧ください。' where id = 'mxh-K6fqs9y6XsqCgnvmU';
update content_bodies set title = 'Rishiri Island: Kamui Coast Park and Souvenir Kombu Making', description = 'This text provides tourism information about Rishiri Island, located in Hokkaido, Japan. For more details on sightseeing in Rishiri Island, please visit ''Rishipura'' at the provided link.' where id = 'hDgBL7Yo0YaqtRHySMxPH';
update content_bodies set title = '利尻島の観光情報', description = 'この文章は、北海道利尻島の観光情報を提供しています。利尻島の名物である湧き水を含む観光名所についての詳細は、ウェブサイト「りしぷら」をご覧ください。URLは https://www.rishiri-plus.jp/ です。' where id = 'V3KcBzj9qvzGGonD278BE';
update content_bodies set title = 'Rishiri Island Tourism', description = 'This text provides tourism information about Rishiri Island, located in Hokkaido, Japan. For more details on the island''s attractions, including its famous spring water, please visit the website ''りしぷら'' at https://www.rishiri-plus.jp/.' where id = 'nuO-1pQGISaBlJAh6qFA0';
update content_bodies set title = 'グレ（メジナ）の調理', description = '一本釣りで獲ったグレの調理方法についてです。活きたグレを締めた際の鮮度は、街では味わえないものです。多くの人が、グレがこんなに美味しい魚だったとは驚くことでしょう。加太観光協会青年部長の稲野雅則氏（活き魚料理いなさ）の技をぜひご覧ください。' where id = 'ccJMPoiu2_eZS7JpIuJvH';
update content_bodies set title = 'Cooking Gure (Mejina)', description = 'This is a cooking method for Gure caught by single-line fishing. The freshness of the Gure, which is killed right after being caught, cannot be experienced in the city. Many people are surprised to discover how delicious Gure can be. Please take a look at the skill of Masanori Inano, the head of the Kada Tourism Association Youth Division, at the live fish restaurant Inasa.' where id = 'vNoBLyrEhicQXZjvEPqDT';
update content_bodies set title = '一本釣りアジの調理', description = '紀淡海峡の速い潮で育った天然一本釣りのアジです。網で獲ったアジとはまったく別物の味で、直前まで活きていた鮮度バツグンの逸品です。加太観光協会青年部長の稲野雅則氏（活き魚料理いなさ）の美技をごらんください。' where id = 'KZrfwPIemzTAvkTrSacS2';
update content_bodies set title = 'Cooking Wild-Caught Horse Mackerel', description = 'This is a wild-caught horse mackerel, raised in the fast currents of the Kitan Strait. It offers a completely different taste compared to those caught with nets! This exceptional fish is incredibly fresh, having been alive just before preparation. Watch the impressive skills of Masanori Inano, the head of the Kadakanko Association Youth Division, at the Ikigai Restaurant Inasa.' where id = 'RjKaSmeXiv-OnBsN4r56n';
update content_bodies set title = '乗船注意ビデオ', description = '本物の一本釣り漁船に乗る体験ができます。海は相手ですので、乗船前にこのビデオで少し学んでいただきます。出演は虹色ポッケさんです。観光船ではなく、男の戦場であり、お客様用の座席もありませんが、貴重な体験が得られます。加太観光協会では、定期的に漁船乗船や一本釣り体験ツアーを開催していますので、お問い合わせください。' where id = 'vasG29jBIibPsOfegL2HI';
update content_bodies set title = 'Boarding Safety Video', description = 'Experience a real longline fishing boat! Before boarding, take a moment to learn from this video, as the sea can be unpredictable. The video features Nijiiro Pokke. This is not a sightseeing boat; it''s a man''s battlefield with no seats for customers. However, it offers a rare and valuable experience. The Kada Tourism Association regularly organizes fishing boat boarding and longline fishing experience tours, so please feel free to inquire.' where id = 'khSdQApCOL6wrnHrvdL9I';
update content_bodies set title = '【兵庫県】日本遺産　西国巡礼二十五番札所　播州清水寺【加東市】', description = '播州清水寺は兵庫県加東市の御嶽山の山頂に位置し、地蔵信仰の聖地として知られています。『今昔物語集』にも登場するこの寺は、西国三十三所巡礼の第25番札所であり、多くの巡礼者が訪れます。特に、4月から11月のシーズンには、花や新緑、紅葉の美しさを楽しむために多くの観光客が訪れます。' where id = '8viq1dQ2VOP8s1JjdSha6';
update content_bodies set title = 'Banshu Shimizu Temple: 25th Sacred Site of the Saigoku Pilgrimage in Hyogo Prefecture', description = 'Banshu Shimizu Temple is located at the summit of Mount Ontake in Kato City, Hyogo Prefecture, and is known as a sacred site for Jizo faith, mentioned in the ''Konjaku Monogatari'' collection. It is the 25th sacred site of the Saigoku 33 Pilgrimage, attracting many pilgrims to its main hall. The temple is particularly popular for sightseeing from April to November, when visitors can enjoy the beauty of flowers, fresh greenery, and autumn leaves.' where id = 'yXo6xh1aGcRC6vgytsbAN';
update content_bodies set title = 'はいむるぶし 2015夏', description = '「はいむるぶし」は、八重山諸島の小浜島に位置するユニークなリゾートです。沖縄本島から400km南にあり、国内最大のサンゴ礁と西表石垣国立公園に囲まれています。このリゾートは、南十字星という名にちなんでおり、沖縄の自然の美しさとのつながりを強調しています。ここでの休日は、特別な体験を提供します。' where id = 'omb5IKFfKHys-coL2Q-aU';
update content_bodies set title = 'Haimurubushi Summer 2015', description = 'Haimurubushi is a unique resort located on Kohama Island in the Yaeyama Islands, 400 km south of Okinawa''s main island. It is surrounded by Japan''s largest coral reefs and the Iriomote-Ishigaki National Park, offering an ideal island vacation experience. The resort is named after the Southern Cross, emphasizing its distinctiveness and connection to the natural beauty of Okinawa.' where id = 'dWiOpGLeeiOK7Ab7Z6JDb';
update content_bodies set title = '10加美恋〜僕と私の冬のデートプラン〜', description = 'この動画は、加美町で生まれ育ち仙台に移り住んだカップルが地元の加美町でデートをする様子を描いたストーリー仕立ての内容です。冬ならではのやくらいの美しい景観やアクティビティを楽しむことができ、視聴者が加美町に興味を持ってくれることを願っています。' where id = 'KSKPimTB4xM1rFsRvZcN1';
update content_bodies set title = '10 Kami Koi - My Winter Date Plan', description = 'This video features a couple who grew up in Kami Town and moved to Sendai, showcasing their date in their hometown. It presents a story-like format that highlights the unique winter scenery and activities in Yakurai. The creators hope that viewers will develop an interest in Kami Town after enjoying the video.' where id = '5u16VGxpU0l2stKcQhV51';
update content_bodies set title = '第56回全国ごてんまりコンクール受賞作品紹介', description = '全国の愛好家から集まった珠玉の作品が展示される「全国ごてんまりコンクール」の入賞作品15点を紹介します。ぜひ会場でご覧ください。開催日は2025年10月11日（土）・12日（日）で、各日9時から16時まで、会場は鶴舞会館（由利本荘市瓦谷地１）です。出品者数は86名、出品点数は140点です。全国ごてんまりコンクールの詳細は、こちらのリンクをご覧ください→https://yurihonjo-kanko.jp/special/mari/' where id = 'BAnXXhbn5iTreWRPP5fX3';
update content_bodies set title = 'Introduction of Award-Winning Works from the 56th National Gotemari Competition', description = 'We present 15 award-winning works from the ''National Gotemari Competition,'' which gathers exquisite pieces from enthusiasts across the country. We invite you to see them at the venue. The event will be held on October 11th and 12th, 2025, from 9 AM to 4 PM each day at Tsuruma Hall (1 Kawatani, Yurihonjo City). There will be 86 exhibitors showcasing a total of 140 pieces. For more details about the National Gotemari Competition, visit: https://yurihonjo-kanko.jp/special/mari/' where id = 'GYlbc1zJN3xU4I0MO7dB5';
update content_bodies set title = '第55回全国ごてんまりコンクール受賞作品紹介', description = '全国の愛好家から集まった珠玉の作品を紹介する「全国ごてんまりコンクール」の入賞作品15点をお届けします。ぜひ会場でご覧ください。開催日は2024年10月26日（土）・27日（日）で、各日9時から16時まで、鶴舞会館（由利本荘市瓦谷地１）で行われます。出品者数は106名、出品点数は164点です。全国ごてんまりコンクールの詳細は、こちらをご覧ください→https://yurihonjo-kanko.jp/special/mari/' where id = 'RiiXFndxtIeOq2HMbsyjL';
update content_bodies set title = 'Introduction of Award-Winning Works from the 55th National Gotemari Competition', description = 'We present 15 award-winning works from the ''National Gotemari Competition,'' which gathers exquisite pieces from enthusiasts across the country. We invite you to view them at the venue. The event will be held on October 26th and 27th, 2024, from 9 AM to 4 PM each day at Tsuruma Hall (1 Kawatani, Yurihonjo City). A total of 106 participants will showcase 164 pieces. For more details about the National Gotemari Competition, visit: https://yurihonjo-kanko.jp/special/mari/' where id = 'XbQ-da9wulkTSSlMuFXLR';
update content_bodies set title = '鳥海高原雪まつり2024オープニング動画【ポニーランド花立】', description = '2024年1月28日から2月28日まで、鳥海高原雪まつりが開催されます。ポニーランド花立では、雪のブロックを積み重ねて作るイグルーの制作や、サウナテント、スノーモービルなど、さまざまなアクティビティを体験できます。さらに、今回はドッグランも完備されており、愛犬を連れて雪原で遊ぶことができます！' where id = 'hZcvsTf4mgY1137BVm5tW';
update content_bodies set title = 'Chokai Kogen Snow Festival 2024 Opening Video at Pony Land Hanatate', description = 'The Chokai Kogen Snow Festival will be held from January 28 to February 28, 2024. At Pony Land Hanatate, visitors can enjoy a variety of activities, including building igloos with snow blocks, using sauna tents, and riding snowmobiles. This year, a dog run is also available, allowing visitors to bring their dogs to play in the snowy fields!' where id = '-ZtxmsWYM_6j4MY9LKuxy';
update content_bodies set title = '観光PV: 笑顔あふれる街、由利本荘市', description = '由利本荘市の観光PR動画です。市民の「笑顔」をキーワードに、鳥海山木のおもちゃ館やハーブワールドAKITAなどの人気観光スポットを紹介しています。' where id = 'xP6Nfi4ZjP2npD1-cmGKB';
update content_bodies set title = 'Tourism Promotion Video: A City Full of Smiles, Yurihonjo', description = 'This is a tourism PR video for Yurihonjo City. It highlights the keyword ''smiles'' from the citizens and introduces popular tourist spots such as the Chokai Mountain Wooden Toy Museum and Herb World AKITA.' where id = 'Zu-fVhVxktGfnWKsPQ0ZY';
update content_bodies set title = '由利本荘市観光ＰＲ動画パート2（由利鉄編）', description = '秋田県由利本荘市の観光PR動画です。今回は市内を走るローカル線、由利高原鉄道を紹介します。' where id = 'lhrvMwqCdQBNMpCkZrkd7';
update content_bodies set title = 'Yurihonjo City Tourism PR Video Part 2 (Yuri Kogen Railway)', description = 'This is a tourism PR video for Yurihonjo City in Akita Prefecture. This time, we introduce the local train, Yuri Kogen Railway, which runs through the city.' where id = 'hSjgZTwWLllsGgxQs69KV';
update content_bodies set title = 'GEO MIRACLE KOBE～ハイライト～', description = 'この動画はGEO MIRACLE KOBEのハイライトについて紹介しています。具体的な内容は明示されていませんが、GEO MIRACLE KOBEの魅力や特徴を視覚的に楽しむことができる内容となっていると考えられます。' where id = 'CKkOmFjJtf3D7S7Vj1Jp7';
update content_bodies set title = 'GEO MIRACLE KOBE Highlights', description = 'This video introduces the highlights of GEO MIRACLE KOBE.' where id = 'a5ju5l1WtfaEq4yJ8nZkE';
update content_bodies set title = 'KUISs×KOBE TOURISM BUREAU', description = '関西国際大学の学生が「神戸の食」をテーマに撮影を行い、動画の編集まで自ら手掛けました。神戸は食の魅力にあふれた街であり、神戸牛や流行のレトロ喫茶、定番のお土産として人気のチーズケーキ店など、多彩な内容が盛り込まれています。このプロジェクトは神戸の多様な食文化を紹介しており、ぜひチェックしてみてください！' where id = 'GfC9EU6QagqJFHSjpdr-T';
update content_bodies set title = 'KUISs×KOBE TOURISM BUREAU', description = 'Students from Kansai University of International Studies conducted a project focusing on ''Kobe''s food''. They were involved in all aspects of production, from filming to video editing. Kobe is a city rich in culinary attractions, featuring iconic Kobe beef, trendy retro cafes, and popular cheesecake shops that have become staple souvenirs. This project showcases the diverse food culture of Kobe and is a must-see!' where id = 'IcPkZudC_jKC2Cf0G_6m8';
update content_bodies set title = '神戸でLOVEを見つけよう', description = 'このプロジェクトは、日本の神戸にあるさまざまな観光名所を紹介しています。神戸メリケンパークオリエンタルホテル、神戸布引ハーブ園／ロープウェイ、兵庫県立美術館が含まれています。また、神戸ポートピアホテルの屋上テラス「ソラフネ神戸」も特集されています。これらの場所への特別な感謝が述べられています。キャストには、YouTubeクリエイターの蔡祥さんとYujiさんが含まれ、彼らのチャンネルやFacebookページを通じて神戸での体験を共有しています。' where id = '6C_QEwLrptyujILB8--v4';
update content_bodies set title = 'Find the LOVE in KOBE', description = 'This project highlights various attractions in Kobe, Japan, including the Kobe Meriken Park Oriental Hotel, Kobe Nunobiki Herb Gardens & Ropeway, and the Hyogo Prefectural Museum of Art. The KOBE PORTOPIA HOTEL SORA FUNE KOBE is also featured, showcasing its rooftop terrace. Special thanks are given to these locations for their contributions. The cast includes YouTube creators 蔡祥 and Yuji, who share their experiences in Kobe through their channels and Facebook pages.' where id = 'aANSs1DBtpbYBU_sSdROB';
update content_bodies set title = 'チルってる神戸～後編～', description = 'この文章では、神戸にあるおしゃれでリラックスできる「チル」なスポットを紹介しています。取り上げられている場所には、王子動物園、南京町、カフェラ大丸神戸店、六甲ケーブル、YUNYUN、神戸どうぶつ王国、ココシカ、布引の滝、有馬川親水広場、五色塚古墳、HATなぎさの湯、三ツ森まんじゅう店、能福寺、淡路屋、メリケンパークが含まれています。神戸についてもっと知りたい方は、公式観光サイト「FeelKOBE」を訪れてみてください。' where id = 'DpV2JHttt-atpyzegCDf4';
update content_bodies set title = 'Chilling in Kobe - Part 2', description = 'This article introduces stylish and relaxing ''chill'' spots in Kobe. Featured locations include the Oji Zoo, Nankinmachi (Chinatown), Cafe La Daimaru Kobe, Rokko Cable, YUNYUN, Kobe Animal Kingdom, Cocoshika, Nunobiki Falls, Arima River Riverside Park, Goshikizuka Kofun, HAT Nagisa no Yu, Mitsumori Manju Shop, Nofukuji Temple, Awajiya, and Meriken Park. For those wanting to learn more about Kobe, visit the official tourism site ''FeelKOBE''.' where id = 'nM9K7TZOX1MIMxrAscDG2';
update content_bodies set title = 'チルってる神戸～前編～', description = 'この記事では、神戸にあるおしゃれでリラックスできる「チル」なスポットを紹介しています。メリケンパークやfeel dining cafe & sea、閉店したプラネタリウムほしぞらカフェ＆BARなど、さまざまな場所が取り上げられています。他にも南京町、サ・マーシュ、相楽園、はなとね、HATなぎさの湯、カフェラ大丸神戸店、アジュール舞子、グラニットカフェ、ポートアイランド北公園などが紹介されています。神戸についてもっと知りたい方には、公式観光サイト「FeelKOBE」をおすすめします。' where id = 'EzbHHsOmYnnsPlZRV36Ml';
update content_bodies set title = 'Chilling in Kobe - Part 1', description = 'This article introduces stylish and relaxing ''chill'' spots in Kobe. It highlights various locations such as Meriken Park, feel dining cafe & sea, and the now-closed Planetarium Hoshizora Cafe & BAR. Other featured places include Nankinmachi, Sa-Marche, Sorakuen, Hanatone, HAT Nagisa no Yu, Cafe La Daimaru Kobe, Azure Maiko, Granite Cafe, and Port Island North Park. For those wanting to learn more about Kobe, the official tourism site ''FeelKOBE'' is recommended.' where id = 'kNfCYzg7VyjFvjfu_lVe6';
update content_bodies set title = '神戸観光プロモーション動画～春夏編～', description = 'この動画では、神戸の春夏の観光スポットを紹介しています。ポートアイランド北公園、旧居留地、乙仲通り、ヴィーナスブリッジ、生田神社、白鶴酒造資料館、六甲山、有馬など、さまざまなスポットが登場します。これらの場所の美しさや特徴、訪れる人々に提供する体験を強調しながら、神戸の多様な魅力を伝えています。風光明媚な公園から文化的な名所まで、神戸の魅力を感じながら、季節ごとの楽しみを味わうことができることを視聴者に呼びかけています。' where id = 'AmcedureB9S_EcMq3G_-P';
update content_bodies set title = 'Welcome to KOBE SS - Spring and Summer Tourism Promotion Video', description = 'This video introduces the spring and summer attractions of Kobe. It features various spots including Port Island North Park, Old Foreign Settlement, Otonakadori, Venus Bridge, Ikuta Shrine, Hakutsuru Sake Brewery Museum, Rokko Mountain, Arima, and more. The video showcases the beauty of these locations, highlighting their unique characteristics and the experiences they offer to visitors. From scenic parks to cultural landmarks, Kobe''s diverse attractions are presented, inviting viewers to explore the city and enjoy its seasonal charm.' where id = 'ulgWn4ODCw0srwRr9i4GA';
update content_bodies set title = '神戸観光プロモーション動画～秋冬編～', description = 'この動画では、神戸の観光スポットの秋冬の様子を紹介しています。登場するスポットには、神戸空港、メリケンパーク、旧居留地、南京町、北野、明石海峡大橋、有馬、六甲山牧場、スノーパーク、岡本梅林公園、北野天満宮、ヴィーナスブリッジなどがあります。秋冬の美しさと魅力を伝え、視聴者に神戸の観光地を訪れることを促しています。' where id = 'jRyDHjZF-ccwpkt7mI2ZS';
update content_bodies set title = 'Welcome to KOBE AW: Autumn and Winter Tourism Promotion Video', description = 'This video introduces the autumn and winter scenery of various tourist spots in Kobe. Featured locations include Kobe Airport, Meriken Park, Old Foreign Settlement, Nankinmachi (Chinatown), Kitano, Akashi Kaikyo Bridge, Arima, Rokko Mountain Farm, Snow Park, Okamoto Plum Grove, Kitano Tenmangu Shrine, Venus Bridge, and more. The video showcases the beauty and charm of these sites during the fall and winter seasons, inviting viewers to explore Kobe''s attractions.' where id = '6rdaWEUeyO_paBEX6UHbP';
update content_bodies set title = 'これは神戸の日本です', description = 'この動画では、神戸のさまざまな撮影スポットを紹介しています。紹介されている場所には、有馬、三津森本舗、天上寺、生田神社、白鶴酒造資料館、須磨寺、北野天満宮、北区、本陣カフェ、相楽園が含まれています。神戸の観光情報については、提供されたリンクを訪れてください。' where id = 'm9JC5tFiwZuKHraPe3Q_k';
update content_bodies set title = 'This is Japan in KOBE', description = 'This video showcases various filming spots in Kobe, Japan. The locations featured include Arima, Mitsumori Honpo, Tenjoji Temple, Ikuta Shrine, Hakutsuru Sake Brewery Museum, Suma Temple, Kitano Tenmangu Shrine, Kita Ward, Honjin Cafe, and Sorakuen. For more tourist information about Kobe, visit the provided link.' where id = 's7sWUHTTT2YcdYX58QjFo';
update content_bodies set title = '神戸の人々', description = 'このテキストは、日本の神戸にある人気の撮影スポットの一覧を提供しています。相楽園、六甲山牧場、北野天満宮、布引の滝、有馬、メリケンパークやハーバーランドなどの公園が含まれています。また、布引ハーブ園、生田神社、ヴィーナスブリッジなどの名所も挙げられています。このリストは、訪問者に提供される多様な観光名所を強調し、それぞれの場所の美しさと文化的重要性を示しています。神戸の観光情報や宿泊予約のリンクも提供されています。' where id = 'd0N1gj_FA_OcFdqmoWiQ0';
update content_bodies set title = 'People in KOBE', description = 'This text provides a list of popular filming spots in Kobe, Japan. The locations include Sogakuen, Rokko Mountain Ranch, Kitano Tenmangu Shrine, Nunobiki Falls, Arima, and various parks such as Meriken Park and Harborland. Other notable sites mentioned are the Herb Garden, Ikuta Shrine, and Venus Bridge. The list highlights the diverse attractions available for visitors, showcasing the beauty and cultural significance of each location. For more information on tourism in Kobe, a link is provided, as well as a link for hotel reservations.' where id = 'm_bNdT0iY2tKlzaKH75a3';
update content_bodies set title = '神戸の自然', description = 'このテキストは、神戸の自然の美しさを楽しめる観光スポットの一覧を提供しています。紹介されているスポットには、桜、灘区の桜トンネル、須磨浦公園、有馬、森林植物園、六甲山牧場、布引の滝、布引ロープウェイ、掬星台、布引ハーブ園、北区の場所、明石などがあります。神戸の観光情報や宿泊予約のリンクも提供されています。' where id = 'Nme0nHJ_9bWq-18Cko_X6';
update content_bodies set title = 'Nature in KOBE', description = 'This text provides a list of scenic spots in Kobe, highlighting various locations known for their natural beauty. The featured spots include cherry blossoms, the Nada Ward Cherry Blossom Tunnel, Sumaura Park, Arima, the Forest Botanical Garden, Rokko Mountain Farm, Nunobiki Falls, the Nunobiki Ropeway, Kikusui-dai, the Nunobiki Herb Garden, and locations in the Kita Ward and Akashi. For more information on tourism in Kobe, a link is provided, as well as a link for accommodation bookings.' where id = 'oS7giTd-7_jm4ikVCAS68';
update content_bodies set title = '神戸の深層', description = 'このコンテンツでは、神戸の撮影スポットを一覧で紹介しています。具体的には、鉄人28号、六間道商店街、青森、能福寺、乙仲通り、モトコーなどの名所が含まれています。神戸の観光情報については、提供されたリンクを訪れてください。また、宿泊予約のための別のリンクも用意されています。' where id = 'h5cvm9WXHTjNvl_mOEz-g';
update content_bodies set title = 'Deep in KOBE', description = 'This content provides a list of filming locations in Kobe, including notable spots such as the Iron Man 28 statue, Rokko-michi shopping street, Aomori, Nofuku-ji Temple, Otonaka Street, and Motoko. For more tourist information about Kobe, visit the provided link, and for accommodation bookings, another link is available.' where id = 'e9ouRk5djWnS8kui9SV6P';
update content_bodies set title = 'A KOBE TRIP HD', description = 'この映像は、神戸の観光魅力を探求し、旅人が何を求めて旅をするのかを問いかけています。人々は普段とは異なる体験や日常からの解放、自己成長の機会を求めていると示唆しています。旅の目的は歴史的遺産の中に見出すことも、変化する都市の現代的な姿の中に感じることもでき、これは旅人の選択に委ねられています。この映像は、変化する神戸の美意識や生活スタイルを3分半に凝縮し、神戸の今を感じることを促しています。' where id = 'qd8A3qqJzWEMOfGkKKdsq';
update content_bodies set title = 'A KOBE TRIP HD', description = 'This video explores the allure of Kobe as a travel destination, questioning what draws people to travel. It suggests that travelers seek unique experiences, a break from daily life, and opportunities for personal growth. The purpose of the journey can be found in historical heritage or in the contemporary essence of the city, reflecting the traveler''s choice. The video condenses Kobe''s evolving aesthetic and lifestyle into a 3.5-minute experience, inviting viewers to feel the essence of modern Kobe.' where id = 'vBkF3KdcS9SwEcBuRcSDv';
update content_bodies set title = 'これからの修学旅行～PRAY,PLAY, NARA～', description = '奈良県への修学旅行を検討している方々に向けて、参考となるスポットや体験を紹介しています。奈良ならではの魅力に触れ、地域の文化や環境を楽しむことを促しています。' where id = 'cP7KaSsCfBmb4CFFjeGae';
update content_bodies set title = 'Future School Trips - PRAY, PLAY, NARA', description = 'This text introduces various spots and experiences that can be considered for school trips to Nara Prefecture. It emphasizes the unique attractions of Nara, encouraging visitors to engage with the local culture and environment.' where id = 'sfrS59m9zAUFWSdqFnO05';
update content_bodies set title = '習うより、奈良体験へ～PRAY,PLAY, NARA～', description = '奈良県の家族で訪れることができるスポットを紹介し、学びや体験を得ることができる内容です。家族で一緒に体感し、発見や学びを感じることの重要性が強調されています。' where id = 'mKuptDJXEqs11CtWl5U_E';
update content_bodies set title = 'Experience Nara: PRAY, PLAY, NARA', description = 'This text introduces spots in Nara Prefecture that families can visit to gain knowledge and experiences. It emphasizes the importance of discovering and learning through hands-on experiences together as a family.' where id = 'qfo-066hgGg36pP9vyn-N';
update content_bodies set title = '【予告】ＶＲ松山城～謎の姫と幻の合戦～【68秒Ver.】', description = '令和3年7月1日に松山城天守内に新たにVR体験コーナーが登場します。360度カメラやCG技術を駆使した臨場感あふれる映像で、普段見ることのできない松山城の姿を楽しむことができます。ナレーションは愛媛県出身の声優・水樹奈々さんが担当し、彼女の圧倒的な演技力で体験者を不思議なストーリーへと誘います。' where id = 'h2Y9mJ_oL66vVUd7qdEf5';
update content_bodies set title = 'VR Matsuyama Castle - The Mysterious Princess and the Phantom Battle - [68 seconds version]', description = 'On July 1, 2021, a new VR experience corner was launched inside the Matsuyama Castle keep. Utilizing 360-degree cameras and CG technology, visitors can enjoy immersive visuals showcasing aspects of Matsuyama Castle that are usually unseen. The narration is provided by Nana Mizuki, a voice actress from Ehime Prefecture, who guides participants into a mysterious story with her outstanding performance.' where id = 'KRkZVEztbODrd_Nw0Toki';
update content_bodies set title = '【予告】ＶＲ松山城～謎の姫と幻の合戦～【40秒Ver.】', description = '令和3年7月1日に松山城天守内に新たにVR体験コーナーが登場します。360度カメラやCG技術を駆使した臨場感あふれる映像で、普段見ることのできない松山城の姿を楽しむことができます。ナレーションは愛媛県出身の声優・水樹奈々さんが担当し、彼女の圧倒的な演技力で体験者を不思議なストーリーへと誘います。' where id = 'EoRGVNENX5HRne7SbZvQF';
update content_bodies set title = 'VR Matsuyama Castle - The Mysterious Princess and the Phantom Battle - [40-second Version]', description = 'On July 1, 2021, a new VR experience corner will be launched inside the Matsuyama Castle keep. Utilizing 360-degree cameras and CG technology, visitors can enjoy immersive visuals that showcase aspects of Matsuyama Castle that are usually unseen. The narration is provided by Nana Mizuki, a voice actress from Ehime Prefecture, who guides participants into a mysterious story with her outstanding performance.' where id = 'e54XwTRoU3JPwpp-1V_Ot';
update content_bodies set title = '【予告】ＶＲ松山城～謎の姫と幻の合戦～【15秒Ver.】', description = '令和3年7月1日に松山城天守内に新たにVR体験コーナーが登場します。360度カメラやCG技術を駆使した臨場感あふれる映像で、普段見ることのできない松山城の姿を楽しむことができます。ナレーションは愛媛県出身の声優・水樹奈々さんが担当し、彼女の圧倒的な演技力で体験者を不思議なストーリーへと誘います。' where id = '8nLAeQj99nFuaS_YblZ_t';
update content_bodies set title = 'VR Matsuyama Castle - The Mysterious Princess and the Phantom Battle - [15-second Version]', description = 'On July 1, 2021, a new VR experience corner will open inside the Matsuyama Castle keep! Enjoy the immersive visuals created using 360-degree cameras and CG technology, showcasing aspects of Matsuyama Castle that are usually unseen. The narration will be provided by Nana Mizuki, a voice actress from Ehime Prefecture, who will guide participants into a mysterious story with her outstanding performance.' where id = 'UDjLfQV47a3M3Ehefy8qi';
update content_bodies set title = '金魚ねぷたの作り方', description = '弘前ねぷたは1722年に初めて文献に登場し、2022年に300年を迎えました。弘前ねぷた300年祭実行委員会は、弘前ねぷたの歴史と伝統を継承し、未来へ繋げるために『金魚ねぷたの作り方』という動画を制作しました。' where id = 'yJXBad6aqpEs-WnHGFVab';
update content_bodies set title = 'How to Make Goldfish Neputa', description = 'The Hirosaki Neputa first appeared in literature in 1722, marking its 300th anniversary in 2022. To preserve the history and traditions of Hirosaki Neputa and connect them to the future, the Hirosaki Neputa 300th Anniversary Executive Committee has produced a video titled ''How to Make Goldfish Neputa.''' where id = 'HMeUp6dpySbUwBh1-Jge6';
update content_bodies set title = '【松山市公式PR動画】 道後温泉歓迎楽団「桶ストラ」', description = '松山市の公式観光PR動画「桶ストラ」では、道後温泉を舞台に、管弦楽団が雄大なウィンナ・ワルツの調べと温泉特有の「桶」の音をミックスし、観光客を迎える気持ちをオーケストラ風に表現しています。温かみのある音楽が、松山市の魅力を伝えています。' where id = 'Z3m8poeTaC8MGlx6Py8M9';
update content_bodies set title = 'Matsuyama City Official PR Video: Dogo Onsen Welcome Orchestra ''Okestra''', description = 'The official tourism PR video of Matsuyama City features the Dogo Onsen Welcome Orchestra, which combines the grand melodies of Viennese waltzes with the unique sounds of the ''桶'' (oku) that evoke the warmth of the hot springs. This orchestral performance expresses the city''s welcoming spirit towards tourists in a charming and engaging manner.' where id = 'S0m8crcbGMVWKeMGKEj5s';
update content_bodies set title = 'アップルブランデーの向こうの郷 ～醸成していく弘前旅～', description = '弘前大学の学生が考案したアート・ツアー「アップルブランデーの向こうの景色　醸成してゆく弘前旅」は、より豊かな文化体験を求めるプレミアム世代をターゲットにしています。このツアーは、県外から訪れる大人の観光客を想定しており、弘前の独自の文化的魅力を紹介することを目的としたイメージショートムービーです。' where id = 'CL9tONPVLuPCxOGwq5LoM';
update content_bodies set title = 'Beyond Apple Brandy: Cultivating a Journey in Hirosaki', description = 'This is a short image movie showcasing an art tour designed by Hirosaki University students, targeting the premium generation seeking richer cultural experiences. Titled ''The Scenery Beyond Apple Brandy: Cultivating a Journey in Hirosaki,'' the tour is aimed at adult tourists coming from outside the prefecture, highlighting the unique cultural offerings of Hirosaki.' where id = 'eSFLJ1CT_tiOSL3QGl4er';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11月1日から11月7日まで弘前公園で「弘前城 菊と紅葉まつり」が開催されています。この祭り（通称：菊もみ）に弘前大学の学生がリポーターとして潜入取材を行い、フラワーアートの制作風景や祭りの楽しみ方を紹介します。今回は「青龍を見つけよう！」という動画をお届けします。植物園内の様々な場所に、縁起の良い守り神「青龍」が9体隠れています。青龍を見つけると良いことが起こるかもしれません。動画内には3体の青龍が映っていますが、見つけられましたか？' where id = 'SKC-VfVHDe4bsR5GXWk7o';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the ''Hirosaki Castle Chrysanthemum and Autumn Leaves Festival'' is being held at Hirosaki Park. Students from Hirosaki University are acting as reporters, conducting undercover coverage of the festival, including the creation of flower art and ways to enjoy the event. This time, we introduce a video segment titled ''Let''s Find the Seiryu!'' In various locations within the botanical garden, there are nine hidden ''Seiryu'' decorations, which are believed to be auspicious guardians that promote joy and development. Finding all nine Seiryu may bring good fortune! The video features three of these Seiryu. Did you spot them?' where id = 'BK3eYhMcNJ-t3n5ZJVoiY';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11月1日から11月7日まで弘前公園で「弘前城 菊と紅葉まつり」が開催されています。弘前大学の学生がリポーターとなり、祭りの潜入取材を行い、フラワーアートの制作風景や楽しみ方をお届けします。今回は学生記者クラブおすすめの巡り方を動画で紹介します。フラワーアートのコンセプトに合わせて、東門から入場するルートです。祭りも終盤に差し掛かり、休日にはクラフトマーケットも開催されるため、混雑する時間帯もあるかもしれません。ゆったり見たい方は、開園直後が狙い目です。' where id = 'SFPuNxVAp7pJPAagjGiKC';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the ''Hirosaki Castle Chrysanthemum and Autumn Leaves Festival'' is being held at Hirosaki Park. Students from Hirosaki University are acting as reporters, conducting undercover coverage of the festival, including the creation of flower art and ways to enjoy the event. This time, the Student Reporter Club introduces a recommended route to explore the festival through a video! The route starts from the East Gate, in line with the concept of flower art. As the festival approaches its end, there may be busy times, especially during the craft market on weekends. For those who prefer a leisurely visit, arriving right when the park opens is advisable.' where id = '8C9-MTfNluHFv3dauCMrC';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11月1日から7日まで弘前公園で「弘前城 菊と紅葉まつり」が開催されています。弘前大学の学生がリポーターとなり、フラワーアートの制作やまつりの楽しみ方を取材しています。すでに来場された方もいるかもしれませんが、今回はフラワーアートをより深く楽しむための鑑賞順序を紹介します。物語のように、東門から入った龍が花くぐりを通り、三の丸庭園に鎮座し、花手水が龍の足跡を表現します。りんごの木には願いが込められた赤い実がなり、追手門へ向かう花手水には木から飛んだりんごの葉が溢れています。このように、フラワーアート「枯木龍吟」の物語を知ることで、鑑賞がより深まります。' where id = 'Rh6AWV0SSV23vpKKoMzJI';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the ''Hirosaki Castle Chrysanthemum and Autumn Leaves Festival'' is being held at Hirosaki Park. Students from Hirosaki University are acting as reporters, conducting undercover coverage of the festival, including the creation of flower art and ways to enjoy the event. For those who have already visited, this report provides a deeper understanding of how to appreciate the flower art. The story of the flower art ''Karekiryuuin'' unfolds as follows: the dragon enters through the East Gate, passes through a flower arch, and sits in the San-no-Maru Garden adorned with white flowers. The flower water represents the dragon''s footprints, while a wish tree with red apples stands beside it. The journey continues towards the Otemon Gate, culminating in a larger apple bearing fruit. Knowing the story enhances the appreciation of the art.' where id = 'iWzFSkGSCF2f_xyrdCW23';
update content_bodies set title = 'HIROHAKO: 雪ミクと桜ミクの季節の冒険', description = '「ひろはこ」は、弘前市と函館市の協力を示すもので、両市の名前を参照しています。冬には、雪に覆われた風景や西洋建築のライトアップを楽しむことができます。春には、弘前城や五稜郭公園などの有名な桜の名所を訪れることができます。弘前市と函館市の美しい景色を体験してください。桜ミクと雪ミクは、それぞれ春と冬の観光キャンペーンの公式サポートキャラクターです。' where id = 'l-fS6iRL2T3c-PHSWDfiY';
update content_bodies set title = 'HIROHAKO: Seasonal Adventure with Snow Miku & Sakura Miku', description = 'HIROHAKO represents the collaboration between Hirosaki City and Hakodate City, highlighting the names of both locations. In winter, visitors can enjoy the illuminated snowy landscapes and the light-up of Western-style buildings. Spring offers the chance to visit renowned cherry blossom spots such as Hirosaki Castle and Goryokaku Park. The campaign features SAKURA MIKU and SNOW MIKU as the official support characters for spring and winter tourism, respectively. Experience the stunning scenery of both Hirosaki City and Hakodate City!' where id = '5kvd3jkMXFFQBN19OsDk9';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11月1日から7日まで弘前公園で「弘前城 菊と紅葉まつり」が開催されています。弘前大学の学生がリポーターとなり、潜入取材を行い、フラワーアートの制作風景や祭りの楽しみ方をお届けします。今回は白い花で飾られた花くぐりの制作風景を動画で紹介します。この花くぐりは大人でも楽に通り抜けられる大きさで、白い花は精巧に作られたアーティフィシャルフラワーです。写真映えするフラワーアートで、通り抜けるだけで心が澄んだ気持ちになります。アーティフィシャルフラワーの精巧さをぜひご覧ください！' where id = '_eYH6Vl0DxDMRoEHYOzYo';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the ''Hirosaki Castle Chrysanthemum and Autumn Leaves Festival'' is being held at Hirosaki Park. Students from Hirosaki University are acting as reporters, conducting undercover interviews to share insights about the festival, including the creation of flower art and ways to enjoy the event. This time, a video showcases the production of a flower arch decorated with white flowers. The arch is large enough for adults to easily pass through, and the white flowers are intricately crafted artificial flowers. This flower art is sure to be a hit for photography. Simply walking through it brings a sense of clarity and joy. Come closer to the artificial flowers and see how exquisitely they are made!' where id = 'GfpsrrNRJbp38cThHjEjQ';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11月1日から11月7日まで弘前公園で「弘前城 菊と紅葉まつり」が開催されています。この祭り（通称 菊もみ）に弘前大学の学生がリポーターとして参加し、潜入取材を行っています。フラワーアートの制作風景や祭りの楽しみ方をお届けします。今回は花手水の制作風景を動画で紹介します。10月31日に行われたワークショップでは、フラワーデザインを担当した阿部喜恵さんの指導のもと、参加者がそれぞれの花手水を制作しました。現在、会場では完成した花手水を観覧できます。ちなみに、学生記者のお気に入りは動画の終盤に登場しますので、ぜひ見つけてみてください！' where id = 'jmUfjfGJ8I23YhsvKaAcZ';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the ''Hirosaki Castle Chrysanthemum and Autumn Leaves Festival'' is being held at Hirosaki Park. Students from Hirosaki University are acting as reporters, conducting undercover coverage of the festival, including the creation of flower art and ways to enjoy the event. This time, a video showcasing the production of ''Hanamizuki'' (flower water) is presented. A workshop was held on October 31, where participants created their own flower water under the guidance of floral designer Yoshie Abe. The completed flower water can currently be viewed at the venue. By the way, the students'' favorite is featured at the end of the video, so be sure to find it!' where id = 'FpTIaYHBgBYWo7tyn8l_M';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11月1日から7日まで弘前公園で「弘前城 菊と紅葉まつり」が開催されています。この祭り（通称 菊もみ）に弘前大学の学生がリポーターとして潜入取材を行い、フラワーアートの制作風景や祭りの楽しみ方をお届けします。今回は白い花で飾られた花くぐりの制作風景を動画で紹介します。大人でも楽に通り抜けられる大きさの花くぐりは、精巧に作られたアーティフィシャルフラワーで飾られています。写真映えするフラワーアートで、通り抜けるだけで澄んだ気持ちになれます。アーティフィシャルフラワーの精巧さをぜひご覧ください！' where id = 'SNQpi1XljJrR-i_Ij4_LB';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the ''Hirosaki Castle Chrysanthemum and Autumn Leaves Festival'' is being held at Hirosaki Park. Students from Hirosaki University are acting as reporters, conducting undercover coverage of the event! They will share insights on the creation of flower art and how to enjoy the festival. This time, a video showcases the production of a flower arch decorated with white flowers. The arch is large enough for adults to easily pass through, and the white flowers are intricately crafted artificial flowers. This flower art is sure to be a hit for photos. Simply walking through it brings a sense of clarity and joy. Come closer to the artificial flowers and see how exquisite they are!' where id = 'pFpSCZ4kZTUgInX8B0n75';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11月1日から11月7日まで弘前公園で「弘前城 菊と紅葉まつり」が開催されています。この祭り（通称：菊もみ）では、弘前大学の学生がリポーターとして潜入取材を行い、フラワーアートの制作風景や祭りの楽しみ方をお届けします。今回は会場内のライトアップの様子を動画で紹介します。ライトアップにより、背景が暗くなることで紅葉の赤さが際立ちます。昼間の昇天華龍は精緻な組みと鮮やかな花が魅力ですが、夜の照明は不思議と気分を高揚させます。会期中は毎日17:00から18:45まで上映されますので、足元に気をつけてお越しください。' where id = '_yAWeMMg_YYcGqZlTqHYD';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the ''Hirosaki Castle Chrysanthemum and Autumn Leaves Festival'' is being held at Hirosaki Park. Students from Hirosaki University are acting as reporters, conducting undercover coverage of the event. They will share insights on the creation of flower art and ways to enjoy the festival. This time, a video showcasing the lighting effects at the venue will be presented. The illumination enhances the vibrant red of the autumn leaves against the dark background. The ''Ascension Dragon'' is not only stunning in the daylight with its intricate design and vivid flowers, but the nighttime lighting creates a unique atmosphere that elevates the mood. The light show runs daily from 5:00 PM to 6:45 PM during the festival. Visitors should be cautious as the ground can be dark.' where id = 'OQ0VjCscAh4gb-4YiFZz9';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11月1日から11月7日まで弘前公園で「弘前城 菊と紅葉まつり」が開催されています。この祭り（通称：菊もみ）に弘前大学の学生がリポーターとして参加し、潜入取材を行っています。フラワーアートの制作風景や祭りの楽しみ方を紹介します。今回は全長100mの昇天華龍の制作風景を動画でお届けします。横に立つとその大きさが実感できるでしょう。会場では完成した昇天華龍を観覧でき、夜の昇天華龍の動画もお楽しみに！' where id = 'LlZ2oBWooJUUVuRH5uDTZ';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the ''Hirosaki Castle Chrysanthemum and Autumn Leaves Festival'' is being held at Hirosaki Park. Students from Hirosaki University are acting as reporters, conducting undercover coverage of the festival, including the creation of flower art and ways to enjoy the event. This time, we present a video of the production of the 100-meter-long ''Shoten Karyu'' (Heavenly Flower Dragon). Standing next to it gives a sense of its size. Currently, visitors can see the completed Shoten Karyu at the venue. A video of the Shoten Karyu at night will also be provided, so stay tuned!' where id = '1zVywrxFcBBy2PFU1dnWR';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11月1日から11月7日まで弘前公園で「弘前城 菊と紅葉まつり」が開催されます。この祭り（通称：菊もみ）に弘前大学の学生がリポーターとして潜入取材を行い、フラワーアートの制作風景や祭りの楽しみ方をお届けします。今年のフラワーアートの目玉である昇天華龍の頭が三の丸庭園に到着しました。全長100メートルの胴体に見合った迫力ある頭部が特徴です。近づくと、その造形の精緻さに驚かされます。この龍は花で彩られ、見る人に活力を与える生命力あふれる作品に仕上がります。また、プロジェクションマッピングも近日中にお見せできる予定です。' where id = 'XUSupNTdz_9_fOsoJcKrw';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the ''Hirosaki Castle Chrysanthemum and Autumn Leaves Festival'' will be held at Hirosaki Park. Students from Hirosaki University will act as reporters, conducting undercover coverage of the event. They will showcase the creation of floral art and share ways to enjoy the festival. A highlight of this year''s floral art, the head of the ''Ascendant Dragon'' has arrived at the San-no-Maru Garden, featuring a 100-meter long body and an impressive head that matches its size. The intricate details of the sculpture are astonishing up close. This dragon will be adorned with flowers, transforming into a vibrant piece that energizes viewers. Projection mapping will also be showcased soon.' where id = 'H80pp54HawgUhTsy88-cG';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11月1日から11月7日まで弘前公園で「弘前城 菊と紅葉まつり」が開催されます。このイベント（通称：菊もみ）に、弘前大学の現役学生がリポーターとして潜入取材を行います。フラワーアートの制作風景や、まつりの楽しみ方などを学生の視点からお届けし、菊もみの魅力を伝えます。また、気になることやおすすめの写真スポットについてコメントを寄せていただけると嬉しいです。' where id = 'sR3dgsxJ7S1SfZfe2d5dq';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the ''Hirosaki Castle Chrysanthemum and Autumn Leaves Festival'' will be held at Hirosaki Park. Current students from Hirosaki University will act as reporters, conducting undercover coverage of the event, commonly known as ''Kiku Momi.'' They will showcase the creation of flower art and share ways to enjoy the festival from a student perspective. The reporters aim to convey the charm of ''Kiku Momi.'' They also encourage readers to share any questions or recommended photo spots in the comments.' where id = 'HnbWss1DCfVibttM5AnL7';
update content_bodies set title = '津軽まちあるき 藤崎', description = '「津軽の普段を、ふかぐあさぐ。」をテーマに、地元のガイドと共にまちあるきツアーを楽しむことができます。このツアーは、津軽まちあるき観光推進実行委員会によって企画されており、弘前市や藤崎町、平川市など、青森県中南地域の複数の市町村が参加しています。詳細や予約は、津軽まちあるきの予約サイトをご覧ください。また、地域の各町のハイライトを紹介する動画リンクも提供されています。' where id = 'sxidnv_tZO-T2cjYxM_Vg';
update content_bodies set title = 'Fujisaki Walking Tour', description = 'Experience the everyday life of Tsugaru with a local guide on this walking tour. The tour is organized by the Tsugaru Machiaruki Tourism Promotion Committee, which includes various municipalities such as Hirosaki City, Fujisaki Town, Hirakawa City, and others in the Aomori Prefecture. For more information and to make reservations, visit the Tsugaru Machiaruki reservation site. Additionally, there are several video links provided that showcase highlights from different towns in the region.' where id = '0uFs3wKdCzLTvhjdHUwyU';
update content_bodies set title = '弘前市りんご公園', description = '弘前市りんご公園には「タイヤチューブすべり台」というユニークなアトラクションがあります。この公園は特に冬季に人気があり、弘前市ウィンターフェスティバルが開催される場所として知られています。詳細については、弘前市りんご公園とウィンターフェスティバルの公式ウェブサイトを訪れることができます。' where id = 'dci_To64k3qiVhm9yxTPL';
update content_bodies set title = 'Hirosaki City Apple Park', description = 'Hirosaki City Apple Park features a unique attraction called the ''Tire Tube Slide.'' This park is a popular destination for visitors, especially during the winter season when it hosts the Hirosaki City Winter Festival. For more information, you can visit the official websites of Hirosaki City Apple Park and the Winter Festival.' where id = 'o554fqrJgbrwUSrKIH7i1';
update content_bodies set title = '弘前城、動く!!タイムラプス動画（一次曳屋）', description = '弘前城の本丸石垣修理工事に伴う天守の曳屋工事の様子をタイムラプス動画で紹介します。地切式から一次曳屋、さらに回転移動までの過程を捉えた映像で、弘前城が動く様子を楽しむことができます。映像は弘前市から提供されています。' where id = 'OT3Yj_hQGT0DQB1Haqjau';
update content_bodies set title = 'Hirosaki Castle in Motion!! Timelapse Video (First Moving)', description = 'This timelapse video showcases the moving process of Hirosaki Castle''s main keep during the stone wall repair work. It features the transition from the cutting method to the first moving and the rotational movement. Watch as Hirosaki Castle comes to life in motion. (Video provided by Hirosaki City)' where id = 'ltt-n40vM4dySrLHQCKSp';
update content_bodies set title = 'Seeing differently 小巷篇【簡体字】｜路地編', description = 'この動画は、日本を訪れる外国人観光客が日本の文化、習慣、行動、社会的規範を理解することを促進し、ストレスや不安、混乱、不快感といった障壁を軽減することを目的としています。また、日本の住民に対して基本的なマナーを再考し、ホスピタリティの精神を育むことを促しています。私たちは、他者の視点に気づき、周囲への配慮を持つことを願っています。' where id = 'nIBN2IC5SFNMjQJq3C0tE';
update content_bodies set title = 'Seeing differently: Backstreet Edition', description = 'This video aims to reduce stress and barriers such as anxiety, confusion, and discomfort for foreign tourists visiting Japan by promoting an understanding of Japanese culture, customs, behaviors, and social norms. It also encourages Japanese residents to reconsider basic manners and foster a spirit of hospitality. The goal is to raise awareness of different perspectives and encourage consideration for those around us.' where id = 'LaIIYCqJzlMo_KmgX5PcJ';
update content_bodies set title = 'Seeing differently 거리편｜路地編', description = 'この動画は、日本を訪れる外国人観光客が日本の文化、習慣、行動、社会的規範を理解することを促し、ストレスや不安、混乱といった障壁を軽減することを目的としています。また、日本の住民に対して基本的なマナーを再考し、ホスピタリティの精神を育むことを目指しています。私たちは、他者の視点に気づき、周囲への配慮を持つことを願っています。' where id = '7QKNfUrceT5OBImxHcyWd';
update content_bodies set title = 'Seeing differently 거리편｜路地編', description = 'This video focuses on reducing stress and barriers such as anxiety and confusion for foreign tourists in Japan. It encourages understanding of Japanese culture, customs, behaviors, and social norms. Additionally, it aims to promote basic manners and foster a spirit of hospitality among Japanese residents. The goal is to raise awareness of different perspectives and encourage consideration for those around us.' where id = '7wBg0MY1DG_F6x3l315H8';
update content_bodies set title = 'Seeing differently 小巷篇【繁体字】｜ 路地編', description = 'この動画は、日本を訪れる外国人観光客が抱えるストレスや不安、混乱を軽減することを目的としています。日本の文化や習慣、行動、社会的規範を理解することを促し、また、日本の住民に対して基本的なマナーを再考し、ホスピタリティの精神を育むことを目指しています。互いの視点を理解し、周囲への配慮を持つことの重要性を皆が認識できることを願っています。' where id = 'uwW45zwwyNJ_37MuFgDlG';
update content_bodies set title = 'Seeing differently 小巷篇【繁体字】｜ 路地編', description = 'This video focuses on reducing stress and barriers such as anxiety and confusion for foreign tourists in Japan. It encourages visitors to understand Japanese culture, customs, behaviors, and social norms. Additionally, it aims to promote basic manners and foster a spirit of hospitality among Japanese residents. The goal is to enhance mutual understanding and encourage everyone to be aware of different perspectives and considerate of those around them.' where id = 'wAQT7m6PR289I7tsyVl18';
update content_bodies set title = '予期せぬ出会い', description = '作品「予期せぬ出会い」は、宮田耕輔監督によるもので、映像は反保シュウジ、写真はEito Marsが担当しています。撮影場所はウドノスビーチ、寺崎漁港、鳩の池、大金久海岸、サトウキビ畑、アジニッチェー神社、居酒屋など多岐にわたります。この作品は、与論島の人々との温かい出会いをテーマにした3泊4日の旅を通じて制作されました。宮田組はゲストハウスKAIを拠点に、島を巡りながら地元の人々と交流し、夕日スポットやテントサウナ体験などを通じて撮影を進めました。島の人々との出会いを基に、宮田監督の文章がテロップとして使用され、スチール写真と実写が融合した映像作品として仕上がりました。' where id = '8OOdjo_3OXrxbosYJ6VRV';
update content_bodies set title = 'Unexpected Encounter', description = 'The film ''Unexpected Encounter'' is directed by Kousuke Miyata, with visuals by Shuji Hanbo and photography by Eito Mars. Filming locations include Udonos Beach, Terasaki Fishing Port, Hato Pond, Okakinuku Coast, sugarcane fields, Ajinichie Shrine, and local eateries. The project aims to capture the warmth of the people on Yoron Island during a 3-night, 4-day journey. The crew, based at Guest House KAI, explored the island, meeting locals and documenting their experiences. They learned about hidden sunset spots from islanders growing Yoron lemons and participated in a tent sauna experience. Encounters with locals, such as those welcoming tourists with traditional music at Hato Pond, enriched the filming process. The film combines Miyata''s written reflections, still photography, and live-action footage to create a tourism video that showcases the beauty and community of Yoron Island.' where id = 'HmTO06trpvyxXLofTZBBU';
update content_bodies set title = 'ヨロン島 | YORON Island 注意してほしい5つのポイント', description = '「ヨロンブルー」と呼ばれる美しい海に囲まれたヨロン島は、サンゴ礁に囲まれた小さな楽園です。ウミガメやカラフルな魚たちが泳ぎ、ハイビスカスやブーゲンビリアが咲き誇る南国の雰囲気が漂います。この動画では、ヨロン島を訪れる前に知っておくべき「注意してほしい5つのポイント」を紹介しています。少し不便に感じることもあるかもしれませんが、それがヨロンの旅の魅力でもあります。美しい自然や優しい人々との出会いは、忘れられない思い出となるでしょう。ぜひこの動画を見て、ヨロン島の旅を楽しんでください。' where id = 'ZZFdUsQvMwRhSY__d_JZh';
update content_bodies set title = 'YORON Island: FIVE THINGS TO KEEP IN MIND', description = 'Yoron Island, surrounded by the beautiful sea known as ''Yoron Blue'', is a small paradise with coral reefs, sea turtles, and colorful fish. The island is adorned with blooming hibiscus and bougainvillea, creating a tropical atmosphere. This video highlights five important points to consider before visiting Yoron Island. While some aspects may feel inconvenient, they contribute to the unique charm of the island experience. Embrace the slower pace of island life, and cherish the beautiful nature and warm encounters with locals, which will create unforgettable memories. Be prepared to make the most of your trip by watching this video before you go.' where id = 'P99x-gc1pfDBbfEhrVU4u';
update content_bodies set title = '秘密の日本の島への旅', description = 'この作品は、Jay Chern監督によるもので、台湾の若者カップルが低予算で日本の美しい秘密の島、与論に旅行する様子を描いています。この映画は、日本国際観光映像祭 ART ＆ FACTORY JAPANで優秀インバウンド映像賞を受賞しました。' where id = '7ruLC2_Sjur1irmWupoYV';
update content_bodies set title = 'A trip to a secret Japanese island', description = 'The film, directed by Jay Chern, showcases a young couple from Taiwan who embark on a budget-friendly trip to the beautiful secret island of Yoron in Japan. The film received the Excellent Inbound Video Award at the Japan International Tourism Film Festival ART & FACTORY JAPAN.' where id = 'MCqf2Ed7CSUXPDqfO6m3m';
update content_bodies set title = '【ヨロン島】沖縄からヨロン島へのフェリーの旅（Travel 編）', description = '沖縄北部エリアは2021年に世界自然遺産に認定され、やんばるの森には美しい緑や清らかな水、希少な動植物が生息しています。本部港からフェリーで約2時間の距離にあるヨロン島は、南国の楽園として知られ、美しい青い海と様々なマリンレジャーが楽しめます。さらに、歴史や郷土文化、美味しい食事、島の人々との出会いが旅の思い出を彩ります。友達やカップル、ファミリーで訪れても、ヨロン島の美しい海と優しい人々があなたを待っています。やんばるの緑とヨロン島の青い海という異なる魅力がフェリーで繋がり、特別な観光体験を提供します。' where id = 'AJe4QfWs5qCClqaRyy0LP';
update content_bodies set title = 'Ferry Journey to Yoron Island from Okinawa (Travel Edition)', description = 'The northern area of Okinawa was designated a UNESCO World Heritage site in 2021. The Yanbaru forest in northern Okinawa is home to lush greenery, clear streams, and numerous rare species of flora and fauna. Yoron Island, a tropical paradise boasting beautiful blue seas, is accessible by a ferry from Motobu Port in northern Okinawa, taking about two hours. On Yoron Island, visitors can enjoy the stunning YORON BLUE sea and various marine leisure activities. Beyond the sea, the island offers rich history, local culture, delicious cuisine, and unforgettable encounters with the island''s people. Whether traveling with friends, as a couple, or with family, the beautiful sea and warm-hearted locals of Yoron Island await you. The contrasting charms of Yanbaru''s greenery and Yoron Island''s blue sea are connected by the ferry, providing a unique tourism experience.' where id = 'bNBLFnZK9STyMe_dVR9l6';
update content_bodies set title = '日日是与論 4K', description = '「日日是与論」というタイトルは、禅語「日日是好日」にオマージュを捧げたもので、2020年のコロナを経て、日常が特別な時間であることを再認識しました。観光地である与論島は、コロナ禍の影響を大きく受けましたが、自然災害や戦争を乗り越えてきた歴史も持っています。本作では、与論島に生きる様々な「いのち」を擬人化し、自然のサイクルを受け入れながら日々を繰り返す島の美しさとたくましさを表現します。これは、同じような問題を抱える離島や過疎の町、今を生きるすべての人々へのエールとなることを目指しています。' where id = 'zxBQkP81Tct8xHMnRm_Wo';
update content_bodies set title = 'Every Day is Yoron: Yoron Island, Nature Moves On, As Do We', description = 'The title "日日是与論" (Every Day is Yoron) pays homage to the Zen phrase "日日是好日" (Every day is a good day), reflecting on the gratitude for daily life, especially after experiencing the COVID-19 pandemic in 2020. Yoron Island, known for its tourism, has faced significant challenges due to the pandemic, similar to many places worldwide. The island has also endured natural disasters like typhoons and wars throughout its history. This work, featured in ART&FACTORY JAPAN, personifies various forms of life on Yoron Island, showcasing its beauty and resilience as it embraces the cycles of nature. The aim is to send a message of encouragement to other remote islands, depopulated towns, and all individuals living in the present, who face similar struggles.' where id = '3f7BO3icPnI3PtoUNZ0mi';
update content_bodies set title = '与論島へようこそ', description = '与論島は「ヨロンブルー」と呼ばれる美しい蒼い海と空に囲まれています。海底が見えるほど透き通った水は、海と空が溶け合う絶景を生み出し、訪れる人々に癒しの体験を提供します。独自の島文化や美味しい料理、温かい人々とのふれあいを通じて、特別な思い出を作ることができる、忘れられないバケーション先です。' where id = '2jOJjHio5KyIHDseyjzNw';
update content_bodies set title = 'Welcome to Paradise - YORON Island, Japan', description = 'Yoron Island, known for its stunning ''Yoron Blue'', features breathtaking blue beaches and skies. The crystal-clear waters allow you to see the ocean floor, creating a serene environment where the ocean and sky merge beautifully. Visitors can immerse themselves in the unique island culture, savor delicious local cuisine, and connect with the warm-hearted people of Yoron Island, making it an unforgettable vacation destination.' where id = 'M5fvMjOT-Ezu_Mcb1Dnqz';
update content_bodies set title = '与論島 - パラダイスでの9時から5時', description = '与論島へようこそ。ここは「ヨロンブルー」と呼ばれる美しい海と空が広がる楽園です。透き通った海水は海底が見えるほどで、海と空が溶け合う絶景が広がります。独自の島文化や美味しい食事、温かい人々との出会いが、あなたのバケーションを特別な思い出に彩ります。この理想的な目的地についてもっと知り、次の冒険を計画しましょう。' where id = 'WeYUPz-brH7IM7XNJB6aN';
update content_bodies set title = 'Nine to Five in Paradise - YORON Island, Japan', description = 'Welcome to Yoron Island, where the stunning blue beaches and skies create a paradise known as ''Yoron Blue.'' The crystal-clear waters allow you to see the ocean floor, offering a breathtaking view where the sea and sky merge. Experience the unique island culture, delicious food, and warm-hearted people that will make your vacation unforgettable. Discover more about this idyllic destination and plan your next adventure.' where id = 'pReyrkl7HCzU4cgNiEhSJ';
update content_bodies set title = '与論島 - 幸せに浸る', description = '与論島は「ヨロンブルー」と呼ばれる美しい青い海と空が広がる場所です。透き通った海水は海底まで見えるほどで、海と空が溶け合う絶景の中で癒しの体験ができます。独自の島の文化や美味しい料理、温かい人々とのふれあいを通じて、特別な思い出に彩られたバケーションを楽しむことができます。' where id = 'uV5kQRpi8FldDRko57gpr';
update content_bodies set title = 'Dive into Bliss - YORON Island, Japan', description = 'Yoron Island, known for its stunning ''Yoron Blue'', features breathtaking blue beaches and skies. The crystal-clear waters allow you to see the ocean floor, creating a serene atmosphere where the sea and sky merge beautifully. Visitors can immerse themselves in the unique island culture, savor delicious local cuisine, and connect with the warm-hearted locals, making for an unforgettable vacation experience.' where id = 'HTNLQ3vV6HsgzRVnLgmXR';
update content_bodies set title = '与論島の未開の美', description = '与論島は「ヨロンブルー」と呼ばれる美しい青い海と空に囲まれています。海底が見えるほど透き通った水は、心を癒す絶景を提供します。独自の島の文化や美味しい料理、温かい人々とのふれあいを通じて、特別な思い出に残るバケーションを体験してください。' where id = 'o2OI8-dmhqNPWEuvSEcD8';
update content_bodies set title = 'Untapped Beauty - YORON Island, Japan', description = 'Discover the stunning beauty of Yoron Island, known for its ''Yoron Blue'' - a mesmerizing blend of blue beaches and skies. The crystal-clear waters allow you to see the ocean floor, creating a serene and blissful atmosphere. Immerse yourself in the unique island culture, savor delicious local cuisine, and connect with the warm-hearted people of Yoron Island for an unforgettable vacation experience.' where id = 'eZMZ_7mMfv7nV-t488PMf';
update content_bodies set title = '船でヨロン島へ', description = '羽田空港から那覇空港、さらに那覇港（本部港経由）を経てヨロン島へ向かう方法についての情報を提供するガイドです。ヨロン島の観光に関する詳細は、提供されたリンクを参照してください。' where id = 'iIEKT3AUFBka8nEgrQLEr';
update content_bodies set title = 'Traveling to Yorontou Island by Ferry', description = 'This guide provides information on how to travel from Haneda Airport to Naha Airport, then from Naha Port (via Motobu Port) to Yorontou Island. For more details on sightseeing in Yorontou Island, visit the provided link.' where id = '3Gdws89VfrE8PD7HMY81l';
update content_bodies set title = '飛行機で行くヨロン島(羽田空港→那覇空港→ヨロン島)', description = 'この文章は、羽田空港から那覇空港を経由してヨロン島に行くための観光ガイドです。ヨロン島の観光情報やアクセス方法について詳しく知りたい方は、提供されたリンクを訪れてください。' where id = '9fk-Bz0DLNfHlr9cqfjfx';
update content_bodies set title = 'Traveling to Yorontou Island by Plane (Haneda Airport → Naha Airport → Yorontou Island)', description = 'This is a travel guide for Yorontou Island, providing information on how to reach the island via flights from Haneda Airport to Naha Airport and then to Yorontou Island. For more details, visit the provided link.' where id = 'HC-uMxtjtvs_sJisYeck-';
update content_bodies set title = '短編映画『YORON』', description = '短編映画『YORON』は、日本語字幕版があり、与論島の美しさを紹介しています。STUDIOauftriebによって制作され、キャストにはアリ・マリー、谷洋子、山下天、山崎拓典、菊千代が参加しています。監督、編集、カラーリングは根岸宏が担当し、プロデューサーは馬場宏樹、ドローンオペレーターは吉沢大和、水中カメラは佐々木宏樹、ジンバルオペレーターは磯藤が務めています。与論島についての詳細は、提供されたリンクを訪れてください。' where id = 'ShEmsLOJDGeu7K8hX5-yY';
update content_bodies set title = 'Short Film ''YORON''', description = 'The short film ''YORON'' features a Japanese subtitled version and showcases the beauty of Yoron Island. It is produced by STUDIOauftrieb and includes a talented cast such as Ali Marie, Yoko Tani, Amana Yamashita, Takunori Yamazaki, and Chiyo Kiku. The film is directed, edited, and colored by Hiroshi Negishi, with contributions from a skilled production team including producer Hiroki Baba, drone operator Yamato Yoshizawa, underwater camera operator Hiroki Sasaki, and gimbal operator Togo Iso. For more information about Yoron Island, visit the provided links.' where id = '5n2rbJGC7Sugoa07xBjzJ';
update content_bodies set title = '短編映画『YORON』ショートバージョン 日本語字幕版', description = '短編映画『YORON』のショートバージョンが日本語字幕付きで公開されています。この映画は、与論島の美しさと文化を紹介しています。制作はSTUDIOauftriebで、キャストにはアリ・マリー、谷洋子、山下天、山崎拓典、菊千代が参加しています。監督・撮影・編集・カラーグレーディングは根岸宏が担当し、ドローンオペレーターや水中カメラ専門家など、さまざまなスタッフが協力しています。与論島についての詳細は、提供されたリンクを訪れてご覧ください。また、映画のフルバージョンもYouTubeで視聴可能です。' where id = 'bancCi9DNgsN2YDfh-l4k';
update content_bodies set title = 'Short Film ''YORON'' Short edition with Japanese subtitles', description = 'The short film ''YORON'' is presented in a short edition with Japanese subtitles. It showcases the beauty and culture of Yoron Island. The film is produced by STUDIOauftrieb and features a talented cast including Ali MARIE, Yoko TANI, Amana YAMASHITA, Takunori YAMAZAKI, and Chiyo KIKU. The film is directed, shot, edited, and color-graded by Hiroshi NEGISHI, with contributions from various staff members including a drone operator and underwater camera specialist. For more information about Yoron Island, visit the provided links. A full version of the movie is also available on YouTube.' where id = '10Eup8xlXn6y3z89qFPio';
update content_bodies set title = '与論島', description = 'この動画では、与論島の美しい風景を8K HDR品質で紹介しています。視聴者は字幕をONにすることで、撮影地を確認できます。動画の監督・編集は栄川幸、撮影は松村隆、空撮は馬場基成、水中撮影はAQUA Geo Graphicが担当しています。音楽はBig Score Audioの「Passing Landscapes」です。' where id = 'Kb4kPqLWsv56Hbav7zIz7';
update content_bodies set title = 'Yoron Island Japan in 8K HDR', description = 'This video provides an overview of Yoron Island, showcasing its stunning landscapes in 8K HDR quality. Viewers are encouraged to turn on subtitles to see the locations where the footage was captured. The video is directed and edited by Yuki Eikawa, with photography by Takashi Matsumura, aerial photography by Motonari Baba, and underwater photography by AQUA Geo Graphic. The background music is ''Passing Landscapes'' by Big Score Audio.' where id = '2I_5kS7jGBHtyfLF6VtnF';
update content_bodies set title = '南阿蘇のやさしい氷2023【キャンペーン第2弾】', description = '「南阿蘇のやさしい氷プロジェクト2023」の第2弾が7月22日から始まります。第1弾に続き、かき氷に関連するオリジナルグッズが登場します。キャンペーンには「南阿蘇かき氷部　入部キャンペーン」があり、かき氷を食べてスタンプを集めることで、特製のリストバンドを受け取ることができます。また、南阿蘇観光案内所では、限定ガチャ（1回500円）を回して、キーホルダーやマスキングテープなどのオリジナルグッズを手に入れることができます。かき氷マップは7月22日から配布され、参加店舗や観光案内所で入手可能です。' where id = '_25IkgUiU8iyEn78rOZLe';
update content_bodies set title = 'Gentle Ice of Minami Aso 2023 Campaign Part 2', description = 'The ''Gentle Ice of Minami Aso Project 2023'' is back with its second campaign starting on July 22, following the first campaign that began on July 15. This year, the project features original merchandise related to kakigori (shaved ice). The campaign includes a ''Kakigori Club Membership Campaign'' where participants can join the club by eating kakigori and collecting stamps on a special map. Once they collect enough stamps, they can receive a unique wristband. Additionally, a limited gacha (500 yen per try) will be available at the Minami Aso Tourist Information Center, offering exclusive items like keychains, masking tape, and even a chance to win free kakigori vouchers. The kakigori map will be distributed starting July 22 at participating stores and tourist information centers.' where id = 'paGd4WRCeL1FjVgOh1UGv';
update content_bodies set title = '南阿蘇のやさしい氷2023【キャンペーン第1弾】', description = '「南阿蘇のやさしい氷プロジェクト2023」が7月15日（土）に始動します。今年は南阿蘇鉄道の全線開通と熊本地震震災ミュージアム「KIOKU」のオープンに合わせて、特に注目される夏となります。このプロジェクトは2019年から始まり、今年で5年目を迎えます。第1弾は「おかえり！南阿蘇鉄道キャンペーン」で、対象店舗でかき氷を食べた方に、南阿蘇鉄道の再開を記念した限定コースターをプレゼントします。数量限定のため、早めの訪問をお勧めします。続く第2弾は7月22日（土）からスタートし、かき氷マップも配布されます。今年は参加店舗が昨年の9店舗から10店舗に増え、詳細は近日公開予定です。暑い夏に、南阿蘇で自慢のかき氷を楽しみに来てください。' where id = 'R0Hyif6eAfnvFrvo2EdKQ';
update content_bodies set title = 'Gentle Ice of Minami Aso 2023 Campaign Part 1', description = 'The ''Gentle Ice of Minami Aso Project 2023'' kicks off on July 15, coinciding with the full reopening of the Minami Aso Railway and the opening of the KIOKU museum. This summer marks the fifth year of this seasonal event, which is divided into two parts. The first part, ''Welcome Back! Minami Aso Railway Campaign,'' offers a limited-edition coaster commemorating the railway''s reopening to customers who enjoy shaved ice at participating stores. Supplies are limited, so customers are encouraged to visit early. The second part will start on July 22, featuring a new shaved ice map with ten participating stores, up from nine last year. The map will be available at various locations starting July 22, with details to be announced soon. Visitors are invited to cool down with delicious shaved ice in Minami Aso this summer.' where id = 'Zsu5cTkx_ADYaNfdyYINC';
update content_bodies set title = '南阿蘇の美味しいがいっぱい！', description = '旅のお楽しみといえば、やっぱり美味しいものです。南阿蘇村には美味しいものがたくさんあり、広大な自然の中で育まれるあか牛や新鮮な野菜、果物などを堪能できます。自然の恵みを生かした食材を楽しむことができる場所です。' where id = 'wq_ZZAKxrmJ7i6NlVN56d';
update content_bodies set title = 'Delicious Delights in Minami-Aso!', description = 'One of the joys of travel is undoubtedly the delicious food! Minami-Aso Village is home to a variety of tasty offerings. Enjoy the rich flavors of the Aso beef, vegetables, and fruits that thrive in the vast natural surroundings.' where id = 'ELH6O88QxXBt1Lt4lG_MT';
update content_bodies set title = 'みなみの阿蘇さんぽ', description = '南阿蘇の魅力を知り尽くしたみなみちゃんが、いつも笑顔になれるお気に入りのスポットを巡ります。道の駅あそ望の郷くぎのやあか牛の館、見晴台駅、白川水源、白川吉見神社、白水温泉 竹の倉山荘など、各スポットは独自の体験を提供し、南阿蘇地域の美しさを際立たせています。' where id = 'ZPhIeqDOhSHTmsRo-7Wz9';
update content_bodies set title = 'Minami''s Aso Walk', description = 'Minami-chan, who knows the charms of Minami Aso, visits her favorite spots that always bring a smile to her face. The journey includes various attractions such as the Asomichi Road Station, the Akagyu Hall, the Mihara Station, the Shirakawa Water Source, the Shirakawa Yoshimi Shrine, and the Shirakawa Onsen Take no Kura Sanso. Each location offers unique experiences and highlights the beauty of the Minami Aso region.' where id = 'GAp2mtw9JaM1PCJID-qip';
update content_bodies set title = '在地紀錄片【鄉野中的日本】EP01 | 修驗道行者隱居深山打造完美治愈空間 | 奈良縣宇陀市深野', description = '今回のエピソードでは、奈良県宇陀市深野にある「笹百合庵」を訪れます。この宿は修験道行者の松林哲司氏によって設立されました。松林氏は大学時代に一人で世界を旅し、ヒマラヤの神秘に魅了されましたが、最終的には大阪で商社を経営するために故郷に戻りました。その後、理想の精神世界を追求するために修験道の僧侶となり、深山の村にある百年の古民家を改造し、修行やビジネス、世界中の旅人を迎える場所としました。彼が求める土地と居住空間は、現代の都市生活を送る人々にどのような体験を提供するのでしょうか？『鄉野中的日本』は、地域の小さなブティック宿を運営するホストに焦点を当て、彼らの理念や生活、地域とのつながりを探る在地紀録片です。' where id = 'yFvsTjlxBYok2ymNCVQY9';
update content_bodies set title = 'Local Documentary ''Japan in the Countryside'' EP01 | A Shugen-do Practitioner Creates a Perfect Healing Space in the Deep Mountains | Uda City, Nara Prefecture', description = 'In this episode, we visit ''Sasayuri-an,'' founded by Shugen-do practitioner Tetsuji Matsubayashi in the deep mountains of Uda City, Nara Prefecture. Matsubayashi has a unique life story, having traveled the world alone during his university years. Although he was captivated by the mystery and solemnity of the Himalayas, he returned to his hometown to run a trading company in Osaka. Later, in pursuit of his ideal spiritual world, he became a Shugen-do monk and transformed a century-old house in a mountain village into a place for practice, business, and welcoming travelers from around the world. What kind of land and living space does he seek, and what can modern urban dwellers experience here? ''Japan in the Countryside'' is a local documentary focusing on small boutique inns run by local hosts, exploring their philosophies, lifestyles, and connections with the community, offering a glimpse into another Japan beyond the metropolis.' where id = '0075qemqgO99wXuaf4U4P';
update content_bodies set title = '宇久島', description = '『宇久島~UKUJIMA~』は、長崎県五島列島最北端の宇久島に伝承される平家盛公の軌跡を辿る観光映像で、観光映像大賞や日本国際観光映像祭でのグランプリ、ポルトガル国際観光映像祭ART&TUR2022での3冠を達成しました。特に、観光庁長官賞を受賞した国際短編映画祭ショートショート フィルムフェスティバル & アジア2022でも評価されました。この映像は、宇久島の美しい自然と歴史的な魅力を紹介し、観光客にその魅力を伝えることを目的としています。' where id = 'YIUX-NmcLWQyIjCQ2gCBL';
update content_bodies set title = 'Ukujima', description = 'The film ''Ukujima'' has won multiple awards, including the Grand Prize at the 4th Japan International Tourism Film Festival and the 1st Prize in the Adventure & Expeditions category at the Portugal International Tourism Film Festival ART&TUR 2022. This tourism film traces the legacy of Heike Morikuni on Ukujima, the northernmost island of the Goto Islands in Nagasaki Prefecture. It has also received recognition at the Short Shorts Film Festival & Asia 2022, which is an Academy Award-accredited event. The film showcases the beautiful nature and rich history of Ukujima, inviting viewers to explore its scenic landscapes and cultural heritage.' where id = '1Iar1zc5LTYs5ibpGCezj';
update content_bodies set title = '♭ヨロン 4K', description = 'このウェブサイトは「ヨロン」を紹介し、訪問者にリラックスした形で島を体験することを促しています。一人でも仲間とでも、到着したら心配事を忘れ、温かい「おかえりなさい」という言葉で迎えられます。新しい人々との出会いがなぜか懐かしく感じられることを強調し、ヨロンを通じた旅は個々の探求として描かれています。好きな道を選び、自分のペースで進むことができます。制作には多くのアーティストや協力者が参加しており、監督・撮影は楠健太郎、演出は福島真希が担当しています。音楽は福島節が作曲し、村上美香が作詞を手掛けています。' where id = 'ZHoy6whZMtgmIyYlaWkJa';
update content_bodies set title = 'Yoron 4K', description = 'The website presents ''Yoron,'' inviting visitors to experience the island in a relaxed manner, whether alone or with others. It encourages letting go of worries upon arrival and offers a warm welcome with the phrase ''Welcome back.'' The narrative emphasizes the nostalgic feeling of meeting new people who somehow feel familiar. The journey through Yoron is depicted as a personal exploration, allowing individuals to choose their own paths. The production features various artists and collaborators, with Kenji Kusunoki as the director and cinematographer, and Maki Fukushima as the director of performance. The music is composed by Setsu Fukushima, with lyrics by Mika Murakami.' where id = 'DJiBglSa5L6hP6qck5jgz';
update content_bodies set title = 'TOR is my ROAD 4K', description = 'このタイトルは、トアロードに立ち寄った時間が、人生の道に花を咲かせるという想いを表現しています。神戸のトアロードは、モスクや中国料理店、インターナショナルスクールがあり、開港以来異文化を受け入れてきました。「風のまち」とも呼ばれ、来る人を拒まず、去る人を追わない特性を持っています。独自のカルチャーが根付いており、遠方から訪れるファンも多いです。この「南北1kmの美しい寄り道」を歩くことで、人生がユニークで豊かになることでしょう。' where id = 'QLRhRTXFDb0z1XKF7hGV1';
update content_bodies set title = 'TOR is my ROAD 4K', description = 'The title reflects the belief that any time spent on Tor Road, whether as a resident or visitor, will enrich one''s life journey. Tor Road in Kobe has embraced cultural diversity since its opening, featuring mosques, Chinese restaurants, and international schools. Known as a ''city of winds,'' it welcomes newcomers and allows departures without resistance, fostering a unique culture that attracts many visitors. Walking this beautiful 1-kilometer stretch in Kobe promises to transform lives into something unique and fulfilling.' where id = 'BrVIjXouwrRLHQ0zKqOx9';
update content_bodies set title = '日日是与論 4K_Yoron Island,Nature moves on,as do we', description = '「日日是与論 4K_Yoron Island,Nature moves on,as do we」は、第3回日本国際観光映像祭ART&FACTORY JAPANで最優秀賞を受賞した作品です。タイトルは禅語「日々是好日」に由来し、2020年のコロナ禍を経て、日常の大切さを再認識しました。与論島は観光地としてコロナの影響を大きく受けましたが、自然災害や戦争を乗り越えてきた歴史もあります。この作品では、与論島に住むさまざまな「いのち」を擬人化し、自然のサイクルを受け入れながら日々を生きる島の美しさとたくましさを表現しています。また、同じような問題を抱える離島や過疎の町、今を生きるすべての人々へのエールとなることを目指しています。' where id = 'g1VEIejHncXDkE6RBRu5-';
update content_bodies set title = 'Yoron Island: Nature Moves On, As Do We', description = 'The film ''Yoron Island: Nature Moves On, As Do We'' is a recipient of the Grand Prize at the 3rd Japan International Tourism Film Festival ART&FACTORY JAPAN. The title pays homage to the Zen phrase ''Every day is a good day,'' reflecting on the gratitude for daily life, especially after experiencing the COVID-19 pandemic in 2020. Yoron Island, known for its tourism, has faced significant challenges due to the pandemic, similar to many places worldwide. The island has also endured natural disasters like typhoons and wars. Through the personification of various lives on Yoron Island, the film expresses the island''s beauty and resilience while accepting the larger cycles of nature. It aims to inspire other remote islands and towns facing similar struggles, offering encouragement to all who live in the present.' where id = 'POtbnZikncqr9-tkmPQh1';
update content_bodies set title = 'ともにいただく Taste Tomonoura Together  -Japanese-【鞆の浦】', description = '鞆の浦は地元で「とも」と呼ばれ、「友」「朋」「共」といった響きを持つこの名は、自然との共生や家族、友人との支え合いを大切にしてきた人々の思いを表しています。本映像「時をともに」は、日本遺産に認定された鞆の浦の穏やかで優しい時間を感じさせてくれます。第二章「ともにいただく」では、瀬戸内の美味しい幸を、地元の漁師や料理人の真摯な姿を通じて紹介し、和食やイタリアンでの楽しみ方を探ります。' where id = 'OUdV5j8DtJpuGYU7BD-BA';
update content_bodies set title = 'Taste Tomonoura Together -Japanese-【Tomonoura】', description = 'In the local dialect, Tomonoura is referred to as ''Tomo,'' which resonates with the meanings of ''friend,'' ''companion,'' and ''together'' in Japanese. This name embodies the harmonious coexistence with nature and the supportive relationships among family and friends that the people of Tomonoura cherish. The video ''Together in Time'' invites viewers to return to the gentle and serene moments that characterize the Japan Heritage site of Tomonoura. In Chapter Two, ''Taste Together,'' the film showcases the dedication of local fishermen and chefs as they present the delicious bounty of the Seto Inland Sea, exploring whether to enjoy it in traditional Japanese style or Italian cuisine.' where id = 'Ya1PjWpPlMWOlqM5wE98a';
update content_bodies set title = 'ともにたのしむ Discover Tomonoura Together -Japanese-', description = '鞆の浦は地元で「鞆＝とも」と呼ばれ、自然との共生や家族・友人との支え合いを象徴する名前です。本映像「時をともに」は、日本遺産に認定された鞆の浦の穏やかで優しい時間を体験することを促します。第一章「ともにたのしむ」では、穏やかな海と自然を楽しむための10のアクティビティを紹介し、潮風を感じながら魚や鳥のように楽しむことができます。' where id = 'XxWVeMtnSl3DBD4kC3yYk';
update content_bodies set title = 'Discover Tomonoura Together -Japanese-', description = 'In Tomonoura, known locally as ''Tomo,'' the name embodies the spirit of coexistence with nature and the bonds of family and friendship. The video ''Time Together'' invites viewers to experience the gentle and serene atmosphere of this Japan Heritage site. The first chapter, ''Enjoy Together,'' introduces ten activities that allow you to connect with nature and enjoy the calm sea. Feel the sea breeze and embrace the joy of being like fish and birds.' where id = 'Sc6gZbIMqwzi5DBmO_GCX';
update content_bodies set title = 'SNOW HIKE（スノーハイク）#ベンセ湿原', description = '気軽に雪を楽しむ「スノーハイク」を体験しませんか？青森県つがる市の冬のベンセ湿原を自由に散策することができます。スキーの経験がなくても「スノーハイク」を使えばすぐに歩けるので安心です。ストレス解消や運動不足の解消にも最適で、美しい雪景色を楽しみながら心身をリフレッシュできます。' where id = 'qtdKuEckIqIVAXzcVmBB_';
update content_bodies set title = 'SNOW HIKE at Bense Wetland', description = 'Experience the joy of snow with SNOW HIKE! This activity allows you to freely stroll through the winter landscape of Bense Wetland in Tsugaru City, Aomori Prefecture. Even if you have never skied before, you can easily walk with SNOW HIKE. It''s a great way to relieve stress and combat lack of exercise while enjoying the beautiful snowy scenery.' where id = 'gijS1T-2UhLMcn9RLDR9x';
update content_bodies set title = '【AOMORI CYCLING】奥津軽ライド - OKUTSUGARU, JAPAN', description = '青森県津軽半島の最北端「龍飛崎」を目指し、自転車で奥津軽を駆け抜けるライドです。自転車持ち込み可能な「津軽鉄道」を利用し、芦野公園駅からスタートします。見どころには、千本鳥居が美しい「高山稲荷神社」、文豪・太宰治の生家「斜陽館」、黄金色の稲穂が広がる「米マイロード」、日本海を見下ろす「竜泊ライン」などがあり、風情ある漁村も楽しめます。走りごたえのあるロングライドで、青森の多様性を体感できます。映像編集の都合上、芦野公園駅から龍飛崎までの行程が一筆書きではない箇所があります。' where id = 'UAYISnmkKXeS31sINFw96';
update content_bodies set title = 'AOMORI CYCLING - OKUTSUGARU, JAPAN', description = 'This cycling adventure takes you through the northernmost tip of the Tsugaru Peninsula in Aomori Prefecture, aiming for ''Tatsudake Cape''. Starting from Ashino Park Station, accessible via the ''Tsugaru Railway'' that allows bicycles, the ride features numerous attractions. Cyclists will encounter the scenic ''Takayama Inari Shrine'' with its thousand torii gates, the birthplace of the famous author Osamu Dazai at ''Shayokan'', the beautiful golden rice fields along ''Kome My Road'', and the breathtaking views from the ''Ryuhoku Line'' overlooking the Japan Sea. The route also includes charming fishing villages, making it a fulfilling long ride experience. Note that due to editing, some sections from Ashino Park Station to Tatsudake Cape may not be in a continuous line.' where id = 'V5LVWzAdoIAx_9-RcmmC0';
update content_bodies set title = '遮光器土偶キャラ弁', description = '縄文遺跡群の世界遺産登録を、日本最古のキャラクターである遮光器土偶をテーマにしたキャラ弁でお祝いします。この取り組みは、青森県の文化や歴史を広める一環として行われており、地域の魅力を再発見する機会となっています。キャラ弁は、見た目にも楽しく、食べる楽しみを提供するだけでなく、縄文時代の遺産を次世代に伝える重要な役割を果たしています。' where id = 'oo9X-Lz_YkCqUjViYABB6';
update content_bodies set title = 'Shakōki-dōji Character Bento', description = 'The registration of the Jomon archaeological sites as a World Heritage site is celebrated with a character bento featuring Japan''s oldest character, the Shakōki-dōji.' where id = 'uJt4v58qj4bFeBHzfM-8V';
update content_bodies set title = '2020種差海岸の日の出 タイムラプス', description = '種差天然芝生地で撮影された日の出のタイムラプス動画です。太陽の光に照らされた海には、金色の道が現れます。' where id = 'oIWk64-IlgJcRP_e_TeRI';
update content_bodies set title = 'Time-lapse of Sunrise at Tanesashi Coast 2020', description = 'This is a time-lapse video of the sunrise captured at the Tanesashi Natural Grassland. A golden path appears on the sea illuminated by the sun.' where id = 'vGPWV2whhvbQMxBFbY7MO';
update content_bodies set title = '2020種差海岸 ドローン映像 Part2', description = '青森県では、美しい種差海岸をご自宅で楽しんでいただけるよう、地域の関係者の協力を得て撮影したドローン映像を公開しています。新型コロナウイルスの収束後には、国内外から多くの方々に青森県を訪れていただけることを願っています。' where id = 'D_xyVYLy-O2KKSdLKzfgq';
update content_bodies set title = 'Drone Footage of Tanesashi Coast 2020 Part 2', description = 'In Aomori Prefecture, we are releasing drone footage of the beautiful Tanesashi Coast, filmed with the cooperation of local stakeholders, so that you can enjoy it from home. We hope that after the resolution of the COVID-19 pandemic, many people from both domestic and international locations will visit Aomori Prefecture again.' where id = 'eMzJwegLac-BQ6ggZElKn';
update content_bodies set title = '2020種差海岸 ドローン映像 Part1', description = '青森県では、美しい種差海岸を自宅で楽しめるよう、地域の関係者の協力のもとで撮影したドローン映像を公開しています。新型コロナウイルスの収束後には、国内外から多くの方々に青森県を訪れていただけることを願っています。' where id = 'VGyJyk2207s7anG0zKCDR';
update content_bodies set title = 'Drone Footage of Tanesashi Coast 2020 Part 1', description = 'In Aomori Prefecture, drone footage of the beautiful Tanesashi Coast has been released with the cooperation of local stakeholders, allowing you to enjoy it from home. After the resolution of the COVID-19 pandemic, we hope to welcome many visitors from both domestic and international locations back to Aomori Prefecture.' where id = 'UnWFGnSIpMIjF7fyTPFQV';
update content_bodies set title = 'DELISH AOMORI「ふかうら雪人参のポタージュ」', description = 'まるごと青森が提供するレシピ動画「DELISH AOMORI」の第11弾では、深浦町で栽培される「ふかうら雪人参」を使用しています。このポタージュスープは、野菜とは思えないフルーティーな甘みを活かしつつ、人参本来の風味を楽しむことができる一品です。ぜひお試しください。「DELISH AOMORI」はまるごと青森のFacebookで随時公開されています。' where id = 'XVI6KSpjoY03OUC36_Ezq';
update content_bodies set title = 'DELISH AOMORI ''Fukaura Snow Carrot Potage''', description = 'The 11th installment of the recipe video series ''DELISH AOMORI'' showcases the ''Fukaura Snow Carrot'' grown in Fukaura Town, Aomori. This potage soup highlights the carrot''s fruity sweetness while allowing the natural flavor of the carrot to shine through. It''s a delicious way to enjoy this unique vegetable. Be sure to give it a try! ''DELISH AOMORI'' is regularly published on the Marugoto Aomori Facebook page.' where id = 'UGhFEPzb8kQ4gEP77lJaW';
update content_bodies set title = 'DELISH AOMORI「美味しい土鍋ごはんの炊き方」', description = 'まるごと青森が提供するレシピ動画「DELISH AOMORI」の第7弾です。平川市で収穫された青森の特A米「青天の霹靂」を土鍋でふっくらと炊き上げ、青森の名物である筋子を添えました。「DELISH AOMORI」は、まるごと青森のFacebookで随時公開されています。' where id = 'mOBMa25b7L0bjsHwV8H70';
update content_bodies set title = 'DELISH AOMORI: How to Cook Delicious Donabe Rice', description = 'This is the seventh installment of the recipe video series ''DELISH AOMORI,'' brought to you by the whole of Aomori. In this episode, we showcase how to cook the premium A rice, ''Seiten no Hekireki,'' harvested in Hirakawa City, using a donabe (Japanese clay pot) to achieve fluffy rice. We also serve it with ''sujiko,'' a local delicacy from Aomori. ''DELISH AOMORI'' videos are regularly published on the Marugoto Aomori Facebook page.' where id = 'hBS4G4wtyzs6z7-X1PS7O';
update content_bodies set title = 'ねぶたの家 ワ・ラッセ', description = '青森市にある文化観光交流施設「ねぶたの家 ワ・ラッセ」では、ねぶた祭の歴史や魅力を余すところなく紹介しています。訪れる人々は、ねぶたのすべてを体感できる夢のような空間を楽しむことができます。' where id = '7X8_lHJqJKiQs1oRx9G5d';
update content_bodies set title = 'Nebuta House Wa Rasse', description = 'Nebuta House Wa Rasse is a cultural and tourism exchange facility located in Aomori City. It thoroughly introduces the history and charm of the Nebuta Festival, providing a dream space where visitors can experience everything about Nebuta.' where id = 'aZbiMNGlLWNon9y0uC445';
update content_bodies set title = 'Go Slow SAGA, Japan - 豊かな自然 -', description = '佐賀市の魅力を紹介する動画です。撮影場所には、レンタサイクルが利用できる21世紀県民の森、下合瀬の大カツラ、巨石パーク、むおんキャンプ、テントサウナ、新北神社が含まれています。また、カヤック体験ができるsagasowも紹介されており、九州の美しい自然の中で楽しめる多様なアウトドアアクティビティが強調されています。' where id = 'QGrwXeEnPL4MRl60QcA-H';
update content_bodies set title = 'Go Slow SAGA, Japan - rich nature -', description = 'Discover SAGA City, known for its rich natural beauty. The video showcases various shooting locations, including the 21st Century Citizens'' Forest, where you can rent bicycles, the giant Katsura tree at Shimoawase, the Giant Stone Park, Muon Camp, a tent sauna, and the Shin-Kitakami Shrine. Additionally, it features kayaking experiences at sagasow, highlighting the diverse outdoor activities available in this picturesque region of Kyushu.' where id = 'F36t7WmjLhyXYsNqIIiz3';
update content_bodies set title = 'Go Slow SAGA, Japan - 地元の食べ物 -', description = '佐賀市の地元料理と文化を紹介する動画です。シェ・ハイジでの地元料理や、木漏れ陽での蕎麦打ち体験など、さまざまな撮影場所が紹介されています。他にも、ボートハウスシノハラでのワカサギ釣り、佐賀ラーメンいちげんでのラーメン、和紅茶専門店の紅葉などが登場します。また、新北神社やシャトー文雅も訪れ、九州・佐賀の地元のライフスタイルや観光名所を垣間見ることができます。' where id = 'LJpB0nH4VGXbxo1NuVtd1';
update content_bodies set title = 'Go Slow SAGA, Japan - local food -', description = 'Discover SAGA City, a place rich in local cuisine and culture. The video showcases various shooting locations, including She Haiji, where you can enjoy local dishes, and Komorebi, known for its soba-making experience. Other highlights include fishing for wakasagi at Boat House Shinohara, savoring Saga ramen at Ichigen, and visiting the specialty tea shop, Kouyou. The video also features the historic Shin-Kitakami Shrine and Chateau Bunga, providing a glimpse into the local lifestyle and attractions in Saga, Kyushu.' where id = 'tL0rb1OJ093_q6r59cKnh';
update content_bodies set title = '『EVで島をMOTTO元気にプロジェクト』 新入社員研修 in 式根島 【東日本三菱自動車販売株式会社】', description = '2024年4月18日から20日の3日間、東日本三菱自動車販売株式会社は、昨年に続き新入社員研修を東京都新島村の式根島で開催しました。この活動は、自然災害による停電復旧のためのBCP対策として、三菱自動車の中古電気自動車と外部給電装置の普及を目指しています。研修前日には新島村役場を訪問し、村長との連携を深めました。研修では、東京電力パワーグリッドの参加により、島の生活と電気自動車の重要性を理解しました。また、環境省や地元商工会の協力でビーチクリーン活動も実施しました。東日本三菱は、式根島のBCP強化に向けて外部給電器を寄贈し、地域の安全・安心に寄与する企業を目指しています。' where id = 'LGU-fnwuJSbrTBtg5F6T7';
update content_bodies set title = 'EV for a More Vibrant Island Project - New Employee Training in Shikine Island by East Japan Mitsubishi Motors Sales Co., Ltd.', description = 'From April 18 to April 20, 2024, East Japan Mitsubishi Motors Sales Co., Ltd. held new employee training on Shikine Island, Tokyo, continuing from the previous year. This initiative addresses the social issue of insufficient infrastructure for power restoration in island regions affected by natural disasters, as part of BCP measures. The project, named ''EV for a More Vibrant Island Project,'' aims to promote the use of used electric vehicles and external power supply devices in collaboration with Tokyo Electric Power Grid Co., Inc. The training included a courtesy visit to the Shikine Village Office, where discussions with Mayor Onuma deepened ties with the local government. Participants gained insights into the importance of electric vehicles in island life, and a beach cleanup activity was conducted with support from the Ministry of the Environment and local organizations. East Japan Mitsubishi donated external power supply devices to the local commerce association to support the community''s BCP efforts and aims to contribute to the safety and security of island residents through the promotion of electric vehicles.' where id = 'MAVz534QH8Cnh76OQWvdP';
update content_bodies set title = '前浜のニイジマ・ヴェロタクシー_210411', description = '旧車とのコラボレーションが行われています。' where id = '6zj0M3pVnyxR-EjLot3eK';
update content_bodies set title = 'Niijima Vero Taxi in Maehama_210411', description = 'Collaboration with classic cars.' where id = 'Vdj8ROMGbn241G04Oj8aS';
update content_bodies set title = 'いつかまた訪れたい佐賀市', description = 'この動画では、日本の佐賀市の美しい景観とさまざまなアトラクションを紹介しています。主な内容には、佐賀インターナショナルバルーンフェスタ、カヤック、三瀬どんぐり村、サイクリング、梶ヶ野里公園、農家民宿ツアー、佐賀城歴史館、ボート、筑後川リフト橋、そして有明海の風景が含まれています。この動画は、視聴者に佐賀でのユニークな体験を探求することを促すことを目的としています。' where id = 'OJJP84PMnV4cfTXxLye_q';
update content_bodies set title = 'Visit Someday Saga City, Japan in 4K', description = 'This video showcases the beautiful Saga City in Japan, highlighting various attractions and activities. Key features include the Saga International Balloon Fiesta, kayaking, Mitsuse Donguri Village, cycling routes, Kajikanosato Park, farm inn tours, the Saga Castle History Museum, boat rides, the Chikugo River Lift Bridge, and the scenic Ariake Sea. The video aims to inspire viewers to explore these unique experiences in Saga.' where id = 'dB4SsyYEzTsbtQxu6n9IA';
update content_bodies set title = '新島ミライプロジェクト', description = '2021年春、新島ミライプロジェクトは東京の新島において、島内全家庭のプラスティック洗濯バサミを、くさや型のアルミ製洗濯バサミ「HOSSY」に交換することを目指しています。この取り組みは、島の重要な産業であるくさやを身近に感じてもらい、壊れない洗濯バサミに交換することでプラスティックゴミを減らすことを目的としています。島の人々が自然環境への影響を考える機会を創出し、東京宝島や企業との連携、クラウドファンディングを通じて多くの人々の参加を促進したいと考えています。最終的には、この取り組みを東京の11の島全体、さらには日本の他の島々へ広げることを目指しています。目標は、日本の食文化への理解を深め、環境問題への気づきを促すことです。' where id = 'H3pOK8101_fC--sC05qCa';
update content_bodies set title = 'Shinjima Mirai Project', description = 'In spring 2021, the Shinjima Mirai Project aims to replace plastic laundry clips in every household on Shinjima Island, Tokyo, with aluminum laundry clips shaped like ''kusaya''. This initiative seeks to promote awareness of the island''s important industry, kusaya, while encouraging a lifestyle that reduces plastic waste by providing durable alternatives. The project emphasizes the need for the island''s residents to consider their impact on the natural environment, given the island''s development has been supported by the sea. The project plans to collaborate with Tokyo''s Treasure Island and various companies, as well as conduct crowdfunding to engage more people. The goal is to expand this initiative to all 11 islands in the Tokyo archipelago and eventually to other islands in Japan. The project has two main objectives: to enhance understanding of Japanese food culture through ''kusaya'' and to create awareness of environmental issues through unique initiatives, embodying the concept of an ''Eco-Island''.' where id = 'w0Su2RrNFcmJCFHk0wopa';
update content_bodies set title = '【秋田市プロモーションビデオ④】よそものを大切にしてくれるまち「式田」ショートバージョン', description = '雄物川が運んだ文化が花開く「新波」と、秋にはこがね色の絨毯が広がる里「式田」を描いた映像です。秋田市のシティプロモーションモデル事業の一環として、地域住民が主体となって見つけたそれぞれの地区の魅力を詰め込んでいます。お金より大事な何かを探しに来た写真家や、長年の夢を追いかけるサラリーマン、笑顔を運ぶ学生たちが、まちに受け入れられ、大切にされる様子が描かれています。秋田市河辺・式田で、彼らは大切なことを見つけました。' where id = '7QvsSuseUe_0eIn0JP8zj';
update content_bodies set title = 'Akita City Promotion Video ④: A Town That Values Outsiders - Shikida (Short Version)', description = 'Shikida, where the culture brought by the Omorogawa River flourishes, is depicted in this short video. In autumn, the area transforms into a golden carpet. This video is part of Akita City''s city promotion model project, showcasing the unique charms discovered by local residents through workshops. Photographers seeking something more valuable than money, salarymen chasing long-held dreams, and students bringing smiles all find a warm welcome in Shikida. The town embraces and cherishes them, allowing them to discover what truly matters.' where id = 'a8hSpNGW7CNNvCgMFZTe2';
update content_bodies set title = 'さくら便り　千秋公園', description = '千秋公園は秋田市民の憩いの場です。毎年春になると、約700本の桜が見事に咲き誇ります。公園内のどの場所でも、桜の美しさを楽しむことができます。' where id = 'xoK-BuplBQttVtcH64LmW';
update content_bodies set title = 'Sakura Report: Chishū Park', description = 'Chishū Park is a place of relaxation for the citizens of Akita. Every spring, approximately 700 cherry blossom trees bloom beautifully. Enjoy the stunning cherry blossoms that harmonize perfectly with any spot in the park.' where id = '9kTbr7NiEaJ6U-Vit7-xi';
update content_bodies set title = '平成最後の土崎港曳山まつり', description = '7月20日と21日に行われた土崎港曳山まつりでは、クライマックスとしていくつかの町内が交差点で勢いよく方向転換する『曳き回し』が行われました。巨大な曳山を曳子たちが力を合わせて旋回させるシーンは壮観で、平成最後の二日間はまさにゲ・キ・ア・ツな体験でした！' where id = '7YtMxZs_He9lx19XyUKh6';
update content_bodies set title = 'Last Tsuchizaki Port Hikiyama Festival of the Heisei Era', description = 'The Tsuchizaki Port Hikiyama Festival took place on July 20 and 21. The climax featured the ''hikimawashi,'' where several neighborhoods made sharp turns at intersections with their massive hikiyama floats. The scene of the participants working together to maneuver the giant floats was truly spectacular. It was an intense and memorable two days marking the end of the Heisei era!' where id = 'k0KHmaHwy5ZI2omOPtTtv';
update content_bodies set title = '秋田竿燈まつり', description = '秋田市の夏の夜空を彩る竿燈は、光の稲穂の輝きと、竿燈を操る差し手の妙技が見どころです。その美しさや迫力に圧倒されること間違いなしです。ぜひ、8月には秋田竿燈祭りにお越しください。' where id = 'KiStjNRvNYuVLdM-5Fv_N';
update content_bodies set title = 'Akita Kanto Festival', description = 'The Kanto Festival lights up the summer night sky of Akita City with its stunning lanterns. The brilliance of the light resembling rice ears and the skillful handling of the lanterns by the performers are sure to leave you in awe. Be sure to visit the Akita Kanto Festival in August!' where id = '0FfvJUvjAmjONLUA117kv';
update content_bodies set title = '伝統の技　秋田の竿燈', description = '秋田竿燈まつりは、国の重要無形民俗文化財であり、東北三大祭りの一つとして知られています。この祭りは毎年8月3日から6日まで、秋田市の竿燈大通りで開催されます。参加者たちは、力強さと技術を駆使して竿燈を巧みに操り、秋田市の夜空を黄金色に彩る幻想的な光の稲穂を作り出します。この美しい光景は、一度は秋田で体験する価値があります。' where id = 'uvtcXMWwQT5NKzLgdWqKu';
update content_bodies set title = 'Traditional Craft: Akita Kanto', description = 'The Akita Kanto Festival is an important intangible folk cultural asset and is one of the three major festivals in the Tohoku region. It takes place annually from August 3rd to 6th on Kanto Street in Akita City. The festival showcases the skillful techniques of the participants who manipulate the Kanto (lantern poles) with strength and precision, creating a magical landscape of golden rice ears that illuminate the night sky of Akita City. This enchanting spectacle is a must-see.' where id = '1-eCTnGyCZuRga5z2nhjT';
update content_bodies set title = '秋田市観光プロモーション動画「ライフ・イズ・ジャーニー」本編', description = '「ライフ・イズ・ジャーニー」は、秋田市に住む夫婦の視点で描かれた観光プロモーション動画です。『人生とは旅である』というテーマのもと、好奇心を持って日々を過ごし、小さな発見を通じて日常をより輝かせることを提案しています。秋田市には多くの人々の『好き』が詰まっており、視聴者にその魅力を旅してみることを促しています。動画には、施設紹介編や30秒の短編、主人公目線の観光地を紹介するInstagramアカウントなどのリソースも用意されています。地元市民の協力を得て制作され、テーマソングはhalosの「君を呼ぶ声」です。' where id = 'qoC_pEm2nBLSHNi8JfpQ9';
update content_bodies set title = 'Akita City Tourism Promotion Video ''Life is Journey'' Full Version', description = 'The tourism promotion video ''Life is Journey'' is a drama-style presentation viewed through the eyes of a couple living in Akita City. It emphasizes the idea that ''life is a journey'' and encourages viewers to live each day with curiosity, discovering small joys that make everyday life more vibrant. The video invites you to explore Akita City, filled with the ''likes'' of many people. Additional resources include a facility introduction video, a short 30-second clip, and an Instagram account showcasing tourist spots and landscapes from the protagonist''s perspective. The project is supported by local citizens and features a theme song by halos.' where id = 'MeBa9qIWKI0GYA25LNgYI';
update content_bodies set title = '秋田市観光プロモーション動画「ライフ・イズ・ジャーニー」施設紹介編', description = '秋田市に住む夫婦の目線で描かれた観光プロモーション動画「ライフ・イズ・ジャーニー」の施設紹介編では、四季折々の観光スポットが紹介されます。登場するスポットには、秋田県立美術館や秋田市民市場、あきた文化産業施設「松下」、千秋公園などが含まれています。公園や歴史的な場所、地元の料理など、秋田市の魅力を幅広く紹介しており、約15分の本編と30秒の短編が用意されています。特設Instagramや秋田市の観光情報サイトでも詳細が確認できます。' where id = 'fMoJ4zpBJvO-e4IeYfDmN';
update content_bodies set title = 'Akita City Tourism Promotion Video ''Life is Journey'' Facility Introduction Edition', description = 'The tourism promotion video ''Life is Journey'' is presented from the perspective of a couple living in Akita City. The Facility Introduction Edition showcases various tourist spots throughout the four seasons. Featured locations include the Akita Prefectural Museum, Museum Café & Shop Kofu, Akita City Citizen Market, Akita Cultural Industry Facility ''Matsushita'', and many more. The video highlights attractions such as parks, historical sites, and local cuisine, providing a comprehensive view of what Akita City has to offer. The full version of the video is approximately 15 minutes long, while a short version is about 30 seconds. Additional information can be found on the special Instagram page and the Akita City tourism website.' where id = 'agqeV7npSi3ozmR_Y9NR2';
update content_bodies set title = '秋田市観光宣伝動画「人生は旅」', description = '「人生は旅」という短編動画は、秋田市に住む夫婦の日常を描いています。彼らの視点から、毎日が好奇心に満ちた冒険であり、小さな発見が日常を輝かせることを強調しています。秋田市には多くの人々が愛する体験があり、視聴者にもぜひ訪れてみてほしいと呼びかけています。本編は約15分、施設紹介編は約5分です。出演は劇団蕨座で、テーマ曲はhalosの「君を呼ぶ声」です。このプロジェクトは秋田市民の協力を得て、秋田市と株式会社Visual Spaceによって制作されました。' where id = 'OSX1SLuKHejRbrRj4toe3';
update content_bodies set title = 'Akita City Tourism Promotional Video ''Life is a Journey''', description = 'The short film ''Life is a Journey'' depicts the daily life of a couple living in Akita City, showcasing their perspective on life. It emphasizes the idea that each day can be an adventure filled with curiosity and small discoveries that brighten everyday life. Akita City is rich in experiences that many people love, inviting viewers to explore the area themselves. The main film is approximately 15 minutes long, and there is a facilities introduction segment that lasts about 5 minutes. The production features the Warabiza theater troupe and includes the theme song ''Kimi wo Yobu Koe'' by halos. The project is supported by the citizens of Akita City and produced by Akita City and Visual Space Co., Ltd.' where id = 'ku2zmsk5S7KFtAe8Qk1nW';
update content_bodies set title = '秋田市観光宣伝映画「人生は旅」', description = '「人生は旅」は、秋田市に住む夫婦の視点から日常生活を描いた短編映画です。好奇心を持って毎日を過ごし、小さな発見が日常を輝かせる様子が表現されています。この映画は、秋田市の魅力を伝え、地元の文化や観光地を体験することを視聴者に促しています。本編は約15分、施設紹介は約5分の内容です。出演は劇団蕨座、テーマ曲はhalosの「君を呼ぶ声」です。制作は秋田市と株式会社Visual Spaceで、地元市民の協力も得ています。' where id = 'BmPLzL7a7gmIxPBhO7Sgy';
update content_bodies set title = 'Akita City Tourism Promotional Film ''Life is a Journey''', description = 'The short film ''Life is a Journey'' presents the perspective of a couple living in Akita City, showcasing their daily life as a journey filled with curiosity and small discoveries that brighten their routine. The film invites viewers to explore the many things to love about Akita City, encouraging them to experience the local culture and attractions. The main film is approximately 15 minutes long, and there is a facilities introduction segment of about 5 minutes. The film features the theater group Warabiza and the theme song ''Kimi wo Yobu Koe'' by halos. It is produced by Akita City and Visual Space, with contributions from local citizens.' where id = 'ARkjzYsEaAIn1YQvQndcO';
update content_bodies set title = '秋田市観光宣伝映像「人生は旅」', description = '「人生は旅」と題されたこの観光宣伝映像は、秋田市に住む夫婦の視点から描かれた短編ドラマです。毎日を好奇心を持って過ごすことで、日常生活がより輝くことを強調しています。秋田市には多くの人々が愛するものがあり、視聴者を地元の「旅」に誘います。映像は約15分の長さで、約30秒の短編も用意されています。出演は劇団蕨座、テーマ曲はhalosの「君を呼ぶ声」で、秋田市民の協力を得て制作され、秋田市と株式会社Visual Spaceが手掛けています。' where id = 'CQwuTsPegnPTsmluvxuat';
update content_bodies set title = 'Akita City Tourism Promotional Film ''Life is a Journey''', description = 'The promotional film ''Life is a Journey'' presents a short drama from the perspective of a couple living in Akita City. It emphasizes the idea that each day can be an adventure filled with curiosity, making everyday life shine with small discoveries. Akita City is rich in things that people love, inviting viewers to explore the area as if they were on a journey. The film is approximately 15 minutes long, with a short version of about 30 seconds available. The project features the theater group Warabiza, with the theme song ''Kimi wo Yobu Koe'' performed by halos, and is supported by the citizens of Akita City, produced by Akita City and Visual Space Co., Ltd.' where id = 'Xir5-QLVRhx4xF3em_ppJ';
update content_bodies set title = '秋田市観光宣伝映像「人生は旅」', description = '「人生は旅」と題されたこの観光宣伝映像は、秋田市に住む夫婦の日常を描いた短編劇です。毎日を好奇心を持って過ごすことで、日常生活がどのように輝くかを表現しています。秋田市には多くの人々が愛する魅力が詰まっており、視聴者にもぜひ訪れてみてほしいと呼びかけています。映像には約5分の施設紹介と約30秒の短編があり、リンクから視聴可能です。出演は劇団蕨座、テーマ曲はhalosの「君を呼ぶ声」で、地元市民の協力を得て、秋田市と株式会社Visual Spaceが制作しました。' where id = 'jOyMocw6Aep8VhR4ymDQy';
update content_bodies set title = 'Akita City Tourism Promotional Film ''Life is a Journey''', description = 'The promotional film ''Life is a Journey'' depicts the daily life of a couple living in Akita City, showcasing their experiences and discoveries. It emphasizes the idea that each day can feel like a journey filled with curiosity and small wonders that brighten everyday life. Akita City is rich in attractions that many people love, inviting viewers to explore the area themselves. The film includes a 5-minute facility introduction and a 30-second short version, both available through provided links. The project features the theater group Warabiza and the theme song ''Kimi wo Yobu Koe'' by halos, with support from local citizens and produced by Akita City and Visual Space.' where id = '_ufGijersmnDwBB0ZHysh';
update content_bodies set title = '秋田市観光宣伝動画「人生は旅」', description = '「人生は旅」というタイトルのこの動画は、秋田市に住む夫婦の視点から描かれた短編ドラマです。毎日を好奇心を持って過ごすことで、日常生活がより輝くことを強調しています。秋田市には多くの人々が愛するものがあり、視聴者に地元の魅力を探求することを促しています。動画には約5分の施設紹介と約30秒の短編が含まれており、リンクから視聴可能です。出演は劇団蕨座、テーマ曲はhalosの「君を呼ぶ声」で、地元市民の協力を得て、秋田市と株式会社Visual Spaceが制作しました。' where id = 'ZZjfpJVL6vgr5V_fOdph2';
update content_bodies set title = 'Akita City Tourism Promotion Video ''Life is a Journey''', description = 'The video ''Life is a Journey'' presents a short drama from the perspective of a couple living in Akita City. It emphasizes the idea that each day can be an adventure filled with curiosity, making everyday life shine with small discoveries. Akita City is rich in things that people love, inviting viewers to explore and experience the local charm. The video includes a 5-minute facility introduction and a 30-second short version, both available through provided links. The production features the Warabiza theater group and the theme song ''Kimi wo Yobu Koe'' by halos, with support from local citizens and produced by Akita City and Visual Space Co.' where id = 'uFC1Th5alvtZmxNV9Mzwy';
update content_bodies set title = '名古屋の春', description = 'コロナ禍で観光が停止している中、早春の名古屋の美しさを感じてもらうために、春の精に誘われるイメージで動画を制作しました。乾杯のシーンでは、在日ベトナム学生青年協会東海支部のメンバーにご協力いただきました。' where id = 'E69ESguTlN4jaMmEqdlkY';
update content_bodies set title = 'Spring in Nagoya', description = 'In the midst of the COVID-19 pandemic, which has halted tourism, a video was created to showcase the beauty of early spring in Nagoya, inspired by the essence of spring. The scene featuring a toast was made possible with the cooperation of members from VYSA Tokai, the Vietnamese Youth and Student Association in the Tokai region.' where id = 'npYH9bwh8G1wvk-f7Z1jv';
update content_bodies set title = '名古屋神社めぐり旅', description = '愛知県は日本一の神社仏閣の数を誇ることをご存じでしょうか？その中でも名古屋市内には700以上の神社が存在しています。神社はその地域の歴史と深く結びついており、さまざまな物語を楽しむことができます。観光名所や施設だけでなく、名古屋の街中に点在する神社を巡ってみるのはいかがでしょうか。' where id = 'a_BNVxlZhnsuEzjQb_dCP';
update content_bodies set title = 'Nagoya Shrine Tour', description = 'Did you know that Aichi Prefecture has the highest number of shrines and temples in Japan? In this area rich with religious sites, there are over 700 shrines located within Nagoya city. These shrines are deeply connected to the local history and offer various stories to explore. Besides popular tourist attractions, why not take a tour of the shrines scattered throughout the city of Nagoya?' where id = 'LuEpO3n0c2JlSnetPaa_y';
update content_bodies set title = 'RAKUGO DE NAGOYA', description = '日本の伝統芸能「RAKUGO」による名古屋観光PR動画です。「楽しい街、行きたくなる街 NAGOYA」の魅力を十分に紹介しています。おじいさんと孫が名古屋を旅する楽しいストーリーをお楽しみください！' where id = '2bPJg0RI3y3gd2pgNQc77';
update content_bodies set title = 'RAKUGO DE NAGOYA', description = 'This is a promotional video for tourism in Nagoya featuring traditional Japanese performance art, RAKUGO. It thoroughly introduces the attractions of Nagoya, a city that invites visitors to enjoy its delightful streets. The video presents a fun story of a grandfather and his grandson traveling around Nagoya.' where id = 'F2fdljvoDJcFCkQ_Cpb2v';
update content_bodies set title = 'COOL！NAGOYA NEWS（アーカイブ）', description = '釜山の皆さん、こんにちは！このライブ配信では「新しいNAGOYA」と「楽しいNAGOYA」を紹介します。視聴後には、きっとNAGOYAに行きたくなることでしょう。なお、クイズの回答は2022年2月17日をもって終了しています。配信内容には、オープニング、GOLDSTAYOSUホテルの紹介、中部電力MIRAIタワー、東山動植物園、BUCYO COFFEE、名古屋の名物菓子の紹介などが含まれています。皆様の視聴と参加をお待ちしております！紹介スポットや名古屋観光サイトへのリンクも掲載されています。' where id = 'n6My0mXXxjkeQgPNxlPiQ';
update content_bodies set title = 'COOL！NAGOYA NEWS (ARCHIVE)', description = 'Hello everyone in Busan! This live broadcast introduces ''New NAGOYA'' and ''Fun NAGOYA.'' After watching, you will surely want to visit NAGOYA! Please note that the quiz answers ended on February 17, 2022. The broadcast includes various segments such as an opening, highlights of GOLDSTAYOSU hotel, Chubu Electric MIRAI Tower, Higashiyama Zoo, and BUCYO COFFEE, along with a presentation of Nagoya''s famous sweets. We look forward to your viewing and participation! For more information, visit the provided links to the featured spots and the official Nagoya tourism site.' where id = 'Zo-8mNsZKnI_TG4m0Y95R';
update content_bodies set title = '名古屋のプロモーション動画「COOL! NAGOYA」【ウェルネス】', description = '名古屋の「伝統」と「近未来」が融合したプロモーション動画「COOL! NAGOYA」が完成しました。この動画では、名古屋の豊かな歴史、美味しい食、活気あるナイトライフ、ウェルネス、アミューズメントなどの魅力を紹介しています。音楽は名古屋出身のDJ/プロデューサーYamatoによるオリジナルのエレクトロニック・ダンスミュージックが使用されています。熱田神宮や東山動植物園などの名所や文化的なパフォーマンスが登場し、視聴者に名古屋の魅力を楽しんでもらうことを目的としています。撮影は新型コロナウイルス感染症対策に配慮して行われました。' where id = '11989b70D6TM_duPAVYiY';
update content_bodies set title = 'Nagoya City Promotion Movie, “COOL! NAGOYA” 【WELLNESS】', description = 'A new promotional movie titled ''COOL! NAGOYA'' has been completed, showcasing the unique blend of traditional and futuristic attractions in Nagoya. The film highlights the city''s rich history, delicious food, vibrant nightlife, wellness options, and amusement activities, all set to original electronic dance music composed by Yamato. The video features various locations, including Atsuta-Jingu Shrine, Higashiyama Zoo and Botanical Garden, and local cultural performances. The production adhered to strict infectious disease measures to ensure safety. Viewers are encouraged to enjoy the captivating sights and sounds of Nagoya.' where id = '_-U89IQg-D9rXgfh-6-3N';
update content_bodies set title = '名古屋のプロモーション動画「COOL! NAGOYA」【FOOD】', description = '名古屋の伝統と近未来的な魅力を融合させたプロモーション動画「COOL! NAGOYA」が完成しました。この動画では、名古屋の豊かな歴史、多様な食文化、活気あるナイトライフを紹介し、名古屋発祥の和楽器「大正琴」の音色を取り入れたDJ/プロデューサーYamatoによるオリジナルのエレクトロニック・ダンスミュージックに乗せて展開されます。コメダ珈琲店や寿司店、柳橋中央市場、味噌カツやひつまぶしなどの名物料理が登場します。新型コロナウイルス感染症対策を徹底して撮影されており、安全に楽しめる内容となっています。名古屋の魅力をぜひご堪能ください。' where id = 'MbWnGIeUtgkjsDHO2iAHz';
update content_bodies set title = 'Nagoya City Promotion Movie, “COOL! NAGOYA” 【FOOD】', description = 'A new promotional movie titled ''COOL! NAGOYA'' has been completed, showcasing the unique blend of traditional and futuristic attractions in Nagoya. The film highlights the city''s rich history, diverse food offerings, and vibrant nightlife, all set to original electronic dance music composed by Yamato. Key locations featured include Komeda Coffee, various sushi spots, Yanagibashi Central Market, and popular dishes like misokatsu and hitsumabushi. The video was produced with strict measures to prevent infectious diseases, ensuring a safe viewing experience. Viewers are encouraged to enjoy the culinary delights and cultural experiences that Nagoya has to offer.' where id = '15MzDiCEVj_odhTsDo98d';
update content_bodies set title = '名古屋市プロモーションムービー「COOL! NAGOYA」【HISTORY】', description = '名古屋の伝統と近未来的な魅力を融合させたプロモーションムービー「COOL! NAGOYA」が完成しました。この動画では、名古屋の豊かな歴史、美味しい食、そして活気あるナイトタイム観光スポットを紹介しています。音楽は名古屋発祥の和楽器「大正琴」を取り入れ、DJ/プロデューサーのYamatoが作曲したオリジナルのエレクトロニック・ダンスミュージックに乗せてお届けします。名古屋大仏（桃巌寺）、名古屋城、徳川園、トヨタ産業技術記念館などの名所が登場します。撮影は新型コロナウイルス感染症対策を徹底して行われました。名古屋の魅力をぜひお楽しみください。' where id = 'p870hIiigUMZFMyKKFE7j';
update content_bodies set title = 'Nagoya City Promotion Movie, “COOL! NAGOYA” 【HISTORY】', description = 'A new promotional movie titled ''COOL! NAGOYA'' has been completed, showcasing the unique blend of traditional and futuristic attractions in Nagoya. The film highlights the city''s rich history, delicious food, and vibrant night-time sightseeing spots, all set to original electronic dance music composed by Yamato. Key locations featured include the Nagoya Buddha at Toganji Temple, Nagoya Castle, Tokugawaen Garden, and the Toyota Commemorative Museum of Industry and Technology. The production adhered to strict infectious disease measures to ensure safety during filming. Viewers are encouraged to enjoy the captivating sights and sounds of Nagoya.' where id = '5JMal78Kojpv5jTE9JfY9';
update content_bodies set title = '名古屋市プロモーションムービー「COOL! NAGOYA」【ナイトタイム】', description = '名古屋の「伝統」と「近未来」が融合した新しいプロモーション動画「COOL! NAGOYA」が完成しました。この動画では、名古屋の豊かな歴史、美味しい食、そして活気あるナイトタイム観光スポットを紹介しています。名古屋発祥の和楽器「大正琴」の音色を取り入れたDJ/プロデューサーYamatoによるオリジナルのエレクトロニック・ダンスミュージックに乗せて、名古屋の空撮や栄中心部、名古屋港クルーズなどの名所を映し出しています。撮影は新型コロナウイルス感染症対策に留意して行われました。ぜひ名古屋の魅力を楽しんでください。' where id = '2hIH-FtmN0_1HR_nlbKaq';
update content_bodies set title = 'Nagoya City Promotion Movie, “COOL! NAGOYA” 【NIGHT TIME】', description = 'A new promotional movie titled ''COOL! NAGOYA'' showcases the unique blend of traditional and futuristic attractions in Nagoya. The film highlights the city''s rich history, delicious food, and vibrant night-time sightseeing spots, all set to original electronic dance music composed by Yamato, featuring the sounds of the traditional Japanese instrument, Taishōgoto. The video includes aerial views of Nagoya, the bustling Sakae area, and various landmarks such as the Chubu Electric Power MIRAI TOWER, Oasis21, and Nagoya Port Cruise. The production adhered to strict infectious disease measures to ensure safety during filming. Viewers are encouraged to enjoy the captivating sights and sounds of Nagoya.' where id = 'Fvpbr-HEvsO7tBp9sIdHI';
update content_bodies set title = 'TRAVEL ROUTINE 名古屋 & 犬山 〈分散型旅行〉', description = '出張で訪れた名古屋で、気になっていたスポットを巡る女子一人旅を紹介しています。朝、ホテルで目覚めてから始まるこのモデルコースでは、名古屋と犬山をまるまる1日楽しむことができます。名古屋の魅力を存分に味わうために、早起きして出かけてみませんか。' where id = 'qIAhHq7GshWe756yYt-RW';
update content_bodies set title = 'TRAVEL ROUTINE NAGOYA & INUYAMA 〈Decentralized Travel〉', description = 'This travel routine showcases a solo trip of a woman exploring Nagoya, where she visited various spots she was curious about during a business trip. The model course allows for a full day of enjoyment in Nagoya and Inuyama, starting from waking up at the hotel in the morning. It encourages others to wake up early and fully experience the delights of Nagoya.' where id = 'aedchl0Jn5RlansM0H6HF';
update content_bodies set title = 'nagoyainfoncvb のライブ配信', description = 'この動画は、nagoyainfoncvbのライブ配信について紹介しています。視聴者に向けて、配信の内容や特徴を説明し、どのように視聴できるかを案内しています。' where id = 'oqgaoKm6vSMNzkDHSmKuD';
update content_bodies set title = 'Live Streaming of nagoyainfoncvb', description = 'This video introduces the live streaming of nagoyainfoncvb.' where id = 'nzM5AGIQA9wVk7fi6duIx';
update content_bodies set title = '名古屋おもてなし武将隊　豊臣秀吉と前田慶次おススメ観光スポットとなごやめし', description = '名古屋おもてなし武将隊の豊臣秀吉と前田慶次が、名古屋の観光スポットとなごやめしについて熱く語ります。動画では、名古屋の魅力的な観光地が紹介されており、歴史的背景や地元の美味しい料理についての情報が得られます。' where id = 'kwJPtU3R0ZcM4xKQgFzU6';
update content_bodies set title = 'Nagoya Hospitality Samurai Team: Recommended Tourist Spots and Nagoya Cuisine by Toyotomi Hideyoshi and Maeda Keiji', description = 'The Nagoya Hospitality Samurai Team features Toyotomi Hideyoshi and Maeda Keiji, who passionately discuss recommended tourist spots and local Nagoya cuisine. The video showcases various attractions in Nagoya, providing insights into the city''s rich history and culinary delights.' where id = 'NVt2VofqBpj4ar3O8K7qC';
update content_bodies set title = '名古屋観光PR動画', description = 'この動画は名古屋の観光スポットや魅力を紹介しており、名古屋を訪れる際の参考になります。名古屋の美しい風景や文化、食べ物などが映し出されており、観光客にとって魅力的な情報が詰まっています。名古屋の観光を楽しむためのヒントやおすすめの場所が紹介されており、旅行計画を立てる際に役立つ内容となっています。' where id = 'C8On9K6VAYu-9d9ocwqkQ';
update content_bodies set title = 'Photogenic Nagoya', description = 'This video introduces tourism in Nagoya.' where id = '78-bq0Hj2a2mF84G_HJKe';
update content_bodies set title = '名古屋市観光PV - フォトジェニックな名古屋', description = 'この動画は名古屋市の観光に関するプロモーションビデオで、名古屋のフォトジェニックな魅力を紹介しています。名古屋の美しい風景や観光スポットが映し出され、訪れる価値のある場所としての名古屋の魅力を伝えています。' where id = 'QnyP5Z7YeOwxd_RnHMV6d';
update content_bodies set title = 'Nagoya City Tourism PV - Photogenic Nagoya', description = 'This video is a promotional video about tourism in Nagoya City, showcasing the photogenic aspects of Nagoya.' where id = 'uj3wHHup3hNuOrFCzeee-';
update content_bodies set title = '名古屋市観光PV - フォトジェニックな名古屋', description = 'この動画は名古屋市の観光に関するプロモーションビデオで、名古屋のフォトジェニックな魅力を紹介しています。名古屋の美しい風景や観光スポットが映し出され、訪れる価値のある場所としての名古屋の魅力を伝えています。' where id = 'i6MfqjUqpyb1OwMBG9zsN';
update content_bodies set title = 'Nagoya City Tourism PV - Photogenic Nagoya', description = 'This video is a promotional video about tourism in Nagoya City, showcasing the photogenic aspects of Nagoya.' where id = 'UuCNsXoPTMxIzk6dZo_ZF';
update content_bodies set title = '名古屋のSTAMPの思い出', description = 'タイの人気アーティスト「STAMP APIWAT」が2018年の名古屋タイフェスティバルで、タイと外国のファンを楽しませるパフォーマンスを行いました。このイベントでは、名古屋でのSTAMPの活動を記録した動画が公開され、彼が訪れた観光名所が紹介されています。訪問した場所には中部国際空港、名古屋城、金シャチ横丁、大須観音などが含まれ、名古屋の魅力が伝わる内容となっています。また、大須商店街や札幌かに本家などの地元の飲食店も紹介されています。名古屋の観光情報については、公式観光サイトを訪れてください。' where id = '1p2A7qufM84ZNtYlt0Dms';
update content_bodies set title = 'STAMP Memories in Nagoya', description = 'Popular Thai artist ''STAMP APIWAT'' performed at the Thai Festival in Nagoya in 2018, entertaining both Thai and international fans. The event featured a video capturing STAMP''s activities in Nagoya, where he explored the city''s attractions. Notable places he visited include Chubu Centrair International Airport, Nagoya Castle, Kinshachi Yokocho, and Osu Kannon Temple. The video showcases the charm of Nagoya and highlights various tourist spots, including shopping areas like Osu Shotengai and local dining options such as Sapporo Kani Honke. For more information on Nagoya tourism, visit the official tourism website.' where id = 'y0Pzuo2CgBN7pSI6zDCQ5';
update content_bodies set title = '【イルミ×AR】なんばに、誰も体験したことのない感動を。', description = 'なんばの冬の夜空を彩る風物詩「なんば光旅」。このイベントのメインスポットであるなんばパークスの光の滝で、他社と共創しながらAR技術を用いて日本初の試みを描いたショートムービーです。南海グループは、ブランドスローガン「‘なんかいいね’があふれてる」をもとに、今後も人やまち、未来に向けて多くの‘なんかいい’を届けていくことを目指しています。' where id = 'YNqMBeYEybsMus8soI5nC';
update content_bodies set title = 'Illumination x AR: An Unforgettable Experience in Namba', description = 'Namba''s winter night sky is illuminated by the seasonal event ''Namba Light Journey.'' This short film showcases the innovative use of AR technology at the main attraction, the Light Waterfall in Namba Parks, marking Japan''s first attempt in this area through collaboration with other companies. The Nankai Group, guided by its brand slogan ''Overflowing with something good,'' aims to continue delivering many ''something good'' experiences to people, communities, and the future.' where id = 'o6RoLyUH4uxIYVtUy5Jrh';
update content_bodies set title = 'めでたいでんしゃ かなたで和歌山・加太の旅（300秒）', description = '和歌山・加太の観光スポットとグルメを楽しむ旅です。めでたいでんしゃ「かなた」でのんびりと移動し、地元の名物料理を堪能します。歴史ある神社や温泉で心と体をリフレッシュし、旅の最後には絶景の夕日を楽しむことができます。主な見どころには、めでたいでんしゃ、淡嶋神社、キシモト商店の「揚げパン」、活魚料理いなさの「加太の真鯛姿作り」、小嶋一商店の「よもぎ餅」、加太春日神社、めでたい焼き八幡前店の「めでたい焼き」、SERENO seafood&cafeの「加太の海の恵み定食」、休暇村紀州加太の「紀州加太天空の湯」が含まれています。' where id = 'D6MPdbz1AUAmpuampaARQ';
update content_bodies set title = 'A Joyful Journey to Kada, Wakayama by Medetai Train (300 Seconds)', description = 'Experience a delightful trip to Kada, Wakayama, exploring local attractions and cuisine! Travel leisurely on the Medetai Train ''Kanata'' and savor regional specialties. Refresh your mind and body at historic shrines and hot springs. Conclude your journey by enjoying a breathtaking sunset. Key highlights include the Medetai Train, Awashima Shrine, Kishimoto Shoten''s ''Aged Bread'', Inasa''s ''Tai Sashimi'', Kojima''s ''Yomogi Mochi'', Kada Kasuga Shrine, Medetai Yaki Hachimanmae''s ''Medetai Yaki'', Sereno Seafood & Cafe''s ''Seafood Set'', and Kishu Kada''s ''Sky Hot Spring''.' where id = 'Gvc6ft_JDWtqBG-QvkHnF';
update content_bodies set title = 'めでたいでんしゃで和歌山・加太の旅（30秒）', description = '和歌山・加太の観光スポットとグルメを楽しむ旅です。めでたいでんしゃでのんびりと移動し、地元の名物料理を堪能します。歴史ある神社や温泉で心と体をリフレッシュし、旅の最後には絶景の夕日を楽しむことができます。主な見どころには、めでたいでんしゃ、淡嶋神社、キシモト商店の揚げパン、活魚料理いなさの真鯛姿作り、小嶋一商店のよもぎ餅、加太春日神社、めでたい焼き八幡前店のめでたい焼き、SERENO seafood&cafeの海の恵み定食、休暇村紀州加太の温泉などがあります。' where id = 'NPquq3BNiEyV6rqHTa7tY';
update content_bodies set title = 'A Trip to Wakayama and Kada on the Medetai Train (30 seconds)', description = 'Enjoy a journey through Wakayama and Kada, exploring local attractions and cuisine! Travel leisurely on the Medetai train and savor local specialties. Refresh your mind and body at historic shrines and hot springs. Conclude your trip by enjoying a breathtaking sunset. Key highlights include the Medetai train, Awashima Shrine, Kishimoto Shoten''s fried bread, Inasa''s Tai sashimi, Kojima Ichishoten''s yomogi mochi, Kada Kasuga Shrine, Medetai Yaki Hachimanmae''s Medetai Yaki, Sereno seafood & cafe''s Kada seafood set meal, and Kishu Kada Tenku no Yu hot spring.' where id = 'B2IzIoMmW6IJ3fj5-28Du';
update content_bodies set title = 'めでたいでんしゃで加太の旅（スポット15秒編）', description = '和歌山・加太の魅力を紹介します。めでたいでんしゃに乗って、淡嶋神社や旧加太警察署、加太春日神社を巡り、休暇村紀州加太の温泉でリラックスしましょう。最後には美しい夕日を楽しむことができます。ぜひ、癒やしの加太へお越しください！' where id = 'GN6BO4n7fxedMHYzTy1wR';
update content_bodies set title = 'A Journey to Kada with the Celebratory Train (15-Second Spot)', description = 'Discover the charm of Kada in Wakayama! Ride the Celebratory Train and visit Awashima Shrine, the former Kada Police Station, and Kada Kasuga Shrine. Relax in the Kishu Kada hot springs at Qkamura Kada, and enjoy the beautiful sunset to conclude your day. We invite you to come and experience the healing atmosphere of Kada!' where id = 'GLSJcDSrQLmsb7cCM1XL7';
update content_bodies set title = 'まちの参観日in河内長野（オンラインイベント）', description = '2024年9月7日に実施された「まちの参観日in河内長野」のオンラインイベントのアーカイブ動画です。このイベントは、南海電鉄の「地域発見クリエイターズ課」が主催し、河内長野市の魅力を市内各所からのLIVE中継でお伝えしました。当日は約500名の全国のお客さまにご視聴いただきました。動画には「ワークワクワク河内長野」や子育て支援施設「あいっく」、奥河内くろまろの郷エリアなどのセグメントが含まれています。また、河内長野市に引っ越してきた先着25世帯に約5万円相当の転入特典が提供される特別オファーもあります。詳しくは公式サイトをご覧ください。' where id = 'yGz9S9h8KwShg0F2ah-tJ';
update content_bodies set title = 'Machi no Sankanbi in Kawachinagano (Online Event)', description = 'This is the archived video of the online event ''Machi no Sankanbi in Kawachinagano'' held on September 7, 2024. The event, organized by the Nankai Electric Railway''s ''Regional Discovery Creators Division,'' showcased the attractions of Kawachinagano City through live broadcasts from various locations. Approximately 500 viewers from across the country participated in the event. The video includes segments such as ''Waku Waku Kawachinagano,'' a child-rearing support facility, and the ''Okukawachi Kuromaro no Sato'' area, among others. Additionally, there is a special offer for new residents moving to Kawachinagano City, providing a benefit worth about 50,000 yen to the first 25 households. For more details, visit the official website.' where id = '2m4N9XvJkcx683KbGAVjz';
update content_bodies set title = '【なんばパークス】人、都市、自然。ともに、未来へ。15秒ver', description = 'なんばパークスは、人、都市、自然の調和を促進し、共に未来を目指すことを強調しています。『なんかいい』ACTIONというフレーズに象徴されるこの取り組みは、都市生活に対する前向きで積極的なアプローチを反映しています。' where id = '1TysJkZbIBcpAf-cSH73m';
update content_bodies set title = 'Namba Parks: People, City, Nature. Together, Towards the Future. 15-second version', description = 'Namba Parks promotes a harmonious relationship between people, the city, and nature, emphasizing a collective future. The initiative is encapsulated in the phrase ''Nanka ii'' Action, which reflects a positive and proactive approach to urban living.' where id = '7sCQOXWcBat0WZj7gVhV8';
update content_bodies set title = '南海8300系・泉北9300系がグッドデザイン賞を受賞！', description = '南海電鉄8300系と泉北高速鉄道9300系が2023年度のグッドデザイン賞を受賞しました。この賞は公益財団法人日本デザイン振興会が主催しています。今後も「人と環境に優しい車両」として、安全・安心・快適な空間づくりを進めていく方針です。' where id = 'rN3Qjz1uXBYcykAHx2wqL';
update content_bodies set title = 'Nankai 8300 Series and Semboku 9300 Series Win Good Design Award!', description = 'The Nankai Electric Railway 8300 series and the Semboku Rapid Railway 9300 series have been awarded the 2023 Good Design Award, organized by the Japan Design Promotion Association. Moving forward, we will continue to develop vehicles that are friendly to both people and the environment, ensuring safety, security, and comfort.' where id = 'OgcrX2m0WzRJareGfSHvH';
update content_bodies set title = '【なんばパークス】人、都市、自然。ともに、未来へ。 パークスガーデン', description = '南海電鉄難波駅に直結するなんばパークスの屋上公園「パークスガーデン」で、自然と共存しながら憩いの場を育んできた私たちの想いをつづったショートムービーです。南海グループでは、ブランドスローガン「‘なんかいいね’があふれてる」をもとに、これからも人やまち、そして未来にたくさんの‘なんかいい’をお届けしていきます。' where id = '7kpRaSCFXAZtXW3P5BdIX';
update content_bodies set title = 'Namba Parks: People, City, Nature. Together, Towards the Future. Parks Garden', description = 'This short movie expresses our commitment to nurturing a place of relaxation in the Parks Garden, the rooftop park directly connected to Nankai Electric Railway''s Namba Station, while coexisting with nature. The Nankai Group aims to continue delivering many ''something good'' to people, cities, and the future, based on our brand slogan ''Overflowing with something good.''' where id = 'tuMvFKaIvIl0LSokFo4Yr';
update content_bodies set title = '南海＆沿線STORY 「ともに走る」', description = '「加太さかな線」の「めでたいでんしゃ」を中心に、地域の活性化に奮闘する南海電鉄社員と沿線の方々の姿を描いたショートムービーです。南海グループは、ブランドスローガン「‘なんかいいね’があふれてる」をもとに、今後も人やまち、そして未来にたくさんの‘なんかいい’を届けていくことを目指しています。' where id = 'Sz9le7yxhh2DxPNXNApeH';
update content_bodies set title = 'Nankai & Line Story: ''Running Together''', description = 'This short movie focuses on the ''Merry Train'' of the Kada Fish Line and depicts the efforts of Nankai Electric Railway employees and local residents to revitalize the community. The Nankai Group aims to continue delivering many ''good things'' to people, towns, and the future, based on their brand slogan, ''Overflowing with something good.''' where id = 'bjtZQyDi17zny_rsx8vv_';
update content_bodies set title = '「NANKAI鉄子の部屋」サイコロトーク！前編(かおりさん)', description = '千代田工場見学会の後に行われた座談会では、サイコロトークが実施されました。サイコロを振って出たテーマは「鉄子あるある」で、かおりさんは特急の車内自動放送をそらで言えることを紹介しました。まるでこうや号に乗っているかのような車内放送を披露しました。このイベント「NANKAI鉄子の部屋」は2016年8月6日に開催され、鉄道アイドルの斉藤雪乃さんをゲストに迎え、鉄道好きの女性たち“鉄子”が参加しました。' where id = 'pWHnDgBa7w3pW7D16fp2n';
update content_bodies set title = 'NANKAI Train Girls'' Room: Dice Talk! Part 1 (Kaori-san)', description = 'Following the Chiyoda Factory tour, a roundtable discussion was held featuring a dice talk segment. The theme rolled on the dice was ''Train Girl Common Experiences.'' Kaori-san shared her experience of being able to recite the automatic announcements on express trains from memory. She even showcased a train announcement as if she were on the ''Kouya'' train! This event, ''NANKAI Train Girls'' Room,'' took place on August 6, 2016, and featured guest railway idol Yukino Saito, welcoming female train enthusiasts known as ''Tetsuko.''' where id = 'F2CGRXeoyhktwJjsC5o1p';
update content_bodies set title = '「NANKAI鉄子の部屋」サイコロトーク！前編(さえこさん)', description = '千代田工場見学会の後に行われた座談会では、サイコロトークが実施されました。サイコロを振って出たテーマは「自慢のベストショット」で、さえこさんの「ベストショット」は、匠の技が詰まった鉄道の魅力が溢れる写真です。このイベント「NANKAI鉄子の部屋」は2016年8月6日に開催され、鉄道アイドルの斉藤雪乃さんをゲストに迎え、鉄道好きの女性たち、いわゆる“鉄子”が参加しました。' where id = 'yy8_Iudg0bsUqbTIonKQ5';
update content_bodies set title = 'NANKAI Tetsuko''s Room: Dice Talk! Part 1 (Saeko-san)', description = 'Following the Chiyoda Factory tour, a roundtable discussion was held featuring a dice talk. The theme rolled on the dice was ''Best Shot.'' Saeko-san''s ''Best Shot'' showcases a photo filled with the essence of craftsmanship and the charm of trains. This event, ''NANKAI Tetsuko''s Room,'' took place on August 6, 2016, and welcomed railway idol Yukino Saito as a guest, inviting female train enthusiasts known as ''Tetsuko'' to participate.' where id = 'nj8p1t2tvzamt8x__GYm7';
update content_bodies set title = '「NANKAI鉄子の部屋」サイコロトーク！前編(さゆりさん)', description = '千代田工場見学会の後に行われた座談会では、サイコロトークが実施され、テーマは「鉄子あるある」となりました。さゆりさんは、電車を友達と考える「あるある」を紹介し、親友も紹介しました。このイベント「NANKAI鉄子の部屋」は2016年8月6日に開催され、鉄道アイドルの斉藤雪乃さんをゲストに迎え、鉄道好きの女性たち、いわゆる「鉄子」が参加しました。' where id = 'MwtFr-RSDITpKkJ8mam7z';
update content_bodies set title = 'NANKAI Train Girls'' Room: Dice Talk! Part 1 (Sayuri)', description = 'Following the Chiyoda Factory tour, a roundtable discussion was held featuring a dice talk segment. The theme rolled on the dice was ''Train Girl Common Experiences.'' Sayuri shared her experience of considering trains as friends, introducing her best friend in the process. This event, ''NANKAI Train Girls'' Room,'' took place on August 6, 2016, and welcomed railway idol Yukino Saito as a guest, inviting female train enthusiasts, known as ''Tetsuko,'' to participate.' where id = 'iibfyTK2ggJktw5Yp8Ypi';
update content_bodies set title = 'なんばEKIKANプロジェクト　メイキングムービー（2014年公開）', description = '大阪の南海なんば駅と今宮戎駅の間にある高架下をリノベーションした「なんばEKIKANプロジェクト」のメイキングムービーです。昭和13年に完成したこの高架下は、自転車店「cycle HERO」、DIYショップ「DIY FACTORY OSAKA」、炭火焼カフェ「チャコールグリルパーラー　オルケスタ」の3店舗が並ぶ商業ゾーンへと生まれ変わりました。この動画では、そのリノベーションの過程が収められています。' where id = 'Uqlb1aFqgWl5LfV7-diNJ';
update content_bodies set title = 'Namba EKIKAN Project Making Movie (Released in 2014)', description = 'This is a making movie of the ''Namba EKIKAN Project,'' which renovated part of the elevated space between Nankai Namba Station and Imamiya Ebisu Station in Osaka. The elevated structure, completed in 1938, was transformed into a commercial zone featuring three stores: a bicycle shop called ''cycle HERO,'' a DIY shop named ''DIY FACTORY OSAKA,'' and a charcoal grill café called ''Charcoal Grill Parlor Orquesta.'' The video captures the renovation process.' where id = '-lrT6P3XxZKfMgfNTE6-H';
update content_bodies set title = '令和5年度岐南地芝居公演(美濃歌舞伎保存会)', description = '令和5年9月10日（日）、岐南町伏屋獅子舞会館で岐南地芝居公演が開催されました。昨年に続き、「伏屋の獅子芝居」と県内の他の獅子芝居や地歌舞伎が同時に楽しめるイベントです。今年は関市獅子舞保存会と美濃歌舞伎保存会が出演しました。地歌舞伎『三人吉三』が上演され、物語は節分の夜にお嬢吉三が夜鷹の女から金百両を奪うところから始まります。お坊吉三との争いを和尚吉三が仲裁し、三人は義兄弟の契りを結びますが、百両を巡る悲劇が展開します。最終的に、彼らは互いの過去を知り、罪を悔いて死を選ぼうとします。' where id = 's_OoqGqjdGzq4Z9N9blXV';
update content_bodies set title = 'Ginan Local Kabuki Performance 2023 (Mino Kabuki Preservation Society)', description = 'On September 10, 2023, the Ginan Local Kabuki Performance was held at the Fushiya Shishimai Hall in Ginan Town. Continuing from last year, this event showcased ''Fushiya''s Lion Dance'' alongside other lion dances and local kabuki from within the prefecture. This year, the Sekishi Lion Dance Preservation Society and the Mino Kabuki Preservation Society performed. The featured play was ''Sannin Kichisa,'' a well-known work by Kawatake Mokuami. The story unfolds on Setsubun night, where Ojo Kichisa steals 100 ryo from a night hawk woman, leading to a conflict with Obo Kichisa. A monk named Osho Kichisa intervenes, and the three, sharing the same name, become sworn brothers. The monk offers the stolen money to his father, but it is rejected. The money eventually leads to tragedy, revealing deep connections and regrets among the characters.' where id = 'YDb1JwsiR5KFZ9A0cGblL';
update content_bodies set title = '令和5年度岐南地芝居公演(岐南町伏屋獅子舞保存会)', description = '令和5年9月10日、岐南町伏屋獅子舞会館で岐南地芝居公演が開催されました。この公演は、令和6年度の第39回国民文化祭および第24回全国障害者芸術・文化祭「清流のぎふ文化祭2024」のプレイベントの一環です。今年は岐南町伏屋獅子舞保存会、関市獅子舞保存会、美濃歌舞伎保存会が出演し、「伏屋の獅子芝居」と他の獅子芝居や地歌舞伎が同時に楽しめる内容でした。プログラムには「道行」「寄」「悪魔払い」、獅子芝居『傾城阿波の鳴門　巡礼歌の段』が含まれています。この物語は、徳島の家宝である名刀「国次」を探すために旅に出た夫婦と、両親に会いたい一心で巡礼の旅に出た娘の物語です。娘は母親に出会うことになりますが、母は娘を守るために帰るように諭します。' where id = 'Q5oQ8mpE8-NvKyRC5miEw';
update content_bodies set title = 'Ginan Local Theater Performance 2023 (Ginan Town Fushiya Lion Dance Preservation Society)', description = 'On September 10, 2023, the Ginan Local Theater Performance was held at the Ginan Town Fushiya Lion Dance Hall as a pre-event for the 39th National Cultural Festival and the 24th National Arts and Culture Festival for Persons with Disabilities, ''Seiryu no Gifu Cultural Festival 2024''. This year''s performance featured the ''Fushiya Lion Theater'' alongside other lion dances and local kabuki from Gifu Prefecture, with participants including the Ginan Town Fushiya Lion Dance Preservation Society, the Seki City Lion Dance Preservation Society, and the Mino Kabuki Preservation Society. The program included various acts such as ''Dōyuki'', ''Yori'', ''Demon Exorcism'', and the lion theater piece ''Keisei Awa no Naruto - Pilgrimage Song Segment''. The story follows Jurobei and his wife, Oyu, who leave their three-year-old daughter, Otsuru, behind to search for a treasured sword, leading to a series of misfortunes. Nine years later, Otsuru embarks on a pilgrimage to find her parents, eventually encountering her mother, Oyu, in Osaka, leading to an emotional reunion.' where id = '2BvCSnlE-6Ja6s8lnvu9g';
update content_bodies set title = '令和6年岐南町二十歳の集い', description = '令和6年1月7日（日）に岐南町中央公民館で岐南町の二十歳の集いが開催されます。詳細については、広報紙『マイタウンぎなん』の特集をご覧ください。' where id = 'vW4-BdmYFU1VpDc4H3Z6t';
update content_bodies set title = 'Ginan Town Coming of Age Ceremony 2024', description = 'The Ginan Town Coming of Age Ceremony will be held on January 7, 2024, at the Ginan Town Central Community Center. Please refer to the special feature in the local newsletter ''My Town Ginan'' for more information.' where id = 'jFc7rCM_WPlNF2TjWcxxK';
update content_bodies set title = '令和5年岐南町二十歳の集いスライドショー', description = '令和5年1月8日（日）に岐南町中央公民館で令和5年岐南町二十歳の集いが開催されました。昨年、成人年齢が引き下げられたことに伴い、成人式は「二十歳の集い」と改名され、この節目を祝う式典が行われました。このイベントは、広報紙『マイタウンぎなん』の特集と併せて紹介されています。' where id = 'qZpXjd2aK1hQrRlRT-1Hj';
update content_bodies set title = 'Ginan Town 20th Anniversary Celebration Slideshow', description = 'On January 8, 2023, the Ginan Town 20th Anniversary Celebration was held at the Ginan Town Central Community Center. With the legal age of adulthood lowered last year, the ceremony was renamed from Coming-of-Age Ceremony to the 20th Anniversary Celebration to commemorate this milestone. The event was featured alongside a special edition of the local newsletter ''My Town Ginan''.' where id = 'UI4052MMX_QbcxjJVmHHz';
update content_bodies set title = '沖縄旅行映像', description = 'この沖縄旅行映像は、2024年2月に沖縄で行われたスタディツアー中に撮影した素材を使用して制作されました。映像には、沖縄の魅力的な風景や伝統文化、スタディツアー中のさまざまな体験が収められています。この動画を通じて、沖縄の豊かな魅力を少しでもお伝えできれば幸いです。撮影協力として沖縄観光コンベンションビューローに感謝を述べています。動画内では、宮古島東急ホテル＆リゾーツやブセナテラス、DMMかりゆし水族館など、いくつかの施設が紹介されています。アヤベックス株式会社が運営するUnexpected Japanは、訪日旅行のプロモーションサービスを専門とし、海外の訪問者と日本の本物の体験をつなぐためのさまざまな旅行関連サービスを提供しています。' where id = '2LhgiXVqF52-iVBs7doms';
update content_bodies set title = 'OKINAWA travel film', description = 'The Okinawa travel film was created using footage from a study tour in Okinawa in February 2024. It features the stunning landscapes, traditional culture, and various experiences encountered during the tour. The video aims to provide viewers with a glimpse of Okinawa''s rich charm. Special thanks are given to the Okinawa Convention & Visitors Bureau for their support. The film highlights several venues, including the Miyakojima Tokyu Hotel & Resorts, The Busena Terrace, and the DMM Kariyushi Aquarium, among others. Unexpected Japan, a creative promotion team operated by Ayabex Inc., specializes in inbound promotion services, offering a range of travel-related services to connect overseas visitors with authentic experiences in Japan.' where id = '8oHDErnHymzHUj2hgp9i3';
update content_bodies set title = '金沢・能登アドベンチャーの旅', description = 'この動画は2021年9月に金沢・能登アドベンチャーツーリズムのファムトリップにアヤベックスが参加した際の記録です。金沢と能登には多くの魅力が詰まっており、視聴者にもこのアドベンチャーの旅を体験していただければ嬉しいです。制作には株式会社地球の歩き方が協力しており、感謝の意を表します。' where id = 'WbH8tJSBBDOt-amCveshI';
update content_bodies set title = 'Kanazawa & Noto Adventure / Cinematic Travel Vlog', description = 'This video documents Ayabex''s participation in a fam trip for Kanazawa and Noto Adventure Tourism in September 2021. Kanazawa and Noto are filled with wonderful attractions, and we hope you can experience the adventure of traveling in these regions as well.' where id = 'YkFrvk30_eYGh2DFxKwQr';
update content_bodies set title = '舞鶴観光PR動画', description = '舞鶴市は京都府の北端に位置する港町で、明治時代から軍港としての長い歴史があります。この動画では舞鶴の東側を紹介し、海軍に関連する史跡や青い海の美しい風景を映し出しています。「軍艦のある海」が舞鶴のシンボルであり、歴史を感じることができる魅力的な動画です。舞鶴観光協会や撮影に協力してくれた地元の皆様に感謝の意が表されています。' where id = 'y9q3L0ZwuUJ7RcUffUgrh';
update content_bodies set title = 'Maizuru Kyoto East Side Story / Travel in Japan / Cinematic Travel Vlog', description = 'Maizuru is a port city located at the northern end of Kyoto Prefecture, known for its long history as a naval harbor since the Meiji era. This video focuses on the eastern part of Maizuru, showcasing its historical sites related to the Navy and the beautiful scenery of the blue sea. The city is symbolized by the ''Marine Landscape with Warships.'' Viewers are encouraged to enjoy the captivating video that highlights the charm of East Maizuru. Special thanks are given to the Maizuru Tourism Association and the local people who assisted in the filming.' where id = 'Gd33FaTV8Wba9_qvmSBzU';
update content_bodies set title = '滋賀＆福井周遊 vol.2 土鍋ごはんと信楽焼工房見学・彦根観光', description = 'この動画は滋賀の旅行シリーズの続編です。信楽焼の土鍋で炊いたご飯を提供するレストランを訪れ、陶芸家から信楽焼の魅力や美味しいご飯の炊き方を学びました。また、長い歴史を持つ多賀大社や国宝に指定されている彦根城も訪れました。滋賀県は、伝統的な方法で作られた信楽焼を見たり、日本の歴史に関連する神社や城を訪れたり、地元の人々の生活の跡を辿ることができるスポットが豊富です。次回の動画では福井県を訪れる予定ですので、お楽しみに！' where id = '7uqf4rYm4U7H4mYBUU2bX';
update content_bodies set title = 'Shigaraki Pottery & Hikone History Japan Travel Cinematic Vlog', description = 'In this continuation of our Shiga travel series, we explore the unique Shigaraki pottery, known for its earthen pots used for cooking rice. We visit a restaurant that serves rice in these traditional pots and learn about the pottery-making process from a skilled potter. Our journey also takes us to Taga Taisha, a shrine with a long history of local visits, and Hikone Castle, a national treasure. Shiga prefecture is rich in cultural heritage, showcasing traditional Shigaraki ware, historical shrines, and castles that reflect the lives of the locals. Stay tuned for our next video featuring Fukui prefecture!' where id = '5UfcEYHylJd3OUrPEJTRv';
update content_bodies set title = 'Excellent Omi Wagyu beef & Sake brewery Japan Travel Vlog / 滋賀＆福井周遊 vol.1滋賀編　日本三大和牛・近江牛と地酒のマリアージュ', description = 'この旅行Vlogは滋賀県から始まります。滋賀の食文化は長い間地元の人々に愛されてきました。私たちは、100年以上の歴史を持つ近江牛の老舗レストランと、甲賀市の水口町にある酒蔵を訪れ、貴重な話をたくさん聞きました。滋賀県を訪れた際には、美味しい近江牛料理とそれにぴったり合う地酒をぜひお試しください。次回の動画では、滋賀の伝統工芸である信楽焼について紹介します。特別な感謝を湖のビワ訪問局に、そして私たちを助けてくれたすべての人に。' where id = 'Br-l-y2O801FBScWRmQvF';
update content_bodies set title = 'Excellent Omi Wagyu beef & Sake brewery Japan Travel Vlog / 滋賀＆福井周遊 vol.1滋賀編　日本三大和牛・近江牛と地酒のマリアージュ', description = 'This travel vlog begins in Shiga Prefecture, where the local food culture has been cherished for generations. The video features a visit to a century-old Omi beef restaurant and a sake brewery in Minakuchi-cho, Koga city, where the hosts share fascinating stories about their culinary heritage. Viewers are encouraged to experience the exquisite Omi beef dishes and the sake that pairs perfectly with them when visiting Shiga. The next installment will focus on Shiga''s traditional craft, Shigaraki ware. Special thanks are given to the Lake Biwa Visitors Bureau and all contributors. The channel, ''Unexpected Japan,'' is run by Ayabex Inc., an inbound travel agency that highlights Japan''s attractions from a professional viewpoint.' where id = 'mWdhoB-p4HCsbRohlJD_i';
update content_bodies set title = '関西周遊トリップ 滋賀＆福井', description = '今回の動画では、滋賀県と福井県を巡る旅を紹介します。美しい景色や歴史的な城、酒造、信楽焼の工房、美味しい海の幸など、魅力的なスポットが満載です。4日間の旅行を3分の予告編にまとめましたので、ぜひご覧ください。本編も後日投稿予定ですので、お楽しみに！制作には（公社）びわこビジターズビューローと福井県の協力を得ており、撮影に協力してくださった皆様にも感謝申し上げます。使用機材はSONY VLOGCAM ZV-1です。' where id = '2fXC2KUcHEGXPCNCQVgCp';
update content_bodies set title = 'Kansai Round Trip - Shiga & Fukui / The trailer / Cinematic Travel Vlog', description = 'In this video, we embark on a journey through Shiga and Fukui Prefectures. The region is rich in attractions, including beautiful landscapes, historic castles, sake breweries, Shigaraki pottery workshops, and delicious seafood. We have condensed our four-day travel experience into a three-minute trailer. Stay tuned for the full video, which will be posted later! Special thanks to the Biwako Visitors Bureau and Fukui Prefecture for their support, as well as everyone who assisted with filming. Equipment used: SONY VLOGCAM ZV-1.' where id = 'xN_2sXmDPvz115hh2h1W2';
update content_bodies set title = 'AYABE KYOTO - 地元の人々と出会う場所', description = '京都府綾部市は、人口約3万人の小さな田舎町です。この観光PR動画は、綾部市の豊かな自然、歴史文化、そして温かい人々の魅力を3分間で紹介しています。綾部市のユニークな体験や地元の観光名所をぜひご覧ください。' where id = 'mo2bHRoU0YHqSvTsmIJXb';
update content_bodies set title = 'AYABE KYOTO - Where to meet locals in Japan', description = 'Ayabe City, located in Kyoto Prefecture, is a small rural town with a population of about 30,000. This promotional video, lasting three minutes, showcases the town''s rich natural beauty, historical culture, and the warmth of its people. It invites viewers to explore the unique experiences and local attractions that Ayabe has to offer.' where id = 'sVZ4ngZwEiuqRtSqBsHiN';
update content_bodies set title = '【Secret Kyoto Vol.2】AYABE - Japan Cinematic Travel Vlog by iphone11pro', description = 'Secret Kyotoの第二弾は綾部市を訪れます。京都駅から約1時間の距離に位置するこの田舎の町は、観光地としてはあまり知られていませんが、町の至る所に美しい景色が広がっています。動画では、農家民宿や露天五右衛門風呂体験、風鈴で有名な東光院など、綾部の夏の風景をお楽しみいただけます。ぜひ綾部の美しさを感じていただき、機会があれば訪れてみてください。' where id = 'KVo9GnIgTGXW_ms-_LDu4';
update content_bodies set title = 'Secret Kyoto Vol.2: AYABE - Japan Cinematic Travel Vlog by iphone11pro', description = 'AYABE is located in Kyoto prefecture, just an hour from central Kyoto city. This rural area is not well-known for sightseeing, but it offers stunning views throughout the city. The video showcases the summer scenery in Ayabe, featuring experiences like staying at a farmhouse, enjoying an outdoor Goemon bath, and visiting Toko-in Temple, famous for its wind chimes. We invite you to enjoy the beauty of Ayabe in summer and hope you can visit us if you have the chance!' where id = 'MFKcWTnY9lPhQJ4Eh7JGB';
update content_bodies set title = '【Secret Kyoto Vol.1】日本のシネマティック旅行Vlog - 海の京都', description = '夏の京都旅行では、自然豊かな北部を訪れ、まだ知られていない秘密のエリアを探ります。外国人旅行者のマキシムが、福知山城やおほもと教庭園、古墳、地元のカフェなど、隠れた名所を巡る様子をシネマティックにVlog形式でまとめました。観光地から離れたこの京都の秘密のエリアで、自然の美しさと文化の豊かさを発見することを視聴者に呼びかけています。' where id = '7XgZ0XLzrzQDmzQrHafli';
update content_bodies set title = 'Secret Kyoto Vol.1 - Japan Cinematic Travel Vlog - Kyoto by the sea', description = 'This travel vlog features Maxim, a foreign traveler living in Japan, as he explores the lesser-known northern part of Kyoto during summer. The video showcases various hidden gems in the region, including Fukuchiyama Castle, Oomoto Garden, ancient tombs, and local cafes. Maxim invites viewers to discover the natural beauty and cultural richness of this secret area of Kyoto, emphasizing the unique experiences available away from the typical tourist spots.' where id = 'KNNadlqwF4W1IVmlP9W_1';
update content_bodies set title = '伊香保エリアとその石段の魅力', description = '伊香保温泉の石段街は、訪れる人々を美しい風景へと導く独特の石段で知られています。これらの石段は単なるアクセス手段ではなく、地域の重要な文化的シンボルでもあります。石段の魅力は、その歴史的な意義と、伝統的な旅館や美しい景色を含む周囲の環境にあります。訪問者は、地元の店を探索し、伊香保の名物である温泉を楽しみながら、これらの石段を歩く体験を楽しむことができます。' where id = 'd4FKGyOqQT2jhU80-Rh9-';
update content_bodies set title = 'Ikaho area and the charm of its stone steps', description = 'The Ikaho area is renowned for its unique stone steps that lead visitors through a picturesque landscape. These steps are not only a means of access but also a significant cultural symbol of the region. The charm of the stone steps lies in their historical significance and the beautiful surroundings, which include traditional ryokan (inns) and scenic views. Visitors can enjoy the experience of walking along these steps while exploring the local shops and enjoying the hot springs that Ikaho is famous for.' where id = 'JsaJfKhrsHRVoCzpt65lU';
update content_bodies set title = '福井市水道100周年記念動画「水と暮らす」', description = 'この記念動画では、福井市の水道事業の100年の歴史と、次の100年にわたり安全で安心な水道水を安定的に供給するための上下水道局の取り組みを紹介しています。' where id = 'fUH_q_uaM1enMs5BgJmhZ';
update content_bodies set title = 'Fukui City Water Supply 100th Anniversary Video ''Living with Water''', description = 'This commemorative video introduces the 100-year history of Fukui City''s water supply services and the efforts of the Waterworks Bureau to ensure a stable supply of safe and secure drinking water for the next 100 years.' where id = 'V4zkisSiO41rBEBZrlFvO';
update content_bodies set title = '輝きを探して　ふくい嶺北連携中枢都市圏 景観PR映像 第７弾', description = '北陸新幹線福井開業に向けて、ふくい嶺北連携中枢都市圏の景観PR映像が制作されています。映像のテーマは「ファインダーのむこう、輝きを探して」で、理想の写真を追い求めるフォトグラファーの姿と、新しい時代の光を帯びた街を映し出しています。映像には、足羽川の桜並木や九頭竜川、新九頭竜橋、村国山展望台、南条の花はす、北潟の風車など、福井の美しい風景が紹介されています。福井市出身のフォトグラファー友㟢雄太は、地元の魅力を伝える写真集を出版しており、映像を通じて福井の魅力を広めています。' where id = 'dFGtAcQztnVbTe2BZhIKl';
update content_bodies set title = 'Looking for the Shine: Fukui Reihoku Core City Area Landscape PR Video No. 7', description = 'In preparation for the opening of the Hokuriku Shinkansen in Fukui, a landscape PR video is being produced for the Fukui Reihoku core city area. The theme of the video is ''Looking for the Shine Beyond the Finder,'' showcasing the dedicated efforts of a photographer in pursuit of ideal photographs, alongside a city illuminated by the light of a new era. The video features various scenic locations, including cherry tree rows, rivers, observatories, lotus flowers, windmills, and more, highlighting the beauty of Fukui. The photographer, Yuta Tomosaki, hails from Fukui City and has published photo collections that reflect his passion for capturing the world around him.' where id = '5FgrsOYr19xOOy3KqYDYR';
update content_bodies set title = 'かごしま市、桜島と海', description = 'かごしま市は、活火山である桜島や周辺の海の美しい景色で知られる人気の観光地です。市内には観光名所やアクティビティが豊富にあり、訪れる人々にとって魅力的な場所となっています。詳細については、公式観光ウェブサイトを訪れることができます。' where id = 'tHZg7cbi7kNSPtYFbi1h-';
update content_bodies set title = 'Kagoshima City, Sakurajima and Sea', description = 'Kagoshima City is a popular tourist destination known for its stunning views of Sakurajima, an active volcano, and the surrounding sea. The city offers various attractions and activities for visitors, making it a great place to explore. For more information, you can visit the official tourism website.' where id = 'Ga16QfEXi1IkDD3FyQJ9M';
update content_bodies set title = 'かごしま市、食', description = 'かごしま市は、その豊かな文化と歴史を反映した多様な料理体験を提供しています。地元の特産品や新鮮な食材を使用した独自の料理が有名で、訪れる人々は伝統的な和食から現代的なアレンジまで、さまざまな食事の選択肢を楽しむことができます。また、かごしまの美しい景色を眺めながら食事を楽しむことができます。詳細については、かごしま市の観光ウェブサイトを訪れてください。' where id = 'sO7wCPn9GyY48zrmAbNHz';
update content_bodies set title = 'Kagoshima City, Food', description = 'Kagoshima City offers a variety of culinary experiences that reflect its rich culture and history. The city is known for its unique local dishes and fresh ingredients sourced from the surrounding areas. Visitors can explore various dining options, from traditional Japanese cuisine to modern interpretations, all while enjoying the beautiful scenery of Kagoshima. For more information, you can visit the Kagoshima City tourism website.' where id = 'tv_GS__Ykw_FYfGXyzuiG';
update content_bodies set title = 'かごしま市、アクティビティ', description = 'かごしま市観光ナビは、地域のさまざまなアクティビティや観光名所についての情報を提供する包括的な観光ガイドです。このウェブサイトは、訪問者がかごしま市のユニークな魅力や体験を学ぶ手助けをすることを目的としています。' where id = 'kwTrO-1kEXUuD4mQF5shD';
update content_bodies set title = 'Kagoshima City, Activity', description = 'Kagoshima City offers a comprehensive tourism guide through its website, providing insights into various activities and attractions in the area. The site is designed to help visitors learn more about the city''s unique offerings and experiences.' where id = 'kuenQUxE2d9GHHKpEghfo';
update content_bodies set title = 'かごしま市、イベント', description = 'かごしま市の観光ナビは、地域のさまざまな観光名所やイベントについての情報を提供しています。このウェブサイトは、ディレクター兼エディターの英川裕樹が管理しており、松村隆志による写真と、馬場基成による空撮が掲載されています。かごしま市の豊かな文化や自然の美しさを訪れる人々が探求できる内容となっています。' where id = '-LnrxmeM8jo7FXrgQAmGr';
update content_bodies set title = 'Kagoshima City, Event', description = 'Kagoshima City offers a comprehensive tourism guide through its website, providing insights into various attractions and events in the area. The site is managed by Director and Editor Yuki Eikawa, with photography contributions from Takashi Matsumura and aerial photography by Motonari Baba. Visitors can explore the rich culture and natural beauty of Kagoshima City.' where id = 'V6T0fIxH9aqZ-51xX86JQ';
update content_bodies set title = '北海道観光PR動画', description = 'この映像は、ソニーストア札幌での個展用に制作されたもので、北海道の魅力を伝えています。KAIという地元のクリエイターたちのチームが制作しており、北海道179市町村の観光や文化をPRすることを目的としています。観光PR映像や地域PR映像、人物や文化に焦点を当てたドキュメンタリーなど、多様な表現方法を用いています。プロジェクト「EzoExplorer」は、各地域の魅力を発信し、地域づくりや移住促進に寄与することを目指しています。制作チームには、プロデューサーやドローンオペレーター、サウンドデザイナーなどが含まれています。' where id = 'tmP9NM66Z_LxeCv7tzEDR';
update content_bodies set title = 'Beginning of KAI for SONY exhibition', description = 'This video was created for a solo exhibition at Sony Store Sapporo. It showcases the beauty and attractions of Hokkaido, produced by KAI, a team of local creators. The project aims to promote tourism and culture across all 179 municipalities in Hokkaido through various forms of media, including tourism PR videos, regional PR videos, and documentaries focusing on people and culture. The KAI Hokkaido Movie Media initiative, known as Project EzoExplorer, seeks to highlight the unique charm of each area, contributing to community development and migration promotion. The production team includes various professionals, such as producers, drone operators, and sound designers.' where id = 'xvxpqagbKJDI1QqDANr4Z';
update content_bodies set title = '北海道千歳市観光PR動画の裏話', description = '#3 CHITOSEは、北海道千歳市の観光PR動画です。「BEHIND THE STORY OF」シリーズでは、ディレクターの岡内翔吾が制作の想いや裏話を紹介しています。この動画では、千歳市の美しさや魅力が描かれ、制作チームには岡内翔吾（プロデューサー・DP）、佐々木亮（Bカメラ）、鳥谷正樹（ドローンオペレーター）が参加しています。また、モデルとして夏、圭介、ヤマが登場し、視覚的な物語を作り上げています。このプロジェクトは、北海道179市町村の魅力を伝えることを目的としたKAI Hokkaido Movie Mediaの一環で、観光や文化に関するドキュメンタリーなど多様な映像表現を通じて地域の魅力を発信しています。' where id = 'nG-h9UKCutbRZNkdTFQ9X';
update content_bodies set title = 'BEHIND THE STORY OF #3 CHITOSE', description = '#3 CHITOSE is a promotional video for Chitose City, Hokkaido. The series ''BEHIND THE STORY OF'' shares insights and behind-the-scenes stories from the director, Shogo Okauchi. The video showcases the beauty and attractions of Chitose, featuring a team of talented individuals including producer and director of photography Shogo Okauchi, camera operator Ryo Sasaki, and drone operator Masaki Toriya. Models Natsu, Keisuke, and Yama also contribute to the visual narrative. The project is part of KAI Hokkaido Movie Media, which aims to promote the charm of all 179 municipalities in Hokkaido through various forms of visual media, including tourism and cultural documentaries. The initiative, known as Project EzoExplorer, is driven by local creators dedicated to highlighting the unique aspects of their regions.' where id = 'zYknxV_hHEscxIQB1Z0LZ';
update content_bodies set title = '心安らぐ美しい砂浜…', description = '離島にはまだあまり知られていない砂浜が多く存在します。島を巡りながら、自分だけの砂浜を見つけて、のんびりと過ごす贅沢な時間を楽しむことができます。心安らぐ美しい景色に癒されることでしょう。' where id = '4sKR8r0dwmi4VmBt8yCp9';
update content_bodies set title = 'Beautiful, Tranquil Sandy Beaches...', description = 'There are many lesser-known sandy beaches on remote islands. As you explore the islands, you can discover your own unique beach and enjoy a luxurious island time at your leisure. The beautiful scenery provides a soothing experience.' where id = 'p35s28ajC_JUD0EBtxVOU';
update content_bodies set title = '【4K】Sea & Me', description = '沖縄の「はいむるぶし」で、ここにしかない美しさを体験してください。南十字星にちなんだこのリゾートは、八重山諸島の小浜島に位置し、沖縄本島からさらに南へ400kmの場所にあります。国内最大のサンゴ礁と西表石垣国立公園に囲まれたこのアイランドリゾートは、特別な休日を提供します。' where id = '22CPebR6XQZcM2YT6YHid';
update content_bodies set title = '【4K】Sea & Me', description = 'Discover the unique beauty of Okinawa at ''Haimurubushi'', a resort named after the Southern Cross. Located on Kohama Island in the Yaeyama Islands, it is situated 400 km south of Okinawa''s main island. This island resort offers a holiday experience surrounded by the largest coral reef in Japan and the Iriomote-Ishigaki National Park.' where id = 'n47EyR9s5E02oqRgJoIrH';
update content_bodies set title = '再出発', description = 'この動画は「An Inspiring Journey　再出発【4K】」について紹介しています。' where id = 'DDlwvuJI2mYQIqUughIcf';
update content_bodies set title = 'An Inspiring Journey', description = 'This video introduces ''An Inspiring Journey'' in 4K resolution.' where id = 'KeZrrbKF8GSuQDaoEmFjh';
update content_bodies set title = '朝食ブッフェの料理はテイクアウト！自然の中で食事を楽しむ「ピクニックブレックファスト」', description = '「ピクニックブレックファスト」は、沖縄の自然の中でテイクアウトのブッフェを楽しむユニークな食事体験を提供します。八重山諸島の小浜島にあるリゾート「はいむるぶし」で行われ、この体験では、国内最大のサンゴ礁と西表石垣国立公園の美しい風景に囲まれながら食事を楽しむことができます。南十字星という名のこのリゾートは、リラックスと自然とのつながりを求める人々にとって理想的な休日を提供します。' where id = 'r21anjaFGQOaZDtjoh58X';
update content_bodies set title = 'Picnic Breakfast: Takeout Buffet in Nature', description = 'The Picnic Breakfast offers a unique dining experience where guests can enjoy a takeout buffet amidst the natural beauty of Okinawa. Located at the resort ''Haimurubushi'' on Kohama Island, which is part of the Yaeyama Islands, this experience allows visitors to savor their meals surrounded by the stunning landscapes of the largest coral reef in Japan and the Iriomote-Ishigaki National Park. The resort, named after the Southern Cross, provides a perfect getaway for those seeking relaxation and connection with nature.' where id = 'TLU3Bj85NGZMDX4WM84X7';
update content_bodies set title = 'はいむるぶしヨガ03【キャンドルヨガ：月礼拝】', description = '沖縄の離島の美しい風景を背景に、お部屋で行うヨガで心身を癒す体験を提供します。リゾート地での特別な時間を楽しみながら、キャンドルの灯りの中で月礼拝を行い、リラックスしたひとときを過ごしましょう。' where id = 'uwvRHx_lF1Ca4gboeUnpf';
update content_bodies set title = 'Candle Yoga: Moon Salutation at Haimurubushi', description = 'Experience relaxation through indoor yoga set against the soothing landscapes of Okinawa''s remote islands.' where id = 'mw7TVJqIiYpElgp5wJ5RU';
update content_bodies set title = 'はいむるぶし 満月の夜　【月光浴】', description = '八重山の神聖な月夜の下、裸足で砂浜に横たわり、月光浴と瞑想を楽しむことができます。大地を直接感じながら、満月からの手放しと浄化のエネルギーを受け取ることができるでしょう。沖縄本島から南へ400kmの場所に位置し、国内最大のサンゴ礁と西表石垣国立公園に囲まれたアイランドリゾートでの休日を提供します。' where id = 'aXEfpi0VO7yuGMcZJI-vL';
update content_bodies set title = 'Haimurubushi Full Moon Night - Moonlight Bathing', description = 'Under the impressive and sacred moonlit night of the Yaeyama Islands, you can lie barefoot on the sandy beach and engage in moonlight bathing and meditation. This experience allows you to directly feel the earth while receiving the energy of release and purification that the full moon offers. Located 400 km south of Okinawa''s main island, this island resort is nestled within the largest coral reef in Japan and the Iriomote-Ishigaki National Park.' where id = '-JSM5l7IYQd67cDfesu2C';
update content_bodies set title = '【かごしまサイクルツーリズム】癒やしの自然で深呼吸！屋久島ルートをサイクリング！', description = '屋久島はその豊かな自然が世界的に注目されています。原生林に囲まれたマイナスイオンの森では、生命力を感じることができ、野生のヤクシカやヤクシマザルと出会うこともあります。ここでしか味わえない貴重な体験があなたを待っています。' where id = 'N4e-I1JcFajByvtsVT-Tj';
update content_bodies set title = 'Kagoshima Cycle Tourism: Breathe Deeply in Healing Nature! Cycling the Yakushima Route!', description = 'Yakushima, known for its rich natural beauty, attracts attention from around the world. Experience the vitality of the negative ion-rich forests filled with ancient trees, and encounter wild Yakushima deer and monkeys. Unique experiences await you that can only be found here.' where id = 'tb8yTYc9eQz1jEgJvQy2W';
update content_bodies set title = '【かごしまサイクルツーリズム】癒やしの自然で深呼吸！屋久島ルート', description = '屋久島は、その豊かな自然が世界的に注目を集めています。原生林が生い茂るマイナスイオンの森では、生命力を感じることができ、野生のヤクシカやヤクザルと出会うこともあります。ここでしか味わえない貴重な体験があなたを待っています。' where id = 'NbOTcnZ8o1_npaL75j1MT';
update content_bodies set title = 'Kagoshima Cycle Tourism: Breathe Deep in the Healing Nature of Yakushima Route', description = 'Yakushima, known for its rich natural beauty, attracts attention from around the world. Here, you can feel the vitality of the negative ion-rich forests filled with ancient trees and encounter wild Yakushima deer and monkeys. Unique experiences that can only be had here await you.' where id = 'Gp8NXXhCKusTiK-4H2jv6';
update content_bodies set title = '祝！世界自然遺産登録決定　奄美大島・徳之島', description = '奄美大島と徳之島では、島唄と呼ばれる歌が日々の出来事や心の動きを紡いでいます。豊かな自然や文化、美味しい地元の食事、そして心温まるおもてなしが、訪れる人々の心にゆっくりと染み渡ります。鹿児島の息をのむような美しさを体験し、島々が提供するユニークな体験を楽しむことができます。' where id = 'rgxGtQES8qyOWCNzK-lmN';
update content_bodies set title = 'World Heritage Registration Decision: Amami Oshima and Tokunoshima', description = 'Island songs known as Shima-uta resonate through the air, telling stories of daily life’s ups and downs. Visitors can immerse themselves in the islands'' rich nature, culture, delicious local cuisine, and warm hospitality. The breathtaking beauty of Kagoshima invites everyone to slow down and appreciate the unique experiences these islands offer.' where id = 'QpRDmTuPRqJuAfz1TP4XV';
update content_bodies set title = '心奪われる鹿児島', description = '屋久島は日本初の世界自然遺産として知られ、その美しい風景で多くの人々を魅了しています。この島は華やかさだけでなく、住民の暮らしや文化も豊かに受け継がれています。訪れる人々は、古代の森林や壮大な山々の中で、何千年も生き続ける杉の木や元気な鹿、好奇心旺盛な猿たちと共に過ごすことができます。地元の文化は、原始的な自然環境と深く結びついており、訪問者に自然と伝統を結びつけるユニークな体験を提供します。' where id = 'JNtmIZ0tu2tmJm20dIcnZ';
update content_bodies set title = 'BREATHTAKING KAGOSHIMA', description = 'Yakushima, Japan''s first World Natural Heritage site, is renowned for its stunning landscapes. The island is not only beautiful but also rich in culture and the daily lives of its residents. Visitors can immerse themselves in the ancient forests and majestic mountains, where ancient cedars, lively deer, and curious macaque monkeys thrive. The local culture is deeply intertwined with the island''s primeval environment, offering a unique experience that connects visitors to nature and tradition.' where id = 'Q88jRbuy20XaVJD12Oj1X';
update content_bodies set title = '心奪われる鹿児島', description = '鹿児島県には2700カ所以上の自然温泉があり、これは火山活動による恵みです。温泉は地元の人々がつながり、生活を共有する場となっています。これらの癒しの水に浸かる体験は、鹿児島の日常生活の中でシンプルでありながら贅沢な一部であり、地域の人々が集まりリラックスし、物語を交換する機会を提供しています。' where id = '-ojsz_ju9kQVZm0Eyy5BU';
update content_bodies set title = 'BREATHTAKING KAGOSHIMA', description = 'Kagoshima Prefecture is home to over 2,700 natural hot springs, a gift from the volcanic activity in the region. These onsen provide a unique opportunity for locals to connect and share their lives while enjoying the soothing waters. The experience of bathing in these nurturing waters is a simple yet luxurious part of daily life in Kagoshima, where the community comes together to relax and exchange stories.' where id = 'qxHzLqoB7RdwrIg35ErST';
update content_bodies set title = '心奪われる鹿児島', description = '鹿児島は、雄大な火山の風景、美しい自然、古くからの海外との交流によって形成された独自の食文化、火山活動によって生まれた豊富な温泉、そして日本の未来を形作った歴史に恵まれた地域です。また、南の海には多様な文化と習慣を持つ離島が点在しており、探検する価値があります。この動画では、地元の人々の日常生活を発見し、鹿児島の魅力に浸ることができます。' where id = 'yr5KiDHDmA5oARtXDRYS8';
update content_bodies set title = 'BREATHTAKING KAGOSHIMA', description = 'Kagoshima is a region rich in natural beauty, featuring stunning volcanic landscapes, a unique food culture shaped by historical exchanges with other countries, and abundant hot springs created by volcanic activity. The area is also steeped in history that has influenced Japan''s development. Additionally, the southern seas are dotted with remote tropical islands, each offering its own distinct culture and traditions. This video invites viewers to explore the daily lives of the local people and immerse themselves in the captivating essence of Kagoshima.' where id = 'gXxWLiRpDkHx1VRs1GlbB';
update content_bodies set title = '自家製番茶作り｜田舎暮らし', description = '「田舎の日常を旅する - Life in Japanese Countryside」という動画シリーズでは、田舎暮らしを探求します。ナレーターは、熊野市新鹿で地元のおばちゃんから熊野の番茶作りを教わり、海の見える丘の家族の美しい風景を楽しみます。コロナの影響で、都会でステイホームを続けている母に御浜町の新緑の香りを届けたいと考えています。三重県御浜町は紀伊半島の太平洋沿いに位置し、年中みかんが収穫できる美しい町です。ここは「よみがえりの地」として知られ、山は神聖な場所とされています。ナレーターは月に2本の動画をアップする予定で、視聴者にいいねやコメント、チャンネル登録を促しています。' where id = 'tWITto0epnDHyPKyKmIR_';
update content_bodies set title = 'Homemade Bancha Tea Making in the Countryside', description = 'This video series, ''Life in Japanese Countryside,'' explores rural living. The narrator learns how to make Kumano bancha tea from a local woman in Shinjika, Kumano City, while enjoying the beautiful scenery from a family home overlooking the sea. Due to COVID-19, the narrator wishes to share the fresh greenery of Mihama Town in Mie Prefecture with their mother, who is staying at home in the city. Mihama Town, located on the Pacific coast of the Kii Peninsula, is known for its year-round production of various citrus fruits and its scenic beauty, including the sacred Kumano Kodo pilgrimage route. The area is considered a ''land of resurrection,'' where the mountains are seen as sacred spaces inhabited by spirits. The narrator plans to upload videos twice a month and encourages viewers to like, comment, and subscribe to their channel, as well as follow their Instagram.' where id = 'DQbnv1ZwG4eo9o0g6kVG2';
update content_bodies set title = '【理想の田舎暮らし】七十三歳のシンデレラ - サステナブルな暮らし 第三話 五右衛門風呂篇', description = 'このエピソードでは、三重県御浜町に住む73歳の女性のサステナブルな日常生活を探ります。特にコロナ禍において、他人の日常を体験することが旅の一形態であることを考察しています。物語は、尾呂志庵での一日を描写し、竃でご飯を炊き、囲炉裏で料理をし、五右衛門風呂でリラックスする様子が紹介されます。美しい自然に囲まれたこの地域は、太平洋と神聖な熊野山脈に近く、精神的な重要性を持っています。この動画シリーズは、視聴者に田舎暮らしの魅力とユニークな体験を考えるきっかけを提供することを目的としています。' where id = '744uCL8acIMYg4PlHmaGu';
update content_bodies set title = 'The Ideal Rural Life: The 73-Year-Old Cinderella - Sustainable Living Episode 3: Goemon Bath', description = 'This episode explores the daily life of a 73-year-old woman living sustainably in the rural area of Mihama, Mie Prefecture, Japan. It reflects on the concept of travel as a way to experience others'' daily lives, especially during the COVID-19 pandemic when traditional travel has become challenging. The narrative describes a day spent at Oroshi-an, where the protagonist cooks rice over a traditional stove, prepares meals using a sunken hearth, and relaxes in a Goemon bath. The setting is rich in natural beauty, with the Pacific Ocean and the sacred Kumano mountains nearby, known for their spiritual significance. The video series aims to inspire viewers to consider rural living and the unique experiences it offers.' where id = 'ZS6ClYluaW77KDtFXFGtw';
update content_bodies set title = '【理想の田舎暮らし】七十三歳のシンデレラ - サステナブルな暮らし 第二話 囲炉裏篇', description = 'このエピソードでは、三重県御浜町に住む73歳の女性のサステナブルな日常生活を探ります。旅が自分の日常からの休息を提供し、他人の生活を垣間見ることの喜びを強調しています。特にコロナ禍で伝統的な旅行が難しくなった今、異なる日常を体験することの楽しさが語られています。囲炉裏でのご飯の炊き方や、鍋料理、五右衛門風呂を楽しむ様子が描かれ、田舎暮らしの美しさと、自然と精神的な遺産で知られる熊野地域の文化的重要性が強調されています。' where id = 'KlNGpSN3dqnY4YaxhDiLD';
update content_bodies set title = 'The Ideal Rural Life: The 73-Year-Old Cinderella - Sustainable Living Episode 2: Irori', description = 'This episode explores the daily life of a 73-year-old woman living sustainably in the rural area of Mihama, Mie Prefecture, Japan. It reflects on how travel can provide a break from one''s own routine and offers a glimpse into the lives of others. The narrative emphasizes the joy of experiencing different daily lives, especially during the COVID-19 pandemic when traditional travel has become challenging. The episode showcases a day filled with traditional activities such as cooking rice over a hearth, preparing meals with a irori (sunken hearth), and enjoying a Goemon bath. It highlights the beauty of rural living and the cultural significance of the Kumano region, known for its natural beauty and spiritual heritage.' where id = 'GhF7MSDSWSRa8HvRfYpzh';
update content_bodies set title = '【理想の田舎暮らし】七十三歳のシンデレラ - サステナブルな暮らし 第一話 竈門でご飯を炊く篇', description = 'この動画では、三重県御浜町尾呂志地区に住む73歳の女性のサステナブルな日常を探ります。コロナ禍で旅の形が変わる中、他人の日常を体験する楽しさに焦点を当てています。竈でご飯を炊き、囲炉裏で料理をする様子が描かれ、夕食後は五右衛門風呂でリラックスし、畳の上で眠る理想的な田舎暮らしが体験されます。このエピソードは、田舎暮らしの美しさとそのユニークな体験を考えるきっかけを提供します。' where id = 'oVJiDHhMUDzxisoZ6IFoZ';
update content_bodies set title = 'The Ideal Rural Life: The 73-Year-Old Cinderella - Sustainable Living Episode 1: Cooking Rice with a Kamado', description = 'This video explores the daily life of a 73-year-old woman living sustainably in the rural area of Oroshi, Mihama Town, Mie Prefecture. It reflects on how the pandemic has changed travel and living experiences, emphasizing the joy of experiencing someone else''s daily life. The episode showcases traditional cooking methods, such as using a kamado to cook rice and preparing meals over an irori (a traditional Japanese hearth). After dinner, the protagonist relaxes in a Goemon bath and sleeps on tatami mats, embodying an ideal rural lifestyle reminiscent of Japanese folklore. The video invites viewers to consider the beauty of rural living and the unique experiences it offers.' where id = '0YAZu9C0QH7sxuCyNV9p_';
update content_bodies set title = '心奪われる鹿児島', description = '鹿児島は、雄大な火山の風景、美しい自然、古くからの海外との交流によって形成された独自の食文化、豊富な温泉など、多彩な魅力を持つ地域です。歴史的背景が日本の発展に影響を与え、個性的な文化や習慣を持つ離島も点在しています。鹿児島の日常生活に触れ、地域の人々と共にその魅力を体験することができます。' where id = 'd9KjP4vrKI14GgzoqS3ej';
update content_bodies set title = 'BREATHTAKING KAGOSHIMA', description = 'Kagoshima is a region rich in natural beauty, featuring stunning volcanic landscapes, a unique food culture shaped by historical exchanges with other countries, and abundant hot springs created by volcanic activity. The area is steeped in history that has influenced Japan''s development, and it is home to diverse remote islands, each with its own distinct culture and traditions. Visitors can immerse themselves in the daily lives of the local people and explore the captivating attractions that Kagoshima has to offer.' where id = 'IzT1wXLB69pMx3lhnpPLP';
update content_bodies set title = '心奪われる鹿児島', description = '鹿児島の食文化は、地域に根ざし、熟練した手によって丁寧に作られた料理が特徴です。火山性の土地が育む多様な食材は、日常生活に欠かせない存在です。この本物の食体験は、農場から食卓への哲学を体現しており、毎食が特別なひとときとなります。鹿児島の味を堪能し、地域の人々の日常を豊かにする食文化を発見してください。' where id = 'vS2200AYUeHzJQe2i8tzJ';
update content_bodies set title = 'BREATHTAKING KAGOSHIMA', description = 'Kagoshima''s food culture is deeply rooted in the local community, with dishes crafted with care by skilled hands. The region''s unique volcanic landscape contributes to a rich variety of produce, which is integral to daily life. This authentic culinary experience showcases the farm-to-table philosophy, making every meal a special occasion. Discover the flavors of Kagoshima and how they enhance the everyday lives of its residents.' where id = 'K1XRkHTGlFQy2ExohSZzN';
update content_bodies set title = '心奪われる鹿児島', description = '鹿児島はかつてアジアと西洋との玄関口であり、火山と共生しながら異文化と交わり、繁栄してきました。その歴史は今も地元の人々の日常生活に息づいており、伝統と現代が融合した独自の文化を感じることができます。鹿児島の魅力は、歴史的な背景と共に、訪れる人々に深い感動を与えています。' where id = 'wlrz9DMNp-Ln2Jz8ZArOJ';
update content_bodies set title = 'BREATHTAKING KAGOSHIMA', description = 'Kagoshima was historically Japan''s gateway to Asia and the Western world. The city has thrived by coexisting with active volcanoes and engaging with diverse cultures. Today, the rich history of Kagoshima continues to resonate in the daily lives of its residents, reflecting a unique blend of tradition and modernity.' where id = 'rgWJhMXJTQDz1axc4jt6P';
update content_bodies set title = '心奪われる鹿児島', description = '鹿児島は、雄大な火山の風景、美しい自然、古くからの海外との交流によって形成された独自の食文化、豊富な温泉など、多彩な魅力を持つ地域です。鹿児島の歴史は日本の未来を形作る重要な要素であり、各々独自の文化や習慣を持つ離島も点在しています。地元の人々の日常生活に触れ、鹿児島の魅力を存分に楽しむことができます。' where id = 'aBSqZ5ym-33wShfRj63fv';
update content_bodies set title = 'BREATHTAKING KAGOSHIMA', description = 'Kagoshima is a region rich in natural beauty, featuring stunning volcanic landscapes, a unique food culture shaped by historical exchanges, and abundant hot springs created by volcanic activity. The area has a significant history that has influenced Japan''s development, and it is home to diverse remote islands, each with its own culture and traditions. Visitors can immerse themselves in the daily lives of the local people and explore the captivating attractions that Kagoshima has to offer.' where id = 'ZcEUF7_2aC4KOwfRLqyC0';
update content_bodies set title = '世界トップバーテンダーが語る本格焼酎', description = 'この動画では、世界トップバーテンダーの視点から、鹿児島県産の本格焼酎の魅力や焼酎カクテルについて紹介しています。' where id = 'Hk2qiOTIM9-i3uUtDNb6y';
update content_bodies set title = 'World''s Top Bartender Talks About Authentic Shochu from Kagoshima', description = 'This video introduces the appeal of authentic shochu produced in Kagoshima Prefecture from the perspective of a world-class bartender, along with shochu cocktails.' where id = 'X_EOmuSV45K1FtqLm5e64';
update content_bodies set title = '【Vol.3】＃キバレかごしまプロジェクト～私たちの手で鹿児島を元気に～', description = '「＃キバレかごしまプロジェクト」の待望の第三弾が登場！鹿児島県かごしまＰＲ課は、新型コロナウィルスとの厳しい戦いの中で頑張る鹿児島の皆さんに向けて、少しでも前向きになってもらえるようなメッセージ動画を制作し、配信しています。今回のメッセージは、市民吹奏楽団ウィンド・オーケストラ「フォレ」のマーチ「Fly to the Star」の爽やかなメロディに乗せて紹介されます。メッセージは応募のあった順に公開され、参加者には高校の吹奏楽部や企業、地域のクラブなど多様な団体が含まれています。プロジェクトは、地域の人々が「今やっていること」をテーマにした動画や写真の提供を呼びかけ、コミュニティの絆を深めることを目指しています。' where id = 'uTNi9cqMCxJMpGRNfly-G';
update content_bodies set title = 'Vol.3 #Kibare Kagoshima Project - Energizing Kagoshima with Our Hands', description = 'The highly anticipated third installment of the #Kibare Kagoshima Project is here! The Kagoshima PR Division aims to uplift the spirits of the local community, who are bravely battling the challenges posed by COVID-19. Together with those who love Kagoshima, they have created and are distributing a message video to inspire positivity. This edition features a refreshing melody from the Wind Orchestra ''Fore'' with their march ''Fly to the Star.'' The messages are released in the order they are submitted. Participants include various local groups and individuals, showcasing their love for Kagoshima. The project encourages submissions of short videos or photos with messages about current efforts and achievements, promoting community engagement and support.' where id = 'E7OmIBhdWLXw9FkZpN_rU';
update content_bodies set title = '【Vol.2】＃キバレかごしまプロジェクト～私たちの手で鹿児島を元気に～', description = '鹿児島県かごしまPR課は、新型コロナウィルスとの厳しい戦いの中で頑張っている鹿児島の皆さんに向けて、少しでも前向きになってもらうためのメッセージ動画を制作・配信しています。今回は「＃キバレかごしまプロジェクト～私の手で鹿児島を元気に～」の待望の第二弾です。メッセージは応募のあった順に公開され、地元の有名人や子どもたち、平川動物園の動物たちが参加しています。このプロジェクトは、地域の愛と努力を示し、コミュニティを元気づけることを目的としています。また、写真展や地元企業とのコラボレーションも行われています。参加希望者は、現在の取り組みや頑張っていることをテーマにした短い動画や写真を提出することができます。' where id = 'IhiA4MfvfKrx2ovWx1TwQ';
update content_bodies set title = '#Kibare Kagoshima Project Vol.2 - Energizing Kagoshima with Our Hands', description = 'The Kagoshima PR Department is producing and distributing message videos to encourage the people of Kagoshima who are fighting hard against the COVID-19 pandemic. This is the highly anticipated second installment of the ''#Kibare Kagoshima Project - Energizing Kagoshima with My Hands.'' The messages are released in the order they are submitted. Various participants, including local celebrities, children, and animals from the Hirakawa Zoo, contribute to the project. The initiative aims to uplift the community by showcasing their efforts and love for Kagoshima. Additionally, there are photo exhibitions and collaborations with local businesses. Those interested in participating can submit a short video or photo with a message about what they are currently doing or striving for.' where id = 'D8ehHR1KIYheFDzR1rry3';
update content_bodies set title = '僕の街は観光地', description = 'コロナ禍による観光地の衰退が懸念される中、その魅力を再確認することが重要です。私が育った伊東には多くの「光源」があり、全国から多くの人々が訪れています。観光地は訪れる人がいることでこそ、その魅力を最大限に発揮します。この素晴らしい魅力を広めるために、ぜひ拡散をお願いします。#伊東市 #伊東 #静岡県

InstagramやTwitterでのフォローもお待ちしています。映像制作やPR動画に関するお問い合わせは、リンクからお気軽にご連絡ください。' where id = '8JxAxXOOj0X5B-6k3P-ha';
update content_bodies set title = 'My hometown is a city that seduces a lot of people', description = 'In the context of the decline of tourist destinations due to the COVID-19 pandemic, it is essential to reaffirm the charm of these places. The city of Ito, where I grew up, has many ''light sources'' that attract visitors from all over the country. A tourist destination truly shines when there are people who visit it. To share this wonderful charm, I encourage everyone to spread the word. #ItoCity #Ito #ShizuokaPrefecture

Follow Me on Instagram and Twitter for more updates. For inquiries regarding video production and PR videos, please feel free to contact me through the provided link.' where id = 'EDl2bRe22Vz3wT4590pll';
update content_bodies set title = 'USAへLet''s Go～レジャースポット巡り編', description = 'このガイドでは、大分県のレジャースポットを2つ紹介します。まずは、安心院葡萄酒工房で、住所は大分県宇佐市安心院町下毛798です。営業時間は午前9時から午後6時までで、毎週火曜日は定休日ですが、祝日の場合は営業します。また、年末年始も休業です。次に、九州自然動物公園アフリカンサファリがあり、住所は大分県宇佐市安心院町南畑2-1755-1です。営業は季節によって異なり、3月1日から10月31日までは午前9時から午後5時、11月1日から2月28日までは午前10時から午後4時まで開いています。入園料金は大人が2,500円、小人（4歳から中学生）が1,400円です。' where id = 'dO7Po88wwifYb0aczgCq_';
update content_bodies set title = 'Let''s Go to the USA - Leisure Spot Tour', description = 'This guide highlights two leisure spots in Oita Prefecture, Japan. The first is the Ajimu Budoushu Koubou, located at 798 Shimoge, Ajimu-machi, Usa-city. It operates from 9 AM to 6 PM and is closed on Tuesdays, except for public holidays, as well as during the New Year holiday. The second spot is the African Safari Kyushu, situated at 2-1755-1 Minamihata, Ajimu-machi, Usa-city. Its operating hours vary by season: from March 1 to October 31, it is open from 9 AM to 5 PM, and from November 1 to February 28, it opens from 10 AM to 4 PM. Admission fees are ¥2500 for adults and ¥1400 for children aged 4 to 15.' where id = 'qtXhx4Q4WletBT4fj2KKt';
update content_bodies set title = 'USAへLet''s Go～自然スポット巡り編', description = 'このガイドでは、大分県の注目スポットを2つ紹介します。まずは道の駅いんないで、住所は大分県宇佐市院内町大字副1381-2です。電話番号は0978-42-5539で、営業時間は午前10時から午後5時までです。次に、ワイナリーレストラン朝霧の庄があり、住所は大分県宇佐市安心院町下毛828-2です。電話は0978-44-1236で、営業時間は午前8時30分から午後5時までですが、12月30日から1月1日は閉館しています。' where id = '1iDp3AlKw9dPbMNGvn8ln';
update content_bodies set title = 'Let''s Go to the USA - Nature Spot Tour', description = 'This guide features two notable locations in Oita Prefecture, Japan. The first is Michi-no-Eki Innai, located at 1381-2, Soi, Innai-machi, Usa-city. It can be reached at 0978-42-5539 and is open from 10 AM to 5 PM. The second location is Restaurant Asagiri-no-shou, situated at 828-2, Shimoge, Ajimu-machi, Usa-city. For inquiries, call 0978-44-1236. This restaurant operates from 8:30 AM to 5 PM but is closed from December 30th to January 1st.' where id = 'qLp6iYimLsLcBfC363qiB';
update content_bodies set title = 'USAへLet''s Go～四日市門前町散策編～', description = 'このガイドでは、大分県宇佐市四日市にある2つの注目スポットを紹介します。まずは、ねぎ屋さんのねぎ焼で、住所は四日市1398-2です。営業時間は午前11時から午後2時30分、午後4時30分から午後9時までで、月曜日は午前11時から午後6時までの短縮営業、火曜日は定休日です。次に、Michiyard cafeが四日市1354-1にあり、正午から午後3時30分、午後9時から午前2時まで営業しており、不定休です。どちらのスポットも、地域のユニークな食体験を提供しています。' where id = '2u7VkV02GURN-bp88jU_X';
update content_bodies set title = 'Let''s Go to the USA - Yokkaichi Monzen Town Exploration', description = 'This guide features two notable places in Yokkaichi, Usa City, Oita Prefecture. The first is Negiya, known for its Negiyaki, located at 1398-2 Yokkaichi. It operates from 11 AM to 2:30 PM and 4:30 PM to 9 PM, with reduced hours on Mondays (11 AM to 6 PM) and is closed on Tuesdays. The second location is Michiyard Cafe at 1354-1 Yokkaichi, which opens from noon to 3:30 PM and again from 9 PM to 2 AM, with irregular holidays. Both spots offer unique dining experiences in the area.' where id = 'f57bNqr5f0Ysbli_v-2Df';
update content_bodies set title = 'USAへLet''s Go～フルーツ狩り編～', description = 'アクトいちごファームは、宇佐市蜷木2215-51に位置しています。電話番号は0978-38-5701です。開園期間は1月15日から5月7日までで、5月9日以降は限定開園となります（詳細はお問い合わせください）。営業時間は午前10時から午後4時までで、日曜・祝日は午前9時から午後4時まで、入園は午後3時30分までです。料金は、中学生以上が1,600円（4月10日から5月7日は1,300円）、小学生が1,200円、3歳から5歳が800円、2歳以下は無料です。' where id = '79DoVWsFGR2R-g3VLYC-7';
update content_bodies set title = 'Let''s Go to the USA - Fruit Picking Edition', description = 'ACT Strawberry Farm is located at 2215-51, Ninagi, Usa-city, Oita-pref. The phone number is 0978-38-5701. The farm is open from January 15 to May 7, with limited openings after May 9 (please inquire for details). Operating hours are from 10 AM to 4 PM, and from 9 AM to 4 PM on Sundays and public holidays, with last entry at 3:30 PM. Admission fees are as follows: Adults (middle school and above) are ¥1,600 (¥1,300 from April 10 to May 7), Elementary students are ¥1,200, children aged 3 to 5 are ¥800, and children under 2 years old can enter for free.' where id = 'HVv_85kqgdzZ4fjdICiYz';
update content_bodies set title = 'USAへLet''s Go～パワースポット巡り編～', description = 'このガイドでは、日本の宇佐市にある3つの注目スポットを紹介します。まずは宇佐神宮で、住所は宇佐市南宇佐2859で、八幡バス停から徒歩10分の距離です。開門時間は午前5時30分から午後9時（10月から3月は午前6時から）で、参拝料は無料、休業日はありません。駐車料金は400円です。次に、里の駅双葉の里が大字下庄269にあり、開館時間は午前9時から午後5時で、入場料は無料ですが、毎月第3月曜日は休館です。駐車場は24台分あります。最後に、からあげすずやも同じ住所にあり、午前10時から午後7時まで営業しており、月曜日は定休日ですが祝日の場合は営業しています。駐車場は7台分です。' where id = 'UMoEVa83ZxLeMBXok8WAP';
update content_bodies set title = 'Let''s Go to the USA - Power Spot Tour Edition', description = 'This guide highlights three notable locations in Usa City, Japan. First is Usa Jingu Shrine, located at 2859 Minami-usa, a 10-minute walk from Hachiman bus stop. It is open from 5:30 am to 9 pm (6 am to 9 pm from October to March) and is free to visit, with no holidays. Parking costs 400 yen. Next is Sato-no-Eki Futaba-no-Sato at 269 Shimosho, open from 9 am to 5 pm, also free to enter, but closed on the third Monday of each month. It has 24 parking bays. Lastly, Fried Chicken Suzuya, located at the same address as Futaba-no-Sato, operates from 10 am to 7 pm and is closed on Mondays unless it''s a public holiday, with 7 parking bays available.' where id = 'mkylJ5BIMybIMZBFE09qh';
update content_bodies set title = '宇佐の湯めぐり', description = 'この文章では、宇佐市内の温泉施設を紹介しています。最初の施設は津房温泉で、アルカリ性単純泉を特徴としています。住所は宇佐市安心院町五朗丸3731で、電話番号は0978-48-2037です。入浴料は市内の一般が250円、小中学生・70歳以上が100円で、市外は一般300円、小中学生150円です。家族風呂は市内700円、市外1,000円です。営業時間は11時から21時までで、10月から3月は11時から20時まで、定休日は水曜日です。次の施設は余温泉で、単純温泉を持っています。住所は宇佐市院内町上余1571で、電話番号は0978-42-7048です。入浴料は津房温泉と同じで、営業時間は12時から21時まで、10月から3月は12時から20時まで、定休日は水曜日です。' where id = '3eexehJUhf1BDDKpf6jQ8';
update content_bodies set title = 'Hot Springs Tour in Usa', description = 'This text introduces hot spring facilities in Usa City. The first facility is Tsubo Onsen, which features alkaline simple spring water. It is located at 3731 Goro-maru, Anjuin-cho, Usa City, and can be contacted at 0978-48-2037. The entrance fee is 250 yen for adults and 100 yen for elementary and middle school students or seniors over 70 for local visitors, while it is 300 yen and 150 yen for non-local visitors. Family baths cost 700 yen for locals and 1,000 yen for non-locals. The operating hours are from 11 AM to 9 PM, with reduced hours from 11 AM to 8 PM during October to March, and it is closed on Wednesdays. The second facility is Yo Onsen, which has simple spring water. It is located at 1571 Kamiyo, Innai-cho, Usa City, and can be reached at 0978-42-7048. The entrance fees are the same as Tsubo Onsen, and the operating hours are from 12 PM to 9 PM, with reduced hours from 12 PM to 8 PM during October to March, also closed on Wednesdays.' where id = 'gBHpTY3CV6BF9UlMc4NI5';
update content_bodies set title = '宇佐市院内のおすすめ観光スポット', description = '宇佐市院内の観光スポットを紹介します。まず、レンタサイクルが利用できる「道の駅いんない」があり、観光の拠点として便利です。次に、歴史的な「逸見邸庭園」があり、美しい庭園を楽しむことができます。そして、最後に「宇佐のマチュピチュ」と呼ばれるスポットがあり、独特の景観が魅力です。これらのスポットは、訪れる価値があります。' where id = '6mHgNKtwyFlTR3tmuehRH';
update content_bodies set title = 'Recommended Tourist Spots in Usuki City Innai', description = 'This article introduces recommended tourist spots in Usuki City Innai, including the ''Michi no Eki Innai'' where you can rent bicycles, the ''Henmi Family Garden,'' and the ''Machu Picchu of Usa.''' where id = 'L3nfPZLB6s4rHpH5wUV4-';
update content_bodies set title = '響山公園 あじさい', description = '響山公園では、約3,000本のあじさいが梅雨の風物詩として古くから愛されています。雨の中でも映える赤、白、紫の色鮮やかなあじさいは、多くの人々に和みを与えてくれます。' where id = 'fJXtjsomistwOY-HKSpfv';
update content_bodies set title = 'Hibiyama Park Hydrangeas', description = 'Hibiyama Park is adorned with approximately 3,000 hydrangeas, cherished as a symbol of the rainy season for many years. The vibrant red, white, and purple hydrangeas shine even in the rain, bringing comfort to many visitors.' where id = 'LS4-1mxCvkOx66AUhtJct';
update content_bodies set title = '家族旅行村「安心院」', description = '家族旅行村「安心院」は、大自然の中で家族や友人と共にリラックスできる本格的なログハウスを提供しています。お子様からお年寄りまで楽しめるパークゴルフ場や、疲れた体を癒す温泉など、多彩なレジャー施設が揃っています。また、最近注目されているオートキャンプ場では、最大16張りのテントを設置でき、バーベキューや昆虫採集、天体観測などのアクティビティを楽しむことができます。家族旅行村「安心院」で、自然を感じながらゆったりとした時間をお過ごしください。' where id = 'XeyUBl3URNHOI2cz0_ubf';
update content_bodies set title = 'Ajimu Family Resort', description = 'Ajimu Family Resort offers a relaxing getaway in the midst of nature, featuring authentic log cabins for families and friends. The resort includes a park golf course suitable for all ages, providing a fun and accessible sports facility. Guests can also enjoy soothing hot springs to rejuvenate their bodies. Recently, the resort has gained attention for its auto camping area, which can accommodate up to 16 tents, allowing for activities such as barbecuing, insect collecting, and stargazing. Experience a leisurely time in nature at Ajimu Family Resort.' where id = 'qDRnUmFZyLidm9SC_XI5H';
update content_bodies set title = '林家三平氏による平和へのメッセージ', description = '令和6年6月1日(土)に開催された「平和を考える 映画と落語」において、林家三平氏が宇佐市に訪れました。彼は宇佐市平和ミュージアム（仮称）の建設予定地にて、平和への想いを語りました。このイベントは、映画と落語を通じて平和について考える機会を提供するものであり、三平氏のメッセージは参加者に深い感銘を与えました。' where id = 't-2LjfFyFa5Rtl_FlX6na';
update content_bodies set title = 'Message for Peace by Sanpei Hayashiya', description = 'On June 1, 2024, Sanpei Hayashiya visited Usa City for the event ''Thinking about Peace: Movies and Rakugo.'' During his visit, he shared his thoughts on peace at the planned site for the Usa City Peace Museum.' where id = 'dBlIw0aKJsK6XqvHAeZO1';
update content_bodies set title = 'フィッシャーマンズワーフ白浜', description = 'フィッシャーマンズワーフ白浜は、地元の漁師が運営する施設です。1階には鮮魚市場があり、2階にはレストランがあります。また、屋上には季節限定のビアガーデンも設けられています。併設された桟橋から直接水揚げされた新鮮な食材を使用した和食やイタリアンを楽しむことができます。' where id = 'SLSw_A683MtGNPmK6RMyv';
update content_bodies set title = 'Fisherman''s Wharf Shirahama', description = 'Fisherman''s Wharf Shirahama is a facility operated by local fishermen. The first floor features a fresh fish market, while the second floor houses a restaurant. Additionally, there is a seasonal beer garden on the rooftop. Guests can enjoy a variety of Japanese and Italian dishes made with fresh ingredients directly sourced from the pier.' where id = 'gq-O-oL0ipv78pUglPvSO';
update content_bodies set title = '三段壁 シネマティック', description = '三段壁は千畳敷の南海岸にそそり立つ高さ50m～60mの断崖で、南北2kmにわたって展開しています。この大岩壁は、漁師たちが船や魚の群れを見張った「見壇」に由来すると言われています。岩肌に打ち寄せる黒潮が激しくぶつかり合う様子は、自然の迫力を感じさせます。2016年4月には、恋人の聖地「南紀白浜/三段壁」として選定されました。' where id = 'i2GNvbSyFfTU_T4V7AONI';
update content_bodies set title = 'Sandanbeki Cinematic', description = 'The Sandanbeki cliffs rise 50 to 60 meters along the southern coast of the Senjojiki area. This massive rock wall, which stretches 2 kilometers from north to south, is said to have originated from a lookout point where fishermen once observed passing ships and schools of fish. The dynamic scene of the Kuroshio current crashing against the rocky surface evokes a powerful sense of nature. In April 2016, Sandanbeki was designated as a ''Sacred Place for Lovers'' in Nanki Shirahama.' where id = 'sZSzMCGCz7oOHTS7_2SKm';
update content_bodies set title = '佐賀・武雄「芸奴なりきり体験」', description = '佐賀県武雄市観光協会の公式チャンネルでは、芸奴なりきり体験を提供しています。この体験では、白い化粧を施し、実際の芸奴の着物やかつらを身に着けることで、芸奴の気分を味わうことができます。予約は、提供されたリンクから行えます。' where id = '2wPOrJ9xd4NqJcos6TKWP';
update content_bodies set title = 'Geisha Makeover Experience in Takeo, Saga', description = 'The official channel of the Saga Prefecture Takeo City Tourism Association offers a unique Geisha makeover experience. Visitors can enjoy the feeling of being a Geisha by applying white make-up and wearing authentic kimonos and wigs. Reservations can be made through the provided link.' where id = '5xmhnkkI_CTGWWckXWKvh';
update content_bodies set title = '【公式】佐賀・武雄／パン・ピザ作り体験', description = '佐賀県武雄市観光協会の公式チャンネルでは、黒髪山の麓にあるピザ窯を利用した手づくりのパンやピザ作り体験ができます。観光客はこのユニークな体験を通じて、地元の文化や食を楽しむことができます。' where id = 'fHqU2mn9xv6k590vt95B9';
update content_bodies set title = 'Making Bread/Pizza Experience - Japan/SAGA/Takeo Tourism Official Channel', description = 'The official channel of the Saga Prefecture Takeo City Tourism Association offers a unique experience of making bread and pizza. Visitors can enjoy hands-on activities using a pizza kiln located at the foot of Mt. Kurokami.' where id = 'I4xVzwuw4HdJVPwkK_5GP';
update content_bodies set title = '公式 佐賀武雄・お寺で写経体験', description = '佐賀県武雄市観光協会の公式チャンネルです。静かな寺院の境内で、筆を持ち、一文字一文字を無心に記す写経体験を提供しています。この特別な体験を通じて、心を落ち着ける時間を持つことができます。予約は下記のリンクから行えます。' where id = 'pzS0wWDUIpGdQqn_h1wbR';
update content_bodies set title = 'Official Sutra-copying Experience in Takeo, Saga', description = 'The official channel of the Takeo City Tourism Association in Saga Prefecture invites you to experience sutra-copying in a tranquil temple setting. This unique activity allows participants to hold a brush and mindfully write each character. Reservations can be made through the provided link.' where id = 'ghVQdMp_xuEq8QFVitX6Y';
update content_bodies set title = 'MOARE - 自然と調和した照明', description = '岐阜県高山市は飛騨の匠としての歴史があり、弊社は天然木を使用した木製照明の開発・製造・販売を行っています。MOAREは、木のぬくもりと優しいあかりの融合から生まれる心地よさを大切にした日本生まれの木製照明ブランドです。' where id = 'G27nApbplzzdD6x3APLJI';
update content_bodies set title = 'MOARE - Illumination in unison with nature', description = 'MOARE is a Japanese brand specializing in wooden lighting, developed, manufactured, and sold using natural wood. Based in Takayama, Gifu Prefecture, known for its craftsmanship, MOARE emphasizes the fusion of the warmth of wood and gentle light, creating a sense of comfort. The brand aims to provide a unique lighting experience that resonates with nature.' where id = 'DT1i4YQwDuhbNQzDyCKG8';
update content_bodies set title = '壷阪寺 秋', description = 'この作品は2020年度に制作されました。壷阪寺は南法華寺とも呼ばれ、奈良県高市郡高取町に位置しています。住所は奈良県高市郡高取町壷阪3、郵便番号は635-0102です。' where id = 'mnNvtcsiuqGORwXQuqvls';
update content_bodies set title = 'Tsubosaka-dera in Autumn', description = 'This work was created in 2020. Tsubosaka-dera, also known as Nanpou Hōkaji, is located in Takaichi-gun, Takatori Town, Nara Prefecture, Japan. The address is 3 Tsubosaka, Takaichi-gun, Takatori Town, Nara 635-0102.' where id = 'AQ0UQcIGuBFoEyTGANVqR';
update content_bodies set title = '世界を旅した1年間', description = '2022年を4分で振り返る動画です。今年は本当に冒険に満ちた1年で、世界中を旅しました。私の旅の最新情報や洞察を得るために、SNSをフォローしてください。撮影に関するお問い合わせは、メールでご連絡ください。私の撮影機材には、α7SⅢカメラ、Sony16-35 F4 Gレンズ、SIGMA 28-70 F2.8レンズ、RSC2、Mavic Air 2、GoPro Hero 10が含まれています。' where id = 'PgF1llk7_4gGkXM3n5GxJ';
update content_bodies set title = 'My year 2022 cinematic in the world', description = 'In this 4-minute video, I reflect on my experiences throughout 2022. It was truly an adventurous year as I traveled around the world. Follow me on my social media platforms for more updates and insights into my journey. For inquiries regarding filming, please contact me via email. My filming gear includes the α7SⅢ camera, Sony 16-35 F4 G lens, SIGMA 28-70 F2.8 lens, RSC2, Mavic Air 2, and GoPro Hero 10.' where id = '-PPfIbSQHytF0ClP7XbVj';
update content_bodies set title = '和歌山県すさみ町&三重県二木島町観光PR動画', description = '和歌山県すさみ町と三重県二木島町のPR動画を制作しました。自然が豊かなすさみ町と漁師町として知られる二木島町の日常をシネマティックに表現しています。ぜひ、これらの美しい場所を訪れてみてください。' where id = 'Y-DppzFX4REflSYfhTQRF';
update content_bodies set title = 'Wakayama & Mie PR Cinematic Japan', description = 'A promotional video has been created for Susami Town in Wakayama Prefecture and Nigi Island Town in Mie Prefecture. The video artistically showcases the rich natural beauty of Susami Town and the daily life of the famous fishing town, Nigi Island. We encourage you to visit these beautiful locations.' where id = '45jxh25M5nBnBDs2S6I8k';
update content_bodies set title = 'My Year 2021 | Cinematic JAPAN | Shunpei Kawai', description = '2021年、私は日本一周の旅に出ました。自転車での移動やヒッチハイクで九州を巡るなど、多くの挑戦をしました。この1年でカメラと出会い、映像制作に目覚めました。日本の美しさを映像に収め、多くの人々と共有しました。この動画は、私の旅の思い出をまとめたもので、映像制作を始めてからの初めての1年を振り返るものです。これからも映像を通じて自分の人生を表現し続けていきます。ぜひプロフィールのリンクからご覧ください！' where id = 'nLcM6PLs-kh0P64kzYaUd';
update content_bodies set title = 'My Year 2021 | Cinematic JAPAN | Shunpei Kawai', description = 'In 2021, I embarked on a journey across Japan, cycling around the country and hitchhiking through Kyushu. This year was transformative as I discovered my passion for videography. I captured the beauty of Japan through my lens and created a video that reflects my experiences. This marks my first full year of working with video, and I am grateful to everyone who has supported me along the way. I aim to continue expressing my life through film and sharing the charm of Japan with others. Please check out my work through the link in my profile!' where id = 'kQ9R7O0-_k5lWkfhq8pQA';
update content_bodies set title = '考えずに過ごす一日 | 東京のシネマティックVlog', description = 'このシネマティックVlogでは、東京での何気ない一日を撮影し、日常生活の美しさを表現しています。動画のモデルになってくれた友達に感謝の気持ちを伝えています。旅動画だけでなく、今後はシネマティックVlogも増やしていく予定で、旅を楽しむ姿勢を強調しています。また、動画にはクリエイターのSNSアカウントや音楽の出所、編集に使用したアプリケーションのリンクも含まれています。' where id = 'mLcj1oFr8frkELJy7sNo6';
update content_bodies set title = 'A Day Without Thinking | Cinematic Vlog in Tokyo', description = 'This cinematic vlog captures an ordinary day in Tokyo, showcasing the beauty of everyday life. The creator expresses gratitude to a friend who modeled for the video. In addition to travel videos, the creator plans to share more cinematic vlogs in the future, emphasizing a passion for travel. The video also includes links to the creator''s social media accounts and music source, as well as the application used for editing.' where id = 'ouphJ3ZFgc65qvjRZn_Dn';
update content_bodies set title = '【神奈川Vlog】旅人の食べ歩きをcinematicに表現してみた', description = 'こんにちは、河合舜平です！バックパッカーの旅の日常を発信しています。チャンネル登録していただけると嬉しいです！今回は神奈川のVlogで、ヒッチハイクで神奈川に来ました。中華街やみなとみらいを訪れました。もっと旅をして、自分の目で様々なものを見たいと思っています。InstagramやTwitterのアカウントもあります。撮影にはa6600カメラとSEL1655Gレンズを使用し、Adobe Premiere Proで編集しました。音楽はArtlistから使用しています。' where id = 'noQL7ukIEDhyiuGDy7bR_';
update content_bodies set title = 'Kanagawa Vlog: Cinematic Expression of a Traveler''s Food Journey', description = 'Hello, I''m Shunpei Kawai! I share my daily experiences as a backpacker. I would be happy if you could subscribe to my channel! This time, I present a Vlog from Kanagawa, where I arrived by hitchhiking. I visited Chinatown and Minato Mirai. I want to travel more and see various things with my own eyes! You can find my social media accounts on Instagram and Twitter. The video was shot using a6600 camera with a SEL1655G lens and edited with Adobe Premiere Pro, featuring music from Artlist.' where id = '07_zpDmChgrHOY3jeZzfi';
update content_bodies set title = '「THE FACES OF SHIKOKU」30秒バージョン', description = 'この動画は、四国の「ひと」、「自然」、そして「お遍路」をテーマにした内容です。四国の魅力を短い時間で伝え、地域の文化や風景を紹介しています。' where id = 'Pb60Izu19403eQDnKA0-Q';
update content_bodies set title = 'THE FACES OF SHIKOKU 30 seconds ver.', description = 'This video showcases the essence of Shikoku through the themes of ''people'', ''nature'', and ''pilgrimage''.' where id = 'w53ZKnUYwJDDlr06eWluX';
update content_bodies set title = 'シネマティックコーヒービデオ | チャイティーヘロン | Sony a6600', description = 'こんにちは、河合舜平です！バックパッカーの旅の日常をシネマティックに発信しています。今回はゲストハウスで仲良くなった方のカフェ、チャイティーヘロンを訪れた際のシネマティック動画を作成しました。チャイティーヘロンは福岡市中央区大宮1-4-22に位置し、営業時間は12:00から20:00まで、ラストオーダーは19:30で、木曜日は定休日です。チャイ専門店で、うきは産の有機紅茶と波照間島の黒糖を使用し、約12種類のホールスパイスを挽いてから一杯ずつチャイを淹れています。スタンダードなものから変わり種まで多様なメニューがあります。SNSではInstagramとYouTubeで情報を発信しています。動画はSony a6600カメラとSEL1655Gレンズで撮影し、Adobe Premiere Proで編集しました。' where id = 'd-eFpqZN4Zdubwx3MZKQq';
update content_bodies set title = 'Cinematic Coffee Video | Chai Tea Heron | Sony a6600', description = 'Hello, I''m Shunpei Kawai! I share my backpacking travel experiences in a cinematic style. In this video, I visited a café where I made friends at a guesthouse and created a cinematic video. The café, Chai Tea Heron, is located at 1-4-22 Omiya, Chuo Ward, Fukuoka City. It opens from 12:00 to 20:00, with the last order at 19:30, and is closed on Thursdays. Specializing in chai, they use organic black tea from Ukiha and brown sugar from Hateruma Island, preparing each cup with about 12 types of whole spices ground fresh upon order. They offer both standard and unique chai options. You can find Chai Tea Heron on Instagram and YouTube. The video was shot with a Sony a6600 camera and SEL1655G lens, edited using Adobe Premiere Pro, and features music from Artlist.' where id = 'oxr9YSBMFsFmQSltYbOaK';
update content_bodies set title = '【福岡Vlog 2】バックパッカーの日常をCinematicにしてみた 太宰府天満宮　竈門神社', description = 'こんにちは、河合舜平です！バックパッカーの旅の日常をシネマティックに発信しています。福岡での2本目の動画では、観光名所の太宰府天満宮や、アニメ『鬼滅の刃』の影響で人気の竈門神社、そしてサザエさん通りを訪れました。現在宿泊中のゲストハウスも居心地が良く、楽しい生活を送っています。チャンネル登録もぜひお願いします！' where id = 'xPkHaKZ-tubvWyd9XssZK';
update content_bodies set title = 'Fukuoka Vlog 2: Cinematic Backpacker Life at Dazaifu Tenmangu and Kamado Shrine', description = 'Hello, I''m Shunpei Kawai! I''m sharing my backpacker journey in a cinematic style. This is my second video in Fukuoka, where I visited famous tourist spots like Dazaifu Tenmangu and Kamado Shrine, which gained popularity due to the anime ''Demon Slayer.'' I also explored the lively Sazae-san Street. I''m currently enjoying my stay at a very comfortable guesthouse. Don''t forget to subscribe to my channel!' where id = 'vFqvn3lsTIlCqqBN53i5U';
update content_bodies set title = '四国の魅力を発見する', description = 'この動画は四国のアドベンチャートラベルを紹介しています。イントロの後、徳島県の祖谷渓谷や高知県の四万十川観光遊覧船、三里沈下橋などの名所が紹介されます。さらに、かずら橋や琵琶の滝、レンタサイクル、愛媛県・高知県の四国カルスト、しまなみ海道、香川県の栗林公園、愛媛県のお座敷遊びなども取り上げられています。内子座や白鳥神社、古武道体験、愛媛県内子町、香川県の父母ヶ浜、高知県の竹林寺、そして徳島県の阿波おどりの様子も紹介され、四国の多様な魅力が伝わります。' where id = 'I8M9kxVyCb8EoJOV7XKII';
update content_bodies set title = 'DISCOVER THE WONDERS OF SHIKOKU', description = 'This video introduces adventure travel in Shikoku, showcasing various attractions across the region. It begins with an introduction and then highlights notable locations such as the Iya Valley in Tokushima, the Shimanto River sightseeing boat in Kochi, and the Sanri Sink Bridge. Other featured sites include the Kazura Bridge, Biwa Waterfall, and cycling rentals. The video also covers the Shikoku Karst, the Shimanami Kaido, Ritsurin Garden in Kagawa, and traditional activities in Ehime. Additional attractions include the Utsukushigawa Theatre, Shiratori Shrine, and experiences in Kōbudo. The video concludes with a glimpse of the Awa Odori dance in Tokushima.' where id = 'C15bCrOsNoDNyd49V-A-D';
update content_bodies set title = '「しこくるり」トリセツYouTube動画', description = '四国をぐるっと楽しむ旅アプリ「しこくるり」のトリセツ動画です。このアプリは無料でダウンロードできます。「しこくるり」を使って、四国観光をおトクに便利に、さらに楽しむことができます。公式ページやApp Store、Google Playのダウンロードリンクも紹介されています。' where id = 'ptw5CAfrlUnKBeal8cSYp';
update content_bodies set title = 'Shikokururi Instructional YouTube Video', description = 'This is an instructional video for the travel app ''Shikokururi'', which allows you to enjoy a comprehensive trip around Shikoku. The app is free to download! Use ''Shikokururi'' to make your Shikoku sightseeing experience more convenient, economical, and enjoyable! You can find the official page and download links for both the App Store and Google Play.' where id = 'Nu1j6zh3YR1R13HkDPJ2f';
update content_bodies set title = 'SPIRITUAL ISLAND ～SHIKOKU HENRO～  KO', description = 'このタイトルは、四国遍路に関連する精神的な旅に焦点を当てていることを示唆しています。説明は現在未指定ですが、四国島でのこの遍路の旅の中で得られる経験や洞察に関連している可能性があります。' where id = 'SvujszL3MJrcL0wkOM2OD';
update content_bodies set title = 'SPIRITUAL ISLAND ～SHIKOKU HENRO～  KO', description = 'This title suggests a focus on the spiritual journey associated with the Shikoku pilgrimage, known as Henro. The description is currently unspecified, but it likely relates to the experiences and insights gained during this pilgrimage on Shikoku Island.' where id = 'HTOIErilouse0mW5--1cF';
update content_bodies set title = '【徳之島】奄美群島認定エコツアーガイド  天城町編', description = 'この動画では、奄美群島エコツーリズム魅力体験事業の一環として、徳之島天城町に住む認定エコツアーガイドの松村さんに密着しています。エコツアーの内容や地域の自然環境について紹介されており、無声で再生可能な日本語字幕付きの動画です。ツアーやガイドに関する問い合わせは、各島の観光協会に連絡するよう案内されています。徳之島観光連盟の情報も提供されています。' where id = 'wwu5LdO0-iHp5IpE0rvuI';
update content_bodies set title = 'Eco tourism in Amagi Town Tokunoshima Island (with Japanese subtitles)', description = 'This video features Matsumura, a certified eco-tour guide residing in Amagi Town, Tokunoshima Island, as part of the Amami Islands Eco-Tourism Experience Project by the Amami Regional Office. The video showcases eco-tours and provides insights into the local environment. For inquiries about tours and guides, please contact the tourism associations of each island. The Tokunoshima Tourism Organization is also mentioned for further information.' where id = 'kWJDR4-YteDWA0GeoO-Ry';
update content_bodies set title = '奄美郡岛认证生态导游  德之岛 天城町', description = 'この文章は、奄美群島におけるエコツーリズム体験について述べており、徳之島天城町に住む認定エコツアーガイドの松村さんへのインタビューを中心に展開しています。オンラインツアーでは、地域の自然の美しさや生物多様性が強調されており、世界自然遺産として認識されています。ツアーやガイドに関する問い合わせは、各島の観光協会に連絡することが推奨されています。エコツーリズムや自然体験の重要性が強調され、奄美の特有の野生動物、特に奄美兔への意識を高めることが目的とされています。' where id = 'JeLHuxa-x3ibZ1hLeHXxv';
update content_bodies set title = 'Eco tourism in Amagi Town Tokunoshima Island Chinese subtitles', description = 'This text discusses the eco-tourism experience in the Amami Islands, focusing on an interview with Mr. Matsumura, a certified eco-tour guide residing in Amagi Town, Tokunoshima Island. The online tour highlights the natural beauty and biodiversity of the region, which is recognized as a World Natural Heritage site. For inquiries about tours and guides, visitors are encouraged to contact the respective tourism associations on each island, including the Tokunoshima Tourism Organization. The text emphasizes the importance of eco-tourism and nature experiences in promoting awareness of the area''s unique wildlife, such as the Amami rabbit.' where id = 'Lz5aVJrp0nIvaAW_WEFOQ';
update content_bodies set title = '奄美群島認定エコツアーガイド 徳之島 天城町編 英語字幕', description = 'この動画では、徳之島の天城町に住む認定エコツアーガイドの松村さんを紹介しています。奄美群島におけるエコツーリズムの機会を強調し、生物多様性や自然体験の重要性について触れています。エコツアーやガイドに関する詳細は、徳之島観光連盟のウェブサイトを訪れることが推奨されています。この動画は、奄美群島の自然遺産を促進するための広範な取り組みの一環であり、アマミノクロウサギを含む独自の生態系や野生動物が認識されています。' where id = 'RJYBg5HD1Rl00XfSjCV69';
update content_bodies set title = 'Eco tourism in Amagi Town Tokunoshima Island English subtitles', description = 'This video features Matsumura-san, a certified ecotour guide residing in Amagi Town on Tokunoshima Island. It highlights the ecotourism opportunities available in the Amami Islands, emphasizing the importance of biodiversity and natural experiences. For further details on eco-tours and guides, viewers are encouraged to visit the Tokunoshima Tourism Organization''s website. The video is part of a broader initiative to promote the natural heritage of the Amami Islands, which are recognized for their unique ecosystems and wildlife, including the Amami rabbit.' where id = 'H5vWRmS_MBvj_3LXpKk6F';
update content_bodies set title = '奄美群島エコツアーガイド 知名町編', description = 'この動画は、沖永良部島の知名町におけるエコツーリズムガイドを紹介しており、日本語字幕が付いています。無声で再生可能です。奄美広域事務組合の奄美群島エコツーリズム魅力体験事業の一環として制作され、地域通訳案内士の有川さんに密着し、地域のエコツアーの魅力を伝えています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。沖永良部島観光協会のウェブサイトは http://www.okinoerabujima.info/ です。動画では、世界自然遺産や生物多様性、伝統的な芭蕉布などのテーマが取り上げられています。' where id = 'yiTZ3cQRjkLu0WFVVozYH';
update content_bodies set title = 'Eco tourism in China Town Okinoerabujima Island (Japanese Subtitles)', description = 'This video features an eco-tourism guide in China Town, Okinoerabujima Island, with Japanese subtitles and is playable without sound. It is part of the Amami Islands Eco-Tourism Experience Project by the Amami Regional Office. The video closely follows a local interpreter guide, Mr. Arikawa, who resides in China Town, showcasing the eco-tourism opportunities available in the area. For inquiries about tours and guides, please contact the respective island''s tourism association. The Okinoerabu Island Tourism Association can be found at http://www.okinoerabujima.info/. The video highlights themes such as World Natural Heritage, biodiversity, and traditional crafts like Bashofu.' where id = '0g95h6izSSPoLvdD6bIlS';
update content_bodies set title = '奄美群島エコツアーガイド 和泊町編', description = 'この動画は、奄美群島エコツーリズム魅力体験事業の一環として、沖永良部島和泊町に住む地域通訳案内士の吉成さんに密着し、エコツアーの様子を紹介しています。地域の自然の美しさや生物多様性を体験できる内容となっており、観光やツアーに関する問い合わせは各島の観光協会にお願いします。沖永良部島観光協会のウェブサイトも参照してください。' where id = 'awBK1-acHPcxdUti8QhKk';
update content_bodies set title = 'Eco tourism in Okinoerabujima Wadomari Town (Japanese subtitles available)', description = 'This video features an eco-tour guide in Wadomari Town, Okinoerabujima, focusing on the experiences offered by the Amami Islands Eco-Tourism project. The video follows Yoshinari, a local interpreter guide, as he showcases the natural beauty and biodiversity of the area. For inquiries about tours and guides, please contact the respective tourism associations of the islands. The Okinoerabu Island Tourism Association is available for more information.' where id = '2D5pFEAIYcSmC05q79YUl';
update content_bodies set title = '【徳之島】奄美群島認定エコツアーガイド  伊仙町編', description = 'この動画は、奄美広域事務組合の奄美群島エコツーリズム魅力体験事業の一環として、徳之島町在住の認定エコツアーガイド・関さんに密着したものです。エコツアーの様子を紹介しており、日本語字幕付きで無声再生が可能です。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。' where id = 'Cbqt0oiCEmVRVnw1I__v_';
update content_bodies set title = 'Eco tourism in Isen Town Tokunoshima Island (with Japanese subtitles)', description = 'This video features a certified eco-tour guide, Mr. Seki, residing in Tokunoshima Town, as part of the Amami Islands Eco-Tourism Experience Project by the Amami Regional Office. The video showcases eco-tours and is available for silent playback with Japanese subtitles. For inquiries about tours and guides, please contact the tourism associations of each island.' where id = 'EK3ILesz-NBVHSuN455y5';
update content_bodies set title = '奄美郡岛认证生态导游 喜界岛 喜界町', description = '奄美群岛総合管理協会は、奄美群島におけるエコツーリズム体験事業に取り組んでいます。喜界島の喜界町に住む奄美郡島認定のエコツアーガイド、武田さんにインタビューを行い、オンラインツアーを実施しました。ガイドや観光に関するお問い合わせは、各島の観光協会にご連絡ください。詳細は喜界島観光協会の公式サイトをご覧ください。' where id = '2oZhykHA_tXN6Z8AKh71u';
update content_bodies set title = 'Eco tourism in Kikai Town Kikaijima Island Chinese subtitles', description = 'The Amami Islands Comprehensive Management Association is involved in eco-tourism experiences in the Amami Islands. We interviewed Mr. Takeda, a certified eco-tour guide living in Kikai Town on Kikaijima Island, and conducted an online tour. For inquiries about guides and tourism, please contact the tourism associations of each island. More information can be found on the Kikaijima Tourism Association''s official website.' where id = 'CJGJRkqI9EyguzYmG5RlI';
update content_bodies set title = '奄美群島エコツアーガイド 宇検村編', description = 'この動画では、奄美大島に住む認定エコツアーガイドの常田さんが、宇検村でのエコツアー体験を紹介しています。日本語字幕付きで、無声で再生可能です。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。このプロジェクトは、奄美群島エコツーリズム魅力体験事業の一環であり、地域の自然遺産や生物多様性を促進しています。' where id = 'RGJVZAjdH8X6L7eL2h6AU';
update content_bodies set title = 'Eco tourism in Amami Oshima Uken Village', description = 'This video features a certified eco-tour guide, Mr. Tsuneda, who lives in Amami Oshima, showcasing eco-tourism experiences in Uken Village. The video is available with Japanese subtitles and can be played without sound. For inquiries about tours and guides, please contact the local tourism associations of each island. The project is part of the Amami Islands Eco-Tourism Experience Initiative, promoting the natural heritage and biodiversity of the region.' where id = 'raKPz9otbAwoESFL21tPM';
update content_bodies set title = '【奄美大島】奄美群島エコツアーガイド 大和村編', description = 'この動画は、奄美大島の大和村におけるエコツアーガイドを紹介しており、日本語字幕が付いています。無声で再生可能です。奄美広域事務組合の奄美群島エコツーリズム魅力体験事業の一環として制作され、地域通訳案内士の中山さんに密着しています。地域の美しさや生物多様性を紹介しており、ツアーやガイドに関する問い合わせは各島の観光協会にお願いします。一般社団法人あまみ大島観光物産連盟がサポートしています。' where id = 'RB8kAEbZ6madbdjmm1m0w';
update content_bodies set title = 'Eco tourism in Yamato Village Amami Oshima Island', description = 'This video features an eco-tour guide in Yamato Village, Amami Oshima Island, with Japanese subtitles and is playable without sound. It is part of the Amami Islands Eco-Tourism Experience Project by the Amami Regional Office. The video closely follows Nakayama, a local interpreter and guide, showcasing the beauty and biodiversity of the area. For inquiries about tours and guides, please contact the tourism associations of each island. The project is supported by the Amami Tourism & Products Federation.' where id = '6iKeAMtppXV-LJw1KIlou';
update content_bodies set title = '【加計呂麻島】奄美群島認定エコツアーガイド 瀬戸内町編', description = 'この動画は、加計呂麻島の瀬戸内町に住む認定エコツアーガイドの寺本さんに密着した内容です。奄美広域事務組合が実施する奄美群島エコツーリズム魅力体験事業の一環として制作されました。動画は無声で再生可能で、日本語字幕が付いています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。このプロジェクトは、世界自然遺産に認定された奄美群島の自然の美しさや生物多様性を紹介しています。' where id = 'ticl0BHcWGkwet_TgSFyd';
update content_bodies set title = 'Eco tourism in Setouchi Town Amami Oshima Island (with Japanese subtitles)', description = 'This video features a certified eco-tour guide, Teramoto, who lives in Setouchi Town on Kakeromajima Island. It is part of the Amami Islands Eco-Tourism Experience Project by the Amami Regional Office. The video is designed to be played silently with Japanese subtitles. For inquiries about tours and guides, please contact the local tourism associations of each island. The project highlights the natural beauty and biodiversity of the Amami Islands, which are recognized as a World Natural Heritage site.' where id = 'O9ovnxjU_sY3RrPkUPgYF';
update content_bodies set title = '【奄美大島】奄美群島エコツアーガイド 龍郷町編', description = 'この動画は、奄美大島の龍郷町におけるエコツーリズムガイドを紹介しており、日本語字幕が付いています。無声で再生可能です。奄美広域事務組合の奄美群島エコツーリズム魅力体験事業の一環として、地域通訳案内士の内野さんに密着した内容です。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。奄美群島の自然遺産や生物多様性を紹介し、地域文化やエコツーリズムの機会を促進しています。' where id = '8x-Tzd6qomcyEwT4wMj4p';
update content_bodies set title = 'Eco tourism in Tatsugo Town Amami Oshima Island', description = 'This video features an eco-tourism guide in Tatsugo Town, Amami Oshima Island, with Japanese subtitles and is playable without sound. It highlights the experiences of Uchino, a local interpreter and guide, as part of the Amami Islands Eco-Tourism Experience Project by the Amami Regional Office. For inquiries about tours and guides, please contact the tourism associations of each island. The video promotes the natural heritage and biodiversity of the Amami Islands, showcasing local culture and eco-tourism opportunities.' where id = 'ZZdYlReOXVqGUEhehm8be';
update content_bodies set title = '【徳之島】奄美群島エコツアー カムイヤキの森ハイキング', description = 'この動画は、奄美群島エコツーリズム魅力体験事業の一環として、奄美群島に住む認定エコツアーガイドに密着したオンラインエコツアーを紹介しています。徳之島のカムイヤキの森で、ガイドの常さんと共にハイキングを楽しむ様子が映し出されています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。また、植物などは無闇に採取せず、ガイドの指示に従うことが求められています。' where id = 'tY5yDe6WpQU31V1g4QcVM';
update content_bodies set title = 'Eco tourism in Tokunoshima Island (Japanese subtitles available)', description = 'This video features an online eco-tour hosted by the Amami Islands Eco-Tourism Experience Project, focusing on the certified eco-tour guides living on the five islands of the Amami archipelago. The tour follows guide Tsunetaka as he leads a hiking trip through the Kamuiyaki Forest on Tokunoshima Island. For inquiries about the guide and tours, please contact the tourism associations of each island. Participants are advised not to collect plants indiscriminately and to follow the guide''s instructions.' where id = 'j7SRUCFw3IaacPHZnEBbo';
update content_bodies set title = '【与論島】奄美群島エコツアー 与論城跡ハイキング', description = 'この動画は、奄美群島におけるエコツーリズム体験を紹介しており、与論城跡のハイキングツアーが奄美群島認定エコツアーガイドの阿由葉さんによって案内されます。このツアーは、奄美広域事務組合によるオンラインエコツーリズムの一環で、奄美群島の5つの島でのエコツーリズムを促進することを目的としています。視聴者は日本語字幕付きで動画を楽しむことができ、ツアーやガイドに関する問い合わせは各島の観光協会に連絡することができます。ヨロン島観光協会は、地域のエコツアーや自然体験に関する情報を提供しています。' where id = 'SlpjjrkS_uAPYQSdszSiB';
update content_bodies set title = 'Eco tourism in Yoronjima Island', description = 'This video features an eco-tourism experience in the Amami Islands, focusing on a hiking tour of the ruins of Yoron Castle, guided by a certified eco-tour guide, Ayuha. The tour is part of an online initiative by the Amami Regional Office to promote eco-tourism across the five islands of the Amami archipelago. Viewers can enjoy the video with Japanese subtitles and can contact the local tourism association for inquiries about the tour and guides. The Yoron Tourism Association provides further information on eco-tours and nature experiences in the region.' where id = 'P6VMhGpSxKxsTmK9pIzZi';
update content_bodies set title = '【奄美大島】奄美群島エコツアー 不思議な巨木ハイキング', description = 'この動画は、奄美群島のエコツアーを紹介しており、奄美大島にある不思議な巨木に焦点を当てています。認定エコツアーガイドの常田さんが案内役を務め、地域の自然の美しさや生物多様性についての解説を行います。奄美群島は豊かな生態系で知られ、世界自然遺産にも登録されています。ツアーやサービスに関する問い合わせは、各島の観光協会に連絡することが推奨されています。' where id = 'h4RxO_yN6rIXVcdJ8ldvW';
update content_bodies set title = 'Eco tourism in Amami Oshima Island (with Japanese subtitles)', description = 'This video features an online eco-tour in the Amami Islands, focusing on the unique giant trees of Amami Oshima. The tour is guided by a certified eco-tour guide, Mr. Tokuda, who provides insights into the natural beauty and biodiversity of the region. The Amami Islands are recognized for their rich ecosystems and are part of a World Natural Heritage site. For inquiries about the tour and other services, visitors are encouraged to contact the local tourism associations of each island.' where id = 'W7_Stunin2vLDVuXfnejn';
update content_bodies set title = '奄美郡岛认证生态导游 5岛12市町村 汇编', description = '奄美広域事務組合は、奄美群島の5つの島でのエコツーリズム体験を推進しています。認定エコツアーガイドや地元の通訳ガイドと密接に連携しており、導入動画も作成されています。ガイドや観光に関する問い合わせは、各島の観光協会に連絡することが推奨されています。奄美大島、喜界島、徳之島、沖永良部島、与論島でのエコツーリズム体験を紹介する動画や観光協会のリンクも提供されています。' where id = 'mjtirapqttUXBOEerA5mU';
update content_bodies set title = 'The Islands of Amami Ecotour Guides: 5 Islands, 1 City, 9 Towns, 2 Villages', description = 'The Amami Regional Administrative Association promotes ecotourism experiences in the Amami Islands, which consist of five islands. They maintain close contact with certified ecotour guides and local interpreters. A summary video has been created, and for inquiries about guides and tourism, visitors are encouraged to contact the tourism associations of each island. Links to various tourism associations and videos showcasing ecotourism experiences in Amami Oshima, Kikaijima, Tokunoshima, Okinoerabujima, and Yoronjima are provided.' where id = 'SSmopRvkaxzH_jc90g_v0';
update content_bodies set title = '奄美郡岛认证生态导游 奄美大岛 宇檢村', description = 'この動画では、奄美大島の宇検村に住む奄美郡島認定のエコツアーガイド、常田さんへのインタビューが紹介されています。これは奄美群島エコツーリズム体験事業の一環で、奄美群島総合管理協会によって企画されています。オンラインツアーでは、エコツーリズムや地域の自然の美しさについての洞察が提供されます。ツアーやガイドに関する問い合わせは、各島の観光協会に連絡することが推奨されています。また、奄美観光物産連盟もさらなる情報源として言及されています。' where id = 'pnHraM5tXPmSibH3i5tC3';
update content_bodies set title = 'Eco tourism in Amami Oshima Island Uken Village Chinese Subtitles', description = 'This video features an interview with Mr. Tokuda, a certified eco-tour guide residing in Uken Village on Amami Oshima Island. It is part of the Amami Islands Eco Tourism Experience Project, organized by the Amami Islands Comprehensive Management Association. The online tour provides insights into eco-tourism and the natural beauty of the region. For inquiries about tours and guides, visitors are encouraged to contact the local tourism associations on each island. The Amami Tourism & Products Federation is also mentioned as a resource for further information.' where id = 'PTZbKqIiwSh0OttqO7DvR';
update content_bodies set title = '奄美郡岛认证生态导游  与论岛 与论町', description = '奄美群岛総合管理協会は、奄美群島におけるエコツーリズム体験事業に取り組んでいます。与論島与論町に住む奄美郡島認定エコツアーガイドの池田さんにインタビューを行い、オンラインツアーを実施しました。ガイドや観光に関する問い合わせは、各島の観光協会にご連絡ください。与論島観光協会は、地域の自然の美しさや生物多様性を探求したい訪問者のための情報やリソースを提供しています。この地域は世界自然遺産として認識されています。' where id = 'SnV_47goujWeKDmL_MyVK';
update content_bodies set title = 'Eco tourism in Yoron Town Yoronima Island Chinese subtitles', description = 'The Amami Islands Comprehensive Management Association is involved in eco-tourism experiences in the Amami Islands. We interviewed Mr. Ikeda, a certified eco-tour guide living in Yoron Town on Yoron Island, and conducted an online tour. For inquiries about guides and tourism, please contact the tourism association of each island. The Yoron Tourism Association provides information and resources for visitors interested in exploring the natural beauty and biodiversity of the region, which is recognized as a World Natural Heritage site.' where id = 'Pf1E1AAbUfFIdf0u3abWF';
update content_bodies set title = '奄美郡岛地区翻译導游 沖永良部島 知名町', description = 'この文章は、奄美群島のエコツーリズム体験について述べており、特に沖永良部島の知名町に焦点を当てています。沖永良部島に住む地域通訳案内士の有川さんへのインタビューが含まれており、オンラインツアーが行われました。このツアーは、地域の生物多様性や自然遺産の重要性を強調しています。ツアーやガイドに関する問い合わせは、各島の観光協会、特に沖永良部島観光協会に連絡することが推奨されています。エコツーリズムや自然体験の重要性が地域の文化的・自然的資産の促進に寄与することが強調されています。' where id = 'WTWjErl0TfjvWfXZKuJcW';
update content_bodies set title = 'Eco tourism in China Town Okinoerabujima Island', description = 'This text discusses the eco-tourism experiences in the Amami Islands, specifically focusing on Okinoerabu Island. It features an interview with Ms. Arakawa, a regional interpreter guide residing in the town of China on Okinoerabu Island. The online tour highlights the importance of biodiversity and the natural heritage of the area. For inquiries regarding tours and guides, visitors are encouraged to contact the respective island''s tourism association, specifically the Okinoerabu Island Tourism Association. The text emphasizes the significance of eco-tourism and nature experiences in promoting the region''s cultural and natural assets.' where id = 'k9clfcuhRC5i4wnMSMDL9';
update content_bodies set title = '奄美郡岛地区翻译导游 沖永良部岛 和泊町', description = '奄美群島総合管理協会は、奄美群島のエコツーリズム体験事業に取り組んでいます。沖永良部島の和泊町に住む地域通訳案内士の吉成さんにインタビューを行い、オンラインツアーを実施しました。ガイドや観光に関する問い合わせは、各島の観光協会にご連絡ください。沖永良部島観光協会のウェブサイトもご覧ください。' where id = '5T6vhj5nifzH8aXKkJPqe';
update content_bodies set title = 'Eco tourism in Wadomari Town Okinoerabujima Island Chinese subtitles', description = 'The Amami Islands Comprehensive Management Association is involved in ecological tourism experiences. We interviewed Ms. Yoshinari, a regional interpreter guide living in Wadomari Town on Okinoerabu Island, and conducted an online tour. For inquiries about guides and tourism, please contact the tourism associations of each island, including the Okinoerabu Island Tourism Association.' where id = 'PPl_-CX8UHVDyQGempBEP';
update content_bodies set title = '奄美郡岛认证生态导游 德之岛 伊仙町', description = 'この文章は、奄美群島におけるエコツーリズムについて述べており、徳之島伊仙町に住む奄美郡島認定のエコツアーガイド関さんへのインタビューを中心に展開しています。奄美群島総合管理協会はエコツーリズム体験の促進に関与しており、観光に関する問い合わせ先として徳之島観光連盟のウェブサイトが紹介されています。内容は、生物多様性や文化遺産、地域の自然の美しさの重要性を強調し、世界自然遺産としての地位を持つことを示しています。' where id = '4WYZrM43NSY7LjsdjtRbJ';
update content_bodies set title = 'Eco tourism in Isen Town Tokunoshima Island', description = 'This text discusses eco-tourism in the Amami Islands, focusing on an interview with Ms. Seki, a certified eco-tour guide residing in Isen Town, Tokunoshima Island. The Amami Islands Comprehensive Management Association is involved in promoting eco-tourism experiences. The text also provides contact information for tourism inquiries, specifically directing readers to the Tokunoshima Tourism Organization''s website. The content emphasizes the importance of biodiversity, cultural heritage, and the natural beauty of the region, highlighting its status as a World Natural Heritage site.' where id = '-fiW62ChyCP-UdCrckY4S';
update content_bodies set title = '奄美郡岛认证生态导游 德之岛 德之岛町', description = '奄美群岛総合管理協会は、奄美群島におけるエコツーリズム体験の促進に関与しています。この記事では、徳之島町に住む奄美郡島認定のエコツアーガイド元田氏へのインタビューを通じて、オンラインツアーが行われました。ガイドや観光に関する問い合わせは、各島の観光協会に連絡してください。徳之島観光連盟のウェブサイトも利用可能です。奄美群島が世界自然遺産としての重要性を強調し、生物多様性や国立公園、ソテツ並木などのユニークな自然体験を紹介しています。' where id = 'LmLM2xolqZa4TaTbCQ9-H';
update content_bodies set title = 'Eco tourism in Tokunoshima Town Tokunoshima Island Chinese subtitles', description = 'The Amami Islands Comprehensive Management Association is involved in promoting eco-tourism experiences in the Amami Islands. This includes an interview with Mr. Motoda, a certified eco-tour guide residing in Tokunoshima Town, where an online tour was conducted. For inquiries regarding guides and tourism, please contact the respective island''s tourism association. The Tokunoshima Tourism Organization can be reached at their website. The content emphasizes the importance of the Amami Islands as a World Natural Heritage site, highlighting biodiversity, national parks, and unique natural experiences such as cycad trees and eco-tours.' where id = 'F7hkztZXT9KAF2EFqxJMK';
update content_bodies set title = '奄美群島認定エコツアーガイド 奄美大島 奄美市編 英語字幕', description = 'この動画では、奄美大島の奄美市に住む認定エコツアーガイドの沖さんを紹介しています。奄美群島のエコツーリズムの重要性を強調し、視聴者にこの地域の自然の美しさや生物多様性を探求することを促しています。エコツアーやガイドに関する詳細は、奄美観光物産連盟のウェブサイトを参照するように案内されています。また、この地域が世界自然遺産であることの意義や、ホエールウォッチング、ウミガメ観察、イルカとの出会いなどのアクティビティも紹介されています。' where id = 'u37jA3IxNJfpGB0lkxWD0';
update content_bodies set title = 'Eco tourism in Amami City Amami Oshima Island English Sub', description = 'This video features Oki-san, a certified ecotour guide residing in Amami City on Amami Oshima Island. It highlights the importance of ecotourism in the region and encourages viewers to explore the natural beauty and biodiversity of the Amami Islands. For more information on eco-tours and guides, viewers are directed to the Amami Tourism & Products Federation''s website. The video emphasizes the significance of the area as a World Natural Heritage site and showcases activities such as whale watching, sea turtle observation, and dolphin encounters.' where id = 'Bps0tdaBvymt-v66HOL_4';
update content_bodies set title = '奄美大島 大和村 - エコツーリズム', description = 'この文章は、奄美大島の大和村におけるエコツーリズム体験について述べています。奄美郡島地区の翻訳ガイドである中山さんへのインタビューが含まれており、オンラインツアーが行われました。このツアーでは、世界自然遺産に認定された地域の自然の美しさや生物多様性が強調されています。ガイドや観光に関する問い合わせは、各島の観光協会に連絡するよう勧められています。また、奄美観光物産連盟がさらなる情報源として紹介されています。' where id = 'o2J-7KK72hyESFteGiSJN';
update content_bodies set title = 'Eco tourism in Yamato Village Amami Oshima Island Chinese subtitles', description = 'This text discusses the eco-tourism experience in Yamato Village, located on Amami Oshima Island. It features an interview with Ms. Nakayama, a translator and tour guide from the Amami Islands region. The online tour highlights the natural beauty and biodiversity of the area, which is recognized as a World Natural Heritage site. For inquiries about guides and tourism, visitors are encouraged to contact the local tourism associations on each island. The Amami Tourism & Products Federation is mentioned as a resource for further information.' where id = 'gGecptO2wEDJd5gD4ygVY';
update content_bodies set title = '奄美郡岛地区翻译导游 奄美大岛 龙乡町', description = '奄美群島総合管理協会は、奄美大島龍乡町に住む翻訳ガイドの内野さんにインタビューを行い、エコツーリズム体験事業についてオンラインツアーを実施しました。観光やガイドに関する問い合わせは、各島の観光協会にご連絡ください。奄美観光物産連盟が詳細情報を提供しています。' where id = 'ffQHYASlrKzu1DmIxcD0y';
update content_bodies set title = 'Eco tourism in Tatsugo Town, Amami Oshima Island - Chinese subtitles', description = 'The Amami Islands Comprehensive Management Association is involved in ecological tourism experiences. We interviewed Ms. Uchino, a translation guide living in Tatsugo Town on Amami Oshima Island, and conducted an online tour. For inquiries about guides and tourism, please contact the tourism associations of each island. The Amami Tourism & Products Federation provides further information.' where id = '4mqjvXXSULzazGBHGeJ97';
update content_bodies set title = '奄美郡岛认证生态导游 奄美大岛 奄美市', description = '奄美群岛総合管理協会は、奄美大島奄美市におけるエコツーリズム体験事業に関与しています。奄美市に住む奄美郡島認定エコツアーガイドの興先生にインタビューを行い、オンラインツアーを実施しました。ガイドや観光に関するお問い合わせは、各島の観光協会にご連絡ください。奄美観光物産連盟がさらなる情報を提供しています。' where id = 'SSNXJ62ie2OmGvJRUi-CT';
update content_bodies set title = 'Eco tourism in Amami City Amami Oshima Island Chinese Subtitles', description = 'The Amami Islands Comprehensive Management Association is involved in eco-tourism experiences in Amami City, Amami Oshima Island. We interviewed Mr. Ikeda, a certified eco-tour guide residing in Amami City, and conducted an online tour. For inquiries regarding guides and tourism, please contact the tourism associations of each island. The Amami Tourism & Products Federation provides further information.' where id = '8m3Uo9Lm5aY5YE8Mx6V8q';
update content_bodies set title = '徳之島 KAMUIYAKI森林生态之旅 - エコツーリズム', description = '奄美群島総合管理協会は、奄美群島におけるエコツーリズム体験事業を紹介しています。このプロジェクトでは、奄美五島に住む認定エコガイドへのインタビューやオンラインツアーが行われています。ガイドや観光に関する問い合わせは、各島の観光協会に連絡してください。徳之島観光連盟のウェブサイトでは、さらなる情報が提供されています。この取り組みは、世界自然遺産や生物多様性、徳之島でのハイキングや自然体験を強調しています。' where id = '9vkQ5FzGy-nCV8D4UXYGm';
update content_bodies set title = 'Eco tourism in Tokunoshima Island - KAMUIYAKI Forest Ecological Tour', description = 'The Amami Islands Comprehensive Management Association presents an ecological tourism experience in the Amami Islands. The project includes interviews with certified eco-guides living on the Amami Islands and offers online tours. For inquiries about guides and tourism, please contact the tourism associations of each island. The Tokunoshima Tourism Organization (一般社団法人 徳之島観光連盟) provides further information at their website. This initiative highlights the importance of World Natural Heritage, biodiversity, and the natural experiences available in Tokunoshima, including hiking and eco-tours.' where id = 'IXLMvhms_VEL9NFITaFbz';
update content_bodies set title = '沖永良部島の洞窟探検 - 中国語字幕付きエコツーリズム', description = '奄美群島総合管理協会が提供するエコツーリズム体験事業について紹介します。奄美五島に住む認定エコガイドへのインタビューやオンラインツアーを実施しました。ガイドや観光に関する問い合わせは、各島の観光協会にご連絡ください。沖永良部島観光協会では、訪問者向けの情報やリソースを提供しています。この取り組みは、奄美群島の自然遺産や生物多様性、国立公園に焦点を当て、洞窟探検や石灰岩洞窟をエコツーリズムや自然体験の一環として強調しています。' where id = '1RVtp5hAPTGczn2_maX95';
update content_bodies set title = 'Cave Exploration in Okinoerabu Island - Eco tourism in Okinoerabujima Island with Chinese Subtitles', description = 'The Amami Islands Comprehensive Management Association presents an ecological tourism experience project. We interviewed certified eco-guides living in the Amami Islands and conducted an online tour. For inquiries about guides and tourism, please contact the tourism association of each island. The Okinoerabu Island Tourism Association provides information and resources for visitors. This initiative highlights the natural heritage, biodiversity, and national parks of the Amami Islands, focusing on caving and limestone caves as part of eco-tourism and nature experiences.' where id = 'tJA4LHC7Cjp7sMqkrXM5A';
update content_bodies set title = '喜界島 黒糖焼酎 醸造所の旅 - 喜界島のエコツーリズム（中国語字幕付き）', description = '奄美群島総合管理協会は、奄美群島におけるエコツーリズム体験を提供しています。奄美五島に住む認定エコツアーガイドへのインタビューを行い、オンラインツアーを実施しました。ガイドや観光に関する問い合わせは、各島の観光協会にご連絡ください。喜界島観光協会は、喜界島に関する総合情報をウェブサイトを通じて提供しています。この取り組みは、地域の自然遺産や生物多様性を強調し、黒糖焼酎の製造体験を通じてエコツーリズムと自然体験の重要性を訴えています。' where id = 'Yt1YJ2a-eHQ323p3UvrTJ';
update content_bodies set title = 'Kikaijima Island Brown Sugar Shochu Brewery Tour - Eco tourism in Kikaijima Island with Chinese subtitles', description = 'The Amami Islands Comprehensive Management Association presents an ecological tourism experience in the Amami Islands. We interviewed certified eco-guides living on the Amami Islands and conducted an online tour. For inquiries about guides and tourism, please contact the tourism associations of each island. The Kikaijima Tourism Association provides comprehensive information about Kikaijima Island through their website. This initiative highlights the region''s natural heritage, biodiversity, and the unique experience of brown sugar shochu production, emphasizing the importance of eco-tourism and nature experiences.' where id = '7Il1XmgBNA4DD34rDNhJk';
update content_bodies set title = '与論島 与論城堡遺跡徒歩旅行 - Eco tourism in Yoronjima Island Chinese subtitles', description = '奄美群島総合管理協会が奄美群島のエコツーリズム体験を提供しています。奄美五島に住む認定エコガイドへのインタビューを行い、オンラインツアーを実施しました。ガイドや観光に関する問い合わせは、各島の観光協会にご連絡ください。与論島については、与論島観光協会（http://www.yorontou.info/）にお問い合わせください。この取り組みは、世界自然遺産や生物多様性の重要性を強調し、国立公園内でのハイキングやクライミングなどのアクティビティを提供しています。' where id = 'urA53AZ7PXK_DsCTBXT4d';
update content_bodies set title = 'Hiking Tour of Yoron Island and Castle Ruins - Eco Tourism in Yoronjima Island with Chinese Subtitles', description = 'The Amami Islands Comprehensive Management Association presents an ecological tourism experience in the Amami Islands. We interviewed certified eco-guides living in the Amami Islands and conducted an online tour. For inquiries about guides and tourism, please contact the tourism association of each island. For Yoron Island, you can reach out to the Yoron Tourism Association at http://www.yorontou.info/. This initiative highlights the importance of world natural heritage, biodiversity, and offers activities such as hiking and climbing in a national park setting.' where id = 'yoGlA5GmFvSbkchwjV0oC';
update content_bodies set title = '奄美大島 神秘森林生态之旅', description = '奄美群島総合管理協会は、奄美大島でのエコツーリズム体験を提供しています。この取り組みでは、奄美の島々に住む認定エコガイドへのインタビューやオンラインツアーが行われています。ガイドや観光に関する問い合わせは、各島の観光協会に連絡することが推奨されています。奄美大島観光物産連盟は、地域の観光に関する情報やサポートを提供する重要なリソースです。' where id = 'RRCG0KpIYZNXyusekMWsD';
update content_bodies set title = 'Eco tourism in Amami Oshima Island', description = 'The Amami Islands Comprehensive Management Association offers an ecological tourism experience in Amami Oshima. The initiative includes interviews with certified eco-guides living on the islands and provides online tours. For inquiries regarding guides and tourism, visitors are encouraged to contact the tourism associations of each island. The Amami Tourism & Products Federation is a key resource for information and support related to tourism in the region.' where id = 'ZLhGPozMmsXuft9g3yxLp';
update content_bodies set title = '奄美群島エコツアーガイド 奄美大島 宇検村編 英語字幕', description = 'この動画では、奄美大島に住む認定エコツアーガイドの常田さんが紹介されています。奄美群島におけるエコツーリズムの機会や、生物多様性、自然遺産の重要性が強調されています。エコツアーやガイドに関する詳細は、奄美観光物産連盟のウェブサイトを訪れることが推奨されています。また、世界自然遺産や生物多様性、バードウォッチングなど、自然環境やエコツーリズムに関連するハッシュタグも含まれています。' where id = 'VrSC_uFnEWF95v0dbMGf4';
update content_bodies set title = 'Eco tourism in Uken Village Amami Oshima Island  English Subtitles -奄美群島エコツアーガイド 奄美大島 宇検村編 英語字幕', description = 'This video features Tsuneda-san, a certified ecotour guide residing on Amami Oshima Island. It highlights the ecotourism opportunities available in the Amami Islands, emphasizing the importance of biodiversity and natural heritage. For further details on eco-tours and guides, viewers are encouraged to visit the Amami Tourism & Products Federation website. The video also includes various hashtags related to the natural environment and ecotourism, such as World Natural Heritage, biodiversity, and bird watching.' where id = 'ZVCvcCQ6y3hFXUnseY67q';
update content_bodies set title = '与論町のエコツーリズム - 奄美群島認定エコツアーガイド 与論島 与論町編', description = 'この動画では、与論島の与論町に住む奄美群島認定エコツアーガイドの池田さんを紹介しています。奄美群島の自然の美しさや生物多様性を強調し、エコツーリズムの重要性を伝えています。エコツアーやガイドに興味がある方は、与論島観光協会のウェブサイトでさらに情報を得ることができます。動画では、自然体験や海岸清掃、マイクロプラスチックの環境への影響など、エコツーリズムに関連するさまざまな活動が紹介されています。' where id = '_q1R_3Qts4MYyMuAput2q';
update content_bodies set title = 'Eco tourism in Yoron Town Yoronima Island English Subtitle - 奄美群島認定エコツアーガイド 与論島 与論町編', description = 'This video features Ikeda-san, a certified ecotour guide residing in Yoron Town on Yoron Island. It highlights the importance of ecotourism in the Amami Islands, showcasing the natural beauty and biodiversity of the region. For those interested in eco-tours and guides, further information can be found through the Yoron Tourism Association''s website. The video emphasizes various activities related to ecotourism, including nature experiences, coast cleaning, and the impact of microplastics on the environment.' where id = 'R4aFBifyufKSs-czMU9M0';
update content_bodies set title = 'エコツーリズム in 沖永良部島のチャイナタウン - 奄美群島エコツアーガイド 沖永良部島 知名町編', description = 'この動画では、沖永良部島のチャイナタウンに住む地域通訳案内士の有川さんが登場し、奄美群島のエコツーリズムの魅力を紹介しています。奄美群島は世界自然遺産に登録されており、その独自の生物多様性や自然遺産について学ぶことができます。エコツアーやガイドに関する詳細は、沖永良部島観光協会のウェブサイトをチェックすることが推奨されています。また、自然体験や芭蕉布などの伝統文化の重要性も強調されています。' where id = 'HMvKLkWXIuYRqn8tY7aA5';
update content_bodies set title = 'Eco tourism in China Town Okinoerabujima Island English Subtitle - 奄美群島エコツアーガイド 沖永良部島 知名町編', description = 'This video features Arikawa-san, a licensed guide interpreter residing in China Town, Okinoerabujima Island, and highlights the ecotourism opportunities in the Amami Islands. Viewers can learn about the unique biodiversity and natural heritage of the region, which is recognized as a World Natural Heritage site. For more details on eco-tours and guides, visitors are encouraged to check the tourism association for Okinoerabujima Island. The video emphasizes the importance of nature experiences and cultural heritage, including traditional crafts like Bashofu.' where id = 'oDQaM_Bvd2syjvIPUP5Tw';
update content_bodies set title = 'エコツーリズム in 和泊町 沖永良部島', description = 'この動画では、沖永良部島の和泊町に住む地域通訳案内士の吉成さんが紹介されています。奄美群島のエコツーリズムの機会を強調し、生物多様性や自然遺産の重要性について触れています。エコツアーやガイドに関する詳細は、沖永良部島観光協会のウェブサイトを訪れることが推奨されています。この動画は、地域の自然体験や文化遺産を促進し、島の環境のユニークな側面を紹介しています。' where id = 'DysHMcf4FjwJALHzOOAJQ';
update content_bodies set title = 'Eco tourism in Wadomari Town Okinoerabujima English Subtitle - 奄美群島エコツアーガイド 沖永良部島 和泊町編', description = 'This video features Yoshinari-san, a licensed guide interpreter residing in Wadomari Town on Okinoerabujima Island. It highlights the ecotourism opportunities available in the Amami Islands, emphasizing the importance of biodiversity and natural heritage. For further details on eco-tours and guides, viewers are encouraged to visit the tourism association''s website for Okinoerabu Island. The video promotes the region''s natural experiences and cultural heritage, showcasing the unique aspects of the island''s environment.' where id = 't7qHKMwREDMckHPi_QfqP';
update content_bodies set title = '奄美群島認定エコツアーガイド 徳之島 伊仙町編', description = 'この動画では、徳之島の伊仙町に住む認定エコツアーガイドの関さんを紹介しています。奄美群島におけるエコツーリズムの機会や、生物多様性、文化遺産の重要性が強調されています。エコツアーやガイドに関する詳細は、徳之島観光連盟のウェブサイトを訪れることが推奨されています。' where id = 'xuSHr6VN7NQG7lbGAS7FK';
update content_bodies set title = 'Eco tourism in Isen Town Tokunoshima Island English subtitles', description = 'This video features Seki-san, a certified ecotour guide residing in Isen Town on Tokunoshima Island. It highlights the ecotourism opportunities available in the Amami Islands, emphasizing the importance of biodiversity and cultural heritage. For further details on eco-tours and guides, viewers are encouraged to visit the Tokunoshima Tourism Organization''s website.' where id = 'LauaSOIKaK1q1QFrk8HPW';
update content_bodies set title = '徳之島町のエコツーリズム 徳之島 英語字幕', description = 'この動画では、徳之島町に住む奄美群島認定エコツアーガイドの本田さんを紹介しています。奄美群島のエコツーリズムの機会を強調し、生物多様性や自然遺産の重要性について触れています。エコツアーやガイドに関する詳細は、徳之島観光連盟のウェブサイトを訪れることが推奨されています。動画では、ソテツ並木や地元の集落など、島の自然の美しさが紹介されており、地域の生態的な重要性についての理解を深めることを目的としています。' where id = 'hgmrPaKtyL7T_eBT9E5T-';
update content_bodies set title = 'Eco tourism in Tokunoshima Town Tokunoshima Island English subtitles', description = 'This video features Motoda-san, a certified ecotour guide residing in Tokunoshima Town on Tokunoshima Island. It highlights the ecotourism opportunities available in the Amami Islands, emphasizing the importance of biodiversity and natural heritage. For further details on eco-tours and guides, viewers are encouraged to visit the Tokunoshima Tourism Organization''s website. The video showcases various aspects of the island''s natural beauty, including cycad trees and local villages, promoting a deeper understanding of the region''s ecological significance.' where id = 'yVb8fvaB_gygBBNHvXa9f';
update content_bodies set title = '奄美群島認定エコツアーガイド 喜界島 喜界町編 英語字幕', description = 'この動画では、喜界島の喜界町に住む奄美群島認定エコツアーガイドの武田さんを紹介しています。地域のエコツーリズムの重要性や、自然の美しさ、生物多様性を強調しています。エコツアーやガイドに興味がある方は、喜界島観光協会のウェブサイトでさらに情報を得ることができます。環境を保護しながら自然を楽しむことの重要性を訴え、農業や地域文化に関連するさまざまな活動を促進しています。' where id = 'dW_EbRvj3HssapK0-v2zi';
update content_bodies set title = 'Eco tourism in Kikai Town Kikaijima Island English subtitles', description = 'This video features Takeda-san, a certified ecotour guide residing in Kikai Town on Kikaijima Island, part of the Amami Islands. It highlights the importance of ecotourism in the region, showcasing the natural beauty and biodiversity of the area. For those interested in eco-tours and guides, further information can be found through the Kikaijima Tourism Association''s website. The video emphasizes the significance of preserving the environment while enjoying nature, and it promotes various activities related to agriculture and local culture.' where id = 'H8gEoNAWIlnH8UEX1xprj';
update content_bodies set title = '奄美群島エコツアーガイド 奄美大島 大和村編 英語字幕', description = 'この動画では、奄美大島の大和村に住む地域通訳案内士の中山さんが紹介されています。奄美群島のエコツーリズムの機会や、生物多様性の重要性、世界自然遺産としての地域の地位が強調されています。エコツアーやガイドに関する詳細は、奄美観光物産連盟のウェブサイトを訪れることが推奨されています。' where id = 'Pv1fOzXmUP8407FgxBh70';
update content_bodies set title = 'Eco tourism in Yamato Village Amami Oshima Island English subtitles', description = 'This video features Nakayama-san, a licensed guide interpreter residing in Yamato Village on Amami Oshima Island. It highlights the ecotourism opportunities available in the Amami Islands, emphasizing the importance of biodiversity and the region''s status as a World Natural Heritage site. For further details on eco-tours and guides, viewers are encouraged to visit the Amami Tourism & Products Federation''s website.' where id = '3W3y5eYmFPw5DSW3SnTSM';
update content_bodies set title = '奄美群島認定エコツアーガイド 加計呂麻島 瀬戸内町編 英語字幕', description = 'この動画では、奄美群島の加計呂麻島に住む認定エコツアーガイドの寺本さんを紹介しています。彼は瀬戸内町でエコツーリズムの重要性を伝え、地域の自然の美しさや生物多様性を紹介しています。エコツアーやガイドに関する詳細は、奄美大島観光物産連盟のウェブサイトを訪れることが推奨されています。この動画は、奄美群島が世界自然遺産であることの重要性を強調し、地域の生態系や歴史的価値への理解を促進しています。' where id = 'LwOijt7l_v68VluBzddGf';
update content_bodies set title = 'Eco tourism in Setouchi Town Amami Oshima Island English subtitles', description = 'This video features Teramoto-san, a certified ecotour guide residing in Setouchi Town on Kakeromajima Island, part of the Amami Islands. It highlights the importance of ecotourism in the region, showcasing the natural beauty and biodiversity of the area. For further details on eco-tours and guides, viewers are encouraged to visit the Amami Tourism & Products Federation website. The video emphasizes the significance of the Amami Islands as a World Natural Heritage site and promotes awareness of its ecological and historical value.' where id = 'iVaWhG8EX0eKw5WYHlb97';
update content_bodies set title = '奄美群島エコツアーガイド 奄美大島 龍郷町編 英語字幕', description = 'この動画では、奄美大島の龍郷町に住む地域通訳案内士の内野さんが紹介されています。奄美群島のエコツーリズムの機会や、生物多様性の重要性、世界自然遺産としての地域の地位が強調されています。エコツアーやガイドに関する詳細は、奄美観光物産連盟のウェブサイトを訪れることが推奨されています。また、奄美群島の自然遺産や文化に関連するさまざまなハッシュタグも含まれています。' where id = 'YNpOJghk6KoTsGnV9KLNz';
update content_bodies set title = 'Eco tourism in Tatsugo Town  Amami Oshima Island English Subtitles', description = 'This video features Uchino-san, a licensed guide interpreter residing in Tatsugo Town on Amami Oshima Island. It highlights the ecotourism opportunities available in the Amami Islands, emphasizing the importance of biodiversity and the region''s status as a World Natural Heritage site. For further details on eco-tours and guides, viewers are encouraged to visit the Amami Tourism & Products Federation website. The video also includes various hashtags related to the natural heritage and cultural aspects of the Amami Islands.' where id = '8GUZfrG0Brvtq_7A28ayI';
update content_bodies set title = '徳之島 カムィヤキの森 ハイキング 英語字幕', description = 'この動画は、奄美群島の一部である徳之島のエコツアーを紹介しています。徳之島に住む認定エコツアーガイドのツネさんが、カムィヤキの森を案内します。エコツアーやガイドに関する詳細は、各島の観光協会を確認することをお勧めします。徳之島に関しては、徳之島観光連盟が情報を提供しています。' where id = 'ah2qFFvcV0dsx8kKI-0iX';
update content_bodies set title = 'Eco tourism in Tokunoshima Island English Subtitles', description = 'This video showcases an eco-tour on Tokunoshima Island, part of the Amami Islands. Led by Tsune-san, a certified ecotour guide residing on the island, the tour explores the Kamuiyaki Forest. For further details on eco-tours and guides, visitors are encouraged to check the tourism association for each island. Specifically, for Tokunoshima Island, the Tokunoshima Tourism Organization provides additional information.' where id = 'kud9t2drfdZbP1l_A2roU';
update content_bodies set title = '沖永良部島 ケイビング 英語字幕', description = 'この動画は奄美群島の一部である沖永良部島のエコツアーを紹介しています。沖永良部島に住む認定エコツアーガイドの小林さんが案内し、独特な石灰岩の洞窟を探検します。エコツアーやガイドに関する詳細は、各島の観光協会を確認することが推奨されています。この動画は、地域の自然の美しさと生物多様性を強調し、世界自然遺産としての地位を強調しています。' where id = 'RpZUG8EiREgm4lqo7qtdJ';
update content_bodies set title = 'Eco tourism in Okinoerabujima Island English subtitles', description = 'This video showcases an eco-tour on Okinoerabujima Island, part of the Amami Islands. Led by Kobayashi-san, a certified ecotour guide residing on the island, the tour explores the unique limestone caves. For further details on eco-tours and guides, visitors are encouraged to check the tourism association for each island. The video highlights the natural beauty and biodiversity of the region, emphasizing its status as a World Natural Heritage site.' where id = 'IQhYy_Y-jfpvYreCGZb4a';
update content_bodies set title = '喜界島のエコツーリズム 英語字幕', description = 'この動画は奄美群島の一部である喜界島のエコツアーを紹介しています。喜界島に住む認定エコツアーガイドのトノチさんが案内役となり、島内の黒糖焼酎の酒造を訪れます。動画では、地域のエコツーリズムや生物多様性の重要性が強調されており、奄美群島の自然の美しさや文化遺産を探求することを視聴者に促しています。エコツアーやガイドに関する詳細は、各島の観光協会を参照するように案内されており、特に喜界島総合情報サイトが紹介されています。' where id = 'U2c4OKtfC6PD2i6ESYvdw';
update content_bodies set title = 'Eco tourism in Kikaijima Island English subtitles', description = 'This video showcases an eco-tour on Kikaijima Island, part of the Amami Islands. Guided by Tonochi-san, a certified ecotour guide residing on the island, viewers are taken on a tour of a Brown Sugar Shochu Distillery. The video emphasizes the importance of ecotourism and biodiversity in the region, encouraging viewers to explore the natural beauty and cultural heritage of the Amami Islands. For further details on eco-tours and guides, visitors are directed to the tourism association of each island, specifically highlighting the Kikaijima Island Tourist Information Office.' where id = 'Tkt_DVT4FVekTcxYY-uPD';
update content_bodies set title = '与論島のエコツーリズム 英語字幕', description = 'この動画では、奄美群島の一部である与論島のエコツアーを紹介しています。与論島に住む奄美群島認定エコツアーガイドのあゆばさんが案内し、与論城跡を訪れます。エコツアーやガイドに関する詳細は、各島の観光協会を確認することをお勧めします。' where id = 'lZRLkSko_nbRg4_wyIIOR';
update content_bodies set title = 'Eco tourism in Yoronjima Island English subtitles', description = 'This video showcases an eco-tour of Yoron Island, part of the Amami Islands. Led by Ayuba-san, a certified ecotour guide residing on Yoron Island, the tour includes a visit to the Yoron Castle Ruins. For further details on eco-tours and guides, viewers are encouraged to consult the tourism association for each island.' where id = 'FSOtwxUwf9oYxbwR9jBUS';
update content_bodies set title = '奄美大島 不思議な巨木 ハイキング英語字幕', description = 'この動画は、奄美群島の一部である奄美大島のエコツアーを紹介しています。奄美大島に住む認定エコツアーガイドの常田さんが案内し、不思議な巨木を見に行くハイキングツアーが行われます。エコツアーやガイドに関する詳細は、奄美大島の観光協会のウェブサイトを訪れることをお勧めします。' where id = 'TnU8foMqq2yZgLaxsNfs8';
update content_bodies set title = 'Eco tourism in Amami Oshima Island English subtitles', description = 'This video showcases an eco-tour on Amami Oshima Island, part of the Amami Islands. Led by Tsuneda-san, a certified ecotour guide residing on the island, the tour focuses on hiking to see mystical giant trees. For further details on eco-tours and guides, viewers are encouraged to visit the tourism association for Amami Oshima Island.' where id = 'tavShNBoe9Ag733LmpVDO';
update content_bodies set title = '奄美群島エコツアーガイド 宇検村編', description = '奄美広域事務組合が実施する奄美群島エコツーリズム魅力体験事業の一環として、奄美大島に住む認定エコツアーガイドの常田さんに密着したエコツアー動画が作成されました。この動画では、奄美大島の自然の美しさや生物多様性が紹介されています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。' where id = 'pfBZsjIJpnUdbHZRJ3Vl7';
update content_bodies set title = 'Eco tourism in Amami Oshima Uken Village', description = 'This video showcases an eco-tour led by certified guide Tsuneda, who lives in Amami Oshima. The project is part of the Amami Islands Eco-Tourism Experience Initiative by the Amami Regional Office. For inquiries about tours and guides, please contact the local tourism associations of each island. The initiative highlights the natural beauty and biodiversity of the Amami Islands, which are recognized as a World Natural Heritage site.' where id = 'oIN24BVC6fY7ajDH63hl1';
update content_bodies set title = '【奄美大島】奄美群島エコツアーガイド 龍郷町編', description = '奄美大島の龍郷町に焦点を当てたエコツーリズムのプロジェクトで、地域通訳案内士の内野さんに密着したエコツアー動画が作成されました。この動画は、地域の自然の美しさや生物多様性を紹介しています。ツアーやガイドに関する問い合わせは、各島の観光協会にお願いします。この取り組みは、世界自然遺産である奄美群島の持続可能な観光を促進するためのエコツーリズム魅力体験事業の一環です。' where id = 'Rep8jKsSikSfpJHBt6nTu';
update content_bodies set title = 'Eco tourism in Tatsugo Town Amami Oshima Island', description = 'This project focuses on eco-tourism in Tatsugo Town, Amami Oshima Island, featuring a local interpreter guide, Mr. Uchino. A video showcasing eco-tours has been created to highlight the region''s natural beauty and biodiversity. For inquiries about tours and guides, please contact the tourism associations of each island. The initiative is part of the Amami Islands Eco-Tourism Experience Project, promoting sustainable tourism in this World Natural Heritage site.' where id = 'g5AaxBZQGPyC50iaDnK6b';
update content_bodies set title = '【喜界島】奄美群島エコツアー 黒糖焼酎の酒造ツアー', description = '奄美広域事務組合が、奄美群島の認定エコツアーガイドに密着したオンラインエコツアーを開催しました。このツアーでは、黒糖焼酎の酒造見学と喜界島の自然を、エコツアーガイドの外内さんが案内してくれます。ガイドやツアーに関する問い合わせは、各島の観光協会にお願いします。詳細は喜界島総合情報サイトをご覧ください。' where id = '4LAiT9rhK34aV4fVaGjK2';
update content_bodies set title = 'Eco tourism in Kikaijima Island', description = 'The Amami Regional Office has launched an online eco-tourism experience featuring certified eco-tour guides from the Amami Islands. The tour includes a visit to a brown sugar shochu distillery and a guided exploration of Kikaijima''s natural environment by the guide, Mr. Soto. For inquiries about the guide and tours, please contact the tourism associations of each island. More information can be found on the Kikaijima comprehensive information site.' where id = 'vrfqGM_a8bHNPMeYmVPRO';
update content_bodies set title = '中津川【富士見台高原】', description = '富士見台高原は、中央アルプスの南端に位置し、標高1,739mの美しい山です。車で中腹までアクセスできるため、手軽にハイキングが楽しめるスポットとして人気があります。晴れた日には、緑色の笹と青空のコントラストが美しく、山頂からは恵那山や北アルプス、南アルプス、中央アルプスを一望できる360度のパノラマが広がります。7月には希少なササユリが見られ、10月中旬から11月上旬には紅葉が楽しめます。登山シーズンは4月末から11月中旬までです。富士見台高原や中津川の観光については、中津川観光協会にお問い合わせください。' where id = '5pFXkJF0H6d2QLFxNEwkL';
update content_bodies set title = 'Fujimidaikogen, Nakatsugawa', description = 'Fujimidaikogen is a beautiful mountain covered in grass, located at an elevation of 1,739 meters in the Ena mountain range at the southern end of the Central Alps. It is a popular hiking spot due to its accessibility by car up to the mid-slope. On clear days, visitors can enjoy the contrast between the lush green grass and the bright blue sky. At the summit, a breathtaking 360-degree panorama awaits, offering views of Ena Mountain, the Northern Alps, the Southern Alps, and the Central Alps. In July, the rare native plant, Sasayuri, can be seen, and from mid-October to early November, the mountains are adorned with vibrant red foliage. The hiking season runs from late April to mid-November. For more information about tourism in Fujimidaikogen and Nakatsugawa, please contact the Nakatsugawa Tourism Association.' where id = 'NCntYw2_RJpDNgg9u9_pE';
update content_bodies set title = '中津川の桜【本町公園】', description = '岐阜県中津川市の桜の名所を紹介するシリーズです。本町公園は市街地中心部に位置し、公園の両側には桜並木が広がっています。毎年多くの市民が花見に訪れ、ミニ中山道と呼ばれる遊歩道を彩る桜並木はまるで桜のトンネルのようです。公園内には野外ステージや複合遊具が設置されており、蒸気機関車「D51」も展示されています。2021年3月26日にドローンで撮影されたこの美しい景色を4Kでお楽しみください。中津川観光協会のホームページもご覧ください。' where id = 'sO5yICqon8gjUIMrhK5J-';
update content_bodies set title = 'Cherry Blossoms in Nakatsugawa: Honmachi Park', description = 'This is a series showcasing the best cherry blossom spots in Nakatsugawa, Gifu Prefecture. Honmachi Park, located in the city center, features cherry blossom tree-lined streets on both sides, attracting many visitors for hanami (flower viewing) each year. The cherry trees along the ''Mini Nakasendo'' walking path create a stunning cherry blossom tunnel. The park also includes an outdoor stage, playground equipment, and a display of the steam locomotive ''D51''. A drone captured this beautiful scenery on March 26, 2021, allowing you to enjoy Nakatsugawa''s cherry blossoms in 4K. For more information, visit the Nakatsugawa Tourism Association''s website.' where id = 'F9aOoWw70BqXz8m2YaSp9';
update content_bodies set title = '中津川の桜【子野の地蔵堂石仏群】', description = '岐阜県中津川市の桜の名所を紹介するシリーズです。こちらは、中山道沿いに位置する「子野の地蔵堂石仏群」の桜です。庚申塚や地蔵、観音像などが数多く祀られており、しだれ桜と相まって厳かな雰囲気が漂います。2021年3月26日、ドローンで撮影しました。中津川の桜を4Kの映像でお楽しみください。中津川観光協会のホームページはこちらから。' where id = 'eGMAZdhEfgA0Hl26qy46p';
update content_bodies set title = 'Cherry Blossoms in Nakatsugawa: Kono Jizodo Stone Buddha Statues', description = 'This is a series showcasing the best cherry blossom spots in Nakatsugawa City, Gifu Prefecture. The cherry blossoms at Kono Jizodo Stone Buddha Statues, located along the historic Nakasendo road, create a solemn atmosphere, complemented by the presence of various statues such as Koshinzuka, Jizo, and Kannon. The footage was captured using a drone on March 26, 2021, allowing viewers to enjoy the cherry blossoms in stunning 4K resolution. For more information, visit the Nakatsugawa Tourism Association''s website.' where id = 'P4KwwrI0YrEop4mVdrVud';
update content_bodies set title = '中津川の桜【四ツ目川】ショートバージョン', description = '岐阜県中津川市の桜の名所を紹介するシリーズです。こちらは、中津川市街地の中心部を流れる「四ツ目川」の桜です。澄んだ水が流れる川の様子はまさに春らしい風景です。2021年3月26日にドローンで撮影した映像で、中津川の桜を4Kでお楽しみください。詳細は中津川観光協会のホームページをご覧ください。' where id = 'PwML7a7NEnq4zMP0FDAHf';
update content_bodies set title = 'Cherry Blossoms of Nakatsugawa: Yotsumegawa (Short Version)', description = 'This series introduces the best cherry blossom spots in Nakatsugawa, Gifu Prefecture. Featured here is the Yotsumegawa river, which flows through the city center. The clear waters of the river create a picturesque spring landscape. The footage was captured using a drone on March 26, 2021, allowing viewers to enjoy the cherry blossoms in stunning 4K quality. For more information, visit the Nakatsugawa Tourism Association''s website.' where id = 'CFbh6mZosyHuMAJ3RdkKq';
update content_bodies set title = '中津川の桜【苗木さくら公園・四ツ目川・子野・落合川・本町公園】', description = '岐阜県中津川市の桜の名所を紹介するシリーズです。苗木さくら公園、四ツ目川、子野の石仏群、落合川沿い、本町公園の5カ所の桜の見どころを紹介しています。ドローンで撮影した4K映像で、中津川の美しい桜をお楽しみください。' where id = '0zeIdBqlkOrlWvpdfx8Z0';
update content_bodies set title = 'Cherry Blossoms in Nakatsugawa: Naegi Sakura Park, Yotsumegawa, Kono, Ochiai River, Honmachi Park', description = 'This series introduces the best cherry blossom spots in Nakatsugawa City, Gifu Prefecture. It features five notable locations: Naegi Cherry Blossom Park, Yotsumegawa, the Stone Buddha statues in Kono, Ochiai River, and Honmachi Park. The video showcases these beautiful cherry blossoms captured with drone footage in stunning 4K resolution. Enjoy the breathtaking views of Nakatsugawa''s cherry blossoms!' where id = 'Y-S8ZKG3SC8hQF5z0MY4s';
update content_bodies set title = '下呂市の食文化 朴葉寿司', description = '下呂市の伝統料理である「朴葉寿司」を紹介するPR動画です。この動画は、文化庁の令和4年度「食文化ストーリー」創出・発信モデル事業の一環として制作されています。' where id = 'TjHDyNXHQBtxvfk9v6UEX';
update content_bodies set title = 'Gero City''s Food Culture: Hoba Sushi', description = 'This is a promotional video for Hoba Sushi, a traditional dish from Gero City. It is part of the Agency for Cultural Affairs'' 2022 ''Food Culture Story'' creation and dissemination model project.' where id = 'DS6YqFOB1WXAuiobFWXAb';
update content_bodies set title = 'けふの下呂温泉', description = '下呂温泉はすっかり秋の雰囲気に包まれています。紅葉を楽しむなら「温泉寺」が特におすすめです。昼間でも美しい紅葉が楽しめますが、11月11日（金）から20日（日）までの期間に行われる紅葉ライトアップも見逃せません。16時半から21時まで、ライトアップされた紅葉の中を散策することができます。入場は無料で、自由に出入りできるため、お参りしながら夜の散歩を楽しむのに最適です。寒さが増してきているので、防寒具の準備をお忘れなく。' where id = 'TB831pYURFIZ0HDwNsNMY';
update content_bodies set title = 'Today’s Gero Onsen', description = 'Gero Onsen has fully embraced autumn, and if you want to enjoy the fall foliage, ''Onsen-ji'' is highly recommended. You can see stunning autumn leaves during the day, but don’t miss the special light-up event from November 11 (Friday) to November 20 (Sunday). From 4:30 PM to 9:00 PM, the foliage will be illuminated, allowing visitors to stroll through the beautiful scenery. Admission is free, and you can enter and exit freely, making it perfect for a nighttime walk while paying your respects. As the weather gets colder, don’t forget to prepare warm clothing.' where id = 'XW1ip4FfMyVYRMZUP05M6';
update content_bodies set title = '中津川＆下呂PR動画「Wonderful autumn days」 短編 【4K】', description = 'この動画は、秋の下呂市と中津川市の観光スポットを紹介するPR映像です。中津川市では、苗木城跡や雲海、椛の湖自然公園、夕森渓谷、いが栗の里中津川マロンパーク、ふれあい牧場、中山道の馬籠宿などが紹介されています。下呂市では、岩屋ダム、金山巨石群、下呂温泉合掌村、馬瀬レンタサイクル、地蔵寺、温泉寺、水明館、下呂温泉花火物語などが登場します。秋の美しい風景と観光名所を楽しむことができる内容となっています。' where id = 'jetTJctndR-mjv4CK_0Dn';
update content_bodies set title = 'Nakatsugawa & Gero PR Video ''Wonderful Autumn Days'' Short Film [4K]', description = 'This video is a promotional film showcasing the autumn scenery of Gero City and Nakatsugawa City. It highlights various tourist attractions in the area, including Nakatsugawa''s Naegi Castle Ruins, Kobano Lake Nature Park, and Yuyamori Valley Park. Other featured spots include Nakatsugawa Maron Park, Nakatsugawa City Fureai Farm, and the historic Magome-juku on the Nakasendo Trail. In Gero City, the video presents Iwaya Dam, Kanayama Giant Stones, Gero Onsen Gassho Village, and various temples and hot springs, including Onsenji and Suimeikan. The video aims to promote the beauty and attractions of these regions during the autumn season.' where id = 'y16qbmCXMYmw3o9r2o4rx';
update content_bodies set title = '下呂温泉', description = '下呂温泉は飛騨川のそばに位置し、哲学者林羅山によって日本三名泉の一つと称されています。彼は徳川家康を含む四人の将軍に仕え、室町時代の禅僧でもありました。下呂の温泉街は美しい山村の風景が広がり、観光地として魅力的です。訪れる人々は公園や神社、伝統的な宿泊施設など様々な観光名所を楽しみながら、地域の自然美や文化遺産を堪能できます。' where id = '-h1DZ0RQwxy3lGZjAoJ-0';
update content_bodies set title = 'Gero Hot Springs', description = 'Gero Hot Springs, located alongside the Hida River, is renowned as one of Japan''s top three hot springs, a title attributed to philosopher Razan Hayashi, who served four shoguns, including Ieyasu Tokugawa, during the Muromachi era. The area is characterized by its picturesque hot spring mountain village, making it a popular tourist destination. Visitors can explore various attractions, including parks, shrines, and traditional inns, while enjoying the natural beauty and cultural heritage of the region.' where id = 'vSTTNdB6Z8m9PxBD5FSwr';
update content_bodies set title = 'けふの下呂温泉', description = '本日は、太陽がずっと雲に隠れていました。雨は降らなかったけれど、涼しくてなんだかしんみりした気持ちになります。市街の道や飛騨川のそばでも、静かでゆったりした時が流れているようでした。河原にある大きな石たちは、ずっと昔から下呂温泉を見てきたのでしょうか？こんな日は、温泉に入って気分転換に限ります！日々是温泉がモットーの、下呂温泉をよろしくお願いいたします！' where id = 'ynIiNshh9kfd-qV8YTmzp';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Today, the sun was hidden behind clouds all day. Although it didn''t rain, the cool weather brought a somewhat melancholic feeling. It felt as if time was flowing quietly and leisurely along the streets of the city and by the Hida River. The large stones by the riverbank have likely witnessed the beauty of Gero Onsen for many years. On such days, there''s nothing better than soaking in the hot springs to refresh oneself! Our motto is ''Every day is a hot spring day,'' so please enjoy Gero Onsen!' where id = 'c1M7atBG24komMCMlrmpx';
update content_bodies set title = '下呂温泉で遊ぶ観光スポット紹介♪ 秋・冬【ショートバージョン】', description = 'このプロモーション動画では、秋から冬にかけて下呂市で楽しめる多彩な体験を紹介しています。温泉だけでなく、紅葉や花火、雪遊びなど、下呂の魅力を伝えています。動画では、JR東海のワイドビューひだや岩屋ダム、下呂温泉花火ミュージカル、そば打ちや陶器の絵付け体験など、さまざまなスポットやアクティビティが紹介されています。下呂の自然の美しさと魅力を強調し、訪れる人々に地域のユニークな体験を楽しむよう呼びかけています。' where id = 'DU-WuDd4_rguItmo0WSiq';
update content_bodies set title = 'Introducing Tourist Spots to Enjoy in Gero Onsen: Autumn & Winter [Short Version]', description = 'This promotional video showcases a variety of experiences available in Gero City during the autumn and winter seasons, highlighting attractions beyond just the hot springs. Viewers can enjoy the beauty of autumn leaves, fireworks, and winter activities. The video features various locations and activities, including the JR Tokai Wide View Hida train, Iwaya Dam, Gero Onsen Fireworks Musical, and hands-on experiences like soba making and pottery painting. The video emphasizes Gero''s charm and natural beauty, inviting visitors to explore the region''s unique offerings.' where id = 'XLgfBNKHFq9pVbI6G-Cc8';
update content_bodies set title = '下呂温泉で遊ぶ観光スポット紹介♪ Spring&Summer【short ver.】', description = '下呂市は豊かな自然を楽しむ体験が盛りだくさんで、温泉だけでなく多様な観光スポットがあります。このプロモーション動画では、春・夏の下呂市の魅力を紹介しています。萩原町の桜めぐりや御嶽山の訪問、健康農園、電動アシスト付きレンタサイクル、水辺の釣りセンターなど、さまざまなアクティビティが紹介されています。また、下呂温泉合掌村や飛騨小坂の滝めぐりも取り上げられています。春・夏の下呂市での多彩で魅力的な体験を促進することを目的としています。' where id = 'GHfa8tzARGh5qARoObs5q';
update content_bodies set title = 'Introducing Tourist Spots to Enjoy in Gero Onsen: Spring & Summer (Short Version)', description = 'Gero City offers a wealth of experiences to enjoy its rich natural surroundings! This promotional video highlights the attractions of Gero City beyond just its hot springs, focusing on spring and summer activities. The video features various activities such as cherry blossom tours in Hagiwara, visits to Mt. Ontake, health farms, electric bicycle rentals, and fishing centers. It also showcases the Gero Onsen Gassho-Mura, a traditional village, and waterfall tours in Hida-Osaka. The video aims to promote the diverse and charming experiences available in Gero City during the spring and summer seasons.' where id = 'iTlrJZWhM7d7DD7OrX2XC';
update content_bodies set title = '下呂温泉で遊ぶスポット紹介♪ Spring&Summer【long ver.】026', description = '下呂市は豊かな自然を楽しむ体験が盛りだくさんで、温泉だけではない魅力を紹介する春・夏の観光プロモーション動画です。動画では、萩原町の桜めぐりや小坂の滝めぐり、御嶽山の訪問、健康農園の体験などが紹介されています。また、電動アシスト付きレンタサイクルや足湯、下呂温泉のスイーツも楽しめます。水辺の館での釣りやカヤックツアー、合掌村の探索など、多彩なアクティビティが盛り込まれており、下呂市の自然美と文化体験を楽しむことができます。' where id = 'P3ys4wXF9nBl_a64QU7uU';
update content_bodies set title = 'Introducing Fun Spots in Gero Onsen♪ Spring & Summer【long ver.】026', description = 'Gero City is full of rich natural experiences! This promotional video showcases the attractions of Gero City beyond just hot springs, focusing on activities for Spring and Summer. The video features various experiences, including a cherry blossom tour in Hagiwara, a waterfalls tour in Hida-Osaka, and visits to Mt. Ontake and health farms. It also highlights electric bicycle rentals, foot baths, and unique sweets from Gero Onsen. Other activities include fishing at the Waterside Fishing Center, kayaking tours, and exploring Gassho-Mura. The video emphasizes the diverse offerings of Gero City, inviting visitors to enjoy its natural beauty and cultural experiences.' where id = 's8454J9qeSZW_8G094z7r';
update content_bodies set title = '下呂温泉', description = '下呂温泉は飛騨川のそばに位置し、哲学者林羅山によって日本三名泉の一つと称されています。彼は徳川家康を含む四人の将軍に仕え、室町時代の禅僧である伴里宿とも関わりがありました。下呂の温泉街は美しい山村の風景が広がり、観光地として魅力的なスポットとなっています。' where id = 'konRoRtcD_C0NCnVdpuvx';
update content_bodies set title = 'Gero Hot Springs', description = 'Gero Hot Springs, located alongside the Hida River, is renowned as one of Japan''s top three hot springs, a title attributed to philosopher Razan Hayashi, who served four shoguns, including Ieyasu Tokugawa, during the Muromachi era. The area is characterized by its picturesque hot spring mountain village, making it a popular tourist destination for those seeking relaxation and natural beauty.' where id = 'JgXWHbV6WAhWxnhY_7Pn4';
update content_bodies set title = 'geroプロモーションムービー冬90英語', description = 'これは、冬のシーズンに向けたGeroのプロモーションムービーであり、''90英語''とラベル付けされています。' where id = 'Et695CHX04Bflpv1wRJIQ';
update content_bodies set title = 'gero promotionmovie winter 90 eng', description = 'This is a promotional movie for Gero, specifically for the winter season, labeled as ''90 eng''.' where id = 'd3jfsF_BDGhiOzpO6zfIn';
update content_bodies set title = 'gero_promotionmovie_winter_korean02', description = 'これは説明です。' where id = 'LMZVLQ-CCoUntuPz2L3eU';
update content_bodies set title = 'gero_promotionmovie_winter_korean02', description = 'This is a description.' where id = 'kSrPrbSI7WdyCMYiS9U63';
update content_bodies set title = '花火ミュージカル冬公演-CM', description = 'これは2009年の下呂温泉花火ミュージカル冬公演のテレビCMです。公演日は12月5日（土）、12日（土）、22日（火）、クリスマス特別公演は12月23日（水・祝）です。詳細については、http://www.gero-spa.comをご覧ください。' where id = 'uvUOYdc_6qT7SLSiilq6x';
update content_bodies set title = 'Fireworks Musical Winter Performance - CM', description = 'This is a TV commercial for the 2009 Gero Onsen Fireworks Musical Winter Performance. The event will take place on December 5 (Saturday), December 12 (Saturday), December 22 (Tuesday), and a special Christmas performance on December 23 (Wednesday, holiday). For more details, please visit http://www.gero-spa.com.' where id = '7LeMBDE3dtX1brF07-q8R';
update content_bodies set title = '奈良秘食旅～冬～', description = '奈良県の食の魅力を季節ごとに紹介するこの動画では、つるし柿、あんぽ柿、いちご、大和牛、大和野菜（大和まな、祝だいこん、宇陀金ごぼう）などの食材が登場します。奈良秘食旅は、お茶やうどん、豆腐といった日本人の生活に欠かせない食材のルーツを探るもので、飛鳥・奈良時代にさかのぼります。この地はシルクロードの終着点として栄え、多くの文化や技術が渡来人によってもたらされ、現在に至るまで受け継がれる食文化が育まれました。「大和肉鶏」は大和かしわの再現を夢見て作られ、「大和野菜」は伝統を守りながら発展を遂げています。これらの食材は大切に育てられ、未来を見据えて進化を続けています。奈良の知られざる食のルーツと魅力的な食材を巡る旅です。' where id = 'nIusnNt3qcFDffdX5Apis';
update content_bodies set title = 'Nara Secret Food Journey - Winter', description = 'This video introduces the culinary attractions of Nara Prefecture by season. Featured ingredients include dried persimmons, anpo persimmons, strawberries, Yamato beef, and Yamato vegetables (Yamato greens, Iwai daikon, Uda golden burdock). The Nara Secret Food Journey highlights essential Japanese ingredients like tea, udon, and tofu, tracing their roots back to Nara during the Asuka and Nara periods. This region flourished as the terminus of the Silk Road, where many cultures and techniques were introduced by immigrants, leading to the development of a rich food culture that continues to thrive today. The ''Yamato chicken,'' inspired by the dream of recreating Yamato kashiwa, and the ''Yamato vegetables,'' which have evolved while preserving tradition, are carefully cultivated and continue to evolve with an eye toward the future. This journey explores the unknown roots of food and the captivating ingredients of Nara.' where id = '2TuroPhSNVmMCkYFmlKcH';
update content_bodies set title = '#あまみ#tabi 4k 30秒ver', description = '奄美大島の魅力を紹介する『#あまみ #tabi』の予告編です。奄美大島は豊かな自然と独特の文化が残る世界自然遺産推薦地域です。この動画では、奄美大島出身の女子二人が観光地や景勝地をレンタカーで巡りながら、奄美大島の魅力を再発見します。奄美大島への旅行前に参考にしていただき、訪れた際には、SNS映えする美しい景色の写真を『#あまみ#tabi』のハッシュタグを付けてシェアしましょう。' where id = 'E30VRGm6iKLnenpixySJe';
update content_bodies set title = '#Amami #tabi 4k 30-second version', description = 'The trailer for ''#Amami #tabi'' showcases the rich attractions of Amami Oshima, a region recommended for World Natural Heritage status, known for its abundant nature and unique culture. The video follows two women from Amami Oshima who, now living away, explore tourist spots and scenic locations by rental car, rediscovering the island''s charm. It serves as a great reference for those planning to visit Amami Oshima. Visitors are encouraged to share their beautiful photos of the island on social media with the hashtag ''#Amami #tabi'' to highlight the picturesque scenery.' where id = 'TBAy8xvVgOWhW8G5zcF_d';
update content_bodies set title = '岡山、鏡野、津山、奥津温泉を巡る日本の田舎探訪 | 秋', description = 'このブログでは、ナレーターと母親が美しい秋の季節に岡山、鏡野、津山の隠れた名所を巡る忘れられない旅を紹介します。観光客の少ない場所での真の日本体験を提供し、岡山の静かな風景や鏡野の美しい紅葉を楽しむ様子が描かれています。また、ナレーターが日本の田舎で初めて運転する挑戦もあり、探検にスリルを加えています。旅程には、奥津渓谷や奥津温泉などのさまざまなスポットが含まれ、自然の美しさや地元の文化を楽しむ様子が紹介されています。視聴者には、彼らのユニークな冒険に参加するためにチャンネル登録を促しています。' where id = 'WZEyFNEOEuyCYzgkCO1pv';
update content_bodies set title = 'Exploring Rural Japan: A Journey to Okayama, Kagamino, Tsuyama, Okutsu Onsen | Autumn', description = 'Join the narrator and their mother on a memorable journey through the lesser-known areas of Okayama, Kagamino, and Tsuyama during the beautiful autumn season. This vlog showcases the serene landscapes and stunning autumn foliage, providing an authentic experience of Japan away from the tourist crowds. The adventure includes the narrator''s first-time driving experience in rural Japan, adding an exciting twist to their exploration. The itinerary features various locations, including Okutsu Valley and Okutsu Onsen, where they enjoy the natural beauty and local culture. Viewers are encouraged to subscribe and join their travel family as they embark on this unique adventure.' where id = 'r8aIG7LBa79eRSDn8Ared';
update content_bodies set title = '奄美旅行4K 30秒ver', description = 'この動画は、世界自然遺産にノミネートされている奄美大島の魅力を紹介する旅行予告編です。奄美大島は豊かな自然と独特の文化を持っています。『奄美旅行』というタイトルの動画では、奄美大島から離れた生活を送る2人の女の子が、レンタカーで観光地を巡りながら奄美大島の魅力を再発見する様子が描かれています。奄美大島を訪れる前に、この動画を参考にしてください。また、訪問時には、奄美大島の風景写真を「#奄美旅行」のハッシュタグを付けて共有することが奨励されています。' where id = 'p7mH-MwEymCIE15hi_Q2q';
update content_bodies set title = 'Amami Travel 4K 30-second Version', description = 'This is a travel trailer showcasing the charm of Amami Oshima, a region nominated as a UNESCO World Heritage site, known for its rich nature and unique culture. In the video titled ''Amami Travel,'' two girls, who have distanced themselves from life on Amami Oshima, explore the island by renting a car, rediscovering its allure. Before visiting Amami Oshima, viewers are encouraged to refer to this video. When visiting, they are invited to share their scenic photos of the island on social media with the hashtag ''#AmamiTravel.''' where id = 'Gq7ixhQ1IoEUcZjYCzeji';
update content_bodies set title = '額田のダシまつり　下夜久野駅前の屋台巡行', description = '2019年10月13日（日）に開催された額田のまつりでは、史上初めて国道9号の交差点で2基の屋台が同時に回るという特別なイベントが行われました。この出来事は、まつりの歴史において重要な瞬間となりました。広報ふくちやま2019年11月号でもこのイベントが取り上げられています。動画は夜久野町下町の衣川伸二さんから提供されました。' where id = 'mue8VDoZtFl0OvfR0jts_';
update content_bodies set title = 'Gakuada''s Dashi Festival: Yatai Parade in front of Shimonoyakuno Station', description = 'On October 13, 2019, the Gakuada Festival took place, featuring a historic event where two yatai (festival floats) simultaneously turned at an intersection on National Route 9. This marked a first in the festival''s history. The event was highlighted in the Fukuchiyama City newsletter for November 2019. Video footage was provided by Shinji Korikawa from Yakunomachi Shimomachi.' where id = '5hiwLVq97H_C3inLjt13G';
update content_bodies set title = '野球‐ダンス ～ブランデッドムービー～', description = '愛媛県松山市発祥の「野球拳おどり」が、古坂大魔王さんの総合監修のもと、令和の新しいコンテンツとしてブランディングされたのが「Baseball-Dance」です。この魅力を伝える“ブランデッドムービー”が完成しました。監督はウスイヒロシで、出演者にはlol（小見山直人）、大原優乃、松山聖陵高校ダンス部、愛媛マンダリンパイレーツ、ひめキュンフルーツ缶、松山市民が含まれています。音楽プロデュースはKENJI03（BACK-ON）が担当。Baseball-Danceの楽曲は各サブスクリプションサービスやダウンロードサイトで配信中です。また、練習動画やイベントのダイジェストもYouTubeで公開されています。Twitter、Instagram、TikTok、FacebookなどのSNSで最新情報をフォローできます。' where id = 'pVV-ttdfcAlFvKKz9U_S-';
update content_bodies set title = 'Baseball‐Dance ～Branded Movie～', description = 'The ''Baseball-Dance'' originated in Matsuyama City, Ehime Prefecture, and has been rebranded as a new content for the Reiwa era under the overall supervision of comedian Kosaka Daimaou. A ''Branded Movie'' has been completed to showcase the charm of Baseball-Dance. Directed by Hiroshi Usui, the film features performances by lol (Naoto Komiyama), Yuno Ohara, the dance club of Matsuyama Seiryo High School, Ehime Mandarin Pirates, Himekyun Fruit Can, and local citizens of Matsuyama. The music is produced by KENJI03 (BACK-ON). The Baseball-Dance song is available on various subscription services and download sites. Additionally, practice movies and event highlights are accessible on YouTube. Follow Baseball-Dance on social media platforms like Twitter, Instagram, TikTok, and Facebook for updates.' where id = 'bj5iLuy-qL4ixh7xW58UO';
update content_bodies set title = 'クリス・ペプラーさん 福知山城 新城主 就任記者会見', description = '2019年3月27日、明智光秀の子孫とされるクリス・ペプラーさんが福知山城の新城主に就任しました。記者会見では、彼は髷を結い、明智家の家紋があしらわれた天正裃を身に着けて登場し、新城主としての抱負を熱く語りました。福知山市は、明智光秀の知られざる魅力と市とのつながりを発信する「知られざる明智光秀プロジェクト」に取り組んでいます。また、福知山城は24時間自由に利用できるようになり、日本初の一日城主を公募することが7月5日まで行われます。' where id = 'UUKN-m9gnoIZDoKMwWdqk';
update content_bodies set title = 'Chris Pepple Appointed as New Lord of Fukuchiyama Castle - Press Conference', description = 'On March 27, 2019, Chris Pepple, believed to be a descendant of the famous samurai Akechi Mitsuhide, was appointed as the new lord of Fukuchiyama Castle. During the press conference, he appeared in traditional attire, including a topknot and a ceremonial garment featuring the Akechi family crest. He passionately expressed his aspirations for his new role. The city of Fukuchiyama is actively promoting the lesser-known aspects of Akechi Mitsuhide and its connections to the city through the ''Unknown Akechi Mitsuhide Project.'' Additionally, the castle will be open for public use 24 hours a day, and a call for applications for Japan''s first one-day castle lord is open until July 5.' where id = 'q7GV6694r5mQZvxo9soVh';
update content_bodies set title = '京都・福知山 プロモーション動画', description = '京都・福知山には、息を飲む絶景や、時間が止まったかのような秘境、季節ごとに異なる特別な風景があります。このプロモーション動画では、それぞれの場所や時間が持つ独特の空気を感じることができます。紹介されている主なロケーションには、元伊勢内宮皇大神社、大原神社、長安寺、福知山城、やくの玄武岩公園、二瀬川渓流、天岩戸神社、そして鬼嶽稲荷神社の雲海があります。' where id = 'JyxJPw3cKNtEIY5BBiroW';
update content_bodies set title = 'This is Fukuchiyama of Kyoto', description = 'Fukuchiyama, located in Kyoto, offers breathtaking views, hidden spots that feel like time has stopped, and unique seasonal landscapes. This promotional video invites you to experience the atmosphere of each location and the essence of time. Key locations featured include the Motoiise Naiku Grand Shrine, Ohara Shrine, Changanji Temple, Fukuchiyama Castle, Yaku no Genbuzan Park, the Nise River Valley, Amano Iwato Shrine, and the sea of clouds at Oe Mountain (Onitake Inari Shrine).' where id = 'V62vBOWYRaOXGmDpSft8F';
update content_bodies set title = '五所川原立佞武多２０１９PV（60秒 ver）', description = '五所川原立佞武多祭りでは、巨大な山車が力強いお囃子と「ヤッテマレ！ヤッテマレ！」の掛け声のもと、市街地を練り歩きます。山車は高さ約23メートル、重さ約19トンにも達し、その圧倒的な迫力で観客を魅了します。各山車は独自のテーマを持ち、細かな造形と鮮やかな色使いで表現されています。迫力ある祭りと美しく灯った立佞武多の絶妙なバランスは必見です。祭りは毎年8月4日から8日まで開催されます。' where id = 'rBlkc58NK_Y3cLINwXKbF';
update content_bodies set title = 'Goshogawara Tachineputa Festival 2019 PV (60sec ver.)', description = 'The Goshogawara Tachineputa Festival features massive parade floats that move through downtown Goshogawara, accompanied by powerful festival music and the chant ''Yattemare! Yattemare!'' These floats can reach heights of 23 meters and weigh up to 19 tons, captivating spectators with their impressive size. Each float is uniquely themed, showcasing intricate designs and vibrant colors. The festival presents a remarkable balance between the energetic atmosphere and the beautifully illuminated Tachineputa floats, making it a must-see event. The festival takes place annually from August 4 to 8.' where id = 'QwvRuwWnTKbEiWOmJHPU3';
update content_bodies set title = 'Wild Winter Activity  " The Grace of Japan, TOCHIGI "', description = '栃木県の日光国立公園でプレミアムな冬を体験できます。森の中でのスノーシューや、壮大な白い景色の中でのスノーボードを楽しむことができます。また、氷瀑の前に立つ日本旅館に宿泊し、新鮮な冬の味覚を味わうことができます。栃木県は日本の品格を静かに保ち続け、荘厳な文化や豊かな自然、美意識を体現しています。この冬の冒険は、心の豊かさを上質に満たしてくれることでしょう。' where id = 'm4VIKQoEZQm2WBAHM4Sss';
update content_bodies set title = 'Wild Winter Activity  " The Grace of Japan, TOCHIGI "', description = 'Experience a premium winter in Nikko National Park, Tochigi. Engage in snowshoeing through the serene woods and enjoy snowboarding amidst breathtaking white landscapes. Stay at a traditional Japanese ryokan located near an icefall and savor fresh winter delicacies. Tochigi quietly maintains the elegance of Japan, showcasing its majestic culture, rich nature, and aesthetic sensibility. This winter adventure promises to enrich your spirit with the grace of Japan.' where id = 'JwLskIHqJKIkarDpq0agB';
update content_bodies set title = '自然（G7版）「日本の品格、栃木」', description = '「日本の品格、栃木」は、穏やかな自然と荘厳な歴史文化が心を溶かす場所です。栃木県は東京から約100km北に位置し、新幹線で約50分、車で約90分の距離で、自然に囲まれた環境を楽しむことができます。2023年6月には、栃木県の日光でG7男女共同参画・女性活躍担当大臣会合が開催され、この地域が現代の社会問題における重要性を示しています。栃木は、日本の品格が静かに保たれ、荘厳な文化、豊かな自然、そして心を豊かにする美意識が体現されています。' where id = '7kRHPlXyc4vaPXbT39o73';
update content_bodies set title = 'Nature(G7 ver.)"The Grace of Japan,TOCHIGI"', description = 'Tochigi Prefecture, located about 100 km north of Tokyo, offers a serene blend of nature and rich historical culture that captivates the heart. Just a 50-minute Shinkansen ride or a 90-minute drive from Tokyo, visitors can immerse themselves in the tranquil environment. In June 2023, the G7 Ministerial Meeting on Gender Equality and Women''s Empowerment will take place in Nikko, Tochigi, highlighting the region''s significance in contemporary discussions on social issues. Tochigi is a place where the elegance of Japan is quietly preserved, showcasing majestic culture, abundant nature, and a refined aesthetic that enriches the spirit.' where id = 'd7OQAl1ODenQrv6izznOe';
update content_bodies set title = '文化（G7版）「日本の品格、栃木」', description = '栃木県は東京から約100km北に位置し、自然と歴史的文化が美しく融合した静かな目的地です。新幹線で約50分、車で約90分の距離にあり、穏やかな逃避を提供します。2023年6月には、栃木県の日光で男女共同参画・女性活躍担当大臣会合が開催され、この地域の重要な問題への取り組みが強調されます。栃木は荘厳な文化、豊かな自然美、洗練された美意識が特徴で、心と心を満たす体験を提供します。' where id = 'PKEmApUb7yW8C1LMk8kWN';
update content_bodies set title = 'Culture(G7 ver.)"The Grace of Japan,TOCHIGI"', description = 'Tochigi Prefecture, located about 100 km north of Tokyo, is a serene destination where nature and historical culture blend beautifully. Just a 50-minute Shinkansen ride or a 90-minute drive from Tokyo, it offers a peaceful escape. In June 2023, the G7 Ministerial Meeting on Gender Equality and Women''s Empowerment will take place in Nikko, Tochigi, highlighting the region''s commitment to these important issues. Tochigi is characterized by its majestic culture, rich natural beauty, and refined aesthetic, providing a fulfilling experience for the heart and mind.' where id = '27ga59pjW-GksDdhTeJPd';
update content_bodies set title = 'Azure Sky「日本の品格、栃木」', description = '早朝、色とりどりの気球が一斉に飛び立ち、紺碧の大空に広がる姿は圧巻です。この光景は、静かな自然と豊かな歴史文化で知られる栃木県の本質を捉えています。栃木は、荘厳な文化遺産、豊かな自然美、そして洗練された美意識を持ち続けており、心の豊かさを感じさせる場所です。「日本の品格、栃木」は、この美しい地域の静けさと豊かさを体験することを訪問者に促しています。' where id = 'YTzM9H1zWcik32Xhufxyu';
update content_bodies set title = 'Azure Sky ''The Grace of Japan, TOCHIGI''', description = 'In the early morning, colorful balloons take off simultaneously, creating a vibrant display against the endless azure sky. This scene captures the essence of Tochigi, a region in Japan known for its serene nature and rich historical culture. Tochigi maintains a quiet dignity, showcasing majestic cultural heritage, abundant natural beauty, and a refined aesthetic. ''The Grace of Japan, TOCHIGI'' invites visitors to experience the richness of the heart and the tranquility of this beautiful area.' where id = 'FNrD42zAEUIUab3TtJrcR';
update content_bodies set title = '清流の国 - 日本の品格、栃木', description = '栃木県は清流に包まれた地域であり、古代から湧き出る湧水や透明な渓谷の流れ、透き通った湖が特徴です。訪れる人々は清流の恵みを感じることができます。栃木は穏やかな自然と豊かな歴史文化が調和し、心温まる雰囲気を醸し出しています。荘厳な文化、豊かな大自然、そして美意識を通じて、日本の品格を静かに保ち続けており、訪れる人々の心を豊かに満たします。' where id = 'WV14VblLSBUPdsbXILQBT';
update content_bodies set title = 'The Land of Clear Stream - The Grace of Japan, TOCHIGI', description = 'Tochigi, known as ''The Grace of Japan,'' is a region enveloped by clear streams and natural beauty. It features spring water that has flowed since before humanity''s existence, alongside a pristine canyon stream and a crystal-clear lake. Visitors can experience the blessings of these clear waters. The area is characterized by its serene nature and rich historical culture, which together create a heartwarming atmosphere. Tochigi maintains the elegance of Japan through its majestic culture, abundant nature, and refined aesthetic, enriching the spirit of those who visit.' where id = 'Ty03wYWFdZLJytOqxayij';
update content_bodies set title = '紅葉の大地 - 日本の品格、栃木', description = '目の前に広がる紅葉の大地は、世の中にあるあらゆる色が存在する風景です。彩豊かな風景の中に美を見いだすことができます。「日本の品格」として知られる栃木県は、荘厳な文化と豊かな自然を通じて静かな品格を保ち、訪れる人々の心を豊かに満たします。' where id = '2U3bSaYVG7QxBvg-EClnP';
update content_bodies set title = 'The Plateau of Autumn Leaves - The Grace of Japan, TOCHIGI', description = 'Tochigi is a land where the beauty of autumn leaves unfolds before us, showcasing a landscape filled with every color imaginable. This rich tapestry of colors allows us to discover beauty in nature. Known as ''The Grace of Japan,'' Tochigi maintains a serene dignity through its majestic historical culture and abundant natural beauty, enriching the heart and spirit of those who visit.' where id = 'GTuoLAEHOR15yLD-nhS4v';
update content_bodies set title = '心の花を咲かせる。"日本の優雅、栃木"', description = 'この文章は、自然と人間のつながりを強調し、内なる美しさを育み、未来への希望を持つことを促しています。読者に心を花開かせる旅に参加するよう呼びかけ、栃木を日本の優雅さの象徴として紹介しています。メッセージは詩的な行動の呼びかけであり、人々に人生と環境の美しさを受け入れるよう促しています。' where id = 'DMUZUd5X06WEHkRP6eirz';
update content_bodies set title = 'Bloom for the flower of heart. "The Grace of Japan, TOCHIGI"', description = 'The text emphasizes the connection between nature and humanity, encouraging individuals to nurture their inner beauty and hope for the future. It invites readers to join in the journey of blossoming their hearts, highlighting Tochigi as a representation of Japan''s grace. The message is a poetic call to action, urging people to embrace the beauty of life and the environment.' where id = 'BYi2MdZ6pKMdazmNv8NGg';
update content_bodies set title = 'あなたの笑顔のために。「日本の優雅さ、栃木」', description = '栃木は、いつか皆様とお会いできるその日に向けて準備を進めています。私たちは、世界中の笑顔のために、日本の優雅さを体現し、栃木の美しさや文化を紹介することに力を入れています。この取り組みは、つながりと喜びの重要性を強調し、皆様にこの地域の温かさとおもてなしを体験していただくことを目的としています。詳細については、公式の栃木ウェブサイトや観光サイトをご覧ください。' where id = 'kok3fuOjQWd1DmsK_vOFU';
update content_bodies set title = 'For your smile. "The Grace of Japan, TOCHIGI"', description = 'Tochigi is preparing to welcome visitors for the day when we can meet again. The focus is on creating smiles and showcasing the grace of Japan through the beauty and culture of Tochigi. The initiative emphasizes the importance of connection and joy, inviting everyone to experience the warmth and hospitality of this region. For more information, you can visit the official Tochigi website and the tourism site.' where id = 'WFGb2kE7nrhusMe6lIfH4';
update content_bodies set title = '美の感覚。「日本の優雅さ、栃木」', description = '紫陽花、ゆり、青竹、紅葉など、栃木の野に咲く色彩は人間の美意識の根源を表しています。四季折々の自然の美しさが織り込まれた装束を身に纏い、舞い踊る栃木は、忘れがたい魅力を持つ地域です。' where id = 'TMu5ChqwY5MgtgKmc9yvM';
update content_bodies set title = 'Sense of Beauty. "The Grace of Japan, TOCHIGI"', description = 'Tochigi is a region that embodies the essence of nature through its vibrant colors found in fields, such as hydrangeas, lilies, green bamboo, and autumn leaves. These elements reflect the roots of human aesthetic sensibility. The beauty of Tochigi is woven into a tapestry that showcases the natural splendor of the four seasons, making it an unforgettable destination.' where id = 'Tkl16amAeGRhOwWZNx0Ks';
update content_bodies set title = '自然の優雅さ。「日本の美、栃木」', description = '栃木は、どこまでも透き通った清流と四季折々の美しい山々が広がる自然の美しさに満ちた地域です。戦場ヶ原は野生動物の宝庫であり、中禅寺湖は雄大な男体山を鏡のように映し出します。この地域は、訪れる人々に栃木の活気ある自然に浸る穏やかなアウトドア体験を提供します。' where id = 'SBzIgIWGnEgGBbEv2ciFv';
update content_bodies set title = 'Elegance of Nature. "The Grace of Japan, TOCHIGI"', description = 'Tochigi is a region of stunning natural beauty, featuring crystal clear waters and breathtaking mountain views that change with the seasons. Senjogahara is a haven for wildlife, while Chuzenji Lake reflects the grandeur of Mt. Nantai like a mirror. This area offers a serene outdoor experience, allowing visitors to immerse themselves in the vibrant nature of Tochigi.' where id = 'Mvn_zbNPCdxrPpwC5NQXl';
update content_bodies set title = '余部鉄橋ライトアップ', description = 'この映像は、平成18年（2006年）8月25日と26日に行われた余部鉄橋のライトアップイベントを紹介しています。' where id = 'EMpXmcjmeLt-TK28YJaAl';
update content_bodies set title = 'Ayabe Bridge Illumination', description = 'This video showcases the Ayabe Bridge illumination event that took place on August 25 and 26, 2006.' where id = 'rKOSbcj9ArDTwQpg69-cX';
update content_bodies set title = '余部彩景【３分００秒】', description = 'この映像は、ドローンを使用して撮影された余部の美しい景色と、余部クリスタルタワーの夜景を紹介しています。' where id = 'j2Eroqr8YW4e2igGl9k9s';
update content_bodies set title = 'Ayabe Scenic Views [3 minutes 00 seconds]', description = 'This video features scenic views of Ayabe captured using a drone, including nighttime footage of the Ayabe Crystal Tower.' where id = 'SnT2exMhGDgRnmWRez8yQ';
update content_bodies set title = '１０月の香美町', description = '１０月も終わり、１１月となりました。いよいよ松葉ガニ漁の解禁の季節となりました。山の木々も色づき始め、紅葉の見ごろを迎えています。香美町の美味しい食材と美しい景色をぜひ味わいに、香美町へお越しください。' where id = 'KcS4kPt2iXojNds2N-CXb';
update content_bodies set title = 'Kōbichō in October', description = 'As October comes to an end and November begins, the season for Matsuba crab fishing has finally arrived. The trees in the mountains are starting to change color, marking the peak of the autumn foliage. We invite you to visit Kōbichō to enjoy its delicious local ingredients and beautiful scenery.' where id = 'D2F1_c4C2NIVfT5jxyABS';
update content_bodies set title = '１１月の香美町', description = '１１月が終わり、１２月に突入しました。寒さが日ごとに増してきており、日本海の波は荒くなっています。山の木々は落葉し、初雪の便りも間近に迫っていることでしょう。香美町を訪れる際は、冬用タイヤを準備してお越しください。' where id = 'AKNAFLxdCIiKXQ6dEqdLr';
update content_bodies set title = 'Kōbichō in November', description = 'As November comes to an end and December begins, the cold weather is becoming more pronounced. The waves of the Sea of Japan are growing rough, the trees in the mountains are shedding their leaves, and the first snow is expected soon. If you plan to visit Kōbichō, please ensure you have winter tires prepared.' where id = 'sZd-Pirb6tHk1MTyFjrik';
update content_bodies set title = '１２月の香美町', description = '新年あけましておめでとうございます。旧年中はお世話になりました。本年もよろしくお願いします。１２月には積雪もあり、冬本番を迎えました。令和３年は「丑年（うしどし）」です。全国の黒毛和牛の素牛「但馬牛」は香美町が誇る名牛です。ぜひ香美町へお越しの際にはとても美味な「但馬牛」を味わってはいかがでしょうか。' where id = 'l8eh83LI9V34zH3O6tjAX';
update content_bodies set title = 'Kōmi Town in December', description = 'Happy New Year! Thank you for your support last year. We look forward to your continued patronage this year. December brings snowfall, marking the full arrival of winter. The year 2021 is the Year of the Ox. Kōmi Town proudly boasts the Tajima cattle, the source of Japan''s black-haired Wagyu beef. If you visit Kōmi Town, be sure to enjoy the delicious Tajima beef.' where id = '0tZCRUY_8hePwmGUwpz26';
update content_bodies set title = '指サス方ヘ/幸 巴(ゆき ともえ)【MV full】', description = '「指サス方ヘ」は、幸巴（ゆきともえ）が木下龍平によって作詞・作曲された楽曲です。この歌は、夢を持つことの大切さを伝え、夢をバカにされた経験について問いかけます。「どうせ無理」といった言葉に惑わされず、夢を追い続けることを促します。道が見えなくなったときに、この歌を聴いて思い出してほしいというメッセージが込められています。サブスクリプション配信も行われています。' where id = '7Zqlfg7SLe8QbQfn_BMeG';
update content_bodies set title = 'Yubi Sasu Kata e / Tomoe Yuki (MV full)', description = 'The song ''Yubi Sasu Kata e'' by Tomoe Yuki, written and composed by Ryuhei Kinoshita, encourages listeners to hold onto their dreams despite facing skepticism or ridicule. It poses the question of whether listeners have dreams and if they have ever been belittled for them. The message is clear: do not be swayed by negative words that suggest your dreams are impossible. When the path ahead seems unclear, the song serves as a reminder to reflect on your aspirations. The song is available for streaming.' where id = 'aJCuSVe14dluk3u8LntEC';
update content_bodies set title = '鹿屋市に一緒に旅行に行こう！', description = 'タイから来た2人の女性が鹿屋市を初めて訪れ、『うれしい、おいしい、楽しい！新しい発見に出逢うまち・鹿屋市』と表現しました。鹿屋市の観光地や特産品であるさつまいもやカンパチの体験、キャラクター「かのやカンパチロウ」とのふれあいを通じて、鹿屋の魅力を凝縮した内容の動画です。' where id = 'g6oM1duV_hLt-_ySMapR5';
update content_bodies set title = 'Let''s go on a trip together around Kanoya!', description = 'Two girls from Thailand visited Kanoya city for the first time and described their experience as ''Happy, delicious, fun! A town where new discoveries are made.'' The video showcases Kanoya''s sightseeing spots, highlights local specialties like sweet potatoes and kanpachi (greater amberjack), and introduces the character ''Kanoya Kanpachirou,'' encapsulating the essence of a Kanoya adventure.' where id = 'bHnmmVxFyyWfo93TItUxB';
update content_bodies set title = '飛騨高山の紅葉', description = '岐阜県高山市は、日本一広い市域を持ち、標高は最低436mから最高3,190mまでの幅があります。市街地より高い場所が多く、豊かな自然が四季折々の美しさを生み出しています。特に秋は、標高によって紅葉のタイミングが異なるため、例年9月下旬から11月中旬まで長期間にわたり紅葉を楽しむことができます。高山市では、古い町並みや歴史的な寺社、渓谷や滝、北アルプスの美しい景観があり、訪れるエリアごとに異なる紅葉の表情が楽しめます。飛騨高山ならではの“紅葉グラデーション”を体験する旅に出かけてみませんか？' where id = 'EED7XqbFm3B327nj5kInr';
update content_bodies set title = 'Autumn Hida', description = 'Takayama City in Gifu Prefecture boasts the largest area in Japan, with an elevation range from 436m to 3,190m. The city is characterized by its high-altitude locations, which create a rich natural environment that changes with the seasons. In autumn, the timing of the foliage changes with elevation, allowing visitors to enjoy the autumn colors from late September to mid-November. Takayama offers a variety of landscapes, from historic streets and temples to valleys, waterfalls, and the Northern Alps, each showcasing unique autumn hues. Experience the distinctive ''autumn gradient'' of Hida Takayama on your journey.' where id = 'BgAdVxl48TpeM0RNTg7zL';
update content_bodies set title = '【LIVE CAMERA】飛騨高山 陣屋前', description = 'このライブカメラでは、高山市にある高山陣屋や陣屋前朝市の様子を観ることができます。飛騨・高山は、歴史的な町並みと美しい自然に囲まれた地域で、温泉や郷土料理を楽しむことができます。宿泊施設としては温泉ホテルやゲストハウスがあり、地元の食材を使った料理や歴史的な建物の見学、工芸品のショッピングも楽しめます。また、近くには合掌造りで知られる世界遺産の白川郷もあります。' where id = '_sXW97JHCKZXiJy0jENwJ';
update content_bodies set title = 'LIVE CAMERA: Hida-Takayama, In front of the Takayama Jinya', description = 'The live camera offers a view of Takayama Jinya and the open-air morning market in Takayama city. Hida Takayama, located in Gifu, Japan, is renowned for its historical streets and beautiful nature surrounded by the Alps. Visitors can enjoy staying at onsen hotels and guesthouses, savoring local dishes made with regional ingredients, exploring historical buildings, and shopping for crafts. Additionally, the village of Shirakawago, a World Heritage Site known for its gasshozukuri architecture, is situated nearby.' where id = 't_re5Ec6pme652R73CQkc';
update content_bodies set title = '【LIVE CAMERA】飛騨高山の中橋', description = '岐阜県高山市に位置する中橋は、飛騨高山の名所です。春には桜、夏には爽やかな緑、秋には紅葉、冬には雪景色と、四季折々の美しさを楽しむことができます。朱色の橋が、飛騨高山の自然の魅力を引き立てています。' where id = 'u5tANmJCz69rl4VtnMfeT';
update content_bodies set title = 'LIVE CAMERA: Nakabashi in Hida Takayama', description = 'Located in Takayama City, Gifu Prefecture, Nakabashi is a famous landmark in Hida Takayama. Visitors can enjoy the beauty of the four seasons: cherry blossoms in spring, refreshing greenery in summer, vibrant autumn leaves, and picturesque snowy landscapes in winter, all framing the iconic red bridge.' where id = 'IEwQXbWM6FJqfpGIP6fjg';
update content_bodies set title = '【2025年保存版】夏の絶景 in #飛騨高山！', description = 'この動画では、2025年の夏における飛騨高山の絶景を紹介しています。空と山が溶け合う圧巻の大パノラマが楽しめる内容です。' where id = 'l2V_e1pGggZgu0-QVz0Yz';
update content_bodies set title = '2025 Summer Spectacular in #HidaTakayama!', description = 'This video introduces the breathtaking summer scenery in #HidaTakayama for 2025, showcasing the stunning panorama where the sky and mountains blend seamlessly.' where id = 'TL9UU5e2GnBxQ-BNFpzsP';
update content_bodies set title = '高山の隠れ家な名店「if珈琲店」', description = 'この動画では、高山にある隠れ家の名店「if珈琲店」を紹介しています。店内に足を踏み入れると、心地よいジャズの音色が流れ、リラックスした雰囲気が漂います。メニューはコーヒーとカボチャプリンの2つだけですが、そのシンプルさが逆に魅力を引き立てており、特別な体験を提供しています。' where id = 'WZj_OCQ0aOEl7r8J5RjMD';
update content_bodies set title = 'Hidden Gem in Takayama: if Coffee Shop', description = 'This video introduces ''if Coffee Shop'', a hidden gem in Takayama. Upon entering the shop, you are greeted by the soothing sounds of jazz music. The menu is simple, offering only coffee and pumpkin pudding, yet it creates a complete experience that speaks for itself.' where id = 'n_qWqbhNyfD0h_IuGwmC-';
update content_bodies set title = '古代神殿の中を散策しながら、アートを楽しむことができる「光ミュージアム」', description = 'この動画では、古代神殿の中を散策しながらアートを楽しむことができる「光ミュージアム」について紹介しています。重厚な神殿のような石造りの外観を持つこの博物館は、建物自体が芸術作品のように壮大で、雨の日でもその魅力を存分に楽しむことができます。' where id = 'Tvja5VdhimhgA64ZVhAmm';
update content_bodies set title = 'Explore Art in the Ancient Temple: The Light Museum', description = 'This video introduces the ''Light Museum,'' where visitors can enjoy art while strolling through an ancient temple. The museum features a grand stone exterior reminiscent of a heavy temple, making it a magnificent work of art in itself. It offers a delightful experience even on rainy days.' where id = 'A98N1-7DommSgK_JTn-f4';
update content_bodies set title = '飛騨高山 五感が目覚める、五色ヶ原の森へ。', description = '五色ケ原は北アルプス乗鞍岳の北西山麓に広がる約3000haの森林地帯で、中部山岳国立公園の南端に位置します。ここはほとんど手つかずの自然が残る秘境で、多くの渓流や滝、池、湿原が点在し、さまざまな野生生物が生息しています。訪れることで、自然の多彩な表情を楽しむことができ、偉大な自然のパワーを感じることができます。' where id = '66fGSBIj7wW8uzl8pqIzB';
update content_bodies set title = 'Goshikigahara Forest: Awaken Your Senses in Hida Takayama', description = 'Goshikigahara, located at the northwestern foot of Mount Norikura in the Northern Alps, is a vast forest area of approximately 3,000 hectares at the southern end of Chubu Sangaku National Park. This pristine natural sanctuary remains largely untouched, making it a true hidden gem. The area is home to numerous streams, waterfalls, ponds, and wetlands originating from Mount Norikura, as well as a diverse range of wildlife including various animals, birds, and insects. Visitors can enjoy the rich and varied expressions of nature, and once you step into this realm, you can truly feel the power of the great outdoors.' where id = 'UJGmnMdlHO-e00tPq7VrF';
update content_bodies set title = 'KUSHIRO Hokkaido Japan in 8K HDR - 釧路 [夏バージョン]', description = 'この動画は、釧路の美しさを8K HDRで紹介しています。釧路と阿寒湖の観光名所を強調し、観光、交通、宿泊、地元のグルメに関する重要な情報を提供しています。公式観光サイトでは、訪問者向けの豊富なリソースが用意されており、イベント情報や文化的な洞察も含まれています。また、地域の歴史やアイヌ文化にも触れ、北海道の手つかずの自然の美しさを強調しています。視聴者は、撮影地を表示するために字幕をオンにすることが推奨されています。動画は、映像監督・編集の栄川裕樹氏、撮影の松村隆氏、空撮の馬場基成氏によって制作されています。' where id = 'XM6Phzs_UzRCJe3HE36RJ';
update content_bodies set title = 'KUSHIRO Hokkaido Japan in 8K HDR - Kushiro [summer ver.]', description = 'This video showcases the beauty of Kushiro, Hokkaido, in stunning 8K HDR quality. It highlights the attractions of Kushiro and Lake Akan, providing essential information on tourism, transportation, accommodation, and local cuisine. The official tourism website offers a wealth of resources for visitors, including event information and cultural insights. Additionally, the video features the history and Ainu culture of the region, emphasizing the untouched natural beauty of Hokkaido. Viewers are encouraged to turn on subtitles to see the shooting locations. The video is directed and edited by Yuki Eikawa, with photography by Takashi Matsumura and aerial photography by Motonari Baba.' where id = 'dj5v4Dl0JtcVZwXaC0ZMe';
update content_bodies set title = '飛騨高山の赤かぶ漬', description = 'この動画では、飛騨高山で昔から人々が栽培し、作られてきた「赤かぶ漬」について紹介しています。雪が多く降るため、生野菜が収穫できない冬の保存食として愛されてきたこの料理は、寒暖差のある気候で育てられた赤かぶの旨みが詰まっています。' where id = '06l82eJf21EgpzTeH5ieP';
update content_bodies set title = 'Pickled Red Turnips from Hida Takayama', description = 'This video introduces ''Pickled Red Turnips,'' a traditional food cultivated and made by the people of Hida Takayama. Due to heavy snowfall, fresh vegetables cannot be harvested in winter, making this pickled dish a beloved winter staple. The red turnips, grown in a climate with significant temperature differences, are packed with flavor.' where id = '8OJ1QL_ck0iEoM9JMGf66';
update content_bodies set title = '滝巡りが楽しめる「#宇津江四十八滝」の紅葉が見頃です', description = 'この動画では、滝巡りが楽しめる「#宇津江四十八滝」の紅葉について紹介しています。渓谷沿いには大小無数の13の滝があり、豊かな自然の中で滝の水音に耳を澄ませながらのんびり散策できるため、リフレッシュに最適です。' where id = 'YwaU7Qik8ReNan2-NDiOH';
update content_bodies set title = 'The Autumn Foliage at ''Uzu-e Forty-eight Waterfalls'' is at its Peak', description = 'This video introduces the autumn foliage at ''Uzu-e Forty-eight Waterfalls,'' where visitors can enjoy a tour of numerous waterfalls along the valley. With 13 waterfalls of various sizes, it offers a chance to relax and refresh while listening to the soothing sounds of the water amidst rich natural surroundings.' where id = 'qo9j1XYZhsMNwiDRadApU';
update content_bodies set title = '10月18日(金)～11月23日(土)の期間限定で高山駅にストリートピアノが登場！その名も「飛騨六花(ひだろっか)」。', description = 'この動画では、高山駅に期間限定で設置されるストリートピアノ「飛騨六花」について紹介しています。「飛騨六花」という名前は、高山の澄み切った冬を表す美しい季語に由来しています。' where id = 'OOk7w3ZZ5PGPpaQEY0LBJ';
update content_bodies set title = 'Street Piano ''Hida Rokka'' at Takayama Station from October 18 to November 23', description = 'This video introduces the street piano ''Hida Rokka,'' which will be temporarily installed at Takayama Station. The name ''Hida Rokka'' is inspired by a beautiful seasonal word that represents the clear winter of Takayama.' where id = 'wGAlljbfooz0QINBD3ZW9';
update content_bodies set title = '獅子舞や闘鶏楽、裃姿の警固など総勢数百名の大行列が町を巡る「御巡幸」', description = 'この動画は「御巡幸」について紹介しています。華やかな衣装を身にまとった数百名の参加者が町を巡る様子が映し出され、まるでタイムスリップしたかのような光景が広がります。獅子舞や闘鶏楽などの伝統的なパフォーマンスも行われ、裃姿の警固も登場し、観客を魅了します。' where id = '5hARCVvlvuh4sxhh_m_mn';
update content_bodies set title = 'The Grand Procession of ''O-Mikoshi'' Featuring Lion Dances and Rooster Fights', description = 'This video introduces the ''O-Mikoshi'' event, showcasing a grand procession with hundreds of participants dressed in vibrant costumes reminiscent of a time long past. The event features traditional performances such as lion dances and rooster fights, along with participants in ceremonial attire, creating a captivating spectacle that draws attention.' where id = 'XmfDGz7aGWNfDffw7DN_O';
update content_bodies set title = '実りみちる町　久々野町', description = '久々野町は、フルーツや野菜、花に囲まれた桃源郷です。りんごや桃、ホウレンソウ、トマトなどの生産が盛んで、寒暖差のある気候と美味しい水、太陽の光に恵まれています。丹精込めて育てられた果物や野菜は、加工品も絶品です。特に、自然の甘さが凝縮されたりんごや桃のジェラートやジュースは、目が覚めるような味わいを提供します。' where id = 'yHhHI81gOTql2vsaCm4jt';
update content_bodies set title = 'A Bountiful Town: Kuzu Town', description = 'Kuzu Town is a paradise surrounded by fruits, vegetables, and flowers. It is known for its abundant production of apples, peaches, spinach, and tomatoes. The region benefits from a climate with significant temperature differences, delicious water, and ample sunlight, which contribute to the careful cultivation of its produce. The fruits and vegetables are not only fresh but also transformed into exquisite processed products. The natural sweetness of the apples and peaches is concentrated in their gelato and juice, offering a refreshing and delightful taste.' where id = 'u5SPMEE5DeqgIbJsZ3EaX';
update content_bodies set title = '4~5種類のイチゴ狩りが楽しめる「#小屋垣内農園」', description = 'この動画では、4~5種類のイチゴ狩りが楽しめる「#小屋垣内農園」について紹介しています。飛騨高山の寒暖差を利用して育てられたイチゴは、濃縮された味わいと強い甘みが特徴です。予約は不要で、開始から終了の15時まで時間無制限で食べ放題です。' where id = 'lfF03tQCo7tUZ9BmPdMGe';
update content_bodies set title = 'Enjoy 4 to 5 Varieties of Strawberry Picking at #Koyagaito Farm', description = 'This video introduces #Koyagaito Farm, where visitors can enjoy picking 4 to 5 varieties of strawberries. The farm takes advantage of the temperature differences in the Hida Takayama region, resulting in strawberries with a rich flavor and strong sweetness. No reservations are required, and visitors can enjoy unlimited strawberry picking from the start time until 3 PM.' where id = '5hPEWHdF2aQjhemV3GOCq';
update content_bodies set title = 'ざらめで作る綿菓子を溶かしながら食べる絶品すき焼きが人気「#岩ト屋」', description = 'この動画では、ざらめで作られた綿菓子を溶かしながら楽しむ絶品のすき焼きについて紹介しています。使用されているのはA5等級の飛騨牛で、口の中でとろけるような食感が特徴です。また、飛騨エリアの特産品も取り入れられています。特に飛騨高山の魅力が詰まった料理です。' where id = 'VbdDgV31K5pJ5h56drAnb';
update content_bodies set title = 'Delicious Sukiyaki with Cotton Candy Made from Zarame is Popular at #Iwatoya', description = 'This video introduces a delicious sukiyaki dish that features A5 grade Hida beef and large cotton candy made from zarame, which melts in your mouth. The dish includes local specialties from the Hida area, particularly from Takayama.' where id = '8SkvPv5girNZztTy8lNVU';
update content_bodies set title = '飛騨高山へようこそ', description = '日本一面積が広い市、高山市は町の至る所に多くの見どころがあり、飛騨山脈（北アルプス）に囲まれた豊かな自然と四季折々の美しい景色が魅力です。ここでは、他では味わえない感動的な体験が待っています。' where id = 'JnwYLgzeGwzsduhw7zW4q';
update content_bodies set title = 'Welcome to Hida Takayama', description = 'Takayama, the largest city in Japan by area, is filled with numerous attractions throughout the town. Nestled in the Hida Mountains (Northern Alps), this area boasts rich nature and beautiful seasonal landscapes that provide a soothing experience. It offers a variety of unique and emotional experiences that you can only find here.' where id = 'Q-XYiIevUlThH5Bzo2x3n';
update content_bodies set title = 'せせらぎが聴こえる町　#飛騨清見', description = '森に囲まれた清見町は、おしゃれなカフェやレストランが点在し、洗練された雰囲気と自然ののどかさが共存しています。町の中央を南北に縦断する全長64㎞の「飛騨美濃せせらぎ街道」は、ドライブに最適なルートです。清流沿いでは初夏に新緑が輝き、秋には紅葉の名所として知られています。標高差によって色づく場所が移り変わるため、長期間にわたって美しい景色を楽しむことができます。' where id = 'XZy-n1yYBVcgHATpqhXhw';
update content_bodies set title = 'The Town Where You Can Hear the Murmuring Stream - Hida Kiyomi', description = 'Surrounded by forests, Kiyomi Town features stylish cafes and restaurants that coexist with a sophisticated atmosphere and tranquil nature. The ''Hida Minou Seseragi Highway,'' a 64 km long route running north to south through the town, is an ideal driving route. Along the clear stream, fresh greenery shines in early summer. In autumn, the area is known for its beautiful foliage, with the changing colors due to elevation differences providing a long-lasting visual delight.' where id = 'bZN4QlYOG51AcUJR_y_vB';
update content_bodies set title = 'レトロなブリキの看板など昭和の雰囲気が漂う「#福地温泉朝市」', description = 'この動画では、レトロなブリキの看板が並ぶ「#福地温泉朝市」を紹介しています。ここでは、味噌などの名物やお菓子が販売されており、店内には昭和のポスターや昔のアイドル、俳優の写真がたくさん飾られています。昭和の雰囲気を楽しむことができる場所です。' where id = 'e5yf0AhjM7VFseoCntBtY';
update content_bodies set title = 'Retro Atmosphere of Fukuchi Onsen Morning Market', description = 'This video introduces the Fukuchi Onsen Morning Market, which exudes a retro Showa era atmosphere with vintage tin signs. The market features local specialties such as miso and various snacks. Inside, there are numerous posters and photographs of past idols and actors from the Showa period.' where id = 'yYIMjaqRvUXXep7umVkaI';
update content_bodies set title = '日本唯一の２階建てゴンドラで北アルプス360°大パノラマを楽しむ「新穂高ロープウェイ」', description = 'この動画では、日本唯一の２階建てゴンドラを利用して、気軽に北アルプスの360°大パノラマを楽しめる「新穂高ロープウェイ」について紹介しています。冬の季節にしか見ることができない幻想的な風景や、限定イベントが多数用意されています。' where id = 'nXiyPgOtkJE7RmH_31DA_';
update content_bodies set title = 'Experience the Unique Two-Story Gondola for a 360° Panorama of the Northern Alps at Shin-Hotaka Ropeway', description = 'This video introduces the Shin-Hotaka Ropeway, which features Japan''s only two-story gondola, allowing visitors to easily enjoy a breathtaking 360° panorama of the Northern Alps. The winter season offers a magical landscape and a variety of exclusive events that can only be experienced during this time.' where id = '9gRYAz-1gMefgUTbpFQN_';
update content_bodies set title = '新平湯温泉「タルマかねこおりライトアップ」', description = 'この動画では、新平湯の名所であるタルマの滝・親水公園で開催される「#新平湯温泉 #タルマかねこおりライトアップ」について紹介しています。息を吞む美しさで圧倒される神秘的な風景が楽しめるイベントです。' where id = 'eqhEHPtOig_yvWdNgS1fx';
update content_bodies set title = 'Tarma Falls and Shinsyu Park: ''#Shin-Hirayu Onsen #Tarma Kaneko Ice Light-Up''', description = 'This video introduces the ''#Shin-Hirayu Onsen #Tarma Kaneko Ice Light-Up'' event held at Tarma Falls and Shinsyu Park, a famous spot in Shin-Hirayu. Visitors can experience breathtaking beauty and a mystical landscape unlike anything they have encountered before.' where id = 'PocTAisUiidHXJlOQIB6U';
update content_bodies set title = '歴史と自然が紡ぐ荘川町', description = '荘川町は山々に囲まれ、北西には富山県、石川県、福井県、岐阜県にまたがる白山の雄大な姿を望むことができる自然豊かな町です。四季折々の美しい景色を楽しむことができ、桜、新緑、紅葉、雪景色など、訪れるたびに異なる絶景が広がります。' where id = 'DcQYCI9BNXJzf39KGRrsi';
update content_bodies set title = 'History and Nature Intertwined: Shokawa Town in Hida Takayama, Gifu Prefecture', description = 'Shokawa Town is surrounded by mountains and offers stunning views of the majestic Hakusan, which spans four prefectures: Toyama, Ishikawa, Fukui, and Gifu. This nature-rich town allows visitors to enjoy breathtaking seasonal landscapes, including cherry blossoms, fresh greenery, autumn leaves, and snowy scenes throughout the year.' where id = 'waNp4wySlq248v7QZkvjr';
update content_bodies set title = 'ReVIEW! #飛騨高山　高根町', description = '飛騨高根観光協会会長の小坂守さんが高根町の魅力を紹介します。高根町は高山市の南東に位置し、乗鞍岳と御嶽山に囲まれた自然豊かな高地です。長野県木曽地域に隣接しており、歴史や文化に木曽の影響が色濃く見られ、飛騨の中でも異郷として知られています。高根町は木曽馬の産地としても有名で、馬の供養のための石仏には人と馬の物語が込められています。また、発酵食品に力を入れており、廃校を再利用したウイスキー蒸溜所が注目を集めています。塩を使わず乳酸菌で漬けた「すな」や、飛騨の郷土料理に使われる田舎味噌も盛んに作られています。涼しい夏と寒冷な冬の環境が、これらの発酵食品の育成に寄与しています。その他にも火畑そばやタカネコーン、野麦峠や御嶽山など多くの見どころがあります。ぜひ高根町にお越しください。高山市街地から車で約50分です。' where id = 'RWBD_Ctttqxgo72iQulJ-';
update content_bodies set title = 'ReVIEW! #Hida Takayama Takane Town', description = 'Mamoru Kosaka, chairman of the Hida Takane Tourism Association, introduces the charms of Takane Town, located southeast of Takayama City. Surrounded by nature and overlooking Mt. Norikura and Mt. Ontake, the town is influenced by the nearby Kiso region of Nagano Prefecture, making it a unique area within Hida. Known for its production of Kiso horses, Takane Town features stone Buddha statues that tell stories of the bond between people and horses. The town is also focusing on fermented foods, with a whiskey distillery repurposed from an abandoned school gaining attention. Other local specialties include suna, pickled with lactic acid bacteria, and country miso, commonly used in Hida cuisine. The region''s cool summers and cold winters support the production of these foods. Takane Town offers various attractions, including Hibata Soba, Takane Corn, Nomai Pass, and Mt. Ontake. Visitors are encouraged to explore this unique destination, just a 50-minute drive from Takayama city center.' where id = 'W7kDi5kH9D-P-0flc-VYE';
update content_bodies set title = '飛騨高山 宇津江四十八滝をトレッキング', description = '宇津江四十八滝は大小無数の滝に囲まれたマイナスイオンあふれる癒しスポットで、岐阜県名水50選にも選ばれた自然公園です。豊かな自然の中で、滝の水音を聞きながら13の滝を巡るのんびりとした散策が楽しめます。特に「王滝」は高さ18.8mで、岩肌を流れ落ちる白い水瀑は圧巻です。滝めぐりの出発地点から四十八滝高原までは約1時間で、途中の展望台からは北アルプスの景色も楽しめます。国府町ならではの自然の美しさをぜひ体験してください。' where id = '0jYpI4u9gbKJkBEOED0cj';
update content_bodies set title = 'Trekking at Utsue 48 Falls', description = 'Utsue 48 Falls is a serene spot filled with negative ions, featuring numerous waterfalls of various sizes. This natural park is recognized as one of Gifu Prefecture''s top 50 famous water sites. Visitors can enjoy a leisurely stroll around 13 waterfalls while listening to the soothing sounds of water in a rich natural setting. Notably, ''Otaki'' stands at 18.8 meters, showcasing a stunning white cascade over the rocky surface. The trek from the starting point to the Shijuhachitaki Plateau takes about an hour, and an observation deck along the way offers views of the Northern Alps. Experience the unique beauty of nature that Kokufu Town has to offer.' where id = 'wRR2PwCBgWb4LJ1rGfnrf';
update content_bodies set title = '飛騨高山 おおくら滝遊歩道を散策', description = '「おおくら百滝」と呼ばれる大小の滝を眺めながら散策できる「おおくら滝遊歩道」は、落差約30メートルの「大倉滝」を目指して渓谷沿いを巡るコースです。特におすすめなのは、あちこちに残る巨石群で、遊歩道にトンネルのように覆いかぶさる「くぐり岩」は神秘的で迫力があります。自然の壮大なパワーと美しさに触れ、ぜひその魅力を体感してください。清見町には最高の自然体験があります。' where id = 'dox890a35OXH4nZktX0V-';
update content_bodies set title = 'Exploring the Okura Falls Promenade', description = 'The Okura Falls Promenade offers a scenic walk alongside the large and small waterfalls known as ''Okura Hyakudaki.'' This trail leads through the valley towards Okura Falls, which cascades down with a height of approximately 30 meters. Notable features include the impressive boulders scattered throughout the area, and the Kuguriiwa, a rock formation that arches over the path like a tunnel, adding a mystical touch to the experience. Visitors can immerse themselves in the magnificent power and beauty of nature, making Kiyomi Town a prime destination for nature enthusiasts.' where id = 'w6rOrpPQsx_m_xpj14wU7';
update content_bodies set title = '文化と民話が根付く飛騨のふるさと - 岐阜県高山市', description = '日本一の面積を誇る高山市は、町の至る所に魅力が溢れています。飛騨高山の独自の魅力を掘り下げ、知られざる逸話やその地でしか味わえない体験を紹介します。千数百年前、飛騨国府は飛騨の中心地として栄え、懐かしさに包まれた温かい村として描かれています。日本の原風景を感じる歴史や民俗、自然を通じて、なぜこの地に国府が置かれたのかを実感できる旅が待っています。' where id = 'o9U5u-ERyGEWJ2aovYcEV';
update content_bodies set title = 'Cultural and Folklore Roots in Hida''s Hometown - Takayama City, Gifu Prefecture', description = 'Takayama City, the largest city in Japan, is rich in attractions throughout its area. This introduction focuses on the unique aspects of Hida Takayama, exploring lesser-known anecdotes and experiences exclusive to this region. Hida Kokufu, which thrived over a thousand years ago as the center of Hidanokuni, is described as a nostalgic village filled with warmth. Visitors can sense the essence of Japan''s original landscape through its history, folk customs, and nature. The journey through Hida Kokufu offers a deeper understanding of why this area was chosen as the location for the Kokufu.' where id = '2k0ByaA0Yh1Ay2NYXwjBH';
update content_bodies set title = '魅せる職人の技！春の高山祭からくり人形', description = '高山祭では、唐子が運ぶ壷から突然現れる龍神のからくり人形が観客を魅了します。龍神は紙吹雪を舞い上げ、荒々しく怒り舞う姿を見せます。熟練の綱方が幾本もの綱を巧みに操り、人形はまるで生きているかのように繊細かつ大胆な演技を披露します。この伝統的な芸術は、職人たちの技術と創造性を示し、祭りのハイライトとなっています。' where id = 'BjawUYha-giSKvNFNA5IC';
update content_bodies set title = 'The Art of Craftsmanship! Spring Takayama Festival - Karakuri Dolls', description = 'At the Takayama Festival, a stunning karakuri doll performance captivates audiences. A dragon god emerges from a pot carried by a child figure, erupting with colorful confetti and performing a fierce dance. Skilled puppeteers manipulate multiple strings, making the doll appear lifelike with its delicate yet bold movements. This traditional art form showcases the craftsmanship and creativity of the artisans involved, making it a highlight of the festival.' where id = 'KEtqZ0S4BjQTTNRgxtYgp';
update content_bodies set title = '飛騨高山で女子旅', description = '岐阜県北部に位置する飛騨高山は、緑豊かな山々に囲まれ、四季折々の自然を楽しむことができます。歴史的な建造物が多く、今も伝統文化が息づいているこの地域は、古き良き伝統を守り続けています。美しい高山の見どころを紹介します。' where id = 'jyV469z4kTq46uXElbxcM';
update content_bodies set title = 'Girls'' Trip to Hida Takayama', description = 'Hida Takayama, located in the northern part of Gifu Prefecture, is surrounded by lush mountains and offers a chance to enjoy the changing nature throughout the seasons. The area is rich in historical buildings and traditional culture that still thrives today. This summary highlights the beautiful sights of Takayama, which has preserved its old traditions.' where id = '4hyXhnYfFFTMlzuLiel4S';
update content_bodies set title = 'どちらが好きですか？ **長いバージョン**', description = '岐阜県の山間部に位置する飛騨高山は、日本列島のほぼ中央にあります。日本で最も大きな市である高山市は、森林率が90％を超える自然豊かな地域です。食、歴史、文化、体験など、多彩な魅力を持つ飛騨高山。あなたはどのような飛騨高山が好きですか？' where id = 'O9QW02j_ODbW_RC55PORp';
update content_bodies set title = 'Which do you like better? **long ver.**', description = 'Hida Takayama, located in the mountainous region of Gifu Prefecture, is situated almost in the center of the Japanese archipelago. Takayama City, the largest city in Japan, boasts a rich natural environment with over 90% forest coverage. Hida Takayama offers a variety of attractions, including food, history, culture, and experiences. What aspects of Hida Takayama do you like the most?' where id = 'Bv55eSeCGhipjBSlvR62X';
update content_bodies set title = '飛騨高山の春と夏', description = '北アルプスに囲まれた飛騨高山は、雄大な自然と四季折々の美しい景色が魅力です。春には桜が咲き誇り、夏には新緑が広がります。この時期にしか味わえない飛騨高山の美しさをぜひ体験しにお越しください。' where id = 'WjIcK8R3ZTifvr7utzrnx';
update content_bodies set title = 'Spring and Summer in Hida Takayama', description = 'Hida Takayama, surrounded by the Northern Alps, offers a majestic natural environment and beautiful seasonal landscapes. In spring, visitors can enjoy cherry blossoms, while summer showcases vibrant greenery. We invite you to experience the unique beauty of Hida Takayama during these seasons.' where id = 'keXVYlt9HKVUOqjANkFI8';
update content_bodies set title = '飛騨高山の秋と冬', description = '北アルプスに囲まれた飛騨高山は、雄大な自然と四季折々の美しい景色が魅力です。秋には紅葉が楽しめ、冬には雪景色が広がります。この時期にしか味わえない飛騨高山の美しさをぜひ体験しにお越しください。' where id = 'i-PH8-pLnVA5hgcg835SU';
update content_bodies set title = 'Autumn and Winter in Hida Takayama', description = 'Hida Takayama, surrounded by the Northern Alps, offers a healing experience with its majestic nature and beautiful seasonal landscapes. In autumn, visitors can enjoy the vibrant foliage, while winter presents a picturesque snowy scenery. We invite you to come and experience the unique beauty of Hida Takayama during these seasons.' where id = 'x20VZahwJCX7AgAXDja_P';
update content_bodies set title = '匠の技　#飛騨家具', description = '「飛騨家具」は、人と共に時を重ねる家具であり、日本の美と飛騨の心が込められたデザインが特徴です。使い手が長く使い続けられるよう工夫されており、使い込むほどに味わいが増す木の家具です。特に、飛騨家具の特徴である曲木など、製作過程を動画でまとめています。ぜひご覧ください。' where id = 'p_vVqb_TLuCXKMskE95de';
update content_bodies set title = 'The Craftsmanship of Hida Furniture', description = 'Hida furniture embodies the beauty of Japan and the spirit of Hida, designed to be cherished over time. These wooden pieces gain character with use, showcasing features like bent wood that are characteristic of Hida craftsmanship. A video captures the process of creating Hida furniture, highlighting the traditional techniques involved. We invite you to watch and appreciate the artistry.' where id = 'xRBcTdXdGOq_x8NydPfd9';
update content_bodies set title = '【公式】長岡市観光プロモーション動画', description = '長岡市の観光プロモーション動画では、自然や街並み、温泉、食文化、日常の風景などが美しい映像で紹介されています。動画では、ぽんしゅ館や摂田屋地区、機那サフラン酒製造本舗、はちすば通り、笹団子作り体験、髙龍神社、魚の市場通り、五・十の市、栃尾の油揚げ、牛の角突き、日蓮宗本山村田妙法寺、宝徳山稲荷大社、長岡米、洋風カツ丼、殿町、小国和紙作り体験、棚田、錦鯉、蓬平温泉、道の駅ながおか花火館、長岡花火など、様々な観光スポットが紹介されています。' where id = 'QZa88BknMFXe-3dblYoRV';
update content_bodies set title = 'Official Nagaoka City Tourism Promotion Video', description = 'This video showcases the beautiful scenery of Nagaoka City, including its nature, cityscape, hot springs, food, and everyday life. For more information about tourism in Nagaoka City, please visit the website.' where id = 'tmXF1_uiy2dAOA-gQ7kEN';
update content_bodies set title = '越前 手仕事を巡る旅 | 越前叡智', description = '越前は、古代から続く手仕事の聖地であり、叡智が集積された場所です。1500年にわたり、先人たちの技と心が受け継がれてきたこの町は、古代の王が治めた「越の国」の入口に位置しています。かつて日本海を越えて最先端の技術と文化が流入し、日本のものづくりの起源となりました。土地の自然と共生する伝統的な産業やここに住む人々には、次の1000年に持ち運びたい普遍の知恵が息づいています。国境や時空を越えた交流を通じて、新しい未来が生まれるこの地へようこそ。光を見つける探究の旅が始まります。' where id = 'evzf9PLpp2MncD5_okcqx';
update content_bodies set title = 'Craft Tourism Echizen | Wisdom Echizen', description = 'Echizen is a sacred place of craftsmanship, rich in wisdom accumulated since ancient times. For 1500 years, the skills and spirit of our ancestors have been passed down in this town. Located at the entrance of ''Echizen no Kuni,'' once ruled by ancient kings, it was the first place in Japan to receive advanced technologies and cultures from across the Sea of Japan, marking the origin of deep craftsmanship in Japan. Traditional industries that coexist with the local nature and the people living here embody universal wisdom that humanity wishes to carry into the next millennium. By fostering exchanges that transcend borders and time, a new future is born in this land. Welcome to Echizen, a journey of exploration to find light.' where id = 'gGcVeB5E3tYKeZ0catxxi';
update content_bodies set title = '南小国町観光プロモーションビデオ　フルバージョン', description = '南小国町の観光プロモーションビデオで、黒川温泉が有名です。このビデオでは、温泉を通じて体験できる日本の伝統的な生活に触れることができると紹介されています。温泉だけでなく、南小国町には他にも多くの魅力があることを伝え、訪れることを促しています。' where id = 'rp73I2a85qK8tpHuB4d2d';
update content_bodies set title = 'Minamioguni Tourism Promotion Video (Full Version)', description = 'This is a tourism promotion video for Minamioguni, a town known for Kurokawa Onsen. The video highlights the traditional Japanese lifestyle that visitors can experience through the town''s hot springs. It encourages people to visit Minamioguni, emphasizing that there is much more to explore beyond just the hot springs.' where id = 'EsMhRUOTHOYYtF11QYcBx';
update content_bodies set title = '【360°VR動画】阿蘇の大自然をガイド付きで巡るバーチャルツアー！熊本県_阿蘇_ロングバージョン', description = '熊本県の阿蘇地域で撮影された360度のVR映像です。阿蘇に住むスウェーデン人が、阿蘇の魅力を語りながら案内します。自宅にいながらお出かけ気分を楽しむことができます。視聴方法は、スマートフォンの場合は最新のAndroidまたはiOS向けYoutubeアプリをインストールし、パソコンの場合はChromeやFirefoxなどの360度動画対応ブラウザを使用してください。' where id = 'KeVQDqk-ai4P_ULjqnXre';
update content_bodies set title = '360° VR Video: Guided Virtual Tour of Aso''s Great Nature! Kumamoto Prefecture_Aso_Long Version', description = 'This is a 360-degree VR video filmed in the Aso region of Kumamoto Prefecture. A Swedish resident of Aso narrates the charm of the area while guiding viewers through the landscape. Enjoy the feeling of going out from the comfort of your home.' where id = 'l6mIsMjqZ5KaE7jgWZMRL';
update content_bodies set title = '出雲 日御碕神社 夕日の祭り', description = '出雲大社から北西約7kmの島根半島西端に位置する日御碕神社は、夜を守る神社として知られています。この神社で行われる夕日の祭り（例大祭、神幸神事）では、年に一度、神官のみが入ることのできる神域である経島から沈む太陽に祈りを捧げます。この特別な行事は、神社の文化的意義と周囲の自然美とのつながりを強調しています。' where id = 'pSBdNi-VW5T4AaC-lurnz';
update content_bodies set title = 'Sunset Festival HINOMISAKI Shrine in IZUMO', description = 'Hinomisaki Shrine, located at the western end of the Shimane Peninsula about 7km northwest of Izumo Taisha, is known as a shrine that protects the night. During the annual sunset festival (Hinomisaki Shrine annual festival, Shinko Shinto ritual), priests gather at Fumishima, a sacred area accessible only to them, to offer prayers to the setting sun. This unique event highlights the cultural significance of the shrine and its connection to the natural beauty of the surrounding landscape.' where id = 'g4hgsvUIEVz3q90zEfiYM';
update content_bodies set title = '里山ミニクルで、観に来るたびに好きになる旅。', description = '「里山ミニクル」は、新型の電動アシスト付き自転車のレンタサイクルサービスです。女性でも扱いやすいミニタイプ、シティータイプ、スポーツタイプの3種類があり、電動アシストにより坂道も楽に登れます。貸出場所では、おすすめのモデルコースや旅行に役立つガイドアプリが用意されており、初めての方でも安心して利用できます。2時間コースや1泊2日の利用が可能で、サイクリングを楽しむことや旅行の目的地への移動手段としても活用できます。' where id = 'RDH56hi9MvbOFE0AIbfPg';
update content_bodies set title = 'Satoyama Minicle: fall into the charm of your travels with every spin of the wheel.', description = 'Satoyama Minicle is a bicycle rental service that offers electric power-assisted bikes in three models: a mini model for easy handling, an urban city model, and a sports model. These bikes make it easy to ride up hills thanks to their electric assistance. At the rental location, users can access a guided app that provides recommended routes and useful travel information, making it user-friendly for first-time riders. Rentals are available for 2-hour periods or overnight, allowing travelers to enjoy cycling or use the bikes as part of their travel plans.' where id = '1AYOnVqQIJa1HMilqnOF9';
update content_bodies set title = '伊予市観光PR動画｜ますます、いよし。', description = '伊予市は、美しい自然や地元の特別なモノ・コトに出会える癒しの旅に最適な場所です。海を眺めたり、森の香りに包まれたりしながら、おいしい食べ物やパワースポット、クラフトなど、今を楽しむときめきがたくさんあります。今日はどこに行こうか迷ったときには、あなたの「好き」を探しに伊予市へ出かけてみてください。' where id = 'AW875t14u8FWLt_p40MlX';
update content_bodies set title = 'Iyo City Tourism PR Video | More and More, Iyo', description = 'Iyo City is the perfect destination for a healing journey, where you can encounter beautiful and rich nature, as well as local treasures. Enjoy leisurely views of the sea, immerse yourself in the scent of the forest, and indulge in delicious food, power spots, and crafts. There are plenty of exciting experiences to enjoy in the present moment. When you''re wondering where to go today, consider heading to Iyo City to discover what you love.' where id = 'xDiWBVjXbWRnEnXN1vKrp';
update content_bodies set title = 'AMAZING TOYAMA 〜 この地を選んだ理由 〜【ダイジェスト版】', description = '「AMAZING TOYAMA」は、地域プロモーションアワード2021で地域活性化センター賞を受賞し、第4回日本国際観光映像祭では日本部門のCitypromotionカテゴリで優秀作品賞、国際部門のTourism Destination Citiesカテゴリで3位を獲得しました。このプロジェクトでは、異なる分野で活躍する5人の成功者が富山を選んだ理由を探り、地域の魅力や豊かさを紹介しています。出演者には、流動研究所のピーター・アイビー、有限会社マツダの大橋智子、キッチン花水木の田中裕信、水橋漁民協同組合の水野勝也、株式会社Travearthの大塚憲一が含まれています。' where id = 'A7jz0QhMil1bqdJfs6j_c';
update content_bodies set title = 'AMAZING TOYAMA - Reasons for Choosing This Place - [Digest Version]', description = 'The video ''AMAZING TOYAMA'' has received several awards, including the Regional Activation Center Award at the 2021 Regional Promotion Award and the Excellent Work Award in the City Promotion category at the 4th Japan International Tourism Film Festival. Additionally, it secured third place in the International category for Tourism Destination Cities. The project explores the reasons behind choosing Toyama through the perspectives of five successful individuals from various fields, highlighting the region''s charm and richness. The featured cast includes Peter Ivy from the Fluid Research Institute, Tomoko Ohashi from Mazda Co., Hiroshi Tanaka from Kitchen Hanamizuki, Katsuya Mizuno from the Mizuhashi Fishermen''s Cooperative, and Kenichi Otsuka from Travearth.' where id = '7qfTC3PXQ7-EbMZ1epZSu';
update content_bodies set title = 'AMAZING TOYAMA 〜 富山を選んだ理由 〜', description = '「AMAZING TOYAMA」は、地域プロモーションアワード2021や第4回日本国際観光映像祭での受賞歴があるプロジェクトです。この動画では、異なる分野で活躍する5人が富山を選んだ理由や地域の魅力について語ります。出演者には、流動研究所のピーター・アイビー、有限会社マツダの大橋智子、キッチン花水木の田中裕信、水橋漁民協同組合の水野勝也、株式会社Travearthの大塚憲一が含まれています。このプロジェクトは、富山の魅力を強調し、訪れる価値のある目的地としてのプロモーションを目指しています。' where id = 'jDGlH_qHdrLaTwi_WY0Eg';
update content_bodies set title = 'AMAZING TOYAMA 〜 Why I chose Toyama 〜', description = 'The project ''AMAZING TOYAMA'' has received several awards, including the Regional Promotion Award 2021 and the Excellent Work Award in the City Promotion category at the 4th Japan International Tourism Film Festival. The video features five successful individuals from various fields discussing their reasons for choosing Toyama and exploring the region''s charm and richness. The cast includes Peter Ivy from the Fluid Research Institute, Tomoko Oohashi from Mazda Co., Hironobu Tanaka from Kitchen Hanamizuki, Katsuya Mizuno from the Mizuhashi Fishermen''s Cooperative, and Kenichi Ootsuka from Travearth. The project aims to highlight Toyama''s appeal and promote it as a desirable destination.' where id = '1jwhWBJS4dr7CUN4BSsuH';
update content_bodies set title = '楽しもう！「大川」大川女子２人旅 フルバージョン', description = 'これは福岡県大川市のPR動画で、2018年に制作されました。モデルのアリョーナとケレンが大川を初めて体験する様子が描かれています。映像はカメラマンの岩尾海生やヘアメイクアーティスト、音楽を担当したマーストライプスなど、さまざまなプロフェッショナルの協力によって制作されています。この動画は大川の美しさや魅力を紹介し、視聴者にこの街を楽しむよう呼びかけています。' where id = 'vfG8EllfWqJUJucKItmqN';
update content_bodies set title = 'Let''s enjoy! ''OKAWA'' - Full Version of the Two Girls'' Trip in Okawa', description = 'This is a promotional video from 2018 showcasing Okawa city in Fukuoka Prefecture. The video features models Alyona and Keren as they experience Okawa for the first time. The film includes contributions from various professionals, including cinematographer Kaisei Iwao, hair and makeup artists, and music by Marstripes. The production highlights the beauty and attractions of Okawa, inviting viewers to enjoy the city.' where id = 'voiQZjAHjGEyW-yXf7Ylk';
update content_bodies set title = '空飛ぶ！KBC（大川市）', description = '汐が引くと現れる「石の道」は、航路を確保し水流を早めるために100年以上前に建造されたと言われています。撮影地は大川市で、ドローンパイロットはBLUE MINTです。' where id = 'VwM_6wabMLrkQWVWrZcix';
update content_bodies set title = 'Flying! KBC (Okawa City)', description = 'The ''Stone Path'' appears when the tide goes out. It is said to have been constructed over 100 years ago to secure navigation routes and accelerate water flow.' where id = 'IUMTJcpp2AqSjnZCpTMdc';
update content_bodies set title = '天空ミュージック（Knock on Wood）', description = '香川県高松市の屋島山上で2012年から開催されているライブイベント「天空ミュージック」が、今年で10周年を迎えます。特に小倉博和さんの美しいギターをフィーチャーした映像が制作され、彼の父の思い出と屋島の形状が重なり、ノスタルジックな魅力を醸し出しています。映像は中野裕之さんが監督し、小倉さんの音楽と山上の空気感を切り取った特別な作品です。この特別な時間を楽しんでいただければと思います。主催は屋島山上ライブイベント実行委員会で、企画制作は街角に音楽を@香川（MUSIC BLUE）が行い、屋島寺と屋島山上観光協会が協力しています。' where id = 'fcfng94hmcrIasqD6D--_';
update content_bodies set title = 'Sky Music (Knock on Wood)', description = 'Sky Music is a live event held on Mount Yashima in Takamatsu City, Kagawa Prefecture, since 2012. This year marks its 10th anniversary, featuring a special video showcasing the beautiful guitar work of Hirokazu Ogura. The video evokes nostalgia, intertwining memories of Ogura''s father with the shape of Yashima. Directed by Hiroyuki Nakano, the film captures the essence of Ogura''s music and the atmosphere of the mountaintop, inviting viewers to immerse themselves in this unique experience. The event is organized by the Yashima Mountain Live Event Executive Committee and produced by Music Blue in Kagawa, with support from Yashima Temple and the Yashima Mountain Tourism Association.' where id = 'rBSlv2IwJziC8ElwgyzUz';
update content_bodies set title = '第1弾【ロボ家具 WEB MOVIE】 職人MADE大川家具By大川市', description = 'これからの家具はどのようなものになるのでしょうか。大川家具はその答えを「ロボ家具」として提案します。外見は従来の家具と変わりませんが、自ら移動し、停止し、さらには回転することができる不思議な家具です。この「ロボ家具」は、生活の新しいパートナーとなり、レイアウトの変更を容易にし、子供たちの遊び道具にもなり、居住空間をより楽しいものにします。伝統的な技術と革新的なアイデアを組み合わせて、大川家具は豊かなライフスタイルを提案します。ロボ家具の詳細や製作秘話については、特設ページをご覧ください。' where id = 'irIfJ9WLqzwYn88958s1N';
update content_bodies set title = 'Robot Furniture WEB MOVIE by Okawa City', description = 'What will the furniture of the future look like? Okawa Furniture has an answer: ''Robot Furniture.'' This innovative furniture appears like traditional pieces but has the ability to move, stop, and even spin on its own. It aims to be a new companion in your life, making redecorating easier, serving as a ride for children, and enhancing your home experience. By combining traditional craftsmanship with innovative ideas, Okawa Furniture offers a rich lifestyle through its products. For more details and behind-the-scenes stories about the creation of Robot Furniture, please visit the special webpage.' where id = 'Td832wQ3E6NYx59h9ppTF';
update content_bodies set title = '天空ミュージック（Father''s Back）', description = '香川県高松市の屋島山上で2012年から開催されているライブイベント「天空ミュージック」が10周年を迎え、小倉博和さんの美しいギターをフィーチャーした映像が制作されました。監督は中野裕之さんで、この映像は小倉さんの音楽と山上の特別な空気感を捉えています。ここでしか味わえない特別な時間に浸っていただければと思います。主催は屋島山上ライブイベント実行委員会で、企画制作は街角に音楽を@香川（MUSIC BLUE）、協力は屋島寺と屋島山上観光協会です。' where id = 'pYnYjgi_Kop5QOmsSNXYd';
update content_bodies set title = 'Sky Music (Father''s Back)', description = 'The ''Sky Music'' live event has been held on Mount Yashima in Takamatsu City, Kagawa Prefecture, since 2012. This year marks its 10th anniversary, and a special video featuring the beautiful guitar of Hirokazu Ogura has been produced. Directed by Hiroyuki Nakano, the video captures Ogura''s music and the unique atmosphere of the mountaintop. It invites viewers to immerse themselves in this special moment that can only be experienced here. The event is organized by the Yashima Mountain Live Event Executive Committee, with planning and production by Music Blue in Kagawa, and support from Yashimaji Temple and the Yashima Mountain Tourism Association.' where id = 'jMTswMdMKDT8LHYmMxDX7';
update content_bodies set title = '渋川に来てね！', description = 'これは渋川市の魅力を紹介するPR動画で、伊香保温泉や水沢うどん、へそまつりなどが取り上げられています。全編英語のナレーションが使用されており、日本語の字幕も付いているため、多くの人にとって理解しやすい作品となっています。' where id = 'T_WVwuEa6QcVS2WBvHbl_';
update content_bodies set title = 'Come Visit Shibukawa!', description = 'This is an award-winning promotional video for Shibukawa City, showcasing its attractions such as Ikaho Onsen, Mizusawa Udon, and the Heso Festival. The entire video features English narration, making it accessible to a wider audience with Japanese subtitles included.' where id = 'iMARFSEma32ceU5tYMiG6';
update content_bodies set title = '津軽塗 ブランドムービー', description = '津軽塗は青森県弘前市の伝統工芸で、300年以上の歴史を持ちます。この工芸は、職人の努力と美的センスによって受け継がれてきました。ヒバの素地に塗り重ね、研ぎや磨きを繰り返すことで、堅牢で優美な塗物が完成します。この工程は40以上のステップを経て2ヶ月以上かかるため、「馬鹿塗」とも呼ばれています。このムービーでは、職人の手仕事とともに、「唐塗」「七々子塗」「紋紗塗」「錦塗」の4つの技法が津軽の美しさと共に表現されています。' where id = '5WMYxQSXg_g9LGhzl7_iu';
update content_bodies set title = 'Tsugaru Nuri Brand Movie', description = 'Tsugaru nuri is a traditional craft from Hirosaki city in Aomori prefecture, Japan, with a history spanning over 300 years. This craft has been passed down through generations, showcasing the craftsmen''s dedication, hard work, and aesthetic sensibility. The process involves painting the surface of cypress wood, followed by repeated sharpening and polishing, culminating in a robust and elegant lacquerware that takes over two months and more than forty steps to complete. Due to the meticulous nature of the work, it is colloquially known as ''Baka nuri,'' or ''Foolish painting.'' The film highlights the craftsmanship and features four techniques: ''Kara-nuri,'' ''Nanako-nuri,'' ''Monsha-nuri,'' and ''Nishiki-nuri,'' all reflecting the beauty of the Tsugaru region.' where id = 'J1M5mqloZ5hNuVCAbvc5y';
update content_bodies set title = '食堂あお - 地産地消 - 熊野の知られざる物語を味わう', description = '三重県熊野市にある注目のレストラン「食堂あお」は、「世界の富裕層は日本で何を食べているのか？」で紹介されています。コンセプトは「Eat Local（地産地消）」で、春には地元の山菜を摘み、夏には瀞峡で天然うなぎを獲り、秋には藻屑がにを獲るなど、地元の食材を活かした料理を提供しています。年間を通じて、天候が良ければカヤックで海に出て自ら釣った魚を提供するという、都会では考えられないユニークなスタイルを貫いています。オーナーのこの特異なレストランへの思いをぜひ聞いてみてください。' where id = 'h3JgxbNuG1ybAK9_Xe0XJ';
update content_bodies set title = 'Shokudo Ao - Eat Local: Taste the Unfolding Story of Kumano', description = 'Shokudo Ao, a notable restaurant in Kumano City, Mie Prefecture, is featured in ''What Are the Wealthy Eating in Japan?''. The restaurant''s concept is ''Eat Local'', emphasizing local food sourcing. In spring, they forage for wild vegetables, in summer, they catch natural eel in the Dorokyo Gorge, and in autumn, they harvest crab. Throughout the year, weather permitting, they kayak into the sea to catch fish, offering a unique dining experience that is rare in urban settings. The owner’s passion for this distinctive style of restaurant is worth exploring.' where id = 'T8DkjiM4oq__TjP4tifmZ';
update content_bodies set title = 'ウェルビーイングな暮らし 柑橘栽培を始める - みかんが教えてくれること', description = 'ウェルビーイングな暮らしを求めていた夫婦が東京から三重県御浜町に移住してから3年半が経過しました。昨年から始めた庭のみかん作りは、趣味の範疇を超えた数の木々を育てる大変な作業ですが、その手間を楽しんでいます。彼らにとってのウェルビーイングな暮らしとは何か、みかんを育てることで得られた新たな人生の喜びについて考えています。' where id = '0SNgL-fvi3Yy9R-P_8tPK';
update content_bodies set title = 'Well-being Living: Starting Citrus Cultivation - Lessons from Mandarins', description = 'A couple seeking a well-being lifestyle moved from Tokyo to Mihama, Mie Prefecture, over three and a half years ago. They began cultivating mandarin oranges in their garden last year, which has turned out to be a challenging yet rewarding endeavor. Growing numerous mandarin trees has exceeded their initial hobby, but they find joy in the effort. They reflect on what a well-being lifestyle means to them and the newfound joys in life that have emerged from nurturing these fruits.' where id = 'mu-t6B2oSIFkGgYxJrzTy';
update content_bodies set title = '青ノ詩を詠う - Pass the Baton -「市木木綿」唯一の職人の挑戦', description = '三重県御浜町の伝統工芸「市木木綿」の唯一の職人、向井浩高さんは、代々続くふとん店を営みながら、週に1度、100年以上前の織り機を使って「市木木綿」を織り続けています。江戸時代から続く木綿織産業は、明治時代に「市木木綿」としてブランド化され、全盛期には40軒以上の工場がありましたが、現在は向井さんだけになっています。工場の移転を余儀なくされ、市木木綿が消滅の危機に直面する中、向井さんは「市木木綿を未来へ紡ぐ会」を発足し、自らの工場を手に入れ、後継者に無償で譲ることを決意しました。クラウドファンディングを通じて資金を集め、新しい縞「御浜ブルー」を制作。全国からの支援を受け、クラウドファンディングは成功を収めました。新工場を拠点に、向井さんは「市木木綿」の魅力を広めるため、伝統工芸と観光を融合させたツアーを開始し、持続可能な伝統工芸の形を作る挑戦を続けています。' where id = 'Q0Z7qJCpX8qYuMmJcMQiG';
update content_bodies set title = 'The Challenge of Hirotaka Mukai, the Sole Craftsman of Ichiki Cotton - Pass the Baton', description = 'Hirotaka Mukai is the only craftsman of Ichiki Cotton, a traditional craft in Mihama Town, Mie Prefecture. He continues to weave Ichiki Cotton using a loom over 100 years old, while running a family bedding business. The Ichiki cotton weaving industry, which dates back to the Edo period, was branded as Ichiki Cotton in the Meiji era, reaching its peak with over 40 factories. However, now only Mukai remains. Facing the risk of extinction due to the forced relocation from his rented factory, he founded the ''Ichiki Cotton Future Weaving Association'' and decided to acquire his own factory to ensure a smooth transition for future successors. He launched a crowdfunding campaign to cover the costs of moving, purchasing, and renovating the factory. As a highlight of the campaign, he created a new stripe called ''Mihama Blue,'' inspired by the town''s sea color. Thanks to nationwide support, the crowdfunding was a success. Mukai has since started ''traditional craft x tourism'' tours to promote Ichiki Cotton''s charm and create a sustainable model for the craft.' where id = 'NxejEZp7qndPhwaHaDAiQ';
update content_bodies set title = '青ノ詩を詠う - 御浜は年中青し', description = '「日本の青」という独特の美意識が存在し、青と呼ばれる「青」と「緑」が融合しています。三重県御浜町は、太平洋の青と紀伊山地の青が出会う場所で、神仏習合の聖地です。詩人・佐藤春夫は故郷の熊野の風景を詠み、「望郷五月歌」で空、山、海の青を表現しました。熊野古道の霧「風伝おろし」が山の青を反射し、青々とした稲穂や特産の青いみかんを駆け抜けます。御浜町の青は、海、山、空、風、みかんに至るまで広がり、訪れる人々はそれぞれの感性でこの町の青を味わい、詩を詠むことができます。あなたには、御浜の町は何色に映りますか？' where id = 'AAnQBne4wrujBXp12rBQt';
update content_bodies set title = 'Searching for Japan Blue - A Poem of Aoi no Uta', description = 'The concept of ''Japan Blue'' is unique to Japanese aesthetics, comprising both the blue and green hues found in nature. Mihama Town in Mie Prefecture, where the blue of the Pacific Ocean meets the blue of the Kii Mountains, serves as a sacred site for the fusion of Shinto and Buddhism. Poet Haruo Sato, reflecting on his hometown of Kumano, captured its essence in his poem ''Bokyo Gogatsu Uta,'' celebrating the blue of the sky, mountains, and sea. The mystical fog known as ''Fuden Oroshi'' flows through the Kumano Kodo trail, reflecting the vibrant greens of the mountains. This blue permeates the town, from the lush rice fields to the famous blue mikan oranges. Visitors are invited to explore and reinterpret the unique shades of blue in Mihama, creating their own poetic expressions of the town''s beauty.' where id = 'G7G2BBb9w001w7nnwZ7Hz';
update content_bodies set title = '【はじめての熊野古道】熊野古道風伝峠を歩く- 熊野を1泊2日で旅する 後編', description = '元アイドルの池山智瑛さんが三重県御浜町を1泊2日で旅する様子を紹介します。初日は、74歳のシンデレラが運営する体験型ゲストハウスでサステナブルな田舎暮らしを体験しました。2日目は、熊野名物のめはり寿司を作り、世界遺産の熊野古道「風伝峠」を歩きます。苔むす石畳をたどりながら、古の旅人の足跡を感じ、熊野の自然に癒される様子が描かれています。池山さんは現在、尾鷲市に移住し、地域おこし協力隊として地域の魅力を発信しています。' where id = 'HMHFXmeuJ67zrDd-87wN_';
update content_bodies set title = 'Walking the Kumano Kodo: A 2-Day Journey in Kumano - Part 2', description = 'In this video, former idol Tomoe Ikeyama embarks on a 2-day trip to Mihama Town in Mie Prefecture. On the first day, she experiences sustainable rural living at a guesthouse run by a 74-year-old ''Cinderella.'' The second day features making a local specialty, mehari sushi, and exploring the World Heritage site, the Kumano Kodo ''Fuden'' pass. The video highlights the beauty of the ancient stone paths and the healing nature of Kumano. Tomoe, now living in Owase City as a community revitalization coordinator, shares the charm of the region through her YouTube channel.' where id = '8BKAOV1SkqEUe8Co_UNkN';
update content_bodies set title = '【田舎暮らし総集編】はじめての田舎暮らし', description = '2020年7月、コロナ禍の中、東京から三重県熊野市御浜町に移住した夫婦の一年間の軌跡を振り返ります。この一年は、初めての田舎暮らしであり、コロナの影響を受けながらも、試行錯誤を重ね、新しい出会いに恵まれた年でした。彼らは、移住初日や夏の出来事、モーニングルーティンなどを記録した動画を視聴するよう視聴者に呼びかけています。また、三重県御浜町についての詳細情報を提供するウェブサイトのリンクも掲載しています。質問があればコメント欄で気軽に尋ねてほしいとし、月に2本の動画をアップする予定であることを伝えています。' where id = '6X9Clzv95Q7pCadF7x8gj';
update content_bodies set title = 'Rural Living Compilation: First Year of Living in the Countryside', description = 'In July 2020, a couple moved from Tokyo to Kumano, Mie Prefecture, during the COVID-19 pandemic. This summary reflects on their first year of rural living, marked by challenges and new experiences. They navigated the difficulties brought on by the pandemic while embracing the joys of rural life. The couple shares their journey filled with trial and error, new encounters, and personal growth. They invite viewers to watch related videos that document their experiences, including their first day of moving, a summer milestone, and their morning routine. For more information about Mihama Town in Mie Prefecture, they provide a link to a website. They encourage comments and interaction, and plan to upload videos twice a month, along with promoting their Instagram account.' where id = '-1m91EkZsD6Ujm_2TJpsc';
update content_bodies set title = '【移住者の暮らし】里山暮らし｜移住ってどう？｜移住者の幸せな暮らし｜熊野｜地方移住｜サステナブル', description = '三重県御浜町尾呂志は移住者が多い地域で、美しい里山の風景と地元の人々の温かい歓迎が魅力です。近年、都会から多くの人が移住してきており、訪れた際には幸せそうな光景に出会いました。子供たちは自然の中で遊び、大人たちは都会ではできなかったことを楽しみながら日々を過ごしています。尾呂志の人々は、移住者の私たちから見ても羨ましい存在です。御浜町は紀伊半島の太平洋沿いに位置し、温暖な気候のおかげで年中みかんが収穫できる町です。熊野は「よみがえりの地」として知られ、訪れる人々に新たな気持ちをもたらします。' where id = '09E4eiw-hso9MEAGN76zv';